CREATE OR REPLACE FUNCTION account_book_close_logic_positions(p_account_id INTEGER,
    p_sold JSONB DEFAULT NULL)
RETURNS JSONB
LANGUAGE plpgsql AS $$
DECLARE
    v_logic RECORD;
    v_one JSONB;
    v_results JSONB := '[]'::JSONB;
    v_closed INTEGER := 0;
BEGIN
    FOR v_logic IN
        SELECT l.id, l.name
        FROM logics l
        WHERE l.account_id = p_account_id
        ORDER BY l.id
    LOOP
        v_one := logic_close_all_positions_at_market(
            v_logic.id,
            FALSE,           -- including cash funds if any open in books
            FALSE,           -- no broker orders
            'account:sell_all',
            p_sold
        );
        v_closed := v_closed + COALESCE((v_one->>'closed')::INTEGER, 0);
        v_results := v_results || jsonb_build_array(jsonb_build_object(
            'logic_id', v_logic.id,
            'logic_name', v_logic.name,
            'result', v_one
        ));
    END LOOP;

    RETURN jsonb_build_object(
        'ok', TRUE,
        'account_id', p_account_id,
        'logics_closed_total', v_closed,
        'logics', v_results
    );
END;
$$;

COMMENT ON FUNCTION account_book_close_logic_positions(INTEGER, JSONB) IS
'РЎРёРЅС…СЂРѕРЅРёР·Р°С†РёСЏ РєРЅРёРіРё: Р·Р°РєСЂС‹С‚СЊ РѕС‚РєСЂС‹С‚С‹Рµ (filled/submitted) РїРѕР·РёС†РёРё РІСЃРµС… Р»РѕРіРёРє СЃС‡С‘С‚Р° Р±РµР· PostOrder; С†РµРЅС‹ РёР· p_sold РїСЂРё РЅР°Р»РёС‡РёРё';

CREATE OR REPLACE FUNCTION account_require_real_tbank(p_account_id INTEGER)
RETURNS TABLE (
    account_id INTEGER,
    account_code VARCHAR,
    api_url TEXT,
    token TEXT,
    broker_account_id TEXT
)
LANGUAGE plpgsql AS $$
DECLARE
    v_type VARCHAR;
    v_broker VARCHAR;
    v_token TEXT;
    v_api TEXT;
    v_code VARCHAR;
    v_resolved JSONB;
BEGIN
    SELECT a.id, a.account_code, a.account_type, b.code, btrim(a.token_encrypted), b.api_url
    INTO account_id, v_code, v_type, v_broker, v_token, v_api
    FROM accounts a
    JOIN brokers b ON b.id = a.broker_id
    WHERE a.id = p_account_id;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'РЎС‡С‘С‚ id=% РЅРµ РЅР°Р№РґРµРЅ', p_account_id;
    END IF;
    IF lower(COALESCE(v_type, '')) <> 'real' THEN
        RAISE EXCEPTION 'Р”РµР№СЃС‚РІРёРµ РґРѕСЃС‚СѓРїРЅРѕ С‚РѕР»СЊРєРѕ РґР»СЏ СЂРµР°Р»СЊРЅРѕРіРѕ СЃС‡С‘С‚Р°';
    END IF;
    IF v_broker <> 'T-BANK' THEN
        RAISE EXCEPTION 'Р”РµР№СЃС‚РІРёРµ РґРѕСЃС‚СѓРїРЅРѕ С‚РѕР»СЊРєРѕ РґР»СЏ Р±СЂРѕРєРµСЂР° T-BANK';
    END IF;
    IF v_token IS NULL OR v_token = '' THEN
        RAISE EXCEPTION 'РќР° СЃС‡С‘С‚Рµ РЅРµС‚ API-С‚РѕРєРµРЅР° T-Bank';
    END IF;

    v_resolved := resolve_tbank_account(v_api, v_token, v_code);
    account_code := v_code;
    api_url := v_api;
    token := v_token;
    broker_account_id := v_resolved->>'account_id';
    RETURN NEXT;
END;
$$;

COMMENT ON FUNCTION account_require_real_tbank(INTEGER) IS
'РџСЂРѕРІРµСЂРєР°: СЂРµР°Р»СЊРЅС‹Р№ СЃС‡С‘С‚ T-Bank СЃ С‚РѕРєРµРЅРѕРј; РІРѕР·РІСЂР°С‰Р°РµС‚ СЂРµРєРІРёР·РёС‚С‹ РґР»СЏ HTTP';

CREATE OR REPLACE FUNCTION account_sell_all_at_market(p_account_id INTEGER)
RETURNS JSONB
LANGUAGE plpgsql AS $$
DECLARE
    v_acc RECORD;
    v_pack JSONB;
    v_pos JSONB;
    v_type TEXT;
    v_figi TEXT;
    v_ticker TEXT;
    v_shares NUMERIC;
    v_blocked_lots NUMERIC;
    v_lot INTEGER;
    v_sell_shares NUMERIC;
    v_lots NUMERIC;
    v_price NUMERIC;
    v_dir TEXT;
    v_order JSONB;
    v_sold JSONB := '[]'::JSONB;
    v_errors JSONB := '[]'::JSONB;
    v_skipped JSONB := '[]'::JSONB;
BEGIN
    SELECT * INTO v_acc FROM account_require_real_tbank(p_account_id) LIMIT 1;
    v_pack := fetch_tbank_portfolio_positions(p_account_id);

    FOR v_pos IN SELECT value FROM jsonb_array_elements(COALESCE(v_pack->'positions', '[]'::JSONB))
    LOOP
        v_type := upper(COALESCE(v_pos->>'instrumentType', v_pos->>'instrument_type', ''));
        IF v_type LIKE '%CURRENCY%' THEN
            v_skipped := v_skipped || jsonb_build_array(jsonb_build_object(
                'figi', v_pos->>'figi',
                'reason', 'currency'
            ));
            CONTINUE;
        END IF;

        v_figi := NULLIF(btrim(COALESCE(v_pos->>'figi', '')), '');
        v_ticker := COALESCE(v_pos->>'ticker', v_figi, '?');
        IF v_figi IS NULL THEN
            v_errors := v_errors || jsonb_build_array(jsonb_build_object(
                'ticker', v_ticker,
                'error', 'no_figi'
            ));
            CONTINUE;
        END IF;

        -- quantity = С€С‚СѓРєРё (Р°РєС‚СѓР°Р»СЊРЅРѕ); quantityLots deprecated вЂ” РЅРµ СЃР»Р°С‚СЊ РµРіРѕ РІ PostOrder РєР°Рє Р»РѕС‚С‹
        -- Р±РµР· РїРѕРІС‚РѕСЂРЅРѕРіРѕ РґРµР»РµРЅРёСЏ: tbank_post_order(..., shares, ..., is_lots=FALSE).
        v_shares := COALESCE(parse_tbank_quotation(v_pos->'quantity'), 0);
        v_blocked_lots := COALESCE(
            parse_tbank_quotation(COALESCE(v_pos->'blockedLots', v_pos->'blocked_lots')),
            0
        );
        v_lot := tbank_figi_lot_size(v_acc.api_url, v_acc.token, v_figi);
        v_sell_shares := v_shares - (v_blocked_lots * v_lot);

        -- Fallback: РµСЃР»Рё quantity РїСѓСЃС‚РѕР№, РІР·СЏС‚СЊ quantityLots Г— lot
        IF abs(v_sell_shares) < v_lot THEN
            v_lots := COALESCE(
                parse_tbank_quotation(COALESCE(v_pos->'quantityLots', v_pos->'quantity_lots')),
                0
            ) - v_blocked_lots;
            IF abs(v_lots) >= 1 THEN
                v_sell_shares := v_lots * v_lot;
            END IF;
        END IF;

        IF abs(v_sell_shares) < v_lot THEN
            v_skipped := v_skipped || jsonb_build_array(jsonb_build_object(
                'figi', v_figi,
                'ticker', v_ticker,
                'reason', 'zero_lots',
                'shares', v_shares,
                'blocked_lots', v_blocked_lots,
                'lot', v_lot
            ));
            CONTINUE;
        END IF;

        IF v_sell_shares > 0 THEN
            v_dir := 'SELL';
        ELSE
            v_dir := 'BUY';
            v_sell_shares := abs(v_sell_shares);
        END IF;

        v_lots := floor(v_sell_shares / v_lot);
        IF v_lots < 1 THEN
            v_skipped := v_skipped || jsonb_build_array(jsonb_build_object(
                'figi', v_figi,
                'ticker', v_ticker,
                'reason', 'below_one_lot',
                'sell_shares', v_sell_shares,
                'lot', v_lot
            ));
            CONTINUE;
        END IF;

        v_price := COALESCE(
            NULLIF(parse_tbank_quotation(v_pos->'currentPrice'), 0),
            NULLIF(parse_tbank_quotation(v_pos->'averagePositionPriceFifo'), 0),
            NULLIF(parse_tbank_quotation(v_pos->'averagePositionPrice'), 0),
            1
        );

        BEGIN
            -- РЈР¶Рµ Р»РѕС‚С‹ (РїРѕСЃС‡РёС‚Р°Р»Рё РёР· quantityв€’blocked). TRUE = РЅРµ РґРµР»РёС‚СЊ РїРѕРІС‚РѕСЂРЅРѕ.
            v_order := tbank_post_order(
                p_account_id, v_figi, v_lots, v_price, v_dir, 'market', TRUE
            );
            v_sold := v_sold || jsonb_build_array(jsonb_build_object(
                'figi', v_figi,
                'ticker', v_ticker,
                'lots', v_lots,
                'shares', v_lots * v_lot,
                'lot_size', v_lot,
                'price', v_price,
                'direction', v_dir,
                'instrument_type', v_type,
                'order', v_order
            ));
        EXCEPTION
            WHEN OTHERS THEN
                v_errors := v_errors || jsonb_build_array(jsonb_build_object(
                    'figi', v_figi,
                    'ticker', v_ticker,
                    'lots', v_lots,
                    'shares', v_lots * v_lot,
                    'direction', v_dir,
                    'error', SQLERRM
                ));
        END;
    END LOOP;

    -- РљРЅРёРіР° Р»РѕРіРёРє: Р·Р°РєСЂС‹С‚СЊ РѕС‚РєСЂС‹С‚С‹Рµ РїРѕР·РёС†РёРё Р±РµР· РІС‚РѕСЂРѕР№ Р·Р°СЏРІРєРё Р±СЂРѕРєРµСЂСѓ.
    RETURN account_sell_all_at_market_with_books(
        p_account_id, v_sold, v_errors, v_skipped, v_pack->'cash_amount'
    );
END;
$$;

COMMENT ON FUNCTION account_sell_all_at_market(INTEGER) IS
'Р РµР°Р»СЊРЅС‹Р№ T-Bank: market sell-all РїРѕ quantity(С€С‚СѓРєРё)в€’blocked; PostOrder С‡РµСЂРµР· sharesв†’lots; Р·Р°С‚РµРј book-close Р»РѕРіРёРє';

-- Book-close after broker is already flat (or repair orphan opens).

CREATE OR REPLACE FUNCTION app_cleanup_last_at()
RETURNS TIMESTAMP
LANGUAGE sql STABLE AS $$
    SELECT NULLIF(btrim(pv.value), '')::TIMESTAMP
    FROM parameter_values pv
    JOIN parameter_types pt ON pt.id = pv.parameter_type_id
    JOIN parameter_sets ps ON ps.id = pv.parameter_set_id
    WHERE ps.name = 'Default'
      AND pt.short_name = 'APP_CLEANUP_LAST_AT'
    LIMIT 1;
$$;

COMMENT ON FUNCTION app_cleanup_last_at() IS
'Р’СЂРµРјСЏ РїРѕСЃР»РµРґРЅРµР№ Р°РІС‚РѕРѕС‡РёСЃС‚РєРё РґРёСЃРєР° (parameter_values APP_CLEANUP_LAST_AT)';

-- CURRENT_TIMESTAMP is timestamptz; CALL with it must match this signature (not TIMESTAMP).
DROP PROCEDURE IF EXISTS set_app_cleanup_last_at(TIMESTAMP);
DROP PROCEDURE IF EXISTS set_app_cleanup_last_at(TIMESTAMPTZ);

CREATE OR REPLACE FUNCTION backtest_indicators_cached(p_security_id INTEGER,
    p_timeframe_id INTEGER,
    p_indicator_id INTEGER,
    p_date_from DATE,
    p_date_to DATE)
RETURNS BOOLEAN
LANGUAGE plpgsql STABLE AS $$
DECLARE
    v_tf_sec INTEGER;
    v_date_to DATE;
    v_span_days INTEGER;
    v_edge_slack INTEGER;
    v_sep_days INTEGER;
    v_min_ind DATE;
    v_max_ind DATE;
    v_min_price DATE;
    v_streak_cnt INTEGER := 0;
    v_has_two_clusters BOOLEAN := FALSE;
BEGIN
    -- Р Р°РЅСЊС€Рµ С…РІР°С‚Р°Р»Рѕ EXISTS(1 С‚РѕС‡РєР°) в†’ РґС‹СЂСЏРІС‹Р№ Stoch (С…РІРѕСЃС‚ СЃ РјР°СЏ) СЃС‡РёС‚Р°Р»СЃСЏ В«Р·Р°РєСЌС€РёСЂРѕРІР°РЅВ».
    -- РўРµРїРµСЂСЊ: в‰Ґ1 СЃРµСЂРёСЏ РёР· 3 Р±Р°СЂРѕРІ РїРѕРґСЂСЏРґ Р±РµР· РїСЂРѕРїСѓСЃРєР° С€Р°РіР° TF; РЅР° РґР»РёРЅРЅРѕРј РїРµСЂРёРѕРґРµ вЂ”
    -- РґРІРµ С‚Р°РєРёРµ СЃРµСЂРёРё СЃ СЂР°Р·РЅРµСЃРµРЅРёРµРј; РїР»СЋСЃ РєСЂР°СЏ СЂСЏРґРѕРј СЃ С†РµРЅР°РјРё/date_to.
    IF p_date_from IS NULL OR p_date_to IS NULL OR p_date_from > p_date_to THEN
        RETURN FALSE;
    END IF;

    v_date_to := LEAST(p_date_to, CURRENT_DATE);
    IF p_date_from > v_date_to THEN
        RETURN FALSE;
    END IF;

    SELECT t.sec INTO v_tf_sec FROM timeframes t WHERE t.id = p_timeframe_id;
    v_tf_sec := COALESCE(v_tf_sec, 86400);
    v_span_days := GREATEST(1, (v_date_to - p_date_from) + 1);
    v_edge_slack := GREATEST(3, LEAST(14, v_span_days / 20));
    -- Р’С‚РѕСЂСѓСЋ В«С‚СЂРѕР№РєСѓВ» С‚СЂРµР±СѓРµРј, РµСЃР»Рё РїРµСЂРёРѕРґ в‰Ґ 10 РґРЅРµР№; СЂР°Р·РЅРѕСЃ в‰€ С‡РµС‚РІРµСЂС‚СЊ РѕРєРЅР°, РјРёРЅ. 3 РґРЅСЏ.
    v_sep_days := GREATEST(3, v_span_days / 4);

    SELECT MIN(iv.dt::date), MAX(iv.dt::date)
    INTO v_min_ind, v_max_ind
    FROM indicator_values iv
    WHERE iv.security_id = p_security_id
      AND iv.timeframe_id = p_timeframe_id
      AND iv.indicator_id = p_indicator_id
      AND iv.dt::date BETWEEN p_date_from AND v_date_to;

    IF v_min_ind IS NULL THEN
        RETURN FALSE;
    END IF;

    SELECT MIN(p.dt::date)
    INTO v_min_price
    FROM prices p
    WHERE p.security_id = p_security_id
      AND p.timeframe_id = p_timeframe_id
      AND p.dt::date BETWEEN p_date_from AND v_date_to;

    -- РљРѕРЅРµС† РёРЅРґРёРєР°С‚РѕСЂР° РґРѕР»Р¶РµРЅ Р±С‹С‚СЊ СЃРІРµР¶РёРј РѕС‚РЅРѕСЃРёС‚РµР»СЊРЅРѕ РєРѕРЅС†Р° РїРµСЂРёРѕРґР° (РєР°Рє Сѓ С†РµРЅ).
    IF v_max_ind < v_date_to - v_edge_slack THEN
        RETURN FALSE;
    END IF;

    -- РЎС‚Р°СЂС‚: РЅРµ РїРѕР·Р¶Рµ РЅР°С‡Р°Р»Р° С†РµРЅРѕРІРѕР№ РёСЃС‚РѕСЂРёРё (+ slack). РќРµС‚ С†РµРЅ вЂ” РѕС‚РЅРѕСЃРёС‚РµР»СЊРЅРѕ date_from.
    IF v_min_price IS NOT NULL THEN
        IF v_min_ind > v_min_price + v_edge_slack THEN
            RETURN FALSE;
        END IF;
    ELSIF v_min_ind > p_date_from + v_edge_slack THEN
        RETURN FALSE;
    END IF;

    -- РЎРµСЂРёРё РёР· в‰Ґ3 Р±Р°СЂРѕРІ РїРѕРґСЂСЏРґ: С€Р°Рі РјРµР¶РґСѓ СЃРѕСЃРµРґСЏРјРё СЂРѕРІРЅРѕ tf_sec (Р±РµР· skip).
    WITH pts AS (
        SELECT DISTINCT iv.dt AS dt
        FROM indicator_values iv
        WHERE iv.security_id = p_security_id
          AND iv.timeframe_id = p_timeframe_id
          AND iv.indicator_id = p_indicator_id
          AND iv.dt::date BETWEEN p_date_from AND v_date_to
    ),
    ordered AS (
        SELECT
            dt,
            LAG(dt, 1) OVER (ORDER BY dt) AS prev1,
            LAG(dt, 2) OVER (ORDER BY dt) AS prev2
        FROM pts
    ),
    streaks AS (
        SELECT prev2 AS start_dt, dt AS end_dt
        FROM ordered
        WHERE prev1 IS NOT NULL
          AND prev2 IS NOT NULL
          AND prev1 = dt - make_interval(secs => v_tf_sec)
          AND prev2 = dt - make_interval(secs => v_tf_sec * 2)
    )
    SELECT COUNT(*)::INTEGER INTO v_streak_cnt FROM streaks;

    IF COALESCE(v_streak_cnt, 0) < 1 THEN
        RETURN FALSE;
    END IF;

    -- Р”Р»РёРЅРЅС‹Р№ РїРµСЂРёРѕРґ: РЅСѓР¶РЅР° РІС‚РѕСЂР°СЏ В«С‚СЂРѕР№РєР°В» СЃРїСѓСЃС‚СЏ sep_days (РµСЃР»Рё РѕРєРЅРѕ РїРѕР·РІРѕР»СЏРµС‚).
    IF v_span_days >= 10 THEN
        WITH pts AS (
            SELECT DISTINCT iv.dt AS dt
            FROM indicator_values iv
            WHERE iv.security_id = p_security_id
              AND iv.timeframe_id = p_timeframe_id
              AND iv.indicator_id = p_indicator_id
              AND iv.dt::date BETWEEN p_date_from AND v_date_to
        ),
        ordered AS (
            SELECT
                dt,
                LAG(dt, 1) OVER (ORDER BY dt) AS prev1,
                LAG(dt, 2) OVER (ORDER BY dt) AS prev2
            FROM pts
        ),
        streaks AS (
            SELECT prev2 AS start_dt
            FROM ordered
            WHERE prev1 IS NOT NULL
              AND prev2 IS NOT NULL
              AND prev1 = dt - make_interval(secs => v_tf_sec)
              AND prev2 = dt - make_interval(secs => v_tf_sec * 2)
        )
        SELECT EXISTS (
            SELECT 1
            FROM streaks a
            JOIN streaks b ON b.start_dt >= a.start_dt + make_interval(days => v_sep_days)
        ) INTO v_has_two_clusters;

        IF NOT COALESCE(v_has_two_clusters, FALSE) THEN
            RETURN FALSE;
        END IF;
    END IF;

    RETURN TRUE;
END;
$$;

COMMENT ON FUNCTION backtest_indicators_cached(INTEGER, INTEGER, INTEGER, DATE, DATE) IS
'True РµСЃР»Рё РёРЅРґРёРєР°С‚РѕСЂ РЅР° РїРµСЂРёРѕРґРµ РґРѕСЃС‚Р°С‚РѕС‡РЅРѕ РїРѕР»РЅС‹Р№: в‰Ґ3 Р±Р°СЂР° РїРѕРґСЂСЏРґ Р±РµР· skip TF; РЅР° РїРµСЂРёРѕРґРµ в‰Ґ10Рґ вЂ” РґРІРµ С‚Р°РєРёРµ СЃРµСЂРёРё СЃ СЂР°Р·РЅРµСЃРµРЅРёРµРј; РєСЂР°СЏ Сѓ С†РµРЅ/date_to. РќРµ РїСѓС‚Р°С‚СЊ СЃ EXISTS(1 С‚РѕС‡РєР°).';

CREATE OR REPLACE FUNCTION backtest_prices_cached(p_security_id INTEGER,
    p_timeframe_id INTEGER,
    p_warmup_from DATE,
    p_date_from DATE,
    p_date_to DATE,
    p_min_warmup INTEGER DEFAULT 20)
RETURNS BOOLEAN
LANGUAGE plpgsql STABLE AS $$
DECLARE
    v_tf_sec INTEGER;
    v_span_days INTEGER;
    v_in_period INTEGER;
    v_warmup_count INTEGER;
    v_min_date DATE;
    v_max_date DATE;
    v_edge_slack INTEGER;
    v_min_bars INTEGER;
    v_date_to DATE;
    v_sep_days INTEGER;
    v_streak_cnt INTEGER := 0;
    v_has_two_clusters BOOLEAN := FALSE;
BEGIN
    IF p_date_from IS NULL OR p_date_to IS NULL OR p_date_from > p_date_to THEN
        RETURN FALSE;
    END IF;

    -- Р‘СѓРґСѓС‰РёРµ РґР°С‚С‹ РІ date_to РЅРµРґРѕСЃС‚РёР¶РёРјС‹ РґР»СЏ СЂС‹РЅРєР° вЂ” РёРЅР°С‡Рµ РІРµС‡РЅС‹Р№ re-fetch T-Bank.
    v_date_to := LEAST(p_date_to, CURRENT_DATE);
    IF p_date_from > v_date_to THEN
        RETURN FALSE;
    END IF;

    SELECT t.sec INTO v_tf_sec FROM timeframes t WHERE t.id = p_timeframe_id;
    v_tf_sec := COALESCE(v_tf_sec, 86400);
    v_span_days := GREATEST(1, (v_date_to - p_date_from) + 1);
    v_edge_slack := GREATEST(3, LEAST(14, v_span_days / 20));
    -- Р’С‚РѕСЂСѓСЋ В«С‚СЂРѕР№РєСѓВ» С‚СЂРµР±СѓРµРј, РµСЃР»Рё РїРµСЂРёРѕРґ >= 10 РґРЅРµР№; СЂР°Р·РЅРѕРµ ~ С‡РµС‚РІРµСЂС‚СЊ РѕРєРЅР°, РјРёРЅ. 3 РґРЅСЏ.
    v_sep_days := GREATEST(3, v_span_days / 4);

    SELECT COUNT(*)::INTEGER, MIN(p.dt::date), MAX(p.dt::date)
    INTO v_in_period, v_min_date, v_max_date
    FROM prices p
    WHERE p.security_id = p_security_id
      AND p.timeframe_id = p_timeframe_id
      AND p.dt::date BETWEEN p_date_from AND v_date_to;

    IF v_in_period = 0 OR v_min_date IS NULL THEN
        RETURN FALSE;
    END IF;

    IF v_tf_sec >= 86400 THEN
        v_min_bars := GREATEST(5, (v_span_days * 2) / 5);
    ELSE
        v_min_bars := GREATEST(
            p_min_warmup,
            GREATEST(20, (v_span_days * 8 * 3600 / v_tf_sec / 4)::INTEGER)
        );
    END IF;

    -- РљРѕРЅРµС† РїРµСЂРёРѕРґР° РѕР±СЏР·Р°РЅ Р±С‹С‚СЊ СЃРІРµР¶РёРј вЂ” РёРЅР°С‡Рµ РґРѕРіСЂСѓР¶Р°РµРј.
    IF v_max_date < v_date_to - v_edge_slack THEN
        RETURN FALSE;
    END IF;

    -- РЎС‚Р°СЂС‚ РёСЃС‚РѕСЂРёРё: СЃС‚СЂРѕРіРёР№ РєСЂР°Р№ С‚РѕР»СЊРєРѕ РµСЃР»Рё Р±Р°СЂРѕРІ РјР°Р»Рѕ.
    -- РЈ M15 Р±СЂРѕРєРµСЂ С‡Р°СЃС‚Рѕ РѕС‚РґР°С‘С‚ РѕРєРЅРѕ РєРѕСЂРѕС‡Рµ date_from (РЅР°РїСЂ. СЃ 27.04 РїСЂРё from=01.04) вЂ”
    -- РїРѕРІС‚РѕСЂРЅС‹Р№ HTTP РЅРµ СѓРґР»РёРЅСЏРµС‚ РёСЃС‚РѕСЂРёСЋ Рё РєР°Р¶РґС‹Р№ РїСЂРѕРіРѕРЅ В«РІРёСЃРёС‚В» РЅР° load_prices.
    IF v_min_date > p_date_from + v_edge_slack
       AND v_in_period < v_min_bars THEN
        RETURN FALSE;
    END IF;

    SELECT COUNT(*)::INTEGER INTO v_warmup_count
    FROM prices p
    WHERE p.security_id = p_security_id
      AND p.timeframe_id = p_timeframe_id
      AND p.dt::date BETWEEN p_warmup_from AND v_date_to;

    IF v_warmup_count < GREATEST(p_min_warmup, 1) THEN
        RETURN FALSE;
    END IF;

    -- РќРµ РґРѕРІРµСЂСЏРµРј СЃС‹СЂРѕРјСѓ СЃС‡С‘С‚Сѓ: РѕРґРёРЅРѕС‡РЅР°СЏ В«Р·Р°РІР°Р»СЏРІС€Р°СЏСЃСЏВ» СЃРІРµС‡Р° РЅРµ РґРѕР»Р¶РЅР° РґРµР»Р°С‚СЊ СЃРµСЂРёСЋ
    -- В«Р·Р°РєСЌС€РёСЂРѕРІР°РЅРЅРѕР№В» (РёРЅР°С‡Рµ СЂРµРіСѓР» РЅРµ РґРѕРіСЂСѓР·РёС‚ РёСЃС‚РѕСЂРёСЋ Рё С‚РµСЃС‚ РїРѕР№РґС‘С‚ РЅР° РґС‹СЂСЏРІС‹С… С†РµРЅР°С…).
    -- РўСЂРµР±СѓРµРј >=1 СЃРµСЂРёСЋ РёР· 3 Р±Р°СЂРѕРІ РїРѕРґСЂСЏРґ СЃ С‚РѕС‡РЅС‹Рј С€Р°РіРѕРј TF (Р±РµР· skip), РєР°Рє Сѓ РёРЅРґРёРєР°С‚РѕСЂРѕРІ
    -- РІ backtest_indicators_cached; РЅР° РґР»РёРЅРЅРѕРј РїРµСЂРёРѕРґРµ вЂ” РґРІРµ С‚Р°РєРёРµ СЃРµСЂРёРё СЃ СЂР°Р·РЅРѕСЃРѕРј.
    WITH pts AS (
        SELECT DISTINCT p.dt AS dt
        FROM prices p
        WHERE p.security_id = p_security_id
          AND p.timeframe_id = p_timeframe_id
          AND p.dt::date BETWEEN p_date_from AND v_date_to
    ),
    ordered AS (
        SELECT
            dt,
            LAG(dt, 1) OVER (ORDER BY dt) AS prev1,
            LAG(dt, 2) OVER (ORDER BY dt) AS prev2
        FROM pts
    ),
    streaks AS (
        SELECT prev2 AS start_dt, dt AS end_dt
        FROM ordered
        WHERE prev1 IS NOT NULL
          AND prev2 IS NOT NULL
          AND prev1 = dt - make_interval(secs => v_tf_sec)
          AND prev2 = dt - make_interval(secs => v_tf_sec * 2)
    )
    SELECT COUNT(*)::INTEGER INTO v_streak_cnt FROM streaks;

    IF COALESCE(v_streak_cnt, 0) < 1 THEN
        RETURN FALSE;
    END IF;

    -- Р”Р»РёРЅРЅС‹Р№ РїРµСЂРёРѕРґ (>=10 РґРЅРµР№): РЅСѓР¶РЅР° РІС‚РѕСЂР°СЏ В«С‚СЂРѕР№РєР°В» СЃРїСѓСЃС‚СЏ sep_days (РµСЃР»Рё РѕРєРЅРѕ РїРѕР·РІРѕР»СЏРµС‚).
    IF v_span_days >= 10 THEN
        WITH pts AS (
            SELECT DISTINCT p.dt AS dt
            FROM prices p
            WHERE p.security_id = p_security_id
              AND p.timeframe_id = p_timeframe_id
              AND p.dt::date BETWEEN p_date_from AND v_date_to
        ),
        ordered AS (
            SELECT
                dt,
                LAG(dt, 1) OVER (ORDER BY dt) AS prev1,
                LAG(dt, 2) OVER (ORDER BY dt) AS prev2
            FROM pts
        ),
        streaks AS (
            SELECT prev2 AS start_dt
            FROM ordered
            WHERE prev1 IS NOT NULL
              AND prev2 IS NOT NULL
              AND prev1 = dt - make_interval(secs => v_tf_sec)
              AND prev2 = dt - make_interval(secs => v_tf_sec * 2)
        )
        SELECT EXISTS (
            SELECT 1
            FROM streaks a
            JOIN streaks b ON b.start_dt >= a.start_dt + make_interval(days => v_sep_days)
        ) INTO v_has_two_clusters;

        IF NOT COALESCE(v_has_two_clusters, FALSE) THEN
            RETURN FALSE;
        END IF;
    END IF;

    RETURN v_in_period >= v_min_bars;
END;
$$;

COMMENT ON FUNCTION backtest_prices_cached(INTEGER, INTEGER, DATE, DATE, DATE, INTEGER) IS
'True РµСЃР»Рё СЃРІРµС‡РµР№ РґРѕСЃС‚Р°С‚РѕС‡РЅРѕ РґРѕ LEAST(date_to, СЃРµРіРѕРґРЅСЏ). РџРѕР·РґРЅРёР№ СЃС‚Р°СЂС‚ РёСЃС‚РѕСЂРёРё РїСЂРё РґРѕСЃС‚Р°С‚РѕС‡РЅРѕРј С‡РёСЃР»Рµ Р±Р°СЂРѕРІ вЂ” РєСЌС€ (Р±РµР· РІРµС‡РЅРѕРіРѕ HTTP).';

CREATE OR REPLACE FUNCTION calc_ind_adx_array(p_period INTEGER,
    p_series VARCHAR,
    p_security_id INTEGER,
    p_timeframe_id INTEGER,
    p_point_count INTEGER DEFAULT 100,
    p_end_dt TIMESTAMP DEFAULT NULL)
RETURNS TABLE (dt TIMESTAMP, value NUMERIC)
LANGUAGE plpgsql STABLE AS $$
DECLARE
    v_end TIMESTAMP;
    v_bars INTEGER;
    v_dts TIMESTAMP[];
    v_highs NUMERIC[];
    v_lows NUMERIC[];
    v_closes NUMERIC[];
    v_n INTEGER;
    v_period INTEGER;
    v_ser TEXT;
    i INTEGER;
    v_start INTEGER;
    v_tr NUMERIC;
    v_plus_dm NUMERIC;
    v_minus_dm NUMERIC;
    v_atr NUMERIC := 0;
    v_plus_dm_s NUMERIC := 0;
    v_minus_dm_s NUMERIC := 0;
    v_plus_di NUMERIC;
    v_minus_di NUMERIC;
    v_dx NUMERIC;
    v_adx NUMERIC := NULL;
    v_dx_sum NUMERIC := 0;
    v_dx_n INTEGER := 0;
BEGIN
    v_ser := upper(btrim(COALESCE(p_series, 'ADX')));
    IF v_ser NOT IN ('ADX', 'PDI', 'MDI', 'VALUE') THEN
        RETURN;
    END IF;
    IF v_ser = 'VALUE' THEN v_ser := 'ADX'; END IF;
    v_period := GREATEST(COALESCE(p_period, 14), 2);

    v_end := ind_resolve_end_dt(p_security_id, p_timeframe_id, p_end_dt);
    IF v_end IS NULL THEN RETURN; END IF;
    v_bars := ind_warmup_bars(v_period * 3, p_point_count);

    SELECT array_agg(x.dt ORDER BY x.dt),
           array_agg(x.high_price ORDER BY x.dt),
           array_agg(x.low_price ORDER BY x.dt),
           array_agg(x.close_price ORDER BY x.dt),
           COUNT(*)::INTEGER
    INTO v_dts, v_highs, v_lows, v_closes, v_n
    FROM (
        SELECT p.dt, p.high_price, p.low_price, p.close_price FROM prices p
        WHERE p.security_id = p_security_id AND p.timeframe_id = p_timeframe_id AND p.dt <= v_end
        ORDER BY p.dt DESC LIMIT v_bars
    ) x;

    IF v_n IS NULL OR v_n < v_period + 2 THEN RETURN; END IF;

    v_start := GREATEST(v_period * 2, v_n - p_point_count + 1);

    FOR i IN 2 .. v_n LOOP
        v_tr := GREATEST(
            v_highs[i] - v_lows[i],
            ABS(v_highs[i] - v_closes[i - 1]),
            ABS(v_lows[i] - v_closes[i - 1])
        );
        v_plus_dm := CASE
            WHEN (v_highs[i] - v_highs[i - 1]) > (v_lows[i - 1] - v_lows[i])
                 AND (v_highs[i] - v_highs[i - 1]) > 0
            THEN v_highs[i] - v_highs[i - 1]
            ELSE 0
        END;
        v_minus_dm := CASE
            WHEN (v_lows[i - 1] - v_lows[i]) > (v_highs[i] - v_highs[i - 1])
                 AND (v_lows[i - 1] - v_lows[i]) > 0
            THEN v_lows[i - 1] - v_lows[i]
            ELSE 0
        END;

        IF i <= v_period THEN
            v_atr := v_atr + v_tr;
            v_plus_dm_s := v_plus_dm_s + v_plus_dm;
            v_minus_dm_s := v_minus_dm_s + v_minus_dm;
            IF i = v_period THEN
                v_atr := v_atr / v_period;
                v_plus_dm_s := v_plus_dm_s / v_period;
                v_minus_dm_s := v_minus_dm_s / v_period;
            END IF;
        ELSE
            v_atr := (v_atr * (v_period - 1) + v_tr) / v_period;
            v_plus_dm_s := (v_plus_dm_s * (v_period - 1) + v_plus_dm) / v_period;
            v_minus_dm_s := (v_minus_dm_s * (v_period - 1) + v_minus_dm) / v_period;
        END IF;

        IF i < v_period THEN
            CONTINUE;
        END IF;

        IF v_atr = 0 THEN
            v_plus_di := 0;
            v_minus_di := 0;
        ELSE
            v_plus_di := 100.0 * v_plus_dm_s / v_atr;
            v_minus_di := 100.0 * v_minus_dm_s / v_atr;
        END IF;

        IF (v_plus_di + v_minus_di) = 0 THEN
            v_dx := 0;
        ELSE
            v_dx := 100.0 * ABS(v_plus_di - v_minus_di) / (v_plus_di + v_minus_di);
        END IF;

        IF i < v_period * 2 THEN
            v_dx_sum := v_dx_sum + v_dx;
            v_dx_n := v_dx_n + 1;
            IF i = v_period * 2 - 1 THEN
                v_adx := v_dx_sum / GREATEST(v_dx_n, 1);
            END IF;
        ELSIF v_adx IS NOT NULL THEN
            v_adx := (v_adx * (v_period - 1) + v_dx) / v_period;
        END IF;

        IF i >= v_start AND v_adx IS NOT NULL THEN
            dt := v_dts[i];
            value := CASE v_ser
                WHEN 'ADX' THEN v_adx
                WHEN 'PDI' THEN v_plus_di
                WHEN 'MDI' THEN v_minus_di
            END;
            RETURN NEXT;
        END IF;
    END LOOP;
END;
$$;

-- ========== LINREG РєР°РЅР°Р» (mid В± DevВ·Пѓ РѕСЃС‚Р°С‚РєРѕРІ) ==========

CREATE OR REPLACE FUNCTION calc_ind_atr(p_period INTEGER,
    p_series VARCHAR,
    p_security_id INTEGER,
    p_timeframe_id INTEGER,
    p_dt TIMESTAMP,
    p_indicator_id INTEGER DEFAULT NULL)
RETURNS NUMERIC
LANGUAGE plpgsql
STABLE
AS $$
DECLARE
    v_ser TEXT := upper(btrim(COALESCE(p_series, 'ATR')));
    v_thr NUMERIC;
BEGIN
    IF v_ser = 'GROWTH5' THEN
        RETURN (
            SELECT a.value
            FROM calc_ind_atr_array(
                p_period, 'GROWTH5', p_security_id, p_timeframe_id, 1, p_dt
            ) a
            ORDER BY a.dt DESC
            LIMIT 1
        );
    END IF;

    IF v_ser = 'ATR_PCT' THEN
        RETURN (
            SELECT a.value
            FROM calc_ind_atr_array(
                p_period, 'ATR_PCT', p_security_id, p_timeframe_id, 1, p_dt
            ) a
            ORDER BY a.dt DESC
            LIMIT 1
        );
    END IF;

    IF v_ser <> 'ATR' AND p_indicator_id IS NOT NULL THEN
        v_thr := get_ind_series_threshold(p_indicator_id, p_series);
        IF v_thr IS NOT NULL THEN RETURN v_thr; END IF;
        RETURN NULL;
    END IF;

    RETURN (
        SELECT a.value
        FROM calc_ind_atr_array(
            p_period, 'ATR', p_security_id, p_timeframe_id, 1, p_dt
        ) a
        ORDER BY a.dt DESC
        LIMIT 1
    );
END;
$$;

COMMENT ON FUNCTION calc_ind_cci(INTEGER, VARCHAR, INTEGER, INTEGER, TIMESTAMP, INTEGER) IS
'РЎРєР°Р»СЏСЂ CCI РЅР° Р±Р°СЂРµ (РєР°Рє calc_ind_sma) вЂ” С‡РµСЂРµР· calc_ind_cci_array';
COMMENT ON FUNCTION calc_ind_adx(INTEGER, VARCHAR, INTEGER, INTEGER, TIMESTAMP, INTEGER) IS
'РЎРєР°Р»СЏСЂ ADX/+DI/в€’DI РЅР° Р±Р°СЂРµ вЂ” С‡РµСЂРµР· calc_ind_adx_array';
COMMENT ON FUNCTION calc_ind_linreg(INTEGER, NUMERIC, VARCHAR, INTEGER, INTEGER, TIMESTAMP, INTEGER) IS
'РЎРєР°Р»СЏСЂ LinReg-РєР°РЅР°Р»Р° РЅР° Р±Р°СЂРµ вЂ” С‡РµСЂРµР· calc_ind_linreg_array';

-- ========== SQUARE: РєРІР°РґСЂР°С‚РёС‡РЅС‹Р№ РєР°РЅР°Р» (y = b + aВ·x + cВ·xВІ; mid В± DevВ·Пѓ РѕСЃС‚Р°С‚РєРѕРІ) ==========
-- РўРµ Р¶Рµ СЃРµСЂРёРё, С‡С‚Рѕ Сѓ LINREG (MIDDLE/UPPER/LOWER/SLOPE) + C (РєРІР°РґСЂР°С‚РёС‡РЅС‹Р№ РєРѕСЌС„С„РёС†РёРµРЅС‚).
-- SLOPE = РјРіРЅРѕРІРµРЅРЅС‹Р№ РЅР°РєР»РѕРЅ РІ РєРѕРЅС†Рµ РѕРєРЅР°: a + 2В·cВ·(periodв€’1).

CREATE OR REPLACE FUNCTION calc_ind_atr_array(p_period INTEGER,
    p_series VARCHAR,
    p_security_id INTEGER,
    p_timeframe_id INTEGER,
    p_point_count INTEGER DEFAULT 100,
    p_end_dt TIMESTAMP DEFAULT NULL)
RETURNS TABLE (dt TIMESTAMP, value NUMERIC)
LANGUAGE plpgsql STABLE AS $$
DECLARE
    v_end TIMESTAMP;
    v_bars INTEGER;
    v_dts TIMESTAMP[];
    v_highs NUMERIC[];
    v_lows NUMERIC[];
    v_closes NUMERIC[];
    v_n INTEGER;
    v_atr NUMERIC;
    v_tr NUMERIC;
    v_tr_high NUMERIC;
    v_tr_low NUMERIC;
    v_tr_close NUMERIC;
    v_atr_hist NUMERIC[] := ARRAY[]::NUMERIC[];
    i INTEGER;
    v_start INTEGER;
    v_lb INTEGER := 5;
    v_prev NUMERIC;
BEGIN
    IF upper(btrim(p_series)) NOT IN ('ATR', 'ATR_PCT', 'GROWTH5') THEN
        RETURN;
    END IF;

    v_end := ind_resolve_end_dt(p_security_id, p_timeframe_id, p_end_dt);
    IF v_end IS NULL THEN RETURN; END IF;
    v_bars := ind_warmup_bars(p_period + v_lb + 5, p_point_count);

    SELECT array_agg(x.dt ORDER BY x.dt),
           array_agg(x.high_price ORDER BY x.dt),
           array_agg(x.low_price ORDER BY x.dt),
           array_agg(x.close_price ORDER BY x.dt),
           COUNT(*)::INTEGER
    INTO v_dts, v_highs, v_lows, v_closes, v_n
    FROM (
        SELECT p.dt, p.high_price, p.low_price, p.close_price FROM prices p
        WHERE p.security_id = p_security_id AND p.timeframe_id = p_timeframe_id AND p.dt <= v_end
        ORDER BY p.dt DESC LIMIT v_bars
    ) x;

    IF v_n IS NULL OR v_n < p_period + 1 THEN RETURN; END IF;

    v_atr := 0;
    v_start := GREATEST(p_period, v_n - p_point_count + 1);
    FOR i IN 2 .. v_n LOOP
        v_tr_high := v_highs[i] - v_lows[i];
        v_tr_low := ABS(v_highs[i] - v_closes[i - 1]);
        v_tr_close := ABS(v_lows[i] - v_closes[i - 1]);
        v_tr := GREATEST(v_tr_high, v_tr_low, v_tr_close);
        IF i <= p_period THEN
            v_atr := v_atr + v_tr;
            IF i = p_period THEN v_atr := v_atr / p_period; END IF;
        ELSE
            v_atr := (v_atr * (p_period - 1) + v_tr) / p_period;
        END IF;
        IF i >= p_period THEN
            v_atr_hist := array_append(v_atr_hist, v_atr);
        END IF;
        IF i >= v_start AND i >= p_period THEN
            dt := v_dts[i];
            IF upper(btrim(p_series)) = 'ATR' THEN
                value := v_atr;
            ELSIF upper(btrim(p_series)) = 'ATR_PCT' THEN
                value := CASE WHEN v_closes[i] = 0 THEN NULL ELSE v_atr / v_closes[i] * 100 END;
            ELSE
                -- GROWTH5
                IF array_length(v_atr_hist, 1) > v_lb THEN
                    v_prev := v_atr_hist[array_length(v_atr_hist, 1) - v_lb];
                    value := CASE
                        WHEN v_prev IS NULL OR v_prev = 0 THEN NULL
                        ELSE (v_atr / v_prev - 1.0) * 100.0
                    END;
                ELSE
                    value := NULL;
                END IF;
            END IF;
            IF value IS NOT NULL THEN
                RETURN NEXT;
            END IF;
        END IF;
    END LOOP;
END;
$$;

-- ========== CCI ==========

CREATE OR REPLACE FUNCTION calc_ind_bb(p_period INTEGER,
    p_std_dev NUMERIC,
    p_series VARCHAR,
    p_security_id INTEGER,
    p_timeframe_id INTEGER,
    p_dt TIMESTAMP,
    p_indicator_id INTEGER DEFAULT NULL)
RETURNS NUMERIC
LANGUAGE plpgsql
STABLE
AS $$
DECLARE
    v_middle NUMERIC;
    v_std NUMERIC;
    v_thr NUMERIC;
BEGIN
    IF p_indicator_id IS NOT NULL AND p_series NOT IN ('UPPER', 'MIDDLE', 'LOWER', 'BANDWIDTH') THEN
        v_thr := get_ind_series_threshold(p_indicator_id, p_series);
        IF v_thr IS NOT NULL THEN RETURN v_thr; END IF;
        RETURN NULL;
    END IF;

    SELECT AVG(close_price), STDDEV_SAMP(close_price)
    INTO v_middle, v_std
    FROM (
        SELECT close_price
        FROM prices
        WHERE security_id = p_security_id
          AND timeframe_id = p_timeframe_id
          AND dt <= p_dt
        ORDER BY dt DESC
        LIMIT p_period
    ) s;

    IF v_middle IS NULL THEN
        RETURN NULL;
    END IF;
    v_std := COALESCE(v_std, 0);

    RETURN CASE p_series
        WHEN 'MIDDLE' THEN v_middle
        WHEN 'UPPER' THEN v_middle + p_std_dev * v_std
        WHEN 'LOWER' THEN v_middle - p_std_dev * v_std
        WHEN 'BANDWIDTH' THEN
            CASE WHEN v_middle = 0 THEN NULL
                 ELSE (2 * p_std_dev * v_std) / v_middle * 100
            END
        ELSE NULL
    END;
END;
$$;

-- Price Channel / Donchian: UPPER = max high, LOWER = min low, MIDDLE = (U+L)/2

CREATE OR REPLACE FUNCTION calc_ind_bb_array(p_period INTEGER,
    p_std_dev NUMERIC,
    p_series VARCHAR,
    p_security_id INTEGER,
    p_timeframe_id INTEGER,
    p_point_count INTEGER DEFAULT 100,
    p_end_dt TIMESTAMP DEFAULT NULL)
RETURNS TABLE (dt TIMESTAMP, value NUMERIC)
LANGUAGE plpgsql STABLE AS $$
DECLARE
    v_end TIMESTAMP;
    v_bars INTEGER;
    v_dts TIMESTAMP[];
    v_closes NUMERIC[];
    v_n INTEGER;
    v_middle NUMERIC;
    v_std NUMERIC;
    v_sum NUMERIC;
    v_sum_sq NUMERIC;
    i INTEGER;
    j INTEGER;
    v_start INTEGER;
BEGIN
    IF p_series NOT IN ('UPPER', 'MIDDLE', 'LOWER', 'BANDWIDTH') THEN RETURN; END IF;

    v_end := ind_resolve_end_dt(p_security_id, p_timeframe_id, p_end_dt);
    IF v_end IS NULL THEN RETURN; END IF;
    v_bars := ind_warmup_bars(p_period, p_point_count);

    SELECT array_agg(x.dt ORDER BY x.dt),
           array_agg(x.close_price ORDER BY x.dt),
           COUNT(*)::INTEGER
    INTO v_dts, v_closes, v_n
    FROM (
        SELECT p.dt, p.close_price FROM prices p
        WHERE p.security_id = p_security_id AND p.timeframe_id = p_timeframe_id AND p.dt <= v_end
        ORDER BY p.dt DESC LIMIT v_bars
    ) x;

    IF v_n IS NULL OR v_n < p_period THEN RETURN; END IF;

    v_start := GREATEST(p_period, v_n - p_point_count + 1);
    FOR i IN v_start .. v_n LOOP
        v_sum := 0;
        v_sum_sq := 0;
        FOR j IN i - p_period + 1 .. i LOOP
            v_sum := v_sum + v_closes[j];
            v_sum_sq := v_sum_sq + v_closes[j] * v_closes[j];
        END LOOP;
        v_middle := v_sum / p_period;
        v_std := sqrt(GREATEST(v_sum_sq / p_period - v_middle * v_middle, 0));
        dt := v_dts[i];
        value := CASE p_series
            WHEN 'MIDDLE' THEN v_middle
            WHEN 'UPPER' THEN v_middle + p_std_dev * v_std
            WHEN 'LOWER' THEN v_middle - p_std_dev * v_std
            WHEN 'BANDWIDTH' THEN CASE WHEN v_middle = 0 THEN NULL ELSE (2 * p_std_dev * v_std) / v_middle * 100 END
        END;
        RETURN NEXT;
    END LOOP;
END;
$$;

-- ATR array

CREATE OR REPLACE FUNCTION calc_ind_cci_array(p_period INTEGER,
    p_series VARCHAR,
    p_security_id INTEGER,
    p_timeframe_id INTEGER,
    p_point_count INTEGER DEFAULT 100,
    p_end_dt TIMESTAMP DEFAULT NULL)
RETURNS TABLE (dt TIMESTAMP, value NUMERIC)
LANGUAGE plpgsql STABLE AS $$
DECLARE
    v_end TIMESTAMP;
    v_bars INTEGER;
    v_dts TIMESTAMP[];
    v_highs NUMERIC[];
    v_lows NUMERIC[];
    v_closes NUMERIC[];
    v_tp NUMERIC[];
    v_n INTEGER;
    i INTEGER;
    j INTEGER;
    v_start INTEGER;
    v_sma NUMERIC;
    v_md NUMERIC;
    v_period INTEGER;
BEGIN
    IF upper(btrim(COALESCE(p_series, 'VALUE'))) NOT IN ('VALUE', 'CCI') THEN
        RETURN;
    END IF;
    v_period := GREATEST(COALESCE(p_period, 20), 2);
    v_end := ind_resolve_end_dt(p_security_id, p_timeframe_id, p_end_dt);
    IF v_end IS NULL THEN RETURN; END IF;
    v_bars := ind_warmup_bars(v_period, p_point_count);

    SELECT array_agg(x.dt ORDER BY x.dt),
           array_agg(x.high_price ORDER BY x.dt),
           array_agg(x.low_price ORDER BY x.dt),
           array_agg(x.close_price ORDER BY x.dt),
           COUNT(*)::INTEGER
    INTO v_dts, v_highs, v_lows, v_closes, v_n
    FROM (
        SELECT p.dt, p.high_price, p.low_price, p.close_price FROM prices p
        WHERE p.security_id = p_security_id AND p.timeframe_id = p_timeframe_id AND p.dt <= v_end
        ORDER BY p.dt DESC LIMIT v_bars
    ) x;

    IF v_n IS NULL OR v_n < v_period THEN RETURN; END IF;

    v_tp := ARRAY[]::NUMERIC[];
    FOR i IN 1 .. v_n LOOP
        v_tp := array_append(v_tp, (v_highs[i] + v_lows[i] + v_closes[i]) / 3.0);
    END LOOP;

    v_start := GREATEST(v_period, v_n - p_point_count + 1);
    FOR i IN v_period .. v_n LOOP
        IF i < v_start THEN CONTINUE; END IF;
        v_sma := 0;
        FOR j IN (i - v_period + 1) .. i LOOP
            v_sma := v_sma + v_tp[j];
        END LOOP;
        v_sma := v_sma / v_period;
        v_md := 0;
        FOR j IN (i - v_period + 1) .. i LOOP
            v_md := v_md + ABS(v_tp[j] - v_sma);
        END LOOP;
        v_md := v_md / v_period;
        dt := v_dts[i];
        value := CASE
            WHEN v_md = 0 THEN 0
            ELSE (v_tp[i] - v_sma) / (0.015 * v_md)
        END;
        RETURN NEXT;
    END LOOP;
END;
$$;

