-- =====================================================================

CREATE OR REPLACE FUNCTION calc_ind_cmo_array(p_period INTEGER,
    p_series VARCHAR,
    p_security_id INTEGER,
    p_timeframe_id INTEGER,
    p_point_count INTEGER DEFAULT 100,
    p_end_dt TIMESTAMP DEFAULT NULL)
RETURNS TABLE (dt TIMESTAMP, value NUMERIC)
LANGUAGE plpgsql STABLE AS $$
DECLARE
    v_end TIMESTAMP;
    v_bars INTEGER;
    v_dts TIMESTAMP[];
    v_closes NUMERIC[];
    v_n INTEGER;
    i INTEGER;
    v_start INTEGER;
    v_period INTEGER;
    v_delta NUMERIC;
    v_sum_up NUMERIC;
    v_sum_down NUMERIC;
BEGIN
    IF upper(btrim(COALESCE(p_series, 'VALUE'))) NOT IN ('VALUE', 'CMO') THEN
        RETURN;
    END IF;
    v_period := GREATEST(COALESCE(p_period, 14), 1);
    v_end := ind_resolve_end_dt(p_security_id, p_timeframe_id, p_end_dt);
    IF v_end IS NULL THEN RETURN; END IF;
    v_bars := ind_warmup_bars(v_period, p_point_count);

    SELECT array_agg(x.dt ORDER BY x.dt),
           array_agg(x.close_price ORDER BY x.dt),
           COUNT(*)::INTEGER
    INTO v_dts, v_closes, v_n
    FROM (
        SELECT p.dt, p.close_price FROM prices p
        WHERE p.security_id = p_security_id AND p.timeframe_id = p_timeframe_id AND p.dt <= v_end
        ORDER BY p.dt DESC LIMIT v_bars
    ) x;

    -- Р”Р»СЏ CMO РЅСѓР¶РЅРѕ period РїСЂРёСЂРѕСЃС‚РѕРІ + РЅР°С‡Р°Р»СЊРЅР°СЏ С†РµРЅР° в†’ period + 1 Р±Р°СЂРѕРІ РјРёРЅРёРјСѓРј.
    IF v_n IS NULL OR v_n < (v_period + 1) THEN RETURN; END IF;

    v_start := GREATEST(v_period + 1, v_n - p_point_count + 1);
    FOR i IN (v_period + 1) .. v_n LOOP
        IF i < v_start THEN CONTINUE; END IF;
        v_sum_up := 0;
        v_sum_down := 0;
        FOR j IN (i - v_period) .. i LOOP
            v_delta := v_closes[j] - v_closes[j - 1];
            IF v_delta > 0 THEN
                v_sum_up := v_sum_up + v_delta;
            ELSE
                v_sum_down := v_sum_down + abs(v_delta);
            END IF;
        END LOOP;
        IF v_sum_down = 0 AND v_sum_up = 0 THEN
            value := 0;
        ELSE
            value := (v_sum_up - v_sum_down) / (v_sum_up + v_sum_down) * 100.0;
        END IF;
        dt := v_dts[i];
        RETURN NEXT;
    END LOOP;
END;
$$;

CREATE OR REPLACE FUNCTION calc_ind_donchian(p_period INTEGER,
    p_series VARCHAR,
    p_security_id INTEGER,
    p_timeframe_id INTEGER,
    p_dt TIMESTAMP,
    p_indicator_id INTEGER DEFAULT NULL)
RETURNS NUMERIC
LANGUAGE plpgsql
STABLE
AS $$
DECLARE
    v_upper NUMERIC;
    v_lower NUMERIC;
    v_thr NUMERIC;
BEGIN
    IF p_indicator_id IS NOT NULL AND p_series NOT IN ('UPPER', 'MIDDLE', 'LOWER') THEN
        v_thr := get_ind_series_threshold(p_indicator_id, p_series);
        IF v_thr IS NOT NULL THEN RETURN v_thr; END IF;
        RETURN NULL;
    END IF;

    SELECT MAX(high_price), MIN(low_price)
    INTO v_upper, v_lower
    FROM (
        SELECT high_price, low_price
        FROM prices
        WHERE security_id = p_security_id
          AND timeframe_id = p_timeframe_id
          AND dt < p_dt
        ORDER BY dt DESC
        LIMIT p_period
    ) s;

    IF v_upper IS NULL OR v_lower IS NULL THEN
        RETURN NULL;
    END IF;

    RETURN CASE p_series
        WHEN 'UPPER' THEN v_upper
        WHEN 'LOWER' THEN v_lower
        WHEN 'MIDDLE' THEN (v_upper + v_lower) / 2.0
        ELSE NULL
    END;
END;
$$;

CREATE OR REPLACE FUNCTION calc_ind_donchian_array(p_period INTEGER,
    p_series VARCHAR,
    p_security_id INTEGER,
    p_timeframe_id INTEGER,
    p_point_count INTEGER DEFAULT 100,
    p_end_dt TIMESTAMP DEFAULT NULL)
RETURNS TABLE (dt TIMESTAMP, value NUMERIC)
LANGUAGE plpgsql STABLE AS $$
DECLARE
    v_end TIMESTAMP;
    v_bars INTEGER;
    v_dts TIMESTAMP[];
    v_highs NUMERIC[];
    v_lows NUMERIC[];
    v_n INTEGER;
    v_upper NUMERIC;
    v_lower NUMERIC;
    i INTEGER;
    j INTEGER;
    v_start INTEGER;
BEGIN
    IF p_series NOT IN ('UPPER', 'MIDDLE', 'LOWER') THEN RETURN; END IF;

    v_end := ind_resolve_end_dt(p_security_id, p_timeframe_id, p_end_dt);
    IF v_end IS NULL THEN RETURN; END IF;
    v_bars := ind_warmup_bars(p_period, p_point_count);

    SELECT array_agg(x.dt ORDER BY x.dt),
           array_agg(x.high_price ORDER BY x.dt),
           array_agg(x.low_price ORDER BY x.dt),
           COUNT(*)::INTEGER
    INTO v_dts, v_highs, v_lows, v_n
    FROM (
        SELECT p.dt, p.high_price, p.low_price FROM prices p
        WHERE p.security_id = p_security_id AND p.timeframe_id = p_timeframe_id AND p.dt <= v_end
        ORDER BY p.dt DESC LIMIT v_bars
    ) x;

    IF v_n IS NULL OR v_n < p_period + 1 THEN RETURN; END IF;

    -- РљР°РЅР°Р» РїРѕ РџР Р•Р”Р«Р”РЈР©РРњ p_period Р±Р°СЂР°Рј (dt < С‚РµРєСѓС‰РµРіРѕ): РїСЂРѕР±РѕР№ СЃСЂР°РІРЅРёРІР°РµС‚СЃСЏ
    -- СЃ СѓР¶Рµ СЃС„РѕСЂРјРёСЂРѕРІР°РЅРЅС‹Рј РєР°РЅР°Р»РѕРј, Р° РЅРµ СЃ Р±Р°СЂРѕРј, РІ РєРѕС‚РѕСЂРѕРј РѕРЅ СЃС‡РёС‚Р°РµС‚СЃСЏ.
    v_start := GREATEST(p_period + 1, v_n - p_point_count + 1);
    FOR i IN v_start .. v_n LOOP
        v_upper := NULL;
        v_lower := NULL;
        FOR j IN i - p_period .. i - 1 LOOP
            v_upper := CASE WHEN v_upper IS NULL OR v_highs[j] > v_upper THEN v_highs[j] ELSE v_upper END;
            v_lower := CASE WHEN v_lower IS NULL OR v_lows[j] < v_lower THEN v_lows[j] ELSE v_lower END;
        END LOOP;
        dt := v_dts[i];
        value := CASE p_series
            WHEN 'UPPER' THEN v_upper
            WHEN 'LOWER' THEN v_lower
            WHEN 'MIDDLE' THEN (v_upper + v_lower) / 2.0
        END;
        RETURN NEXT;
    END LOOP;
END;
$$;

-- ATR

CREATE OR REPLACE FUNCTION calc_ind_ema(p_period INTEGER,
    p_series VARCHAR,
    p_security_id INTEGER,
    p_timeframe_id INTEGER,
    p_dt TIMESTAMP,
    p_indicator_id INTEGER DEFAULT NULL)
RETURNS NUMERIC
LANGUAGE plpgsql
STABLE
AS $$
DECLARE
    v_thr NUMERIC;
    v_ema NUMERIC;
    v_mult NUMERIC;
    r RECORD;
BEGIN
    IF p_series IS NOT NULL AND p_series <> 'VALUE' AND p_indicator_id IS NOT NULL THEN
        v_thr := get_ind_series_threshold(p_indicator_id, p_series);
        IF v_thr IS NOT NULL THEN RETURN v_thr; END IF;
        RETURN NULL;
    END IF;

    v_mult := 2.0 / (p_period + 1);
    v_ema := NULL;
    FOR r IN
        SELECT close_price
        FROM prices
        WHERE security_id = p_security_id
          AND timeframe_id = p_timeframe_id
          AND dt <= p_dt
        ORDER BY dt
    LOOP
        IF v_ema IS NULL THEN
            v_ema := r.close_price;
        ELSE
            v_ema := (r.close_price - v_ema) * v_mult + v_ema;
        END IF;
    END LOOP;
    RETURN v_ema;
END;
$$;

-- MACD

CREATE OR REPLACE FUNCTION calc_ind_ema_array(p_period INTEGER,
    p_series VARCHAR,
    p_security_id INTEGER,
    p_timeframe_id INTEGER,
    p_point_count INTEGER DEFAULT 100,
    p_end_dt TIMESTAMP DEFAULT NULL)
RETURNS TABLE (dt TIMESTAMP, value NUMERIC)
LANGUAGE plpgsql STABLE AS $$
DECLARE
    v_end TIMESTAMP;
    v_bars INTEGER;
    v_dts TIMESTAMP[];
    v_closes NUMERIC[];
    v_n INTEGER;
    v_mult NUMERIC;
    v_ema NUMERIC;
    i INTEGER;
    v_start INTEGER;
BEGIN
    IF p_series IS NOT NULL AND p_series <> 'VALUE' THEN RETURN; END IF;

    v_end := ind_resolve_end_dt(p_security_id, p_timeframe_id, p_end_dt);
    IF v_end IS NULL THEN RETURN; END IF;
    v_bars := ind_warmup_bars(p_period, p_point_count);
    v_mult := 2.0 / (p_period + 1);

    SELECT array_agg(x.dt ORDER BY x.dt),
           array_agg(x.close_price ORDER BY x.dt),
           COUNT(*)::INTEGER
    INTO v_dts, v_closes, v_n
    FROM (
        SELECT p.dt, p.close_price FROM prices p
        WHERE p.security_id = p_security_id AND p.timeframe_id = p_timeframe_id AND p.dt <= v_end
        ORDER BY p.dt DESC LIMIT v_bars
    ) x;

    IF v_n IS NULL OR v_n < 1 THEN RETURN; END IF;

    v_ema := v_closes[1];
    v_start := GREATEST(2, v_n - p_point_count + 1);
    FOR i IN 2 .. v_n LOOP
        v_ema := (v_closes[i] - v_ema) * v_mult + v_ema;
        IF i >= GREATEST(p_period, v_start) THEN
            dt := v_dts[i];
            value := v_ema;
            RETURN NEXT;
        END IF;
    END LOOP;
END;
$$;

-- MACD array (РѕРґРёРЅ РїСЂРѕС…РѕРґ в†’ MACD / SIGNAL / HISTOGRAM)

CREATE OR REPLACE FUNCTION calc_ind_linreg(p_period INTEGER,
    p_std_dev NUMERIC,
    p_series VARCHAR,
    p_security_id INTEGER,
    p_timeframe_id INTEGER,
    p_dt TIMESTAMP,
    p_indicator_id INTEGER DEFAULT NULL)
RETURNS NUMERIC
LANGUAGE plpgsql
STABLE
AS $$
DECLARE
    v_ser TEXT := upper(btrim(COALESCE(p_series, 'MIDDLE')));
    v_lv RECORD;
BEGIN
    IF v_ser = 'VALUE' THEN
        v_ser := 'MIDDLE';
    END IF;
    SELECT * INTO v_lv
    FROM calc_ind_linreg_levels_at(
        p_period, COALESCE(p_std_dev, 2.0),
        p_security_id, p_timeframe_id, p_dt
    );
    IF NOT FOUND THEN
        RETURN NULL;
    END IF;
    RETURN CASE v_ser
        WHEN 'MIDDLE' THEN v_lv.middle
        WHEN 'UPPER' THEN v_lv.upper
        WHEN 'LOWER' THEN v_lv.lower
        WHEN 'SLOPE' THEN v_lv.slope
        ELSE v_lv.middle
    END;
END;
$$;

-- ATR: СЃРµСЂРёСЏ GROWTH5 С‡РµСЂРµР· array (СЃС‚Р°СЂС‹Р№ scalar СѓРјРµР» С‚РѕР»СЊРєРѕ ATR / ATR_PCT)

CREATE OR REPLACE FUNCTION calc_ind_linreg_array(p_period INTEGER,
    p_std_dev NUMERIC,
    p_series VARCHAR,
    p_security_id INTEGER,
    p_timeframe_id INTEGER,
    p_point_count INTEGER DEFAULT 100,
    p_end_dt TIMESTAMP DEFAULT NULL)
RETURNS TABLE (dt TIMESTAMP, value NUMERIC)
LANGUAGE plpgsql STABLE AS $$
DECLARE
    v_end TIMESTAMP;
    v_bars INTEGER;
    v_dts TIMESTAMP[];
    v_closes NUMERIC[];
    v_n INTEGER;
    v_period INTEGER;
    v_dev NUMERIC;
    v_ser TEXT;
    i INTEGER;
    j INTEGER;
    v_start INTEGER;
    v_sum_x NUMERIC;
    v_sum_y NUMERIC;
    v_sum_xy NUMERIC;
    v_sum_xx NUMERIC;
    v_slope NUMERIC;
    v_intercept NUMERIC;
    v_mid NUMERIC;
    v_var NUMERIC;
    v_std NUMERIC;
    v_pred NUMERIC;
    n NUMERIC;
BEGIN
    v_ser := upper(btrim(COALESCE(p_series, 'VALUE')));
    IF v_ser NOT IN ('VALUE', 'MIDDLE', 'UPPER', 'LOWER', 'SLOPE') THEN
        RETURN;
    END IF;
    IF v_ser = 'VALUE' THEN v_ser := 'MIDDLE'; END IF;
    v_period := GREATEST(COALESCE(p_period, 20), 3);
    v_dev := GREATEST(COALESCE(p_std_dev, 2.0), 0.1);

    v_end := ind_resolve_end_dt(p_security_id, p_timeframe_id, p_end_dt);
    IF v_end IS NULL THEN RETURN; END IF;
    v_bars := ind_warmup_bars(v_period, p_point_count);

    SELECT array_agg(x.dt ORDER BY x.dt),
           array_agg(x.close_price ORDER BY x.dt),
           COUNT(*)::INTEGER
    INTO v_dts, v_closes, v_n
    FROM (
        SELECT p.dt, p.close_price FROM prices p
        WHERE p.security_id = p_security_id AND p.timeframe_id = p_timeframe_id AND p.dt <= v_end
        ORDER BY p.dt DESC LIMIT v_bars
    ) x;

    IF v_n IS NULL OR v_n < v_period THEN RETURN; END IF;

    v_start := GREATEST(v_period, v_n - p_point_count + 1);
    n := v_period;

    FOR i IN v_period .. v_n LOOP
        IF i < v_start THEN CONTINUE; END IF;
        v_sum_x := 0;
        v_sum_y := 0;
        v_sum_xy := 0;
        v_sum_xx := 0;
        FOR j IN 0 .. (v_period - 1) LOOP
            -- x = 0..period-1 РЅР° РѕРєРЅРµ, y = close
            v_sum_x := v_sum_x + j;
            v_sum_y := v_sum_y + v_closes[i - v_period + 1 + j];
            v_sum_xy := v_sum_xy + j * v_closes[i - v_period + 1 + j];
            v_sum_xx := v_sum_xx + j * j;
        END LOOP;
        v_slope := (n * v_sum_xy - v_sum_x * v_sum_y) / NULLIF(n * v_sum_xx - v_sum_x * v_sum_x, 0);
        v_intercept := (v_sum_y - v_slope * v_sum_x) / n;
        v_mid := v_intercept + v_slope * (v_period - 1);

        v_var := 0;
        FOR j IN 0 .. (v_period - 1) LOOP
            v_pred := v_intercept + v_slope * j;
            v_var := v_var + power(v_closes[i - v_period + 1 + j] - v_pred, 2);
        END LOOP;
        v_std := sqrt(v_var / n);

        dt := v_dts[i];
        value := CASE v_ser
            WHEN 'MIDDLE' THEN v_mid
            WHEN 'UPPER' THEN v_mid + v_dev * v_std
            WHEN 'LOWER' THEN v_mid - v_dev * v_std
            WHEN 'SLOPE' THEN v_slope
        END;
        RETURN NEXT;
    END LOOP;
END;
$$;

