CREATE OR REPLACE FUNCTION calc_ind_soldiers_array(p_period INTEGER,
    p_series VARCHAR,
    p_security_id INTEGER,
    p_timeframe_id INTEGER,
    p_point_count INTEGER DEFAULT 100,
    p_end_dt TIMESTAMP DEFAULT NULL)
RETURNS TABLE (dt TIMESTAMP, value NUMERIC)
LANGUAGE plpgsql STABLE AS $$
DECLARE
    v_end TIMESTAMP;
    v_bars INTEGER;
    v_dts TIMESTAMP[];
    v_opens NUMERIC[];
    v_closes NUMERIC[];
    v_n INTEGER;
    v_soldiers INTEGER;
    v_start INTEGER;
    i INTEGER;
    j INTEGER;
    v_bull BOOLEAN;
    v_bear BOOLEAN;
BEGIN
    IF upper(btrim(COALESCE(p_series, 'VALUE'))) NOT IN ('VALUE', 'SOLDIERS') THEN
        RETURN;
    END IF;

    v_soldiers := GREATEST(COALESCE(p_period, 3), 1);
    v_end := ind_resolve_end_dt(p_security_id, p_timeframe_id, p_end_dt);
    IF v_end IS NULL THEN RETURN; END IF;
    v_bars := ind_warmup_bars(v_soldiers, p_point_count);

    SELECT array_agg(x.dt ORDER BY x.dt),
           array_agg(x.open_price ORDER BY x.dt),
           array_agg(x.close_price ORDER BY x.dt),
           COUNT(*)::INTEGER
    INTO v_dts, v_opens, v_closes, v_n
    FROM (
        SELECT p.dt, p.open_price, p.close_price FROM prices p
        WHERE p.security_id = p_security_id AND p.timeframe_id = p_timeframe_id AND p.dt <= v_end
        ORDER BY p.dt DESC LIMIT v_bars
    ) x;

    IF v_n IS NULL OR v_n < v_soldiers THEN RETURN; END IF;

    v_start := GREATEST(v_soldiers, v_n - COALESCE(p_point_count, 100) + 1);
    FOR i IN v_start .. v_n LOOP
        v_bull := TRUE;
        v_bear := TRUE;
        FOR j IN (i - v_soldiers + 1) .. i LOOP
            -- РўРµР»Рѕ СЃРІРµС‡Рё: Р±С‹С‡СЊСЏ Open < Close, РјРµРґРІРµР¶СЊСЏ Open > Close (РґРѕРґР¶Рё РЅРµ РїРѕРґС…РѕРґРёС‚).
            IF v_opens[j] >= v_closes[j] THEN v_bull := FALSE; END IF;
            IF v_opens[j] <= v_closes[j] THEN v_bear := FALSE; END IF;

            -- Р”Р»СЏ 2-Р№ Рё РїРѕСЃР»РµРґСѓСЋС‰РёС… СЃРІРµС‡РµР№: Open РІРЅСѓС‚СЂРё С‚РµР»Р° РїСЂРµРґС‹РґСѓС‰РµР№ Рё Close РґР°Р»СЊС€Рµ.
            IF j > i - v_soldiers + 1 THEN
                IF NOT (v_opens[j] > LEAST(v_opens[j - 1], v_closes[j - 1])
                    AND v_opens[j] < GREATEST(v_opens[j - 1], v_closes[j - 1])) THEN
                    v_bull := FALSE;
                    v_bear := FALSE;
                END IF;
                IF v_closes[j] <= v_closes[j - 1] THEN v_bull := FALSE; END IF;
                IF v_closes[j] >= v_closes[j - 1] THEN v_bear := FALSE; END IF;
            END IF;

            IF NOT v_bull AND NOT v_bear THEN EXIT; END IF;
        END LOOP;

        dt := v_dts[i];
        value := CASE WHEN v_bull THEN 1 WHEN v_bear THEN -1 ELSE 0 END;
        RETURN NEXT;
    END LOOP;
END;
$$;

COMMENT ON FUNCTION calc_ind_soldiers_array(INTEGER, VARCHAR, INTEGER, INTEGER, INTEGER, TIMESTAMP) IS
'РџР°С‚С‚РµСЂРЅ В«N СЃРѕР»РґР°С‚В»: +1 Р±С‹С‡СЊРё N СЃРІРµС‡РµР№ (Open<Close, Open СЃР»РµРґСѓСЋС‰РµР№ РІРЅСѓС‚СЂРё С‚РµР»Р° РїСЂРµРґС‹РґСѓС‰РµР№, Close РІС‹С€Рµ), в€’1 РјРµРґРІРµР¶СЊРё (Р·РµСЂРєР°Р»СЊРЅРѕ), 0 вЂ” РЅРµС‚ РїР°С‚С‚РµСЂРЅР°; p_period = С‡РёСЃР»Рѕ СЃРѕР»РґР°С‚.';

CREATE OR REPLACE FUNCTION calc_ind_square_array(p_period INTEGER,
    p_std_dev NUMERIC,
    p_series VARCHAR,
    p_security_id INTEGER,
    p_timeframe_id INTEGER,
    p_point_count INTEGER DEFAULT 100,
    p_end_dt TIMESTAMP DEFAULT NULL)
RETURNS TABLE (dt TIMESTAMP, value NUMERIC)
LANGUAGE plpgsql STABLE AS $$
DECLARE
    v_end TIMESTAMP;
    v_bars INTEGER;
    v_dts TIMESTAMP[];
    v_closes NUMERIC[];
    v_n INTEGER;
    v_period INTEGER;
    v_dev NUMERIC;
    v_ser TEXT;
    i INTEGER;
    j INTEGER;
    x NUMERIC;
    y NUMERIC;
    v_start INTEGER;
    s0 NUMERIC;
    s1 NUMERIC;
    s2 NUMERIC;
    s3 NUMERIC;
    s4 NUMERIC;
    sy NUMERIC;
    sxy NUMERIC;
    sx2y NUMERIC;
    det NUMERIC;
    det_b NUMERIC;
    det_a NUMERIC;
    det_c NUMERIC;
    v_b NUMERIC;
    v_a NUMERIC;
    v_c NUMERIC;
    v_mid NUMERIC;
    v_var NUMERIC;
    v_std NUMERIC;
    v_pred NUMERIC;
    v_x_end NUMERIC;
BEGIN
    v_ser := upper(btrim(COALESCE(p_series, 'VALUE')));
    IF v_ser NOT IN ('VALUE', 'MIDDLE', 'UPPER', 'LOWER', 'SLOPE', 'C') THEN
        RETURN;
    END IF;
    IF v_ser = 'VALUE' THEN v_ser := 'MIDDLE'; END IF;
    -- РњРёРЅРёРјСѓРј 3 С‚РѕС‡РєРё РґР»СЏ С‚СЂС‘С… РєРѕСЌС„С„РёС†РёРµРЅС‚РѕРІ (b, a, c).
    v_period := GREATEST(COALESCE(p_period, 20), 3);
    v_dev := GREATEST(COALESCE(p_std_dev, 2.0), 0.1);

    v_end := ind_resolve_end_dt(p_security_id, p_timeframe_id, p_end_dt);
    IF v_end IS NULL THEN RETURN; END IF;
    v_bars := ind_warmup_bars(v_period, p_point_count);

    SELECT array_agg(x.dt ORDER BY x.dt),
           array_agg(x.close_price ORDER BY x.dt),
           COUNT(*)::INTEGER
    INTO v_dts, v_closes, v_n
    FROM (
        SELECT p.dt, p.close_price FROM prices p
        WHERE p.security_id = p_security_id AND p.timeframe_id = p_timeframe_id AND p.dt <= v_end
        ORDER BY p.dt DESC LIMIT v_bars
    ) x;

    IF v_n IS NULL OR v_n < v_period THEN RETURN; END IF;

    v_start := GREATEST(v_period, v_n - p_point_count + 1);
    s0 := v_period;
    v_x_end := v_period - 1;

    FOR i IN v_period .. v_n LOOP
        IF i < v_start THEN CONTINUE; END IF;

        s1 := 0; s2 := 0; s3 := 0; s4 := 0;
        sy := 0; sxy := 0; sx2y := 0;
        FOR j IN 0 .. (v_period - 1) LOOP
            x := j;
            y := v_closes[i - v_period + 1 + j];
            s1 := s1 + x;
            s2 := s2 + x * x;
            s3 := s3 + x * x * x;
            s4 := s4 + x * x * x * x;
            sy := sy + y;
            sxy := sxy + x * y;
            sx2y := sx2y + x * x * y;
        END LOOP;

        -- РќРѕСЂРјР°Р»СЊРЅС‹Рµ СѓСЂР°РІРЅРµРЅРёСЏ: [s0 s1 s2; s1 s2 s3; s2 s3 s4] В· [b;a;c] = [sy;sxy;sx2y]
        det := s0 * (s2 * s4 - s3 * s3)
             - s1 * (s1 * s4 - s2 * s3)
             + s2 * (s1 * s3 - s2 * s2);
        IF det IS NULL OR abs(det) < 1e-18 THEN
            CONTINUE;
        END IF;

        det_b := sy * (s2 * s4 - s3 * s3)
               - s1 * (sxy * s4 - s3 * sx2y)
               + s2 * (sxy * s3 - s2 * sx2y);
        det_a := s0 * (sxy * s4 - s3 * sx2y)
               - sy * (s1 * s4 - s2 * s3)
               + s2 * (s1 * sx2y - s2 * sxy);
        det_c := s0 * (s2 * sx2y - s3 * sxy)
               - s1 * (s1 * sx2y - s2 * sxy)
               + sy * (s1 * s3 - s2 * s2);

        v_b := det_b / det;
        v_a := det_a / det;
        v_c := det_c / det;
        v_mid := v_b + v_a * v_x_end + v_c * v_x_end * v_x_end;

        v_var := 0;
        FOR j IN 0 .. (v_period - 1) LOOP
            x := j;
            v_pred := v_b + v_a * x + v_c * x * x;
            v_var := v_var + power(v_closes[i - v_period + 1 + j] - v_pred, 2);
        END LOOP;
        v_std := sqrt(v_var / s0);

        dt := v_dts[i];
        value := CASE v_ser
            WHEN 'MIDDLE' THEN v_mid
            WHEN 'UPPER' THEN v_mid + v_dev * v_std
            WHEN 'LOWER' THEN v_mid - v_dev * v_std
            WHEN 'SLOPE' THEN v_a + 2 * v_c * v_x_end
            WHEN 'C' THEN v_c
        END;
        RETURN NEXT;
    END LOOP;
END;
$$;

COMMENT ON FUNCTION calc_ind_square_array(INTEGER, NUMERIC, VARCHAR, INTEGER, INTEGER, INTEGER, TIMESTAMP) IS
'РљРІР°РґСЂР°С‚РёС‡РЅР°СЏ СЂРµРіСЂРµСЃСЃРёСЏ РїРѕ close (b+aВ·x+cВ·xВІ): MIDDLE/UPPER/LOWER/SLOPE/C (РєР°РЅР°Р» DevВ·Пѓ РѕСЃС‚Р°С‚РєРѕРІ)';

CREATE OR REPLACE FUNCTION calc_ind_stoch(p_k_period INTEGER,
    p_d_period INTEGER,
    p_smooth INTEGER,
    p_series VARCHAR,
    p_security_id INTEGER,
    p_timeframe_id INTEGER,
    p_dt TIMESTAMP,
    p_indicator_id INTEGER DEFAULT NULL)
RETURNS NUMERIC
LANGUAGE plpgsql
STABLE
AS $$
DECLARE
    v_highs NUMERIC[];
    v_lows NUMERIC[];
    v_closes NUMERIC[];
    v_idx INTEGER;
    v_k_values NUMERIC[] := ARRAY[]::NUMERIC[];
    v_stoch_k NUMERIC;
    v_stoch_d NUMERIC;
    i INTEGER;
    j INTEGER;
    v_lowest NUMERIC;
    v_highest NUMERIC;
    v_sum NUMERIC;
    v_thr NUMERIC;
BEGIN
    IF p_indicator_id IS NOT NULL AND p_series IN ('OVERBOUGHT', 'OVERSOLD') THEN
        v_thr := get_ind_series_threshold(p_indicator_id, p_series);
        IF v_thr IS NOT NULL THEN RETURN v_thr; END IF;
    END IF;

    SELECT
        array_agg(high_price ORDER BY dt),
        array_agg(low_price ORDER BY dt),
        array_agg(close_price ORDER BY dt),
        COUNT(*)
    INTO v_highs, v_lows, v_closes, v_idx
    FROM prices
    WHERE security_id = p_security_id
      AND timeframe_id = p_timeframe_id
      AND dt <= p_dt;

    IF v_idx IS NULL OR v_idx < p_k_period THEN
        RETURN NULL;
    END IF;

    FOR i IN p_k_period .. v_idx LOOP
        v_lowest := v_lows[i];
        v_highest := v_highs[i];
        FOR j IN i - p_k_period + 1 .. i LOOP
            IF v_lows[j] < v_lowest THEN v_lowest := v_lows[j]; END IF;
            IF v_highs[j] > v_highest THEN v_highest := v_highs[j]; END IF;
        END LOOP;
        IF v_highest = v_lowest THEN
            v_stoch_k := 50;
        ELSE
            v_stoch_k := (v_closes[i] - v_lowest) / (v_highest - v_lowest) * 100;
        END IF;
        v_k_values := array_append(v_k_values, v_stoch_k);
    END LOOP;

    IF array_length(v_k_values, 1) IS NULL THEN
        RETURN NULL;
    END IF;

    v_stoch_k := v_k_values[array_length(v_k_values, 1)];

    IF p_series = 'K' THEN
        RETURN v_stoch_k;
    END IF;

    IF p_series = 'D' THEN
        v_sum := 0;
        FOR i IN GREATEST(1, array_length(v_k_values, 1) - p_d_period + 1) .. array_length(v_k_values, 1) LOOP
            v_sum := v_sum + v_k_values[i];
        END LOOP;
        RETURN v_sum / LEAST(p_d_period, array_length(v_k_values, 1));
    END IF;

    RETURN NULL;
END;
$$;

-- ============================================
-- РњР°СЃСЃРёРІРЅС‹Рµ С„СѓРЅРєС†РёРё РёРЅРґРёРєР°С‚РѕСЂРѕРІ (РѕРґРёРЅ РїСЂРѕС…РѕРґ РїРѕ С†РµРЅР°Рј)
-- РЎРёРіРЅР°С‚СѓСЂР°: (РїР°СЂР°РјРµС‚СЂС‹ РёРЅРґРёРєР°С‚РѕСЂР°вЂ¦, series, security_id, timeframe_id, point_count, end_dt)
-- Р’РѕР·РІСЂР°С‰Р°РµС‚ TABLE(dt, value) вЂ” РїРѕСЃР»РµРґРЅРёРµ point_count С‚РѕС‡РµРє РґРѕ end_dt
-- ============================================

CREATE OR REPLACE FUNCTION calc_ind_stoch_array(p_k_period INTEGER,
    p_d_period INTEGER,
    p_smooth INTEGER,
    p_series VARCHAR,
    p_security_id INTEGER,
    p_timeframe_id INTEGER,
    p_point_count INTEGER DEFAULT 100,
    p_end_dt TIMESTAMP DEFAULT NULL)
RETURNS TABLE (dt TIMESTAMP, value NUMERIC)
LANGUAGE plpgsql STABLE AS $$
DECLARE
    v_end TIMESTAMP;
    v_bars INTEGER;
    v_dts TIMESTAMP[];
    v_highs NUMERIC[];
    v_lows NUMERIC[];
    v_closes NUMERIC[];
    v_n INTEGER;
    v_k_values NUMERIC[];
    v_stoch_k NUMERIC;
    v_stoch_d NUMERIC;
    i INTEGER;
    j INTEGER;
    v_lowest NUMERIC;
    v_highest NUMERIC;
    v_sum NUMERIC;
    v_start INTEGER;
BEGIN
    IF p_series NOT IN ('K', 'D') THEN RETURN; END IF;

    v_end := ind_resolve_end_dt(p_security_id, p_timeframe_id, p_end_dt);
    IF v_end IS NULL THEN RETURN; END IF;
    v_bars := ind_warmup_bars(p_k_period + p_d_period, p_point_count);

    SELECT array_agg(x.dt ORDER BY x.dt),
           array_agg(x.high_price ORDER BY x.dt),
           array_agg(x.low_price ORDER BY x.dt),
           array_agg(x.close_price ORDER BY x.dt),
           COUNT(*)::INTEGER
    INTO v_dts, v_highs, v_lows, v_closes, v_n
    FROM (
        SELECT p.dt, p.high_price, p.low_price, p.close_price FROM prices p
        WHERE p.security_id = p_security_id AND p.timeframe_id = p_timeframe_id AND p.dt <= v_end
        ORDER BY p.dt DESC LIMIT v_bars
    ) x;

    IF v_n IS NULL OR v_n < p_k_period THEN RETURN; END IF;

    v_k_values := ARRAY[]::NUMERIC[];
    FOR i IN p_k_period .. v_n LOOP
        v_lowest := v_lows[i];
        v_highest := v_highs[i];
        FOR j IN i - p_k_period + 1 .. i LOOP
            IF v_lows[j] < v_lowest THEN v_lowest := v_lows[j]; END IF;
            IF v_highs[j] > v_highest THEN v_highest := v_highs[j]; END IF;
        END LOOP;
        IF v_highest = v_lowest THEN v_stoch_k := 50;
        ELSE v_stoch_k := (v_closes[i] - v_lowest) / (v_highest - v_lowest) * 100;
        END IF;
        v_k_values := array_append(v_k_values, v_stoch_k);
    END LOOP;

    v_start := GREATEST(1, array_length(v_k_values, 1) - p_point_count + 1);
    FOR i IN v_start .. array_length(v_k_values, 1) LOOP
        dt := v_dts[p_k_period + i - 1];
        IF p_series = 'K' THEN
            value := v_k_values[i];
            RETURN NEXT;
        ELSE
            v_sum := 0;
            FOR j IN GREATEST(1, i - p_d_period + 1) .. i LOOP
                v_sum := v_sum + v_k_values[j];
            END LOOP;
            value := v_sum / LEAST(p_d_period, i);
            RETURN NEXT;
        END IF;
    END LOOP;
END;
$$;

-- ============================================
-- РњРЅРѕРіРѕС‡Р»РµРЅРЅС‹Рµ РёРЅРґРёРєР°С‚РѕСЂС‹: РїР°СЂСЃРёРЅРі Рё РІС‹С‡РёСЃР»РµРЅРёРµ
-- РЎРёРЅС‚Р°РєСЃРёСЃ РїРѕ MultiLogic PolynomialIndicators:
--   pp oo hh ll vv вЂ” OHLCV; (a; b; c) вЂ” СЏРґСЂРѕ; * вЂ” СЃРІС‘СЂС‚РєР°; # /# вЂ” РїРѕРєРѕРјРїРѕРЅРµРЅС‚РЅРѕ; @CODE вЂ” РёРЅРґРёРєР°С‚РѕСЂ
-- ============================================

CREATE OR REPLACE FUNCTION calc_poly_formula_array(p_formula TEXT,
    p_series VARCHAR,
    p_security_id INTEGER,
    p_timeframe_id INTEGER,
    p_point_count INTEGER DEFAULT 100,
    p_end_dt TIMESTAMP DEFAULT NULL,
    p_period INTEGER DEFAULT NULL,
    p_fast_period INTEGER DEFAULT NULL,
    p_slow_period INTEGER DEFAULT NULL,
    p_signal_period INTEGER DEFAULT NULL,
    p_std_dev NUMERIC DEFAULT NULL,
    p_k_period INTEGER DEFAULT NULL,
    p_d_period INTEGER DEFAULT NULL,
    p_smooth INTEGER DEFAULT NULL)
RETURNS TABLE (dt TIMESTAMP, value NUMERIC)
LANGUAGE plpgsql STABLE AS $$
DECLARE
    v_end TIMESTAMP;
    v_bars INTEGER;
    v_dts TIMESTAMP[];
    v_ast JSONB;
    v_ctx JSONB;
    v_values NUMERIC[];
    v_n INTEGER;
    v_start INTEGER;
    i INTEGER;
BEGIN
    IF p_series IS NOT NULL AND btrim(p_series) = '' THEN
        RETURN;
    END IF;

    v_end := ind_resolve_end_dt(p_security_id, p_timeframe_id, p_end_dt);
    IF v_end IS NULL THEN RETURN; END IF;

    v_bars := poly_formula_warmup_bars(p_formula, COALESCE(p_period, 14), p_point_count);

    v_dts := poly_load_market_dts(p_security_id, p_timeframe_id, v_end, v_bars);
    v_n := COALESCE(array_length(v_dts, 1), 0);
    IF v_n = 0 THEN RETURN; END IF;

    v_ctx := jsonb_build_object(
        'security_id', p_security_id,
        'timeframe_id', p_timeframe_id,
        'end_dt', to_char(v_end, 'YYYY-MM-DD HH24:MI:SS'),
        'bars', v_bars,
        'param_period', p_period,
        'param_fast_period', p_fast_period,
        'param_slow_period', p_slow_period,
        'param_signal_period', p_signal_period,
        'param_std_dev', p_std_dev,
        'param_k_period', p_k_period,
        'param_d_period', p_d_period,
        'param_smooth', p_smooth,
        'dts', to_jsonb(v_dts)
    );

    IF position('pp' IN lower(btrim(p_formula))) > 0
       OR position('sma' IN lower(btrim(p_formula))) > 0
       OR position('ema' IN lower(btrim(p_formula))) > 0
       OR position('ww' IN lower(btrim(p_formula))) > 0 THEN
        v_ctx := v_ctx || jsonb_build_object(
            'm_pp', to_jsonb(poly_load_market_array('pp', p_security_id, p_timeframe_id, v_end, v_bars))
        );
    END IF;
    IF position('oo' IN lower(btrim(p_formula))) > 0 THEN
        v_ctx := v_ctx || jsonb_build_object(
            'm_oo', to_jsonb(poly_load_market_array('oo', p_security_id, p_timeframe_id, v_end, v_bars))
        );
    END IF;
    IF position('hh' IN lower(btrim(p_formula))) > 0 THEN
        v_ctx := v_ctx || jsonb_build_object(
            'm_hh', to_jsonb(poly_load_market_array('hh', p_security_id, p_timeframe_id, v_end, v_bars))
        );
    END IF;
    IF position('ll' IN lower(btrim(p_formula))) > 0 THEN
        v_ctx := v_ctx || jsonb_build_object(
            'm_ll', to_jsonb(poly_load_market_array('ll', p_security_id, p_timeframe_id, v_end, v_bars))
        );
    END IF;
    IF position('vv' IN lower(btrim(p_formula))) > 0 THEN
        v_ctx := v_ctx || jsonb_build_object(
            'm_vv', to_jsonb(poly_load_market_array('vv', p_security_id, p_timeframe_id, v_end, v_bars))
        );
    END IF;

    v_ast := poly_parse(p_formula);
    v_values := poly_eval_node(v_ast, v_ctx);
    v_n := LEAST(COALESCE(array_length(v_values, 1), 0), COALESCE(array_length(v_dts, 1), 0));
    IF v_n = 0 THEN RETURN; END IF;

    v_start := GREATEST(1, v_n - COALESCE(p_point_count, 100) + 1);
    FOR i IN v_start .. v_n LOOP
        dt := v_dts[i];
        value := v_values[i];
        RETURN NEXT;
    END LOOP;
END;
$$;

COMMENT ON FUNCTION calc_poly_formula_array IS
'Р’С‹С‡РёСЃР»СЏРµС‚ РјРЅРѕРіРѕС‡Р»РµРЅРЅСѓСЋ С„РѕСЂРјСѓР»Сѓ РёРЅРґРёРєР°С‚РѕСЂР° (pp * (1;-2;1), @SMA # pp, вЂ¦) Рё РІРѕР·РІСЂР°С‰Р°РµС‚ РїРѕСЃР»РµРґРЅРёРµ point_count С‚РѕС‡РµРє.';

-- @begin calc_ind_extra
-- Р”РѕРї. РёРЅРґРёРєР°С‚РѕСЂС‹ РґР»СЏ Р»РѕРіРёРє L1вЂ“L4 (РёР· MultiLogicTradeA / FINRESP):
-- ADX, CCI, LINREG (+ ATR series GROWTH5).
-- РџРѕРґРєР»СЋС‡Р°РµС‚СЃСЏ РІ 02 С‡РµСЂРµР· РјР°СЂРєРµСЂС‹ begin/end calc_ind_extra (СЃРј. sync-sql-modules-to-02.mjs)

-- ========== SOLDIERS: РїР°С‚С‚РµСЂРЅ В«N СЃРѕР»РґР°С‚В» (РѕР±РѕР±С‰РµРЅРёРµ В«3 СЃРѕР»РґР°С‚В» OsEngine) ==========
-- РќР° РєР°Р¶РґРѕРј Р±Р°СЂРµ РІРѕР·РІСЂР°С‰Р°РµС‚ +1 вЂ” Р±С‹С‡СЊРё N СЃРѕР»РґР°С‚, в€’1 вЂ” РјРµРґРІРµР¶СЊРё N СЃРѕР»РґР°С‚, 0 вЂ” РїР°С‚С‚РµСЂРЅР° РЅРµС‚.
-- Р‘С‹С‡СЊРё: Сѓ РІСЃРµС… N РїРѕСЃР»РµРґРЅРёС… СЃРІРµС‡РµР№ Open < Close; Сѓ РєР°Р¶РґРѕР№ СЃР»РµРґСѓСЋС‰РµР№ СЃРІРµС‡Рё Open Р»РµР¶РёС‚
-- СЃС‚СЂРѕРіРѕ РјРµР¶РґСѓ Open Рё Close РїСЂРµРґС‹РґСѓС‰РµР№, Р° Close СЃС‚СЂРѕРіРѕ Р±РѕР»СЊС€Рµ Close РїСЂРµРґС‹РґСѓС‰РµР№.
-- РњРµРґРІРµР¶СЊРё вЂ” Р·РµСЂРєР°Р»СЊРЅРѕ: Open > Close, Open СЃР»РµРґСѓСЋС‰РµР№ РјРµР¶РґСѓ Open/Close РїСЂРµРґС‹РґСѓС‰РµР№,
-- Close СЃР»РµРґСѓСЋС‰РµР№ СЃС‚СЂРѕРіРѕ РјРµРЅСЊС€Рµ Close РїСЂРµРґС‹РґСѓС‰РµР№.

CREATE OR REPLACE FUNCTION cleanup_trading_disk_space(p_keep_days_active INTEGER DEFAULT 90,
    p_keep_days_other INTEGER DEFAULT 14,
    p_tech_log_keep_days INTEGER DEFAULT 7)
RETURNS JSONB
LANGUAGE plpgsql AS $$
DECLARE
    v_cutoff_active TIMESTAMP;
    v_cutoff_other TIMESTAMP;
    v_cutoff_tech TIMESTAMP;
    v_prices_deleted INTEGER := 0;
    v_tech_deleted INTEGER := 0;
    v_test_trades_deleted INTEGER := 0;
    v_rating_test_deleted INTEGER := 0;
    v_backtest_runs_deleted INTEGER := 0;
    v_indicator_cleanup JSONB;
    v_got_lock BOOLEAN := FALSE;
    v_lock_key BIGINT := hashtext('multilogictrade_disk_cleanup');
BEGIN
    PERFORM set_config('lock_timeout', '5s', TRUE);
    PERFORM set_config('statement_timeout', '600s', TRUE);

    v_got_lock := pg_try_advisory_lock(v_lock_key);
    IF NOT v_got_lock THEN
        RETURN jsonb_build_object(
            'skipped', TRUE,
            'reason', 'cleanup_lock_busy',
            'message', 'РћС‡РёСЃС‚РєР° СѓР¶Рµ РІС‹РїРѕР»РЅСЏРµС‚СЃСЏ РёР»Рё lock Р·Р°РЅСЏС‚ вЂ” РїРѕРІС‚РѕСЂРёС‚Рµ РїРѕР·Р¶Рµ'
        );
    END IF;

    BEGIN
        v_cutoff_active := CURRENT_TIMESTAMP - (GREATEST(COALESCE(p_keep_days_active, 90), 1) || ' days')::INTERVAL;
        v_cutoff_other := CURRENT_TIMESTAMP - (GREATEST(COALESCE(p_keep_days_other, 14), 1) || ' days')::INTERVAL;
        v_cutoff_tech := CURRENT_TIMESTAMP - (GREATEST(COALESCE(p_tech_log_keep_days, 7), 1) || ' days')::INTERVAL;

        CREATE TEMP TABLE IF NOT EXISTS _cleanup_active_securities (
            security_id INTEGER PRIMARY KEY
        ) ON COMMIT DROP;
        TRUNCATE _cleanup_active_securities;

        INSERT INTO _cleanup_active_securities (security_id)
        SELECT DISTINCT security_id
        FROM (
            SELECT sis.security_id
            FROM security_indicator_series sis
            WHERE sis.is_active
            UNION
            SELECT ls.security_id
            FROM logic_securities ls
            JOIN logics l ON l.id = ls.logic_id
            WHERE l.is_enabled
        ) u
        ON CONFLICT DO NOTHING;

        ANALYZE _cleanup_active_securities;

        DELETE FROM prices p
        WHERE p.dt < CASE
            WHEN EXISTS (
                SELECT 1 FROM _cleanup_active_securities a WHERE a.security_id = p.security_id
            )
            THEN v_cutoff_active
            ELSE v_cutoff_other
        END;
        GET DIAGNOSTICS v_prices_deleted = ROW_COUNT;

        -- #834: РїРѕСЃР»РµРґРЅРёР№ Р·Р°РІРµСЂС€С‘РЅРЅС‹Р№ РїСЂРѕРіРѕРЅ РєР°Р¶РґРѕР№ Р»РѕРіРёРєРё (Рё Р°РєС‚РёРІРЅС‹Рµ РїСЂРѕРіРѕРЅС‹)
        -- РІС‹Р¶РёРІР°СЋС‚ вЂ” СЂРµР·СѓР»СЊС‚Р°С‚ РїРѕСЃР»РµРґРЅРµРіРѕ С‚РµСЃС‚РёСЂРѕРІР°РЅРёСЏ РІРёРґРµРЅ РґРѕ РЅРѕРІРѕРіРѕ Р·Р°РїСѓСЃРєР°.
        CREATE TEMP TABLE IF NOT EXISTS _cleanup_keep_runs (
            run_id BIGINT PRIMARY KEY
        ) ON COMMIT DROP;
        TRUNCATE _cleanup_keep_runs;

        INSERT INTO _cleanup_keep_runs (run_id)
        SELECT id
        FROM logic_backtest_runs
        WHERE status IN ('pending', 'loading_prices', 'loading_indicators', 'running');

        INSERT INTO _cleanup_keep_runs (run_id)
        SELECT DISTINCT ON (logic_id) id
        FROM logic_backtest_runs
        WHERE status IN ('completed', 'cancelled', 'failed')
        ORDER BY logic_id, COALESCE(finished_at, created_at) DESC, id DESC;

        ANALYZE _cleanup_keep_runs;

        DELETE FROM logic_trades t
        WHERE t.is_test
          AND (
              t.run_id IS NULL
              OR NOT EXISTS (
                  SELECT 1 FROM _cleanup_keep_runs k WHERE k.run_id = t.run_id
              )
          );
        GET DIAGNOSTICS v_test_trades_deleted = ROW_COUNT;

        DELETE FROM logic_signal_rating_history h
        WHERE h.is_test
          AND (
              h.run_id IS NULL
              OR NOT EXISTS (
                  SELECT 1 FROM _cleanup_keep_runs k WHERE k.run_id = h.run_id
              )
          );
        GET DIAGNOSTICS v_rating_test_deleted = ROW_COUNT;

        DELETE FROM logic_backtest_runs r
        WHERE r.status IN ('completed', 'cancelled', 'failed')
          AND NOT EXISTS (
              SELECT 1 FROM _cleanup_keep_runs k WHERE k.run_id = r.id
          );
        GET DIAGNOSTICS v_backtest_runs_deleted = ROW_COUNT;

        IF to_regclass('public.app_tech_log') IS NOT NULL THEN
            DELETE FROM app_tech_log
            WHERE created_at < v_cutoff_tech;
            GET DIAGNOSTICS v_tech_deleted = ROW_COUNT;
        END IF;

        -- Release lock before indicator trim (same lock key inside that function).
        PERFORM pg_advisory_unlock(v_lock_key);
        v_got_lock := FALSE;

        -- keep_days for indicators: max(active price keep, 120)
        v_indicator_cleanup := cleanup_unused_indicator_values(
            GREATEST(COALESCE(p_keep_days_active, 90), 120),
            45,
            50000
        );

        RETURN jsonb_build_object(
            'ok', TRUE,
            'prices_deleted', v_prices_deleted,
            'test_trades_deleted', v_test_trades_deleted,
            'rating_test_history_deleted', v_rating_test_deleted,
            'backtest_runs_deleted', v_backtest_runs_deleted,
            'indicator_values', v_indicator_cleanup,
            'tech_log_deleted', v_tech_deleted,
            'keep_days_active', GREATEST(COALESCE(p_keep_days_active, 90), 1),
            'keep_days_other', GREATEST(COALESCE(p_keep_days_other, 14), 1),
            'tech_log_keep_days', GREATEST(COALESCE(p_tech_log_keep_days, 7), 1)
        );
    EXCEPTION
        WHEN OTHERS THEN
            IF v_got_lock THEN
                PERFORM pg_advisory_unlock(v_lock_key);
            END IF;
            RAISE;
    END;
END;
$$;

COMMENT ON FUNCTION cleanup_trading_disk_space(INTEGER, INTEGER, INTEGER) IS
'РЈРґР°Р»СЏРµС‚ Р»РёС€РЅРёРµ С†РµРЅС‹/С‚РµСЃС‚С‹/Р»РѕРіРё + cleanup_unused_indicator_values; advisory lock; timeouts. РџРѕСЃР»РµРґРЅРёР№ Р·Р°РІРµСЂС€С‘РЅРЅС‹Р№ РїСЂРѕРіРѕРЅ РєР°Р¶РґРѕР№ Р»РѕРіРёРєРё СЃРѕС…СЂР°РЅСЏРµС‚СЃСЏ (#834).';


-- ============================================
-- РРЅРґРёРєР°С‚РѕСЂС‹: РїРѕРґСЃС‚Р°РЅРѕРІРєР° РїР»РµР№СЃС…РѕР»РґРµСЂРѕРІ Рё С„СѓРЅРєС†РёРё calc_ind_*
-- (РІСЃС‚Р°РІР»СЏРµС‚СЃСЏ РІ 02_multilogictrade_functions_and_procedures.sql)
-- ============================================

CREATE OR REPLACE FUNCTION cleanup_unused_indicator_values(p_keep_days INTEGER DEFAULT 120,
    p_warmup_days INTEGER DEFAULT 45,
    p_batch_size INTEGER DEFAULT 50000)
RETURNS JSONB
LANGUAGE plpgsql AS $$
DECLARE
    v_keep_from TIMESTAMP;
    v_test_from TIMESTAMP;
    v_batch INTEGER := GREATEST(COALESCE(p_batch_size, 50000), 1000);
    v_orphans INTEGER := 0;
    v_aged INTEGER := 0;
    v_n INTEGER;
    v_got_lock BOOLEAN := FALSE;
    v_lock_key BIGINT := hashtext('multilogictrade_disk_cleanup');
BEGIN
    PERFORM set_config('lock_timeout', '5s', TRUE);
    PERFORM set_config('statement_timeout', '600s', TRUE);

    v_got_lock := pg_try_advisory_lock(v_lock_key);
    IF NOT v_got_lock THEN
        RETURN jsonb_build_object(
            'skipped', TRUE,
            'reason', 'cleanup_lock_busy',
            'message', 'РћС‡РёСЃС‚РєР° СѓР¶Рµ РІС‹РїРѕР»РЅСЏРµС‚СЃСЏ РёР»Рё lock Р·Р°РЅСЏС‚ вЂ” РїРѕРІС‚РѕСЂРёС‚Рµ РїРѕР·Р¶Рµ'
        );
    END IF;

    BEGIN
        v_keep_from := CURRENT_TIMESTAMP
            - (GREATEST(COALESCE(p_keep_days, 120), 14) || ' days')::INTERVAL;

        -- Р—Р°С‰РёС‚Р° РѕРєРЅР° С‚РµСЃС‚РѕРІ: Р°РєС‚РёРІРЅС‹Рµ РїСЂРѕРіРѕРЅС‹ + РїРѕСЃР»РµРґРЅРёР№ Р·Р°РІРµСЂС€С‘РЅРЅС‹Р№ РїСЂРѕРіРѕРЅ
        -- РєР°Р¶РґРѕР№ Р»РѕРіРёРєРё, Р·Р°РІРµСЂС€РёРІС€РёР№СЃСЏ Р·Р° РїРѕСЃР»РµРґРЅРёРµ 7 РґРЅРµР№. РРЅР°С‡Рµ РїРѕСЃР»Рµ С‚РµСЃС‚Р°
        -- РµРіРѕ СЃРѕР±СЃС‚РІРµРЅРЅРѕРµ РѕРєРЅРѕ РІС‹С‡РёС‰Р°РµС‚СЃСЏ, Рё РїРѕРІС‚РѕСЂРЅС‹Р№ РїСЂРѕРіРѕРЅ Р·Р° С‚Рѕ Р¶Рµ
        -- РёСЃС‚РѕСЂРёС‡РµСЃРєРѕРµ РѕРєРЅРѕ РїР°РґР°РµС‚ (В«РќРµС‚ РёРЅРґРёРєР°С‚РѕСЂРѕРІВ»). РћРіСЂР°РЅРёС‡РµРЅРёРµ 7 РґРЅРµР№
        -- РЅРµ РґР°С‘С‚ СЃС‚Р°СЂС‹Рј (Р·Р°Р±СЂРѕС€РµРЅРЅС‹Рј) РїСЂРѕРіРѕРЅР°Рј РІС‹РєР»СЋС‡РёС‚СЊ С‡РёСЃС‚РєСѓ С†РµР»РёРєРѕРј.
        SELECT MIN(r.date_from::TIMESTAMP)
            - (GREATEST(COALESCE(p_warmup_days, 45), 7) || ' days')::INTERVAL
        INTO v_test_from
        FROM logic_backtest_runs r
        WHERE r.status IN (
            'pending', 'loading_prices', 'loading_indicators', 'running'
        )
           OR r.id IN (
               SELECT DISTINCT ON (r2.logic_id) r2.id
               FROM logic_backtest_runs r2
               WHERE r2.status IN ('completed', 'cancelled', 'failed')
                 AND COALESCE(r2.finished_at, r2.created_at) >= CURRENT_TIMESTAMP - INTERVAL '7 days'
               ORDER BY r2.logic_id, COALESCE(r2.finished_at, r2.created_at) DESC, r2.id DESC
           );

        IF v_test_from IS NOT NULL AND v_test_from < v_keep_from THEN
            v_keep_from := v_test_from;
        END IF;

        -- 1) РЎРёСЂРѕС‚С‹: РЅРµС‚ Р°РєС‚РёРІРЅРѕР№ СЃРµСЂРёРё sis РЅР° (security, indicator, series_code)
        LOOP
            DELETE FROM indicator_values iv
            WHERE iv.id IN (
                SELECT x.id
                FROM indicator_values x
                JOIN indicator_value_types ivt ON ivt.id = x.indicator_value_type_id
                WHERE NOT EXISTS (
                    SELECT 1
                    FROM security_indicator_series sis
                    WHERE sis.security_id = x.security_id
                      AND sis.indicator_id = x.indicator_id
                      AND sis.is_active
                      AND upper(btrim(sis.series_code)) = upper(btrim(ivt.code))
                )
                LIMIT v_batch
            );
            GET DIAGNOSTICS v_n = ROW_COUNT;
            v_orphans := v_orphans + v_n;
            EXIT WHEN v_n = 0;
        END LOOP;

        -- 2) РЎС‚Р°СЂС‹Рµ С‚РѕС‡РєРё РґР°Р¶Рµ Сѓ Р°РєС‚РёРІРЅС‹С… СЃРµСЂРёР№ (РѕРєРЅРѕ + Р·Р°С‰РёС‚Р° running-С‚РµСЃС‚РѕРІ).
        -- РљР°Р¶РґСѓСЋ РїР°С‡РєСѓ РїРµСЂРµСЃС‡РёС‚С‹РІР°РµРј РіСЂР°РЅРёС†Сѓ: РјРµР¶РґСѓ Р±Р°С‚С‡Р°РјРё РјРѕРі СЃС‚Р°СЂС‚РѕРІР°С‚СЊ РЅРѕРІС‹Р№
        -- РїСЂРѕРіРѕРЅ, С‡СЊС‘ РѕРєРЅРѕ РЅРµР»СЊР·СЏ СѓРґР°Р»СЏС‚СЊ (РёРЅР°С‡Рµ РіРѕРЅРєР° в†’ В«РќРµС‚ РёРЅРґРёРєР°С‚РѕСЂРѕРІВ»).
        LOOP
            SELECT MIN(r.date_from::TIMESTAMP)
                - (GREATEST(COALESCE(p_warmup_days, 45), 7) || ' days')::INTERVAL
            INTO v_test_from
            FROM logic_backtest_runs r
            WHERE r.status IN (
                'pending', 'loading_prices', 'loading_indicators', 'running'
            )
               OR r.id IN (
                   SELECT DISTINCT ON (r2.logic_id) r2.id
                   FROM logic_backtest_runs r2
                   WHERE r2.status IN ('completed', 'cancelled', 'failed')
                     AND COALESCE(r2.finished_at, r2.created_at) >= CURRENT_TIMESTAMP - INTERVAL '7 days'
                   ORDER BY r2.logic_id, COALESCE(r2.finished_at, r2.created_at) DESC, r2.id DESC
               );

            v_keep_from := CURRENT_TIMESTAMP
                - (GREATEST(COALESCE(p_keep_days, 120), 14) || ' days')::INTERVAL;
            IF v_test_from IS NOT NULL AND v_test_from < v_keep_from THEN
                v_keep_from := v_test_from;
            END IF;

            DELETE FROM indicator_values iv
            WHERE iv.id IN (
                SELECT x.id
                FROM indicator_values x
                WHERE x.dt < v_keep_from
                LIMIT v_batch
            );
            GET DIAGNOSTICS v_n = ROW_COUNT;
            v_aged := v_aged + v_n;
            EXIT WHEN v_n = 0;
        END LOOP;

        PERFORM pg_advisory_unlock(v_lock_key);

        RETURN jsonb_build_object(
            'ok', TRUE,
            'orphans_deleted', v_orphans,
            'aged_deleted', v_aged,
            'keep_from', v_keep_from,
            'keep_days', GREATEST(COALESCE(p_keep_days, 120), 14),
            'warmup_days', GREATEST(COALESCE(p_warmup_days, 45), 7),
            'protected_test_from', v_test_from
        );
    EXCEPTION
        WHEN OTHERS THEN
            PERFORM pg_advisory_unlock(v_lock_key);
            RAISE;
    END;
END;
$$;

COMMENT ON FUNCTION cleanup_unused_indicator_values(INTEGER, INTEGER, INTEGER) IS
'РђРІС‚РѕРѕР±СЂРµР·РєР° indicator_values: СЃРёСЂРѕС‚С‹ Р±РµР· Р°РєС‚РёРІРЅРѕР№ sis + СЃС‚Р°СЂС€Рµ keep_days; Р·Р°С‰РёС‰РµРЅС‹ РѕРєРЅР° Р°РєС‚РёРІРЅС‹С… Рё РїРѕСЃР»РµРґРЅРµРіРѕ Р·Р°РІРµСЂС€С‘РЅРЅРѕРіРѕ РїСЂРѕРіРѕРЅР° РєР°Р¶РґРѕР№ Р»РѕРіРёРєРё (date_from-warmup).';

CREATE OR REPLACE FUNCTION configure_http_ssl()
RETURNS VOID
LANGUAGE plpgsql AS $$
DECLARE
    v_path TEXT;
    v_timeout_ms TEXT;
    v_connect_ms TEXT;
    v_candidates TEXT[] := ARRAY[
        'C:/Program Files/PostgreSQL/15/ssl/certs/curl-ca-bundle.crt',
        'C:/Program Files/PostgreSQL/15/ssl/certs/cacert.pem',
        '/etc/ssl/certs/ca-certificates.crt',
        '/etc/pki/tls/certs/ca-bundle.crt'
    ];
BEGIN
    -- РќР°СЃС‚СЂРѕР№РєРё curl (pgsql-http) Р¶РёРІСѓС‚ РЅР° СЃРѕРµРґРёРЅРµРЅРёРё Рё РїРµСЂРµРёСЃРїРѕР»СЊР·СѓСЋС‚СЃСЏ РїСѓР»РѕРј.
    -- РЇРІРЅРѕ Р·Р°РґР°С‘Рј С‚Р°Р№Рј-Р°СѓС‚С‹ РїСЂРё РєР°Р¶РґРѕРј http-РІС‹Р·РѕРІРµ, РёРЅР°С‡Рµ В«РїСЂРѕС‚С‘РєС€РёРµВ» Р·РЅР°С‡РµРЅРёСЏ СЂСѓР±РёР»Рё
    -- Р·Р°РіСЂСѓР·РєСѓ СЃРІРµС‡РµР№ вЂ” В«РјРѕР»РЅРёСЏВ» СЃС‚Р°РІРёР»Р° CURLOPT_TIMEOUT_MS=1500 (СЃРј. logic_lightning_run),
    -- Р° СЌС‚Рѕ СѓС…РѕРґРёР»Рѕ РІ РїСѓР» Рё РґР°РІР°Р»Рѕ 502 РЅР° /api/prices/refresh. Override вЂ” С‡РµСЂРµР·
    -- app.http_timeout_ms / app.http_connect_timeout_ms (transaction-local).
    v_timeout_ms := COALESCE(NULLIF(current_setting('app.http_timeout_ms', TRUE), ''), '20000');
    v_connect_ms := COALESCE(NULLIF(current_setting('app.http_connect_timeout_ms', TRUE), ''), '5000');
    BEGIN
        PERFORM http_set_curlopt('CURLOPT_TIMEOUT_MS', v_timeout_ms);
        PERFORM http_set_curlopt('CURLOPT_CONNECTTIMEOUT_MS', v_connect_ms);
    EXCEPTION
        WHEN OTHERS THEN
            NULL;
    END;

    FOREACH v_path IN ARRAY v_candidates
    LOOP
        BEGIN
            PERFORM http_set_curlopt('CURLOPT_CAINFO', v_path);
            PERFORM http_set_curlopt('CURLOPT_SSL_VERIFYPEER', '1');
            RETURN;
        EXCEPTION
            WHEN OTHERS THEN
                CONTINUE;
        END;
    END LOOP;
END;
$$;

COMMENT ON FUNCTION configure_http_ssl() IS
'РќР°СЃС‚СЂР°РёРІР°РµС‚ pgsql-http: CA-bundle РґР»СЏ HTTPS Рё С‚Р°Р№Рј-Р°СѓС‚С‹ (CURLOPT_TIMEOUT_MS/CONNECTTIMEOUT_MS; override С‡РµСЂРµР· app.http_*_timeout_ms). РЎРј. scripts/fix_pgsql_http_ssl.ps1';

-- @begin logic_cash_fund_park_http
-- ============================================
-- РџР°СЂРєРѕРІРєР° СЃРІРѕР±РѕРґРЅРѕРіРѕ РєСЌС€Р° РІ РґРµРЅРµР¶РЅС‹Р№ С„РѕРЅРґ (TMON/LQDT/SBMM)
-- Р’С‹Р·РѕРІ РёР· run_trade_cycle / Node trade-runner
-- ============================================

CREATE OR REPLACE FUNCTION evaluate_signal_condition(p_condition TEXT,
    p_pp NUMERIC,
    p_value NUMERIC)
RETURNS BOOLEAN
LANGUAGE plpgsql IMMUTABLE AS $$
DECLARE
    v_expr TEXT;
    v_left TEXT;
    v_right TEXT;
    v_op TEXT;
    v_lv NUMERIC;
    v_rv NUMERIC;
    v_i INTEGER;
    v_ch TEXT;
    v_next TEXT;
    v_num_pp TEXT;
    v_num_value TEXT;
    v_depth INTEGER := 0;
BEGIN
    v_expr := btrim(COALESCE(p_condition, ''));
    IF v_expr = '' OR p_pp IS NULL OR p_value IS NULL THEN
        RETURN FALSE;
    END IF;
    IF p_pp <= 0 THEN
        RETURN FALSE;
    END IF;

    -- РџРѕРґСЃС‚Р°РЅРѕРІРєР° Р·РЅР°С‡РµРЅРёР№ РєР°Рє NUMERIC-Р»РёС‚РµСЂР°Р»РѕРІ (СЃ С‚РѕС‡РєРѕР№),
    -- РёРЅР°С‡Рµ Р°СЂРёС„РјРµС‚РёРєР° СЃС‚Р°РЅРѕРІРёС‚СЃСЏ С†РµР»РѕС‡РёСЃР»РµРЅРЅРѕР№: -10/90 = 0 РІРјРµСЃС‚Рѕ -0.111вЂ¦
    v_num_pp := btrim(p_pp::TEXT);
    IF position('.' IN v_num_pp) = 0 THEN
        v_num_pp := v_num_pp || '.0';
    END IF;
    v_num_value := btrim(p_value::TEXT);
    IF position('.' IN v_num_value) = 0 THEN
        v_num_value := v_num_value || '.0';
    END IF;

    v_expr := regexp_replace(v_expr, '\mpp\y', v_num_pp, 'gi');
    v_expr := regexp_replace(v_expr, '\yVALUE\y', v_num_value, 'gi');
    IF v_expr ~ '[A-Za-z_]' THEN
        RETURN FALSE;
    END IF;

    -- РћРїРµСЂР°С‚РѕСЂ СЃСЂР°РІРЅРµРЅРёСЏ РЅР° РІРµСЂС…РЅРµРј СѓСЂРѕРІРЅРµ (РІРЅРµ СЃРєРѕР±РѕРє): >= <= <> != > < =
    v_op := NULL;
    FOR v_i IN 1..length(v_expr) LOOP
        v_ch := substr(v_expr, v_i, 1);
        IF v_ch = '(' THEN
            v_depth := v_depth + 1;
        ELSIF v_ch = ')' THEN
            v_depth := v_depth - 1;
        ELSIF v_depth = 0 AND (v_ch = '>' OR v_ch = '<' OR v_ch = '=' OR v_ch = '!') THEN
            v_next := CASE WHEN v_i < length(v_expr) THEN substr(v_expr, v_i + 1, 1) ELSE '' END;
            IF (v_ch = '>' AND v_next = '=') OR (v_ch = '<' AND (v_next = '=' OR v_next = '>'))
               OR (v_ch = '!' AND v_next = '=') THEN
                v_op := substr(v_expr, v_i, 2);
                v_left := btrim(substr(v_expr, 1, v_i - 1));
                v_right := btrim(substr(v_expr, v_i + 2));
            ELSIF v_ch <> '!' THEN
                v_op := v_ch;
                v_left := btrim(substr(v_expr, 1, v_i - 1));
                v_right := btrim(substr(v_expr, v_i + 1));
            END IF;
            EXIT WHEN v_op IS NOT NULL;
        END IF;
    END LOOP;

    IF v_op IS NULL OR v_left IS NULL OR v_right IS NULL OR v_left = '' OR v_right = '' THEN
        RETURN FALSE;
    END IF;

    -- РђСЂРёС„РјРµС‚РёРєР° РЅР°Рґ СЂСЏРґР°РјРё: # вЂ” РїРѕРєРѕРјРїРѕРЅРµРЅС‚РЅРѕРµ РїСЂРѕРёР·РІРµРґРµРЅРёРµ (РЅР° Р±Р°СЂРµ = *),
    -- * / + - Рё СЃРєРѕР±РєРё вЂ” С‡РёСЃР»РѕРІРѕРµ РІС‹СЂР°Р¶РµРЅРёРµ; РґР»СЏ СЂСЏРґРѕРІ: СЃРІС‘СЂС‚РєР°/РїРѕРєРѕРјРїРѕРЅРµРЅС‚РЅРѕ.
    v_left := replace(v_left, '#', '*');
    v_right := replace(v_right, '#', '*');
    IF v_left ~ '[^0-9+*/().[:space:]-]' OR v_right ~ '[^0-9+*/().[:space:]-]' THEN
        RETURN FALSE;
    END IF;

    BEGIN
        EXECUTE 'SELECT (' || v_left || ')::numeric' INTO v_lv;
        EXECUTE 'SELECT (' || v_right || ')::numeric' INTO v_rv;
    EXCEPTION WHEN OTHERS THEN
        RETURN FALSE;
    END;

    IF v_lv IS NULL OR v_rv IS NULL THEN
        RETURN FALSE;
    END IF;

    CASE v_op
        WHEN '>' THEN RETURN v_lv > v_rv;
        WHEN '<' THEN RETURN v_lv < v_rv;
        WHEN '>=' THEN RETURN v_lv >= v_rv;
        WHEN '<=' THEN RETURN v_lv <= v_rv;
        WHEN '=' THEN RETURN v_lv = v_rv;
        WHEN '!=' THEN RETURN v_lv <> v_rv;
        WHEN '<>' THEN RETURN v_lv <> v_rv;
        ELSE RETURN FALSE;
    END CASE;
END;
$$;

CREATE OR REPLACE FUNCTION exec_indicator_script(p_template TEXT,
    p_period INTEGER DEFAULT NULL,
    p_fast_period INTEGER DEFAULT NULL,
    p_slow_period INTEGER DEFAULT NULL,
    p_signal_period INTEGER DEFAULT NULL,
    p_std_dev NUMERIC DEFAULT NULL,
    p_k_period INTEGER DEFAULT NULL,
    p_d_period INTEGER DEFAULT NULL,
    p_smooth INTEGER DEFAULT NULL,
    p_series VARCHAR DEFAULT NULL,
    p_security_id INTEGER DEFAULT NULL,
    p_timeframe_id INTEGER DEFAULT NULL,
    p_dt TIMESTAMP DEFAULT NULL,
    p_indicator_id INTEGER DEFAULT NULL)
RETURNS NUMERIC
LANGUAGE plpgsql
AS $$
DECLARE
    v_sql TEXT;
    v_result NUMERIC;
BEGIN
    v_sql := substitute_indicator_script(
        p_template, p_period, p_fast_period, p_slow_period, p_signal_period,
        p_std_dev, p_k_period, p_d_period, p_smooth, p_series,
        p_security_id, p_timeframe_id, p_dt, p_indicator_id
    );
    IF v_sql IS NULL THEN
        RETURN NULL;
    END IF;
    EXECUTE v_sql INTO v_result;
    RETURN v_result;
EXCEPTION
    WHEN OTHERS THEN
        RAISE NOTICE 'exec_indicator_script [%]: %', p_series, SQLERRM;
        RETURN NULL;
END;
$$;

COMMENT ON FUNCTION exec_indicator_script(TEXT, INTEGER, INTEGER, INTEGER, INTEGER, NUMERIC, INTEGER, INTEGER, INTEGER, VARCHAR, INTEGER, INTEGER, TIMESTAMP, INTEGER) IS
