CREATE OR REPLACE FUNCTION format_money_ru(p_amount NUMERIC,
    p_currency VARCHAR DEFAULT 'RUB')
RETURNS TEXT
LANGUAGE plpgsql AS $$
BEGIN
    IF p_amount IS NULL THEN
        RETURN NULL;
    END IF;
    RETURN to_char(p_amount, 'FM999G999G999G990D00') || ' '
        || CASE upper(COALESCE(p_currency, 'RUB'))
            WHEN 'RUB' THEN 'в‚Ѕ'
            WHEN 'USD' THEN '$'
            WHEN 'EUR' THEN 'в‚¬'
            ELSE upper(p_currency)
        END;
END;
$$;

