CREATE OR REPLACE FUNCTION get_logic_param_boolean(p_logic_id INTEGER,
    p_param_key TEXT,
    p_default BOOLEAN DEFAULT FALSE)
RETURNS BOOLEAN
LANGUAGE plpgsql STABLE AS $$
DECLARE
    v_raw TEXT;
BEGIN
    v_raw := lower(btrim(COALESCE(get_logic_param_text(p_logic_id, p_param_key), '')));
    IF v_raw = '' THEN
        RETURN COALESCE(p_default, FALSE);
    END IF;
    IF v_raw IN ('true', '1', 'yes', 't', 'on', 'y') THEN
        RETURN TRUE;
    END IF;
    IF v_raw IN ('false', '0', 'no', 'f', 'off', 'n') THEN
        RETURN FALSE;
    END IF;
    RETURN COALESCE(p_default, FALSE);
END;
$$;

COMMENT ON FUNCTION get_logic_param_boolean(INTEGER, TEXT, BOOLEAN) IS
'Р‘СѓР»РµРІ РїР°СЂР°РјРµС‚СЂ logic_params (true/1/yes вЂ¦); РїСѓСЃС‚Рѕ в†’ p_default';

-- РРЅРІРµСЂСЃРёСЏ СЃСЂР°РІРЅРµРЅРёСЏ: >=в†”<=, >в†”< (legacy helper).
-- Param В«inversionВ» / ReverseSides Р±РѕР»СЊС€Рµ РќР• РІС‹Р·С‹РІР°РµС‚ СЌС‚Рѕ РЅР° СЃРёРіРЅР°Р»Р°С…:
-- РґР»СЏ РєР°РЅР°Р»РѕРІ (pp<=LOWER) РёРЅРІРµСЂСЃРёСЏ СѓСЃР»РѕРІРёСЏ РґР°С‘С‚ pp>=LOWER в‰€ РІСЃРµРіРґР° true в†’ СЃРїР°Рј СЃРґРµР»РѕРє.
-- РРЅРІРµСЂСЃРёСЏ Р»РѕРіРёРєРё = С‚РѕР»СЊРєРѕ Longв†”Short РїСЂРё С‚РѕРј Р¶Рµ СѓСЃР»РѕРІРёРё.

CREATE OR REPLACE FUNCTION get_logic_param_numeric(p_logic_id INTEGER, p_param_key TEXT, p_default NUMERIC)
RETURNS NUMERIC
LANGUAGE plpgsql STABLE AS $$
DECLARE
    v_raw TEXT;
    v_num NUMERIC;
BEGIN
    v_raw := btrim(COALESCE(get_logic_param_text(p_logic_id, p_param_key), ''));
    IF v_raw = '' THEN
        RETURN p_default;
    END IF;
    v_num := replace(v_raw, ',', '.')::NUMERIC;
    IF v_num IS NULL THEN
        RETURN p_default;
    END IF;
    RETURN v_num;
END;
$$;

