CREATE OR REPLACE FUNCTION indicator_signal_formula(p_indicator_id INTEGER,
    p_kind TEXT)
RETURNS TEXT
LANGUAGE plpgsql STABLE AS $$
DECLARE
    v_code TEXT;
    v_series TEXT;
    v_condition TEXT;
BEGIN
    SELECT i.code INTO v_code FROM indicators i WHERE i.id = p_indicator_id;
    IF v_code IS NULL THEN
        RETURN NULL;
    END IF;

    SELECT f.series, f.condition INTO v_series, v_condition
    FROM indicator_signal_series_and_condition(p_indicator_id, p_kind) f;

    RETURN '@' || v_code || '(' || indicator_signal_default_params(v_code, v_series) || ') ' || v_condition;
END;
$$;

COMMENT ON FUNCTION indicator_signal_formula(INTEGER, TEXT) IS
'Р“РѕС‚РѕРІР°СЏ СЃС‚СЂРѕРєР° Р°РІС‚Рѕ-С„РѕСЂРјСѓР»С‹ С‚РµСЃС‚Р° СЂРµР№С‚РёРЅРіР° РёРЅРґРёРєР°С‚РѕСЂР° (РґРёР°РіРЅРѕСЃС‚РёРєР°/РѕС‚Р»Р°РґРєР°)';

-- Р Р°Р·Р±РѕСЂ РїСЂРѕСЃС‚РѕРіРѕ СѓСЃР»РѕРІРёСЏ РІРёРґР° В«pp <op> VALUEВ» (РёР»Рё В«VALUE <op> ppВ») РѕРґРёРЅ СЂР°Р·,
-- С‡С‚РѕР±С‹ РІ С‚СЏР¶С‘Р»РѕРј С†РёРєР»Рµ РЅРµ РІС‹Р·С‹РІР°С‚СЊ evaluate_signal_condition РЅР° РєР°Р¶РґСѓСЋ СЃРІРµС‡Сѓ.

CREATE OR REPLACE FUNCTION indicator_signal_series_and_condition(p_indicator_id INTEGER,
    p_kind TEXT)
RETURNS TABLE(series TEXT, condition TEXT)
LANGUAGE plpgsql STABLE AS $$
DECLARE
    v_kind TEXT := CASE WHEN lower(COALESCE(p_kind, 'trend')) = 'counter' THEN 'counter' ELSE 'trend' END;
    v_def TEXT;
    v_tokens TEXT[];
    v_hits TEXT[];
    v_check TEXT;
BEGIN
    SELECT CASE v_kind
               WHEN 'counter' THEN COALESCE(NULLIF(btrim(i.sig_ct_def), ''), 'VALUE < 50')
               ELSE COALESCE(NULLIF(btrim(i.sig_trend_def), ''), 'VALUE > 50')
           END
    INTO v_def
    FROM indicators i
    WHERE i.id = p_indicator_id;

    v_def := COALESCE(NULLIF(btrim(v_def), ''),
                      CASE v_kind WHEN 'counter' THEN 'VALUE < 50' ELSE 'VALUE > 50' END);

    SELECT array_agg(upper(ivt.code) ORDER BY ivt.display_order, ivt.id)
    INTO v_tokens
    FROM indicator_value_types ivt
    WHERE ivt.indicator_id = p_indicator_id
      AND ivt.is_threshold = FALSE;

    SELECT array_agg(DISTINCT t)
    INTO v_hits
    FROM unnest(COALESCE(v_tokens, ARRAY[]::TEXT[])) AS t
    WHERE v_def ~ ('\y' || t || '\y');

    IF v_hits IS NOT NULL AND array_length(v_hits, 1) = 1 THEN
        series := v_hits[1];
        condition := regexp_replace(v_def, '\y' || v_hits[1] || '\y', 'VALUE', 'gi');
    ELSIF v_hits IS NOT NULL AND array_length(v_hits, 1) > 1 THEN
        series := v_hits[1];
        condition := CASE v_kind WHEN 'counter' THEN 'VALUE < 50' ELSE 'VALUE > 50' END;
    ELSE
        series := COALESCE(v_tokens[1], 'VALUE');
        condition := v_def;
    END IF;

    v_check := upper(condition);
    v_check := regexp_replace(v_check, '\yPP\y', '', 'g');
    v_check := regexp_replace(v_check, '\yVALUE\y', '', 'g');
    v_check := regexp_replace(v_check, '\y(AND|OR)\y', '', 'g');
    IF v_check ~ '[A-Z]' THEN
        condition := CASE v_kind WHEN 'counter' THEN 'VALUE < 50' ELSE 'VALUE > 50' END;
    END IF;

    RETURN NEXT;
END;
$$;

COMMENT ON FUNCTION indicator_signal_series_and_condition(INTEGER, TEXT) IS
'Р СЏРґ (series) Рё СѓСЃР»РѕРІРёРµ (VALUE/pp) РґР»СЏ Р°РІС‚Рѕ-СЃРёРіРЅР°Р»Р° С‚РµСЃС‚Р°; РґРІСѓС…СЂСЏРґРЅС‹Рµ СѓСЃР»РѕРІРёСЏ в†’ VALUE vs 50';

-- Р“РѕС‚РѕРІР°СЏ СЃС‚СЂРѕРєР° С„РѕСЂРјСѓР»С‹ РІРёРґР° @CODE(params,series=X) VALUE > 50 (РґРёР°РіРЅРѕСЃС‚РёРєР°/РѕС‚Р»Р°РґРєР°).

CREATE OR REPLACE FUNCTION indicator_simple_condition(p_condition TEXT)
RETURNS TABLE(is_simple BOOLEAN, op TEXT, pp_left BOOLEAN)
LANGUAGE plpgsql IMMUTABLE AS $$
DECLARE
    m TEXT[];
BEGIN
    m := regexp_match(
        upper(btrim(COALESCE(p_condition, ''))),
        '^(PP|VALUE)\s*(>=|<=|<>|!=|>|<|=)\s*(PP|VALUE)$'
    );

    IF m IS NULL OR m[1] = m[3] THEN
        is_simple := FALSE; op := NULL; pp_left := NULL;
        RETURN NEXT;
        RETURN;
    END IF;

    is_simple := TRUE;
    op := CASE m[2] WHEN '!=' THEN '<>' ELSE m[2] END;
    pp_left := (m[1] = 'PP');
    RETURN NEXT;
END;
$$;

COMMENT ON FUNCTION indicator_simple_condition(TEXT) IS
'Р Р°Р·Р±РѕСЂ РїСЂРѕСЃС‚РѕРіРѕ СѓСЃР»РѕРІРёСЏ В«pp <op> VALUEВ» РґР»СЏ РёРЅР»Р°Р№РЅР° РІ С‚РµСЃС‚Рµ СЂРµР№С‚РёРЅРіР° (is_simple, op, pp_left)';

-- #1011: СЂСѓС‡РЅРѕР№ СЂР°СЃС‡С‘С‚ СЂРµР№С‚РёРЅРіР° РћР”РќРћР“Рћ РёРЅРґРёРєР°С‚РѕСЂР° РїРѕ РєРЅРѕРїРєРµ. РќР°Р±РѕСЂ РІРЅСѓС‚СЂРёРґРЅРµРІРЅС‹С… РўР¤
-- В«РѕС‚ РјРёРЅСѓС‚РЅРѕРіРѕ РґРѕ С‡Р°СЃРѕРІРѕРіРѕВ»: M1, M5, M15, M30, H1.

CREATE OR REPLACE FUNCTION logic_account_net_equity(p_logic_id INTEGER,
    p_timeframe_id INTEGER)
RETURNS NUMERIC
LANGUAGE plpgsql AS $$
DECLARE
    v_account_id INTEGER;
    v_account_type VARCHAR;
    v_bal JSONB;
    v_cash NUMERIC;
    v_equity NUMERIC;
    v_short_notional NUMERIC;
    v_long_mtm NUMERIC := 0;
    v_sec RECORD;
    v_price NUMERIC;
    v_long_qty NUMERIC;
BEGIN
    SELECT l.account_id, lower(COALESCE(a.account_type, 'fake'))
    INTO v_account_id, v_account_type
    FROM logics l
    JOIN accounts a ON a.id = l.account_id
    WHERE l.id = p_logic_id;

    IF NOT FOUND THEN
        RETURN 0;
    END IF;

    v_short_notional := logic_open_short_entry_notional(p_logic_id, FALSE);

    IF v_account_type <> 'fake' THEN
        BEGIN
            v_bal := fetch_tbank_account_balance(v_account_id);
            IF v_bal IS NULL OR (v_bal->>'error') IS NOT NULL THEN
                RETURN 0;
            END IF;
            -- Р—Р°С‰РёС‚РЅС‹Р№ РЅРµС‚С‚РёРЅРі: РґР°Р¶Рµ РµСЃР»Рё Р±СЂРѕРєРµСЂ РІРµСЂРЅСѓР» В«РіСЂСЏР·РЅС‹Р№В» amount
            -- (СЃ С€РѕСЂС‚-РІС‹СЂСѓС‡РєРѕР№/Р·Р°С‘РјРѕРј), РІС‹С‡РёС‚Р°РµРј РЅР°С€Рё РѕС‚РєСЂС‹С‚С‹Рµ С€РѕСЂС‚С‹.
            RETURN GREATEST(
                0,
                COALESCE((v_bal->>'amount')::NUMERIC, 0) - COALESCE(v_short_notional, 0)
            );
        EXCEPTION
            WHEN OTHERS THEN
                RETURN 0;
        END;
    END IF;

    -- Fake: current_balance includes short proceeds вЂ” subtract short entry notional.
    v_cash := COALESCE(logic_ensure_balance(p_logic_id), 0);

    FOR v_sec IN
        SELECT ls.security_id
        FROM logic_securities ls
        WHERE ls.logic_id = p_logic_id AND ls.is_active = TRUE
    LOOP
        v_long_qty := logic_long_position_qty(p_logic_id, v_sec.security_id, FALSE);
        IF v_long_qty <= 0 THEN
            CONTINUE;
        END IF;
        v_price := logic_ensure_security_market_price(
            p_logic_id, v_sec.security_id, p_timeframe_id
        );
        IF v_price IS NOT NULL AND v_price > 0 THEN
            v_long_mtm := v_long_mtm + v_long_qty * v_price;
        END IF;
    END LOOP;

    v_equity := v_cash - COALESCE(v_short_notional, 0) + COALESCE(v_long_mtm, 0);
    RETURN GREATEST(0, v_equity);
END;
$$;

COMMENT ON FUNCTION logic_account_net_equity(INTEGER, INTEGER) IS
'Equity РґР»СЏ РїРѕС‚РѕР»РєР° Open (РїР»РµС‡Рѕ 1): real=amountв€’РѕС‚РєСЂС‹С‚С‹Рµ С€РѕСЂС‚С‹ (#844); fake=cashв€’short+long_mtm.';

-- Р‘Р°Р·Р° С†РёРєР»Р° / РїРѕС‚РѕР»РєР°: min(Р±Р°Р·Р° Р»РѕС‚Р°, equity).
-- #844: equity РЅРµРёР·РІРµСЃС‚РµРЅ РёР»Рё СЂР°РІРµРЅ 0 (Р±СЂРѕРєРµСЂ РЅРµ РѕС‚РІРµС‚РёР» / Р»РёРјРёС‚С‹ API) в†’ Р±СЋРґР¶РµС‚ 0 вЂ”
-- РќР• С‚РѕСЂРіСѓРµРј. РџСЂРµР¶РЅРёР№ fallback РЅР° СЃС‹СЂРѕР№ sizing РїСЂРё equity=0 РѕС‚РєСЂС‹РІР°Р» РјР°СЂР¶Сѓ СЃРІРµСЂС… СЃС‡С‘С‚Р°.

CREATE OR REPLACE FUNCTION logic_apply_moex_non_trading_periods(p_logic_id INTEGER)
RETURNS INTEGER
LANGUAGE plpgsql AS $$
DECLARE
    v_n INTEGER;
BEGIN
    IF p_logic_id IS NULL OR p_logic_id <= 0 THEN
        RAISE EXCEPTION 'logic_id required';
    END IF;

    DELETE FROM logic_non_trading_intervals WHERE logic_id = p_logic_id;

    INSERT INTO logic_non_trading_intervals (
        logic_id, day_of_week, time_from, time_to, note, display_order, is_active
    )
    SELECT
        p_logic_id,
        t.day_of_week,
        t.time_from,
        t.time_to,
        t.note,
        ROW_NUMBER() OVER (ORDER BY t.day_of_week, t.time_from)::INTEGER,
        TRUE
    FROM logic_moex_equity_non_trading_template() t;

    GET DIAGNOSTICS v_n = ROW_COUNT;
    RETURN v_n;
END;
$$;

COMMENT ON FUNCTION logic_apply_moex_non_trading_periods(INTEGER) IS
'Р—Р°РјРµРЅРёС‚СЊ РЅРµС‚РѕСЂРіРѕРІС‹Рµ РёРЅС‚РµСЂРІР°Р»С‹ Р»РѕРіРёРєРё С€Р°Р±Р»РѕРЅРѕРј MOEX TQBR';

CREATE OR REPLACE FUNCTION logic_apply_real_account_balances(p_logic_id INTEGER,
    p_force_initial BOOLEAN DEFAULT TRUE)
RETURNS NUMERIC
LANGUAGE plpgsql AS $$
DECLARE
    v_account_id INTEGER;
    v_account_type VARCHAR;
    v_bal JSONB;
    v_amount NUMERIC := 0;
    v_ok BOOLEAN := FALSE;
BEGIN
    SELECT l.account_id, lower(COALESCE(a.account_type, 'fake'))
    INTO v_account_id, v_account_type
    FROM logics l
    JOIN accounts a ON a.id = l.account_id
    WHERE l.id = p_logic_id;

    IF NOT FOUND OR v_account_type = 'fake' THEN
        RETURN NULL;
    END IF;

    BEGIN
        v_bal := fetch_tbank_account_balance(v_account_id);
        IF v_bal IS NOT NULL AND (v_bal->>'error') IS NULL THEN
            -- РўРѕР»СЊРєРѕ РєСЌС€ Р±СЂРѕРєРµСЂР°. Р¤РѕР»Р±СЌРє РЅР° РІРµСЃСЊ РїРѕСЂС‚С„РµР»СЊ Р·Р°РїСЂРµС‰С‘РЅ:
            -- РѕРЅ Р·Р°РІС‹С€Р°Р» current_balance Рё СЂР°Р·РјРµСЂ РїРѕР·РёС†РёРё СЃРІРµСЂС… РѕСЃС‚Р°С‚РєР°.
            IF v_bal ? 'cash_amount' AND (v_bal->>'cash_amount') IS NOT NULL THEN
                v_amount := COALESCE((v_bal->>'cash_amount')::NUMERIC, 0);
            ELSE
                v_amount := 0;
            END IF;
            IF v_amount < 0 THEN
                v_amount := 0;
            END IF;
            v_ok := TRUE;
        END IF;
    EXCEPTION
        WHEN OTHERS THEN
            v_ok := FALSE;
            v_amount := 0;
    END;

    IF NOT v_ok THEN
        v_amount := 0;
    END IF;

    -- Real: С‚РµРєСѓС‰РёР№ вЂ” СЃ Р±СЂРѕРєРµСЂР°; РЅР°С‡Р°Р»СЊРЅС‹Р№ вЂ” СЂРµРґР°РєС‚РёСЂСѓРµС‚СЃСЏ РІСЂСѓС‡РЅСѓСЋ, РЅРµ Р·Р°С‚РёСЂР°РµС‚СЃСЏ sync.
    PERFORM logic_upsert_param(p_logic_id, 'current_balance', v_amount::TEXT, 'money');

    RETURN v_amount;
END;
$$;

COMMENT ON FUNCTION logic_apply_real_account_balances(INTEGER, BOOLEAN) IS
'Real: current = T-Bank cash РёР»Рё 0; initial_balance СЂРµРґР°РєС‚РёСЂСѓРµС‚СЃСЏ РІСЂСѓС‡РЅСѓСЋ. Fake: no-op.';

CREATE OR REPLACE FUNCTION logic_auto_optimize_on_close(p_logic_id INTEGER,
    p_security_id INTEGER,
    p_timeframe_id INTEGER,
    p_bar_dt TIMESTAMP,
    p_position_side TEXT DEFAULT NULL,
    p_is_test BOOLEAN DEFAULT FALSE,
    p_run_id BIGINT DEFAULT NULL)
RETURNS INTEGER
LANGUAGE plpgsql AS $$
DECLARE
    v_enabled TEXT;
    v_max_shift INTEGER := 10;
    v_tf_sec INTEGER;
    v_tf_id INTEGER;
    v_sides TEXT[];
    v_side TEXT;
    v_close RECORD;
    v_pnl NUMERIC;
    v_entry_price NUMERIC;
    v_entry_bar_dt TIMESTAMP;
    v_prev_bar_dt TIMESTAMP;
    v_prev_price NUMERIC;
    v_earlier_better BOOLEAN;
    v_is_profit BOOLEAN;
    v_sig RECORD;
    v_parsed RECORD;
    v_base INTEGER;
    v_new INTEGER;
    v_new_formula TEXT;
    v_changed INTEGER := 0;
BEGIN
    v_enabled := lower(btrim(COALESCE(get_logic_param_text(p_logic_id, 'auto_optimize'), 'false')));
    IF v_enabled NOT IN ('true', 't', '1', 'on', 'yes', 'РґР°') THEN
        RETURN 0;
    END IF;

    v_tf_id := p_timeframe_id;
    IF v_tf_id IS NULL THEN
        v_tf_id := logic_resolve_timeframe_id(p_logic_id);
    END IF;
    SELECT t.sec INTO v_tf_sec FROM timeframes t WHERE t.id = v_tf_id;
    IF v_tf_sec IS NULL OR v_tf_sec <= 0 THEN
        RETURN 0;
    END IF;

    v_sides := CASE logic_normalize_position_side(p_position_side)
        WHEN 'long' THEN ARRAY['long']
        WHEN 'short' THEN ARRAY['short']
        ELSE ARRAY['long', 'short']
    END;

    FOREACH v_side IN ARRAY v_sides LOOP
        SELECT lt.id, lt.price, lt.bar_dt,
               COALESCE(
                   lt.financial_result,
                   (SELECT SUM(l.financial_result)
                    FROM logic_trade_lots l
                    WHERE l.close_trade_id = lt.id)
               ) AS pnl
        INTO v_close
        FROM logic_trades lt
        JOIN sides sd ON sd.id = lt.side_id
        JOIN actions ac ON ac.id = lt.action_id
        WHERE lt.logic_id = p_logic_id
          AND lt.security_id = p_security_id
          AND lt.position_event = 'close'
          AND COALESCE(lt.opt_lane, '') = ''
          AND COALESCE(lt.is_test, FALSE) = COALESCE(p_is_test, FALSE)
          AND lt.status IN ('filled', 'submitted')
          AND lower(ac.name) = v_side
          AND lt.bar_dt <= p_bar_dt
        ORDER BY lt.bar_dt DESC, lt.id DESC
        LIMIT 1;

        IF NOT FOUND THEN
            CONTINUE;
        END IF;

        v_pnl := v_close.pnl;
        IF v_pnl IS NULL THEN
            CONTINUE;
        END IF;
        v_is_profit := v_pnl > 0;

        -- РўРѕС‡РЅР°СЏ С†РµРЅР°/Р±Р°СЂ РІС…РѕРґР° РёР· РїР°РєРµС‚РѕРІ Р·Р°РєСЂС‹С‚РёСЏ; РёРЅР°С‡Рµ вЂ” РїРѕСЃР»РµРґРЅСЏСЏ РѕС‚РєСЂС‹РІР°СЋС‰Р°СЏ СЃРґРµР»РєР°.
        SELECT SUM(l.open_amount) / NULLIF(SUM(l.quantity), 0), MIN(o.bar_dt)
        INTO v_entry_price, v_entry_bar_dt
        FROM logic_trade_lots l
        JOIN logic_trades o ON o.id = l.open_trade_id
        WHERE l.close_trade_id = v_close.id;

        IF v_entry_price IS NULL OR v_entry_bar_dt IS NULL THEN
            SELECT lt.price, lt.bar_dt
            INTO v_entry_price, v_entry_bar_dt
            FROM logic_trades lt
            JOIN sides sd ON sd.id = lt.side_id
            JOIN actions ac ON ac.id = lt.action_id
            WHERE lt.logic_id = p_logic_id
              AND lt.security_id = p_security_id
              AND lt.position_event = 'open'
              AND COALESCE(lt.opt_lane, '') = ''
              AND COALESCE(lt.is_test, FALSE) = COALESCE(p_is_test, FALSE)
              AND lt.status IN ('filled', 'submitted')
              AND lower(ac.name) = v_side
              AND lt.bar_dt <= v_close.bar_dt
            ORDER BY lt.bar_dt DESC, lt.id DESC
            LIMIT 1;
        END IF;

        IF v_entry_price IS NULL OR v_entry_bar_dt IS NULL THEN
            CONTINUE;
        END IF;

        v_prev_bar_dt := v_entry_bar_dt - make_interval(secs => v_tf_sec);
        SELECT p.close_price INTO v_prev_price
        FROM prices p
        WHERE p.security_id = p_security_id
          AND p.timeframe_id = v_tf_id
          AND p.dt = v_prev_bar_dt
        LIMIT 1;

        IF v_prev_price IS NULL OR v_prev_price <= 0 THEN
            CONTINUE;
        END IF;

        -- Р’С‹РіРѕРґРЅРµРµ Р»Рё Р±С‹Р» Р±С‹ РІС…РѕРґ РЅР° РїСЂРµРґС‹РґСѓС‰РµРј Р±Р°СЂРµ (РґР»СЏ РЅР°С€РµР№ СЃС‚РѕСЂРѕРЅС‹).
        v_earlier_better := CASE v_side
            WHEN 'long' THEN v_prev_price < v_entry_price
            ELSE v_prev_price > v_entry_price
        END;

        IF v_is_profit AND NOT v_earlier_better THEN
            CONTINUE;
        END IF;

        FOR v_sig IN
            SELECT lis.id, lis.formula
            FROM logic_indicator_signals lis
            WHERE lis.logic_id = p_logic_id
              AND lis.is_active = TRUE
              AND lis.position_event = 'open'
              AND lower(COALESCE(lis.position_side, '')) = v_side
        LOOP
            SELECT * INTO v_parsed FROM parse_signal_formula(v_sig.formula);
            IF NOT COALESCE(v_parsed.valid, FALSE) THEN
                CONTINUE;
            END IF;
            -- РЎРёРіРЅР°Р»С‹ СЃРѕ СЃРІРѕРёРј tf= РЅРµ С‚СЂРѕРіР°РµРј: РѕС†РµРЅРєР° РёРґС‘С‚ РїРѕ TF Р»РѕРіРёРєРё.
            IF parse_signal_param_num(v_parsed.params, 'tf') IS NOT NULL THEN
                CONTINUE;
            END IF;
            v_base := parse_signal_param_num(v_parsed.params, 'period')::INTEGER;
            IF v_base IS NULL OR v_base < 1 THEN
                CONTINUE;
            END IF;

            IF v_is_profit THEN
                v_new := logic_autoopt_find_period(
                    v_sig.id, p_security_id, v_tf_id, v_prev_bar_dt, v_base, TRUE, v_max_shift
                );
            ELSE
                v_new := logic_autoopt_find_period(
                    v_sig.id, p_security_id, v_tf_id, v_entry_bar_dt, v_base, FALSE, v_max_shift
                );
            END IF;

            IF v_new IS NULL OR v_new = v_base THEN
                CONTINUE;
            END IF;

            v_new_formula := logic_opt_rewrite_formula_bases(
                v_sig.formula, jsonb_build_object('period', v_new)
            );
            IF v_new_formula IS DISTINCT FROM v_sig.formula THEN
                UPDATE logic_indicator_signals SET formula = v_new_formula WHERE id = v_sig.id;
                v_changed := v_changed + 1;
            END IF;
        END LOOP;

        IF v_changed > 0 THEN
            PERFORM logic_trade_log(
                p_logic_id,
                'auto_opt.adjust',
                format(
                    'РђРІС‚Рѕ РѕРїС‚РёРјРёР·Р°С†РёСЏ (%s): РїРµСЂРёРѕРґ СЃРёРіРЅР°Р»РѕРІ РІС…РѕРґР° РёР·РјРµРЅС‘РЅ, %s СЃРёРіРЅ.; PnL=%s, РІС…РѕРґ=%s, РїСЂРµРґ.%s',
                    v_side, v_changed, v_pnl, v_entry_price, v_prev_price
                ),
                jsonb_build_object(
                    'side', v_side,
                    'changed', v_changed,
                    'pnl', v_pnl,
                    'entry_price', v_entry_price,
                    'entry_bar_dt', v_entry_bar_dt,
                    'prev_price', v_prev_price,
                    'prev_bar_dt', v_prev_bar_dt
                ),
                p_security_id,
                v_tf_id
            );
        END IF;
    END LOOP;

    IF v_changed > 0 AND NOT p_is_test THEN
        CALL logic_apply_indicator_params_from_signals(p_logic_id, p_security_id);
    END IF;

    RETURN v_changed;
END;
$$;

COMMENT ON FUNCTION logic_auto_optimize_on_close(INTEGER, INTEGER, INTEGER, TIMESTAMP, TEXT, BOOLEAN, BIGINT) IS
'РђРІС‚Рѕ РѕРїС‚РёРјРёР·Р°С†РёСЏ: РїРѕ Р·Р°РєСЂС‹С‚РёСЋ РїРѕР·РёС†РёРё РїРѕРґР±РёСЂР°РµС‚ РіР»Р°РІРЅС‹Р№ РїРµСЂРёРѕРґ (period) СЃРёРіРЅР°Р»РѕРІ РІС…РѕРґР° вЂ” РїСЂРѕРёРіСЂС‹С€: РїРµСЂРёРѕРґ, РїСЂРё РєРѕС‚РѕСЂРѕРј СЃРёРіРЅР°Р» РЅРµ СЃСЂР°Р±РѕС‚Р°Р» Р±С‹ РЅР° Р±Р°СЂРµ РІС…РѕРґР°; РІС‹РёРіСЂС‹С€: РїРµСЂРёРѕРґ, РїСЂРё РєРѕС‚РѕСЂРѕРј СЃРёРіРЅР°Р» СЃСЂР°Р±РѕС‚Р°Р» Р±С‹ РЅР° РїСЂРµРґС‹РґСѓС‰РµРј Р±Р°СЂРµ (РµСЃР»Рё РІС…РѕРґ С‚Р°Рј РІС‹РіРѕРґРЅРµРµ).';

-- Р РµР№С‚РёРЅРі СЃРёРіРЅР°Р»Р° РЅР° Р»РѕРіРёРєРµ: Р±РѕРµРІРѕР№ (rating) Рё С‚РµСЃС‚РѕРІС‹Р№ (rating_test) СЂР°Р·РґРµР»СЊРЅРѕ.
-- РќРµ РїСѓС‚Р°С‚СЊ СЃ СЂРµР№С‚РёРЅРіРѕРј РёРЅРґРёРєР°С‚РѕСЂР° РІ СЃРїСЂР°РІРѕС‡РЅРёРєРµ indicators.
--
-- РђР»РіРѕСЂРёС‚Рј СѓСЃРїРµС…Р° (РЅРµ В«РїСЂРѕСЃС‚Рѕ СЃСЂР°Р±РѕС‚Р°Р»В»):
--   1) СЃРёРіРЅР°Р» СЃСЂР°Р±РѕС‚Р°Р» РЅР° СЃРІРµС‡Рµ в†’ pending (Р·Р°РїРѕРјРЅРёС‚СЊ С†РµРЅСѓ);
--   2) РЅР° РЎР›Р•Р”РЈР®Р©Р•Р™ СЃРІРµС‡Рµ TF: С…РѕРґ С†РµРЅС‹ в†’ % РіРѕРґРѕРІС‹С… Р·Р° РґР»РёС‚РµР»СЊРЅРѕСЃС‚СЊ TF;
--   3) СЃСЂР°РІРЅРёС‚СЊ СЃ base_annual_rate_pct Р»РѕРіРёРєРё (РїРѕ СѓРјРѕР»С‡Р°РЅРёСЋ 20);
--   4) СѓСЃРїРµС… в†’ +1, РЅРµСѓСЃРїРµС… в†’ в€’1 (СЂРµР№С‚РёРЅРі РјРѕР¶РµС‚ Р±С‹С‚СЊ РѕС‚СЂРёС†Р°С‚РµР»СЊРЅС‹Рј).
-- РСЃС‚РѕСЂРёСЏ РїРёС€РµС‚СЃСЏ РїРѕ (signal Г— security); РіСЂР°С„РёРє вЂ” РїРѕ Р±СѓРјР°РіРµ.

