'РЎР±СЂРѕСЃ С‚РµСЃС‚РѕРІРѕРіРѕ СЂРµР№С‚РёРЅРіР° Рё РёСЃС‚РѕСЂРёРё РїРµСЂРµРґ РЅРѕРІС‹Рј РїСЂРѕРіРѕРЅРѕРј Р±СЌРєС‚РµСЃС‚Р°';

CREATE OR REPLACE FUNCTION logic_backtest_sec_inverted(p_run_id BIGINT,
