CREATE OR REPLACE FUNCTION logic_backtest_security_side_drawdown_pct(p_logic_id INTEGER,
    p_security_id INTEGER,
    p_timeframe_id INTEGER,
    p_bar_dt TIMESTAMP,
    p_is_shadow BOOLEAN,
