CREATE OR REPLACE FUNCTION logic_bar_annual_threshold_pct(p_tf_sec INTEGER,
    p_base_annual_pct NUMERIC)
RETURNS NUMERIC
LANGUAGE sql IMMUTABLE AS $$
    SELECT GREATEST(
        0::NUMERIC,
        COALESCE(p_base_annual_pct, 20)
            * (GREATEST(COALESCE(p_tf_sec, 900), 1)::NUMERIC / (365.25 * 24 * 3600))
    );
$$;

COMMENT ON FUNCTION logic_bar_annual_threshold_pct(INTEGER, NUMERIC) IS
'Р­РєРІРёРІР°Р»РµРЅС‚ РїРѕСЂРѕРіР° РЅР° 1 СЃРІРµС‡Рµ: base_annual Г— (tf_sec / РіРѕРґ). РЎРѕРіР»Р°СЃРѕРІР°РЅ СЃ annualized_move >= base.';

-- РЈСЃРїРµС…: РіРѕРґРѕРІР°СЏ СЃС‚Р°РІРєР° С…РѕРґР° РІ РѕР¶РёРґР°РµРјСѓСЋ СЃС‚РѕСЂРѕРЅСѓ >= base_annual_rate_pct

CREATE OR REPLACE FUNCTION logic_bar_data_at(p_security_id INTEGER,
    p_timeframe_id INTEGER,
    p_indicator_id INTEGER,
    p_series TEXT,
    p_bar_dt TIMESTAMP)
RETURNS TABLE (bar_dt TIMESTAMP, ind_value NUMERIC, close_price NUMERIC)
LANGUAGE plpgsql STABLE AS $$
DECLARE
    v_tf_sec INTEGER;
    v_ind_dt TIMESTAMP;
    v_ind_val NUMERIC;
    v_pp NUMERIC;
BEGIN
    SELECT t.sec INTO v_tf_sec FROM timeframes t WHERE t.id = p_timeframe_id;

    SELECT iv.dt, iv.value
    INTO v_ind_dt, v_ind_val
    FROM indicator_values iv
    JOIN indicator_value_types ivt ON ivt.id = iv.indicator_value_type_id
    WHERE iv.security_id = p_security_id
      AND iv.timeframe_id = p_timeframe_id
      AND iv.indicator_id = p_indicator_id
      AND upper(ivt.code) = upper(COALESCE(p_series, 'VALUE'))
      AND iv.dt = p_bar_dt
    LIMIT 1;

    IF v_ind_dt IS NULL AND v_tf_sec IS NOT NULL THEN
        SELECT iv.dt, iv.value
        INTO v_ind_dt, v_ind_val
        FROM indicator_values iv
        JOIN indicator_value_types ivt ON ivt.id = iv.indicator_value_type_id
        WHERE iv.security_id = p_security_id
          AND iv.timeframe_id = p_timeframe_id
          AND iv.indicator_id = p_indicator_id
          AND upper(ivt.code) = upper(COALESCE(p_series, 'VALUE'))
          AND iv.dt > p_bar_dt - make_interval(secs => v_tf_sec)
          AND iv.dt <= p_bar_dt
        ORDER BY iv.dt DESC
        LIMIT 1;
    END IF;

    IF v_ind_dt IS NULL THEN
        RETURN;
    END IF;

    SELECT p.close_price
    INTO v_pp
    FROM prices p
    WHERE p.security_id = p_security_id
      AND p.timeframe_id = p_timeframe_id
      AND p.dt = v_ind_dt
    LIMIT 1;

    IF v_pp IS NULL THEN
        SELECT p.close_price
        INTO v_pp
        FROM prices p
        WHERE p.security_id = p_security_id
          AND p.timeframe_id = p_timeframe_id
          AND p.dt <= v_ind_dt
        ORDER BY p.dt DESC
        LIMIT 1;
    END IF;

    IF v_pp IS NULL OR v_pp <= 0 THEN
        RETURN;
    END IF;

    bar_dt := v_ind_dt;
    ind_value := v_ind_val;
    close_price := v_pp;
    RETURN NEXT;
END;
$$;

COMMENT ON FUNCTION logic_bar_data_at(INTEGER, INTEGER, INTEGER, TEXT, TIMESTAMP) IS
'РРЅРґРёРєР°С‚РѕСЂ Рё close РЅР° РєРѕРЅРєСЂРµС‚РЅРѕР№ Р·Р°РєСЂС‹С‚РѕР№ СЃРІРµС‡Рµ (exact dt, Р·Р°С‚РµРј fallback РІ РїСЂРµРґРµР»Р°С… РѕРґРЅРѕРіРѕ Р±Р°СЂР°)';

CREATE OR REPLACE FUNCTION logic_calc_open_quantity(p_balance NUMERIC,
    p_position_size_pct NUMERIC,
    p_price NUMERIC,
    p_lot_size INTEGER DEFAULT 1,
    p_max_order_amount NUMERIC DEFAULT NULL)
RETURNS INTEGER
LANGUAGE plpgsql IMMUTABLE AS $$
DECLARE
    v_amount NUMERIC;
    v_raw INTEGER;
    v_lot INTEGER;
    v_qty INTEGER;
BEGIN
    IF p_balance IS NULL OR p_balance <= 0 THEN
        RETURN 0;
    END IF;
    IF p_price IS NULL OR p_price <= 0 THEN
        RETURN 0;
    END IF;
    IF p_position_size_pct IS NULL OR p_position_size_pct <= 0 THEN
        RETURN 0;
    END IF;
    v_lot := GREATEST(1, COALESCE(p_lot_size, 1));
    v_amount := p_balance * (p_position_size_pct / 100.0);
    IF p_max_order_amount IS NOT NULL AND p_max_order_amount > 0 THEN
        v_amount := LEAST(v_amount, p_max_order_amount);
    END IF;
    v_raw := floor(v_amount / p_price)::INTEGER;
    -- РћРєСЂСѓРіР»РµРЅРёРµ РІРЅРёР· РґРѕ С†РµР»РѕРіРѕ С‡РёСЃР»Р° Р»РѕС‚РѕРІ
    v_qty := (v_raw / v_lot) * v_lot;
    IF v_qty >= v_lot THEN
        RETURN v_qty;
    END IF;
    RETURN 0;
END;
$$;

COMMENT ON FUNCTION logic_calc_open_quantity(NUMERIC, NUMERIC, NUMERIC, INTEGER, NUMERIC) IS
'Р›РѕС‚: % Р±Р°Р·С‹ / С†РµРЅР° (РѕРїС†. РїРѕС‚РѕР»РѕРє СЃСѓРјРјС‹), РІРЅРёР· РґРѕ lot_size';

-- MTM РІС‹Р±СЂР°РЅРЅРѕРіРѕ РґРµРЅРµР¶РЅРѕРіРѕ С„РѕРЅРґР° Р»РѕРіРёРєРё (РґР»СЏ РёСЃРєР»СЋС‡РµРЅРёСЏ РёР· Р±Р°Р·С‹ В«РІРµСЃСЊ РїРѕСЂС‚С„РµР»СЊВ»).

CREATE OR REPLACE FUNCTION logic_cash_set_param(p_logic_id INTEGER,
    p_balance NUMERIC)
RETURNS NUMERIC
LANGUAGE plpgsql AS $$
DECLARE
    v_account_type VARCHAR;
    v_account_id INTEGER;
    v_cash NUMERIC;
BEGIN
    SELECT lower(COALESCE(a.account_type, 'fake')), l.account_id
    INTO v_account_type, v_account_id
    FROM logics l
    LEFT JOIN accounts a ON a.id = l.account_id
    WHERE l.id = p_logic_id;

    IF NOT FOUND THEN
        RETURN p_balance;
    END IF;

    IF v_account_type = 'fake' THEN
        SELECT COALESCE(terminal_cash, 0) INTO v_cash FROM accounts WHERE id = v_account_id;
        v_cash := COALESCE(v_cash, 0);
        PERFORM logic_upsert_param(p_logic_id, 'current_balance', v_cash::TEXT, 'money');
        RETURN v_cash;
    END IF;

    PERFORM logic_upsert_param(p_logic_id, 'current_balance', COALESCE(p_balance, 0)::TEXT, 'money');
    RETURN p_balance;
END;
$$;

COMMENT ON FUNCTION logic_cash_set_param(INTEGER, NUMERIC) IS
'#1065: fake вЂ” current_balance = accounts.terminal_cash; real вЂ” current_balance = Р°СЂРіСѓРјРµРЅС‚.';

-- #1065: СЂСѓС‡РЅР°СЏ РїСЂР°РІРєР° РѕСЃС‚Р°С‚РєР° СЃС‡С‘С‚Р° РІ UI в†’ РѕР±РЅРѕРІРёС‚СЊ Р·РµСЂРєР°Р»Рѕ Сѓ РІСЃРµС… Р»РѕРіРёРє СЃС‡С‘С‚Р°.

CREATE OR REPLACE FUNCTION logic_check_portfolio_resume(p_logic_id INTEGER,
    p_timeframe_id INTEGER)
RETURNS BOOLEAN
LANGUAGE plpgsql AS $$
DECLARE
    v_logic RECORD;
    v_shadow_pnl NUMERIC;
    v_track NUMERIC;
BEGIN
    SELECT
        COALESCE(portfolio_trading_paused, FALSE) AS paused,
        portfolio_stop_resume_equity AS target,
        portfolio_stop_resume_baseline AS baseline
    INTO v_logic
    FROM logics
    WHERE id = p_logic_id;

    IF NOT FOUND OR NOT v_logic.paused THEN
        RETURN FALSE;
    END IF;
    IF v_logic.target IS NULL OR v_logic.baseline IS NULL THEN
        RETURN FALSE;
    END IF;

    v_shadow_pnl := logic_portfolio_shadow_pnl(p_logic_id);
    v_track := COALESCE(v_logic.baseline, 0) + COALESCE(v_shadow_pnl, 0);

    IF v_track >= COALESCE(v_logic.target, 0) THEN
        UPDATE logics
        SET portfolio_trading_paused = FALSE,
            portfolio_stop_resume_equity = NULL,
            portfolio_stop_resume_baseline = NULL,
            portfolio_stop_resume_at = NULL,
            portfolio_equity_peak = GREATEST(
                COALESCE(portfolio_equity_peak, 0),
                COALESCE(v_logic.target, 0),
                COALESCE(v_track, 0)
            )
        WHERE id = p_logic_id;

        PERFORM logic_trade_log(
            p_logic_id,
            'stop.portfolio_resume',
            format(
                'Р’РѕР·РѕР±РЅРѕРІР»РµРЅРёРµ СЂРµР°Р»СЊРЅРѕР№ С‚РѕСЂРіРѕРІР»Рё РїРѕСЂС‚С„РµР»СЏ (baseline=%s shadow=%s track=%s target=%s)',
                v_logic.baseline, v_shadow_pnl, v_track, v_logic.target
            ),
            jsonb_build_object(
                'baseline', v_logic.baseline,
                'shadow_pnl', v_shadow_pnl,
                'track', v_track,
                'target', v_logic.target
            ),
            NULL,
            p_timeframe_id
        );
        RETURN TRUE;
    END IF;

    RETURN FALSE;
END;
$$;

-- ============================================
-- Linear Take Profit on whole portfolio with renewal (portfolio_ltp_renew)
-- РџРѕСЂРѕРі РІР·РІРµРґРµРЅРёСЏ: track% = (equityв€’initial)/initial >= base_annual_rateГ—РіРѕРґС‹ + TP%
-- РџРёРє (РІСЃРїР»РµСЃРє) С‚СЂРµР№Р»РёС‚СЃСЏ РІРІРµСЂС…; РїСЂРѕРґР°Р¶Р° С‚РѕР»СЊРєРѕ РµСЃР»Рё РѕС‚РєР°С‚ РѕС‚ РїРёРєР° >= TP% (РЅРµ Р»СЋР±РѕР№ С‚РёРє РІРЅРёР·)
-- РџРѕСЃР»Рµ РїСЂРѕРґР°Р¶Рё вЂ” latch: СЃРЅРѕРІР° РІР·РІРѕРґРёС‚СЊ С‚РѕР»СЊРєРѕ РєРѕРіРґР° track% СѓС€С‘Р» РЅРёР¶Рµ arm%
-- Р—Р°С‚РµРј portfolio pause/shadow в†’ renew; СЃР±СЂРѕСЃ armed РїСЂРё track% < base%
-- ============================================

CREATE OR REPLACE FUNCTION logic_check_security_inversion(p_logic_id INTEGER,
    p_security_id INTEGER,
    p_timeframe_id INTEGER)
RETURNS BOOLEAN
LANGUAGE plpgsql AS $$
DECLARE
    v_ls RECORD;
    v_shadow_track NUMERIC;
    v_resumed BOOLEAN := FALSE;
    v_paused_long BOOLEAN;
    v_paused_short BOOLEAN;
    v_was_inverted BOOLEAN;
    v_now_inverted BOOLEAN;
BEGIN
    -- Recovery only (like logic_check_security_resume). New SL в†’ process_logic_stops.
    SELECT
        COALESCE(ls.real_trading_inverted, FALSE) AS inverted,
        COALESCE(ls.real_trading_paused_long, FALSE) AS paused_long,
        COALESCE(ls.real_trading_paused_short, FALSE) AS paused_short,
        ls.stop_resume_equity_long,
        ls.stop_resume_baseline_long,
        ls.stop_resume_equity_short,
        ls.stop_resume_baseline_short,
        COALESCE(ls.real_trading_paused, FALSE) AS paused_paper,
        ls.stop_resume_equity,
        ls.stop_resume_baseline
    INTO v_ls
    FROM logic_securities ls
    WHERE ls.logic_id = p_logic_id
      AND ls.security_id = p_security_id;

    IF NOT FOUND THEN
        RETURN FALSE;
    END IF;

    v_paused_long := v_ls.paused_long;
    v_paused_short := v_ls.paused_short;

    IF v_ls.paused_paper AND NOT v_paused_long AND NOT v_paused_short THEN
        v_paused_long := TRUE;
        v_paused_short := TRUE;
        IF v_ls.stop_resume_equity_long IS NULL THEN
            v_ls.stop_resume_equity_long := v_ls.stop_resume_equity;
            v_ls.stop_resume_baseline_long := v_ls.stop_resume_baseline;
        END IF;
        IF v_ls.stop_resume_equity_short IS NULL THEN
            v_ls.stop_resume_equity_short := v_ls.stop_resume_equity;
            v_ls.stop_resume_baseline_short := v_ls.stop_resume_baseline;
        END IF;
    END IF;

    IF v_paused_long
       AND v_ls.stop_resume_equity_long IS NOT NULL
       AND v_ls.stop_resume_baseline_long IS NOT NULL THEN
        v_shadow_track := logic_security_side_track_value(
            p_logic_id, p_security_id, p_timeframe_id, TRUE, 'long'
        );
        IF COALESCE(v_ls.stop_resume_baseline_long, 0) + COALESCE(v_shadow_track, 0)
           >= COALESCE(v_ls.stop_resume_equity_long, 0) THEN
            v_was_inverted := v_ls.inverted;
            v_now_inverted := NOT v_was_inverted;
            UPDATE logic_securities
            SET real_trading_paused_long = FALSE,
                stop_resume_equity_long = NULL,
                stop_resume_baseline_long = NULL,
                stop_resume_triggered_at_long = NULL,
                real_trading_inverted = v_now_inverted,
                real_trading_paused = COALESCE(real_trading_paused_short, FALSE),
                stop_resume_equity = CASE
                    WHEN COALESCE(real_trading_paused_short, FALSE) THEN stop_resume_equity
                    ELSE NULL
                END,
                stop_resume_baseline = CASE
                    WHEN COALESCE(real_trading_paused_short, FALSE) THEN stop_resume_baseline
                    ELSE NULL
                END,
                stop_resume_triggered_at = CASE
                    WHEN COALESCE(real_trading_paused_short, FALSE) THEN stop_resume_triggered_at
                    ELSE NULL
                END
            WHERE logic_id = p_logic_id
              AND security_id = p_security_id;
            PERFORM logic_trade_log(
                p_logic_id, 'stop.inversion_toggle',
                format(
                    'SL inversion sec=%s long: shadowв†’РЅРѕР»СЊ в†’ inverted %sв†’%s',
                    p_security_id, v_was_inverted, v_now_inverted
                ),
                jsonb_build_object(
                    'security_id', p_security_id,
                    'position_side', 'long',
                    'inverted_before', v_was_inverted,
                    'inverted_after', v_now_inverted,
                    'shadow_track', v_shadow_track,
                    'target', v_ls.stop_resume_equity_long
                ),
                p_security_id, p_timeframe_id
            );
            v_resumed := TRUE;
            v_ls.inverted := v_now_inverted;
            v_paused_long := FALSE;
        END IF;
    END IF;

    IF v_paused_short
       AND v_ls.stop_resume_equity_short IS NOT NULL
       AND v_ls.stop_resume_baseline_short IS NOT NULL THEN
        v_shadow_track := logic_security_side_track_value(
            p_logic_id, p_security_id, p_timeframe_id, TRUE, 'short'
        );
        IF COALESCE(v_ls.stop_resume_baseline_short, 0) + COALESCE(v_shadow_track, 0)
           >= COALESCE(v_ls.stop_resume_equity_short, 0) THEN
            v_was_inverted := v_ls.inverted;
            v_now_inverted := NOT v_was_inverted;
            UPDATE logic_securities
            SET real_trading_paused_short = FALSE,
                stop_resume_equity_short = NULL,
                stop_resume_baseline_short = NULL,
                stop_resume_triggered_at_short = NULL,
                real_trading_inverted = v_now_inverted,
                real_trading_paused = COALESCE(real_trading_paused_long, FALSE),
                stop_resume_equity = CASE
                    WHEN COALESCE(real_trading_paused_long, FALSE) THEN stop_resume_equity
                    ELSE NULL
                END,
                stop_resume_baseline = CASE
                    WHEN COALESCE(real_trading_paused_long, FALSE) THEN stop_resume_baseline
                    ELSE NULL
                END,
                stop_resume_triggered_at = CASE
                    WHEN COALESCE(real_trading_paused_long, FALSE) THEN stop_resume_triggered_at
                    ELSE NULL
                END
            WHERE logic_id = p_logic_id
              AND security_id = p_security_id;
            PERFORM logic_trade_log(
                p_logic_id, 'stop.inversion_toggle',
                format(
                    'SL inversion sec=%s short: shadowв†’РЅРѕР»СЊ в†’ inverted %sв†’%s',
                    p_security_id, v_was_inverted, v_now_inverted
                ),
                jsonb_build_object(
                    'security_id', p_security_id,
                    'position_side', 'short',
                    'inverted_before', v_was_inverted,
                    'inverted_after', v_now_inverted,
                    'shadow_track', v_shadow_track,
                    'target', v_ls.stop_resume_equity_short
                ),
                p_security_id, p_timeframe_id
            );
            v_resumed := TRUE;
        END IF;
    END IF;

    RETURN v_resumed;
END;
$$;

COMMENT ON FUNCTION logic_check_security_inversion(INTEGER, INTEGER, INTEGER) IS
'security_inversion: per side shadowв†’peak/zero в†’ unpause that side + toggle real_trading_inverted.';

CREATE OR REPLACE FUNCTION logic_close_all_positions_at_market(p_logic_id INTEGER,
    p_except_cash_funds BOOLEAN DEFAULT FALSE,
    p_post_broker BOOLEAN DEFAULT TRUE,
    p_trade_reason TEXT DEFAULT NULL,
    p_sold JSONB DEFAULT NULL)
RETURNS JSONB
LANGUAGE plpgsql AS $$
DECLARE
    v_logic RECORD;
    v_tf_id INTEGER;
    v_balance NUMERIC;
    v_side_close_id INTEGER;
    v_action_long_id INTEGER;
    v_action_short_id INTEGER;
    v_sec RECORD;
    v_long_qty NUMERIC;
    v_short_qty NUMERIC;
    v_price NUMERIC;
    v_trade_id BIGINT;
    v_closed INTEGER := 0;
    v_skipped INTEGER := 0;
    v_errors JSONB := '[]'::jsonb;
    v_bar_dt TIMESTAMP;
    v_reason TEXT;
    v_quantity INTEGER;
    v_notional NUMERIC;
    v_is_simulated BOOLEAN;
    v_broker_order_id TEXT;
    v_status TEXT;
    v_note TEXT;
    v_figi TEXT;
    v_order JSONB;
    v_commission NUMERIC;
    v_direction TEXT;
    v_action_id INTEGER;
    v_close_idx INTEGER := 0;
    v_fill_price NUMERIC;
    v_sold_row JSONB;
    v_books_skip BOOLEAN;
    v_cash_before NUMERIC;
    v_demo_delta NUMERIC;
BEGIN
    v_reason := COALESCE(
        NULLIF(btrim(p_trade_reason), ''),
        CASE WHEN p_except_cash_funds THEN 'eod.close' ELSE 'market:close_all' END
    );

    SELECT l.id, l.account_id, lower(COALESCE(a.account_type, 'fake')) AS account_type
    INTO v_logic
    FROM logics l
    JOIN accounts a ON a.id = l.account_id
    WHERE l.id = p_logic_id
      AND a.is_active = TRUE;

    IF NOT FOUND THEN
        RETURN jsonb_build_object(
            'ok', FALSE,
            'error', 'Р›РѕРіРёРєР° РЅРµ РЅР°Р№РґРµРЅР° РёР»Рё СЃС‡С‘С‚ РЅРµР°РєС‚РёРІРµРЅ',
            'closed', 0
        );
    END IF;

    v_tf_id := logic_resolve_timeframe_id(p_logic_id);
    IF v_tf_id IS NULL THEN
        RETURN jsonb_build_object(
            'ok', FALSE,
            'error', 'РќРµ Р·Р°РґР°РЅ timeframe РІ logic_params',
            'closed', 0
        );
    END IF;

    SELECT id INTO v_side_close_id FROM sides WHERE name = 'Close' LIMIT 1;
    SELECT id INTO v_action_long_id FROM actions WHERE name = 'Long' LIMIT 1;
    SELECT id INTO v_action_short_id FROM actions WHERE name = 'Short' LIMIT 1;

    IF v_side_close_id IS NULL OR v_action_long_id IS NULL OR v_action_short_id IS NULL THEN
        RETURN jsonb_build_object(
            'ok', FALSE,
            'error', 'РЎРїСЂР°РІРѕС‡РЅРёРєРё sides/actions РЅРµ РЅР°СЃС‚СЂРѕРµРЅС‹',
            'closed', 0
        );
    END IF;

    v_balance := logic_ensure_balance(p_logic_id);
    v_is_simulated := v_logic.account_type = 'fake';

    FOR v_sec IN
        SELECT DISTINCT lt.security_id
        FROM logic_trades lt
        WHERE lt.logic_id = p_logic_id
          AND NOT lt.is_shadow
          AND NOT lt.is_test
          AND lt.status IN ('filled', 'submitted')
          AND (
              NOT p_except_cash_funds
              OR NOT EXISTS (
                  SELECT 1 FROM security_prefixes sp
                  WHERE sp.security_id = lt.security_id
                    AND upper(sp.prefix) IN ('TMON', 'LQDT', 'SBMM')
              )
          )
    LOOP
        v_long_qty := logic_long_position_qty(p_logic_id, v_sec.security_id, FALSE);
        v_short_qty := logic_short_position_qty(p_logic_id, v_sec.security_id, FALSE);

        IF v_long_qty <= 0 AND v_short_qty <= 0 THEN
            CONTINUE;
        END IF;

        v_price := logic_ensure_security_market_price(p_logic_id, v_sec.security_id, v_tf_id);
        IF v_price IS NULL OR v_price <= 0 THEN
            v_skipped := v_skipped + 1;
            v_errors := v_errors || jsonb_build_array(
                jsonb_build_object(
                    'security_id', v_sec.security_id,
                    'reason', 'РќРµ СѓРґР°Р»РѕСЃСЊ РїРѕР»СѓС‡РёС‚СЊ С†РµРЅСѓ (Р·Р°РіСЂСѓР·РєР° Рё fallback РЅРµ РґР°Р»Рё СЂРµР·СѓР»СЊС‚Р°С‚)'
                )
            );
            CONTINUE;
        END IF;

        SELECT sp.tbank_figi INTO v_figi
        FROM security_prefixes sp
        WHERE sp.security_id = v_sec.security_id
          AND sp.tbank_figi IS NOT NULL
        ORDER BY sp.exchange_id
        LIMIT 1;

        IF v_long_qty > 0 THEN
            v_close_idx := v_close_idx + 1;
            v_bar_dt := clock_timestamp() + (v_close_idx * interval '1 millisecond');
            v_quantity := floor(v_long_qty)::INTEGER;
            IF v_quantity < 1 THEN
                v_skipped := v_skipped + 1;
                CONTINUE;
            END IF;

            v_action_id := v_action_long_id;
            v_direction := 'SELL';
            v_broker_order_id := NULL;
            v_status := 'filled';
            v_note := NULL;
            v_commission := 0;
            v_order := NULL;
            v_books_skip := FALSE;

            IF NOT v_is_simulated AND p_post_broker THEN
                BEGIN
                    IF v_figi IS NULL THEN
                        v_status := 'rejected';
                        v_note := 'РќРµС‚ tbank_figi РґР»СЏ Р±СѓРјР°РіРё';
                    ELSE
                        v_order := tbank_post_order(
                            v_logic.account_id, v_figi, v_quantity, v_price, v_direction,
                            logic_order_execution(p_logic_id)
                        );
                        v_broker_order_id := COALESCE(
                            v_order->>'orderId',
                            v_order->>'order_id',
                            v_order->'orderState'->>'orderId'
                        );
                        v_status := tbank_trade_status_from_post_order(v_order);
                        v_commission := tbank_order_commission(v_order);
                        IF v_commission <= 0 AND v_broker_order_id IS NOT NULL THEN
                            BEGIN
                                v_order := tbank_get_order_state(
                                    v_logic.account_id, v_broker_order_id
                                );
                                v_commission := tbank_order_commission(v_order);
                            EXCEPTION
                                WHEN OTHERS THEN
                                    NULL;
                            END;
                        END IF;
                        v_fill_price := tbank_order_unit_price(v_order);
                        IF v_fill_price IS NOT NULL AND v_fill_price > 0 THEN
                            v_price := v_fill_price;
                        END IF;
                        IF v_status = 'rejected' THEN
                            v_note := v_order::TEXT;
                        END IF;
                    END IF;
                EXCEPTION
                    WHEN undefined_function THEN
                        v_status := 'rejected';
                        v_note := 'tbank_post_order РЅРµРґРѕСЃС‚СѓРїРµРЅ (РЅРµС‚ HTTP-СЂР°СЃС€РёСЂРµРЅРёСЏ)';
                    WHEN OTHERS THEN
                        v_status := 'rejected';
                        v_note := SQLERRM;
                END;
            ELSIF NOT v_is_simulated AND NOT p_post_broker THEN
                -- books-only: account sell-all closes all; Node close-all only sold[].
                v_sold_row := logic_sold_fill_for_figi(p_sold, v_figi);
                IF v_sold_row IS NULL
                   AND COALESCE(p_trade_reason, '') = 'market:close_all_node' THEN
                    v_books_skip := TRUE;
                    v_skipped := v_skipped + 1;
                    v_errors := v_errors || jsonb_build_array(
                        jsonb_build_object(
                            'security_id', v_sec.security_id,
                            'action', 'Long',
                            'reason', 'Р±СЂРѕРєРµСЂ: Р·Р°СЏРІРєР° РЅРµ РёСЃРїРѕР»РЅРµРЅР° (Node)'
                        )
                    );
                ELSE
                    IF v_sold_row IS NOT NULL THEN
                        v_order := v_sold_row->'order';
                        IF NULLIF(v_sold_row->>'price', '')::NUMERIC > 0 THEN
                            v_price := (v_sold_row->>'price')::NUMERIC;
                        END IF;
                        v_fill_price := tbank_order_unit_price(v_order);
                        IF v_fill_price IS NOT NULL AND v_fill_price > 0 THEN
                            v_price := v_fill_price;
                        END IF;
                        v_commission := COALESCE(tbank_order_commission(v_order), 0);
                        v_broker_order_id := COALESCE(
                            v_order->>'orderId',
                            v_order->>'order_id',
                            v_order->'orderState'->>'orderId'
                        );
                    END IF;
                    v_status := 'filled';
                    v_note := 'books_only: broker already flat';
                END IF;
            END IF;

            IF NOT v_books_skip THEN
            IF v_is_simulated THEN
                SELECT COALESCE(terminal_cash, 0) INTO v_cash_before
                FROM accounts
                WHERE id = v_logic.account_id
                FOR UPDATE;
            ELSE
                v_cash_before := NULL;
            END IF;

            INSERT INTO logic_trades (
                logic_id, account_id, security_id, timeframe_id,
                side_id, action_id, position_event, signal_kind, signal_formula,
                quantity, price, commission, bar_dt, is_simulated, is_fictitious, is_shadow, is_test,
                trade_reason, broker_order_id, status, note
            )
            VALUES (
                p_logic_id, v_logic.account_id, v_sec.security_id, v_tf_id,
                v_side_close_id, v_action_id, 'close', 'counter', v_reason,
                v_quantity, v_price, COALESCE(v_commission, 0), v_bar_dt, v_is_simulated, FALSE, FALSE, FALSE,
                v_reason, v_broker_order_id, v_status, v_note
            )
            RETURNING id INTO v_trade_id;

            IF v_status <> 'rejected' THEN
                IF v_is_simulated AND v_balance IS NOT NULL THEN
                    v_balance := logic_trade_finalize(v_trade_id, v_balance);
                ELSE
                    PERFORM logic_trade_finalize(v_trade_id, v_balance);
                END IF;

                IF v_is_simulated THEN
                    SELECT COALESCE(commission, 0) INTO v_commission
                    FROM logic_trades WHERE id = v_trade_id;
                    -- Close Long: РїСЂРѕРґР°С‘Рј Р»РѕРЅРі в†’ +РІС‹СЂСѓС‡РєР°, -РєРѕРјРёСЃСЃРёСЏ.
                    v_demo_delta := (v_quantity * v_price) - COALESCE(v_commission, 0);
                    UPDATE accounts
                    SET terminal_cash = COALESCE(v_cash_before, 0) + v_demo_delta,
                        updated_at = CURRENT_TIMESTAMP
                    WHERE id = v_logic.account_id;
                    v_balance := COALESCE(v_cash_before, 0) + v_demo_delta;
                    PERFORM logic_mirror_account_cash(v_logic.account_id);
                ELSE
                    v_balance := logic_cash_set_param(p_logic_id, v_balance);
                END IF;

                v_closed := v_closed + 1;
                PERFORM logic_trade_log(
                    p_logic_id,
                    'trade.closed_market',
                    format('Р—Р°РєСЂС‹С‚РёРµ long #%s qty=%s price=%s', v_trade_id, v_quantity, v_price),
                    jsonb_build_object(
                        'trade_id', v_trade_id,
                        'security_id', v_sec.security_id,
                        'action', 'Long',
                        'quantity', v_quantity,
                        'price', v_price,
                        'status', v_status,
                        'post_broker', p_post_broker,
                        'trade_reason', v_reason
                    ),
                    v_sec.security_id,
                    v_tf_id
                );
            ELSE
                v_skipped := v_skipped + 1;
                v_errors := v_errors || jsonb_build_array(
                    jsonb_build_object(
                        'security_id', v_sec.security_id,
                        'action', 'Long',
                        'reason', COALESCE(v_note, 'rejected')
                    )
                );
            END IF;
            END IF;
        END IF;

        IF v_short_qty > 0 THEN
            v_close_idx := v_close_idx + 1;
            v_bar_dt := clock_timestamp() + (v_close_idx * interval '1 millisecond');
            v_quantity := floor(v_short_qty)::INTEGER;
            IF v_quantity < 1 THEN
                v_skipped := v_skipped + 1;
                CONTINUE;
            END IF;

            v_action_id := v_action_short_id;
            v_direction := 'BUY';
            v_broker_order_id := NULL;
            v_status := 'filled';
            v_note := NULL;
            v_commission := 0;
            v_order := NULL;
            v_books_skip := FALSE;

            IF NOT v_is_simulated AND p_post_broker THEN
                BEGIN
                    IF v_figi IS NULL THEN
                        v_status := 'rejected';
                        v_note := 'РќРµС‚ tbank_figi РґР»СЏ Р±СѓРјР°РіРё';
                    ELSE
                        v_order := tbank_post_order(
                            v_logic.account_id, v_figi, v_quantity, v_price, v_direction,
                            logic_order_execution(p_logic_id)
                        );
                        v_broker_order_id := COALESCE(
                            v_order->>'orderId',
                            v_order->>'order_id',
                            v_order->'orderState'->>'orderId'
                        );
                        v_status := tbank_trade_status_from_post_order(v_order);
                        v_commission := tbank_order_commission(v_order);
                        IF v_commission <= 0 AND v_broker_order_id IS NOT NULL THEN
                            BEGIN
                                v_order := tbank_get_order_state(
                                    v_logic.account_id, v_broker_order_id
                                );
                                v_commission := tbank_order_commission(v_order);
                            EXCEPTION
                                WHEN OTHERS THEN
                                    NULL;
                            END;
                        END IF;
                        v_fill_price := tbank_order_unit_price(v_order);
                        IF v_fill_price IS NOT NULL AND v_fill_price > 0 THEN
                            v_price := v_fill_price;
                        END IF;
                        IF v_status = 'rejected' THEN
                            v_note := v_order::TEXT;
                        END IF;
                    END IF;
                EXCEPTION
                    WHEN undefined_function THEN
                        v_status := 'rejected';
                        v_note := 'tbank_post_order РЅРµРґРѕСЃС‚СѓРїРµРЅ (РЅРµС‚ HTTP-СЂР°СЃС€РёСЂРµРЅРёСЏ)';
                    WHEN OTHERS THEN
                        v_status := 'rejected';
                        v_note := SQLERRM;
                END;
            ELSIF NOT v_is_simulated AND NOT p_post_broker THEN
                v_sold_row := logic_sold_fill_for_figi(p_sold, v_figi);
                IF v_sold_row IS NULL
                   AND COALESCE(p_trade_reason, '') = 'market:close_all_node' THEN
                    v_books_skip := TRUE;
                    v_skipped := v_skipped + 1;
                    v_errors := v_errors || jsonb_build_array(
                        jsonb_build_object(
                            'security_id', v_sec.security_id,
                            'action', 'Short',
                            'reason', 'Р±СЂРѕРєРµСЂ: Р·Р°СЏРІРєР° РЅРµ РёСЃРїРѕР»РЅРµРЅР° (Node)'
                        )
                    );
                ELSE
                    IF v_sold_row IS NOT NULL THEN
                        v_order := v_sold_row->'order';
                        IF NULLIF(v_sold_row->>'price', '')::NUMERIC > 0 THEN
                            v_price := (v_sold_row->>'price')::NUMERIC;
                        END IF;
                        v_fill_price := tbank_order_unit_price(v_order);
                        IF v_fill_price IS NOT NULL AND v_fill_price > 0 THEN
                            v_price := v_fill_price;
                        END IF;
                        v_commission := COALESCE(tbank_order_commission(v_order), 0);
                        v_broker_order_id := COALESCE(
                            v_order->>'orderId',
                            v_order->>'order_id',
                            v_order->'orderState'->>'orderId'
                        );
                    END IF;
                    v_status := 'filled';
                    v_note := 'books_only: broker already flat';
                END IF;
            END IF;

            IF NOT v_books_skip THEN
            IF v_is_simulated THEN
                SELECT COALESCE(terminal_cash, 0) INTO v_cash_before
                FROM accounts
                WHERE id = v_logic.account_id
                FOR UPDATE;
            ELSE
                v_cash_before := NULL;
            END IF;

            INSERT INTO logic_trades (
                logic_id, account_id, security_id, timeframe_id,
                side_id, action_id, position_event, signal_kind, signal_formula,
                quantity, price, commission, bar_dt, is_simulated, is_fictitious, is_shadow, is_test,
                trade_reason, broker_order_id, status, note
            )
            VALUES (
                p_logic_id, v_logic.account_id, v_sec.security_id, v_tf_id,
                v_side_close_id, v_action_id, 'close', 'counter', v_reason,
                v_quantity, v_price, COALESCE(v_commission, 0), v_bar_dt, v_is_simulated, FALSE, FALSE, FALSE,
                v_reason, v_broker_order_id, v_status, v_note
            )
            RETURNING id INTO v_trade_id;

            IF v_status <> 'rejected' THEN
                IF v_is_simulated AND v_balance IS NOT NULL THEN
                    v_balance := logic_trade_finalize(v_trade_id, v_balance);
                ELSE
                    PERFORM logic_trade_finalize(v_trade_id, v_balance);
                END IF;

                IF v_is_simulated THEN
                    SELECT COALESCE(commission, 0) INTO v_commission
                    FROM logic_trades WHERE id = v_trade_id;
                    -- Close Short: РѕС‚РєСѓРї С€РѕСЂС‚Р° в†’ -СЃСѓРјРјР°, -РєРѕРјРёСЃСЃРёСЏ.
                    v_demo_delta := -((v_quantity * v_price) + COALESCE(v_commission, 0));
                    UPDATE accounts
                    SET terminal_cash = COALESCE(v_cash_before, 0) + v_demo_delta,
                        updated_at = CURRENT_TIMESTAMP
                    WHERE id = v_logic.account_id;
                    v_balance := COALESCE(v_cash_before, 0) + v_demo_delta;
                    PERFORM logic_mirror_account_cash(v_logic.account_id);
                ELSE
                    v_balance := logic_cash_set_param(p_logic_id, v_balance);
                END IF;

                v_closed := v_closed + 1;
                PERFORM logic_trade_log(
                    p_logic_id,
                    'trade.closed_market',
                    format('Р—Р°РєСЂС‹С‚РёРµ short #%s qty=%s price=%s', v_trade_id, v_quantity, v_price),
                    jsonb_build_object(
                        'trade_id', v_trade_id,
                        'security_id', v_sec.security_id,
                        'action', 'Short',
                        'quantity', v_quantity,
                        'price', v_price,
                        'status', v_status,
                        'post_broker', p_post_broker,
                        'trade_reason', v_reason
                    ),
                    v_sec.security_id,
                    v_tf_id
                );
            ELSE
                v_skipped := v_skipped + 1;
                v_errors := v_errors || jsonb_build_array(
                    jsonb_build_object(
                        'security_id', v_sec.security_id,
                        'action', 'Short',
                        'reason', COALESCE(v_note, 'rejected')
                    )
                );
            END IF;
            END IF;
        END IF;
    END LOOP;

    RETURN jsonb_build_object(
        'ok', TRUE,
        'closed', v_closed,
        'skipped', v_skipped,
        'errors', v_errors,
        'post_broker', p_post_broker,
        'trade_reason', v_reason
    );
END;
$$;

COMMENT ON FUNCTION logic_close_all_positions_at_market(INTEGER, BOOLEAN, BOOLEAN, TEXT, JSONB) IS
'Р—Р°РєСЂС‹С‚РёРµ long/short: p_post_broker=FALSE вЂ” С‚РѕР»СЊРєРѕ РєРЅРёРіР° (account sell-all / Node close-all). market:close_all_node Р·Р°РєСЂС‹РІР°РµС‚ С‚РѕР»СЊРєРѕ figi РёР· p_sold.';

-- @include sql/logic_opt.sql
-- ============================================
-- OPT() on-the-fly formula optimization (live + backtest)
-- Challenger books: opt_lane <> '', paper only, no broker
-- Backtest: is_test=TRUE, run_id set; promote cursor on logic_backtest_runs
-- ============================================

-- Nested @CODE(...OPT(...)) parsers (also in logic_trade_runner.sql; kept here so 02 sync applies them)

CREATE OR REPLACE FUNCTION logic_close_futures_near_expiry(p_logic_id INTEGER,
    p_as_of_date DATE DEFAULT CURRENT_DATE)
RETURNS JSONB
LANGUAGE plpgsql AS $$
DECLARE
    v_threshold INTEGER;
    v_sec RECORD;
    v_days_left INTEGER;
    v_n INTEGER;
    v_closed INTEGER := 0;
    v_checked INTEGER := 0;
BEGIN
    IF NOT get_logic_param_boolean(p_logic_id, 'sell_futures_before_expiry', FALSE) THEN
        RETURN jsonb_build_object('ok', TRUE, 'closed', 0, 'checked', 0, 'reason', 'disabled');
    END IF;

    v_threshold := GREATEST(
        0,
        ROUND(COALESCE(
            get_logic_param_numeric(p_logic_id, 'sell_futures_days_before_expiry', 3),
            3
        ))::INTEGER
    );

    FOR v_sec IN
        SELECT DISTINCT lt.security_id
        FROM logic_trades lt
        WHERE lt.logic_id = p_logic_id
          AND COALESCE(lt.is_test, FALSE) = FALSE
          AND lt.status IN ('filled', 'submitted')
          AND logic_security_is_futures(lt.security_id)
    LOOP
        IF COALESCE(logic_long_position_qty(p_logic_id, v_sec.security_id, FALSE), 0) <= 0
           AND COALESCE(logic_short_position_qty(p_logic_id, v_sec.security_id, FALSE), 0) <= 0
           AND COALESCE(logic_long_position_qty(p_logic_id, v_sec.security_id, TRUE), 0) <= 0
           AND COALESCE(logic_short_position_qty(p_logic_id, v_sec.security_id, TRUE), 0) <= 0
        THEN
            CONTINUE;
        END IF;

        v_checked := v_checked + 1;
        v_days_left := logic_futures_days_to_expiry(v_sec.security_id, p_as_of_date);
        IF v_days_left IS NULL OR v_days_left > v_threshold THEN
            CONTINUE;
        END IF;

        v_n := logic_close_security_positions_market(
            p_logic_id, v_sec.security_id, FALSE, 'futures_expiry:close'
        );
        v_closed := v_closed + COALESCE(v_n, 0);
        v_n := logic_close_security_positions_market(
            p_logic_id, v_sec.security_id, TRUE, 'futures_expiry:close'
        );
        v_closed := v_closed + COALESCE(v_n, 0);
    END LOOP;

    RETURN jsonb_build_object(
        'ok', TRUE,
        'closed', v_closed,
        'checked', v_checked,
        'days_threshold', v_threshold,
        'as_of_date', p_as_of_date
    );
END;
$$;

COMMENT ON FUNCTION logic_close_futures_near_expiry(INTEGER, DATE) IS
'Р‘РѕР№: РЅР° EOD Р·Р°РєСЂС‹С‚СЊ РѕС‚РєСЂС‹С‚С‹Рµ С„СЊСЋС‡РµСЂСЃС‹ СЃ days_to_expiry в‰¤ sell_futures_days_before_expiry';

-- Р–РёРІРѕР№ Р±РѕР№: Р·Р°РєСЂС‹С‚СЊ РІСЃРµ РїРѕР·РёС†РёРё РєСЂРѕРјРµ TMON/LQDT/SBMM.

