COMMENT ON FUNCTION logic_close_positions_eod_except_funds(INTEGER) IS
'Р‘РѕР№: Р·Р°РєСЂС‹С‚СЊ РїРѕР·РёС†РёРё РІ РєРѕРЅС†Рµ РґРЅСЏ, РєСЂРѕРјРµ РґРµРЅРµР¶РЅС‹С… С„РѕРЅРґРѕРІ TMON/LQDT/SBMM';

-- @include sql/logic_backtest_runner.sql (СЃРј. sql/logic_backtest_runner.sql вЂ” РґСѓР±Р»РёСЂСѓРµС‚СЃСЏ РЅРёР¶Рµ)
-- ============================================
-- Historical backtest runner (is_test=TRUE book)
-- ============================================

CREATE OR REPLACE FUNCTION logic_close_security_positions_market(p_logic_id INTEGER,
    p_security_id INTEGER,
    p_is_shadow BOOLEAN DEFAULT FALSE,
    p_reason TEXT DEFAULT NULL,
    p_position_side TEXT DEFAULT NULL)
RETURNS INTEGER
LANGUAGE plpgsql AS $$
DECLARE
    v_result JSONB;
    v_closed INTEGER := 0;
    v_closed_long INTEGER := 0;
    v_closed_short INTEGER := 0;
    v_long_qty NUMERIC;
    v_short_qty NUMERIC;
    v_tf_id INTEGER;
    v_logic RECORD;
    v_balance NUMERIC;
    v_side_close_id INTEGER;
    v_action_long_id INTEGER;
    v_action_short_id INTEGER;
    v_price NUMERIC;
    v_trade_id BIGINT;
    v_quantity INTEGER;
    v_bar_dt TIMESTAMP;
    v_formula TEXT;
    v_notional NUMERIC;
    v_is_simulated BOOLEAN;
    v_close_idx INTEGER := 0;
    v_side TEXT;
    v_close_long BOOLEAN := TRUE;
    v_close_short BOOLEAN := TRUE;
    v_figi TEXT;
    v_order JSONB;
    v_broker_order_id TEXT;
    v_status TEXT;
    v_note TEXT;
    v_commission NUMERIC;
    v_direction TEXT;
    v_fill_price NUMERIC;
BEGIN
    -- Р”РµРЅРµР¶РЅС‹Р№ С„РѕРЅРґ РѕСЃС‚Р°С‘С‚СЃСЏ РєСѓРїР»РµРЅРЅС‹Рј: РїРѕСЂС‚С„РµР»СЊРЅС‹Р№/Р±СѓРјР°Р¶РЅС‹Р№ SL РЅРµ РїСЂРѕРґР°С‘С‚ TMON/LQDT/SBMM.
    IF logic_is_cash_fund_security(p_security_id) THEN
        RETURN 0;
    END IF;

    v_side := logic_normalize_position_side(p_position_side);
    IF v_side = 'long' THEN
        v_close_short := FALSE;
    ELSIF v_side = 'short' THEN
        v_close_long := FALSE;
    END IF;

    v_formula := COALESCE(NULLIF(btrim(p_reason), ''), 'stop_loss:close');
    v_tf_id := logic_resolve_timeframe_id(p_logic_id);

    SELECT l.id, l.account_id, a.account_type,
           COALESCE(l.use_as_terminal_signal, FALSE) AS use_sig
    INTO v_logic
    FROM logics l
    JOIN accounts a ON a.id = l.account_id
    WHERE l.id = p_logic_id;

    IF NOT FOUND THEN
        RETURN 0;
    END IF;

    SELECT id INTO v_side_close_id FROM sides WHERE name = 'Close' LIMIT 1;
    SELECT id INTO v_action_long_id FROM actions WHERE name = 'Long' LIMIT 1;
    SELECT id INTO v_action_short_id FROM actions WHERE name = 'Short' LIMIT 1;

    v_balance := logic_ensure_balance(p_logic_id);
    v_is_simulated := v_logic.account_type = 'fake';
    v_price := logic_ensure_security_market_price(p_logic_id, p_security_id, v_tf_id);

    IF v_price IS NULL OR v_price <= 0 THEN
        RETURN 0;
    END IF;

    v_long_qty := CASE WHEN v_close_long
        THEN logic_long_position_qty(p_logic_id, p_security_id, p_is_shadow) ELSE 0 END;
    v_short_qty := CASE WHEN v_close_short
        THEN logic_short_position_qty(p_logic_id, p_security_id, p_is_shadow) ELSE 0 END;

    IF v_long_qty > 0 THEN
        v_close_idx := v_close_idx + 1;
        v_bar_dt := clock_timestamp() + (v_close_idx * interval '1 millisecond');
        v_quantity := floor(v_long_qty)::INTEGER;
        IF v_quantity >= 1 THEN
            v_broker_order_id := NULL;
            v_status := 'filled';
            v_note := NULL;
            v_commission := 0;
            v_direction := 'SELL';

            IF NOT p_is_shadow AND NOT v_is_simulated THEN
                BEGIN
                    SELECT sp.tbank_figi INTO v_figi
                    FROM security_prefixes sp
                    WHERE sp.security_id = p_security_id
                      AND sp.tbank_figi IS NOT NULL
                    ORDER BY sp.exchange_id
                    LIMIT 1;

                    IF v_figi IS NULL THEN
                        v_status := 'rejected';
                        v_note := 'РќРµС‚ tbank_figi РґР»СЏ Р±СѓРјР°РіРё';
                    ELSE
                        v_order := tbank_post_order(
                            v_logic.account_id, v_figi, v_quantity, v_price, v_direction,
                            logic_order_execution(p_logic_id)
                        );
                        v_broker_order_id := COALESCE(
                            v_order->>'orderId',
                            v_order->>'order_id',
                            v_order->'orderState'->>'orderId'
                        );
                        v_status := tbank_trade_status_from_post_order(v_order);
                        v_commission := tbank_order_commission(v_order);
                        IF v_commission <= 0 AND v_broker_order_id IS NOT NULL THEN
                            BEGIN
                                v_order := tbank_get_order_state(
                                    v_logic.account_id, v_broker_order_id
                                );
                                v_commission := tbank_order_commission(v_order);
                            EXCEPTION
                                WHEN OTHERS THEN
                                    NULL;
                            END;
                        END IF;
                        v_fill_price := tbank_order_unit_price(v_order);
                        IF v_fill_price IS NOT NULL AND v_fill_price > 0 THEN
                            v_price := v_fill_price;
                        END IF;
                        IF v_status = 'rejected' THEN
                            v_note := left(COALESCE(v_order::TEXT, ''), 500);
                        END IF;
                    END IF;
                EXCEPTION
                    WHEN undefined_function THEN
                        v_status := 'rejected';
                        v_note := 'tbank_post_order РЅРµРґРѕСЃС‚СѓРїРµРЅ';
                    WHEN OTHERS THEN
                        v_status := 'rejected';
                        v_note := SQLERRM;
                END;
            END IF;

            INSERT INTO logic_trades (
                logic_id, account_id, security_id, timeframe_id,
                side_id, action_id, signal_kind, signal_formula,
                quantity, price, commission, bar_dt, is_simulated, is_fictitious, is_shadow, is_test,
                trade_reason, broker_order_id, status, note
            )
            VALUES (
                p_logic_id, v_logic.account_id, p_security_id, v_tf_id,
                v_side_close_id, v_action_long_id, 'counter', v_formula,
                v_quantity, v_price, COALESCE(v_commission, 0), v_bar_dt, v_is_simulated, FALSE, p_is_shadow, FALSE,
                v_formula, v_broker_order_id, v_status, v_note
            )
            RETURNING id INTO v_trade_id;

            IF v_status <> 'rejected' THEN
                IF NOT p_is_shadow AND v_is_simulated AND v_balance IS NOT NULL THEN
                    v_balance := logic_trade_finalize(v_trade_id, v_balance);
                    v_notional := v_quantity * v_price;
                    v_balance := v_balance + v_notional;
                    v_balance := logic_cash_set_param(p_logic_id, v_balance);
                ELSIF NOT p_is_shadow THEN
                    PERFORM logic_trade_finalize(v_trade_id, v_balance);
                ELSE
                    PERFORM logic_trade_finalize(v_trade_id, NULL);
                END IF;
                v_closed := v_closed + 1;
                v_closed_long := v_closed_long + 1;
            END IF;
        END IF;
    END IF;

    IF v_short_qty > 0 THEN
        v_close_idx := v_close_idx + 1;
        v_bar_dt := clock_timestamp() + (v_close_idx * interval '1 millisecond');
        v_quantity := floor(v_short_qty)::INTEGER;
        IF v_quantity >= 1 THEN
            v_broker_order_id := NULL;
            v_status := 'filled';
            v_note := NULL;
            v_commission := 0;
            v_direction := 'BUY';

            IF NOT p_is_shadow AND NOT v_is_simulated THEN
                BEGIN
                    SELECT sp.tbank_figi INTO v_figi
                    FROM security_prefixes sp
                    WHERE sp.security_id = p_security_id
                      AND sp.tbank_figi IS NOT NULL
                    ORDER BY sp.exchange_id
                    LIMIT 1;

                    IF v_figi IS NULL THEN
                        v_status := 'rejected';
                        v_note := 'РќРµС‚ tbank_figi РґР»СЏ Р±СѓРјР°РіРё';
                    ELSE
                        v_order := tbank_post_order(
                            v_logic.account_id, v_figi, v_quantity, v_price, v_direction,
                            logic_order_execution(p_logic_id)
                        );
                        v_broker_order_id := COALESCE(
                            v_order->>'orderId',
                            v_order->>'order_id',
                            v_order->'orderState'->>'orderId'
                        );
                        v_status := tbank_trade_status_from_post_order(v_order);
                        v_commission := tbank_order_commission(v_order);
                        IF v_commission <= 0 AND v_broker_order_id IS NOT NULL THEN
                            BEGIN
                                v_order := tbank_get_order_state(
                                    v_logic.account_id, v_broker_order_id
                                );
                                v_commission := tbank_order_commission(v_order);
                            EXCEPTION
                                WHEN OTHERS THEN
                                    NULL;
                            END;
                        END IF;
                        v_fill_price := tbank_order_unit_price(v_order);
                        IF v_fill_price IS NOT NULL AND v_fill_price > 0 THEN
                            v_price := v_fill_price;
                        END IF;
                        IF v_status = 'rejected' THEN
                            v_note := left(COALESCE(v_order::TEXT, ''), 500);
                        END IF;
                    END IF;
                EXCEPTION
                    WHEN undefined_function THEN
                        v_status := 'rejected';
                        v_note := 'tbank_post_order РЅРµРґРѕСЃС‚СѓРїРµРЅ';
                    WHEN OTHERS THEN
                        v_status := 'rejected';
                        v_note := SQLERRM;
                END;
            END IF;

            INSERT INTO logic_trades (
                logic_id, account_id, security_id, timeframe_id,
                side_id, action_id, signal_kind, signal_formula,
                quantity, price, commission, bar_dt, is_simulated, is_fictitious, is_shadow, is_test,
                trade_reason, broker_order_id, status, note
            )
            VALUES (
                p_logic_id, v_logic.account_id, p_security_id, v_tf_id,
                v_side_close_id, v_action_short_id, 'counter', v_formula,
                v_quantity, v_price, COALESCE(v_commission, 0), v_bar_dt, v_is_simulated, FALSE, p_is_shadow, FALSE,
                v_formula, v_broker_order_id, v_status, v_note
            )
            RETURNING id INTO v_trade_id;

            IF v_status <> 'rejected' THEN
                IF NOT p_is_shadow AND v_is_simulated AND v_balance IS NOT NULL THEN
                    v_balance := logic_trade_finalize(v_trade_id, v_balance);
                    v_notional := v_quantity * v_price;
                    v_balance := v_balance - v_notional;
                    v_balance := logic_cash_set_param(p_logic_id, v_balance);
                ELSIF NOT p_is_shadow THEN
                    PERFORM logic_trade_finalize(v_trade_id, v_balance);
                ELSE
                    PERFORM logic_trade_finalize(v_trade_id, NULL);
                END IF;
                v_closed := v_closed + 1;
                v_closed_short := v_closed_short + 1;
            END IF;
        END IF;
    END IF;

    -- РўРµСЂРјРёРЅР°Р»: СЂРµР°Р»СЊРЅРѕРµ Р·Р°РєСЂС‹С‚РёРµ РїРѕР·РёС†РёРё Р»РѕРіРёРєРѕР№ РїРѕ Р±СѓРјР°РіРµ = СЃРёРіРЅР°Р» В«Р·Р°РєСЂС‹С‚РёРµВ».
    -- РўРµСЂРјРёРЅР°Р» СЃ С‡РµРєР±РѕРєСЃРѕРј В«Р—Р°РєСЂС‹РІР°С‚СЊ РїРѕ СЃРёРіРЅР°Р»СѓВ» Р·Р°РєСЂРѕРµС‚ СЃРІРѕСЋ РїРѕР·РёС†РёСЋ СЌС‚РѕР№ Р±СѓРјР°РіРё
    -- (РІ С‚.С‡. РїСЂРё СЃСЂР°Р±Р°С‚С‹РІР°РЅРёРё СЃС‚РѕРї-Р»РѕСЃСЃР° Р»СЋР±РѕРіРѕ РІРёРґР°) РґР»СЏ Р»РѕРіРёРє СЃ
    -- use_as_terminal_signal.
    -- #982: С„Р»Р°Рі РїРµСЂРµС‡РёС‚С‹РІР°РµРј Р—Р”Р•РЎР¬ (Р° РЅРµ С‚РѕР»СЊРєРѕ РЅР° РІС…РѕРґРµ С„СѓРЅРєС†РёРё) вЂ” РµСЃР»Рё РіР°Р»РѕС‡РєСѓ
    -- РІС‹РєР»СЋС‡РёР»Рё РІРѕ РІСЂРµРјСЏ РґР»РёРЅРЅРѕРіРѕ РїСЂРѕРіРѕРЅР°, СЃРёРіРЅР°Р» Рѕ Р·Р°РєСЂС‹С‚РёРё РЅРµ СЃРѕР·РґР°С‘Рј.
    IF v_closed > 0 AND NOT p_is_shadow AND COALESCE(
        (SELECT l.use_as_terminal_signal FROM logics l WHERE l.id = p_logic_id), FALSE
    ) THEN
        IF v_closed_long > 0 THEN
            INSERT INTO logic_terminal_signals (
                logic_id, security_id, timeframe_id, bar_dt,
                position_side, signal_kind, formula, price,
                suggested_quantity, suggested_amount, indicator_ids
            )
            VALUES (
                p_logic_id, p_security_id, v_tf_id, clock_timestamp(),
                'long', 'close', v_formula, v_price,
                0, 0, NULL
            )
            ON CONFLICT (logic_id, security_id, timeframe_id, bar_dt, position_side)
                DO NOTHING;
        END IF;
        IF v_closed_short > 0 THEN
            INSERT INTO logic_terminal_signals (
                logic_id, security_id, timeframe_id, bar_dt,
                position_side, signal_kind, formula, price,
                suggested_quantity, suggested_amount, indicator_ids
            )
            VALUES (
                p_logic_id, p_security_id, v_tf_id, clock_timestamp(),
                'short', 'close', v_formula, v_price,
                0, 0, NULL
            )
            ON CONFLICT (logic_id, security_id, timeframe_id, bar_dt, position_side)
                DO NOTHING;
        END IF;
    END IF;

    -- РђРІС‚Рѕ РѕРїС‚РёРјРёР·Р°С†РёСЏ: РїРѕ С„Р°РєС‚Сѓ Р·Р°РєСЂС‹С‚РёСЏ РїРѕРґСЃС‚СЂР°РёРІР°РµРј РїРµСЂРёРѕРґ СЃРёРіРЅР°Р»РѕРІ РІС…РѕРґР°.
    IF v_closed > 0 AND NOT p_is_shadow THEN
        IF v_closed_long > 0 THEN
            PERFORM logic_auto_optimize_on_close(
                p_logic_id, p_security_id, v_tf_id, v_bar_dt, 'long', FALSE, NULL
            );
        END IF;
        IF v_closed_short > 0 THEN
            PERFORM logic_auto_optimize_on_close(
                p_logic_id, p_security_id, v_tf_id, v_bar_dt, 'short', FALSE, NULL
            );
        END IF;
    END IF;

    RETURN v_closed;
END;
$$;

-- Р¦РµР»СЊ resume РґР»СЏ security_resume: РїСЂРё resume_sl_no_reduce РЅРµ РЅРёР¶Рµ HWM (С‚РѕР»СЊРєРѕ РІРІРµСЂС…).

