COMMENT ON FUNCTION logic_contango_security_id(INTEGER) IS
'security_id СЃРёРЅС‚РµС‚РёРєРё contango (СЃРѕР·РґР°С‘С‚ РїСЂРё РѕС‚СЃСѓС‚СЃС‚РІРёРё)';

-- РњР°С‚РµСЂРёР°Р»РёР·РѕРІР°С‚СЊ OHLC РєРѕРЅС‚Р°РЅРіРѕ: fut в€’ und РЅР° РѕР±С‰РёС… timestamp.

CREATE OR REPLACE FUNCTION logic_ensure_balance(p_logic_id INTEGER)
RETURNS NUMERIC
LANGUAGE plpgsql AS $$
DECLARE
    v_account_type VARCHAR;
    v_account_id INTEGER;
    v_cash NUMERIC;
BEGIN
    SELECT lower(COALESCE(a.account_type, 'fake')), l.account_id
    INTO v_account_type, v_account_id
    FROM logics l
    LEFT JOIN accounts a ON a.id = l.account_id
    WHERE l.id = p_logic_id;

    IF NOT FOUND THEN
        RETURN NULL;
    END IF;

    -- Р РµР°Р»СЊРЅС‹Р№ СЃС‡С‘С‚: С‚РµРєСѓС‰РёР№ вЂ” СЃ Р±СЂРѕРєРµСЂР° (РёР»Рё 0), РЅРµ РёР· РїР°СЂР°РјРµС‚СЂРѕРІ С‚РµСЃС‚Р°.
    IF v_account_type <> 'fake' THEN
        RETURN COALESCE(logic_apply_real_account_balances(p_logic_id, TRUE), 0);
    END IF;

    -- #1065: С„РµР№РєРѕРІС‹Р№ СЃС‡С‘С‚ вЂ” РґРµРЅСЊРіРё Р»РµР¶Р°С‚ РЅР° accounts.terminal_cash,
    -- РїР°СЂР°РјРµС‚СЂ Р»РѕРіРёРєРё current_balance Р»РёС€СЊ Р·РµСЂРєР°Р»Рѕ (РґР»СЏ UI). Р‘СЌРєС‚РµСЃС‚ СЃСЋРґР° РЅРµ Р·Р°С…РѕРґРёС‚.
    SELECT COALESCE(terminal_cash, 0) INTO v_cash FROM accounts WHERE id = v_account_id;
    v_cash := COALESCE(v_cash, 0);
    PERFORM logic_upsert_param(p_logic_id, 'current_balance', v_cash::TEXT, 'money');
    RETURN v_cash;
END;
$$;

COMMENT ON FUNCTION logic_ensure_balance(INTEGER) IS
'#1065 Fake: РѕСЃС‚Р°С‚РѕРє СЃ accounts.terminal_cash (Р·РµСЂРєР°Р»Рѕ РІ current_balance). Real: СЃ T-Bank (РёР»Рё 0).';

-- #1065: Р·Р°РїРёСЃСЊ РїР°СЂР°РјРµС‚СЂР° current_balance РїРѕСЃР»Рµ СЃРґРµР»РєРё.
-- Fake: С‚СЂРёРіРіРµСЂ logic_trades_demo_cash_ins СѓР¶Рµ РёР·РјРµРЅРёР» accounts.terminal_cash вЂ”
-- С‚РѕР»СЊРєРѕ Р·РµСЂРєР°Р»РёРј РµРіРѕ РІ РїР°СЂР°РјРµС‚СЂ, С‡С‚РѕР±С‹ РЅРµ СЃРїРёСЃР°С‚СЊ СЃСѓРјРјСѓ РґРІР°Р¶РґС‹.
-- Real: РєР°Рє Рё СЂР°РЅСЊС€Рµ вЂ” РїРёС€РµРј РїРµСЂРµРґР°РЅРЅРѕРµ Р·РЅР°С‡РµРЅРёРµ (СЃ Р±СЂРѕРєРµСЂР°).

CREATE OR REPLACE FUNCTION logic_ensure_cash_fund_security(p_logic_id INTEGER,
    p_code TEXT)
RETURNS VOID
LANGUAGE plpgsql AS $$
DECLARE
    v_code TEXT;
    v_security_id INTEGER;
BEGIN
    v_code := upper(btrim(COALESCE(p_code, '')));

    DELETE FROM logic_securities ls
    USING security_prefixes sp
    WHERE ls.security_id = sp.security_id
      AND ls.logic_id = p_logic_id
      AND upper(sp.prefix) IN ('TMON', 'LQDT', 'SBMM')
      AND (v_code = '' OR upper(sp.prefix) <> v_code);

    IF v_code = '' OR v_code NOT IN ('TMON', 'LQDT', 'SBMM') THEN
        RETURN;
    END IF;

    SELECT s.id
    INTO v_security_id
    FROM securities s
    JOIN security_prefixes sp ON sp.security_id = s.id
    WHERE upper(sp.prefix) = v_code
    ORDER BY sp.exchange_id
    LIMIT 1;

    IF v_security_id IS NULL THEN
        RETURN;
    END IF;

    UPDATE logic_securities
    SET display_order = display_order + 1
    WHERE logic_id = p_logic_id
      AND security_id <> v_security_id
      AND display_order >= 0;

    INSERT INTO logic_securities (logic_id, security_id, display_order, is_active)
    VALUES (p_logic_id, v_security_id, 0, TRUE)
    ON CONFLICT (logic_id, security_id) DO UPDATE SET
        is_active = TRUE,
        display_order = 0;
END;
$$;

COMMENT ON FUNCTION logic_ensure_cash_fund_security(INTEGER, TEXT) IS
'Р”РѕР±Р°РІРёС‚СЊ РІС‹Р±СЂР°РЅРЅС‹Р№ РґРµРЅРµР¶РЅС‹Р№ С„РѕРЅРґ РІ logic_securities СЃ display_order=0 (РІРµСЂС… СЃРїРёСЃРєР°)';

CREATE OR REPLACE FUNCTION logic_ensure_contango_security(p_future_security_id INTEGER)
RETURNS INTEGER
LANGUAGE plpgsql AS $$
DECLARE
    v_und INTEGER;
    v_synth INTEGER;
    v_prefix VARCHAR(50);
    v_type_id INTEGER;
    v_exch_id INTEGER;
BEGIN
    IF p_future_security_id IS NULL THEN
        RETURN NULL;
    END IF;

    SELECT cs.synthetic_security_id
    INTO v_synth
    FROM contango_securities cs
    WHERE cs.future_security_id = p_future_security_id
    LIMIT 1;
    IF v_synth IS NOT NULL THEN
        RETURN v_synth;
    END IF;

    v_und := logic_future_underlying_security_id(p_future_security_id);
    IF v_und IS NULL THEN
        RETURN NULL;
    END IF;

    SELECT sp.prefix
    INTO v_prefix
    FROM security_prefixes sp
    WHERE sp.security_id = p_future_security_id
      AND sp.instrument_market = 'futures'
    ORDER BY sp.exchange_id
    LIMIT 1;

    SELECT id INTO v_type_id FROM security_types WHERE name = 'Index' LIMIT 1;
    IF v_type_id IS NULL THEN
        SELECT id INTO v_type_id FROM security_types ORDER BY id LIMIT 1;
    END IF;
    SELECT id INTO v_exch_id FROM exchanges WHERE name = 'MOEX' LIMIT 1;
    IF v_exch_id IS NULL THEN
        SELECT id INTO v_exch_id FROM exchanges ORDER BY id LIMIT 1;
    END IF;

    INSERT INTO securities (name, security_type_id, lot_size)
    VALUES (
        format('Contango %s', COALESCE(NULLIF(btrim(v_prefix), ''), p_future_security_id::TEXT)),
        v_type_id,
        1
    )
    RETURNING id INTO v_synth;

    INSERT INTO security_prefixes (
        security_id, exchange_id, prefix, instrument_market, note, underlying_security_id
    )
    VALUES (
        v_synth,
        v_exch_id,
        left(format('CTG:%s', COALESCE(NULLIF(btrim(v_prefix), ''), p_future_security_id::TEXT)), 50),
        'other',
        'РЎРёРЅС‚РµС‚РёРєР°: РєРѕРЅС‚Р°РЅРіРѕ (С„СЊСЋС‡РµСЂСЃ в€’ Р±Р°Р·РѕРІС‹Р№ Р°РєС‚РёРІ)',
        v_und
    )
    ON CONFLICT (security_id, exchange_id) DO UPDATE SET
        prefix = EXCLUDED.prefix,
        instrument_market = EXCLUDED.instrument_market,
        note = EXCLUDED.note,
        underlying_security_id = EXCLUDED.underlying_security_id;

    INSERT INTO contango_securities (
        future_security_id, underlying_security_id, synthetic_security_id
    )
    VALUES (p_future_security_id, v_und, v_synth)
    ON CONFLICT (future_security_id) DO UPDATE SET
        underlying_security_id = EXCLUDED.underlying_security_id,
        synthetic_security_id = EXCLUDED.synthetic_security_id
    RETURNING synthetic_security_id INTO v_synth;

    RETURN v_synth;
END;
$$;

COMMENT ON FUNCTION logic_ensure_contango_security(INTEGER) IS
'РЎРёРЅС‚РµС‚РёС‡РµСЃРєР°СЏ Р±СѓРјР°РіР° РєРѕРЅС‚Р°РЅРіРѕ РґР»СЏ С„СЊСЋС‡РµСЂСЃР°; NULL РµСЃР»Рё РЅРµС‚ underlying';

