'Р•СЃР»Рё Сѓ Р»РѕРіРёРєРё РЅРµС‚ РёРЅС‚РµСЂРІР°Р»РѕРІ вЂ” РїРѕСЃС‚Р°РІРёС‚СЊ MOEX РїРѕ СѓРјРѕР»С‡Р°РЅРёСЋ';

-- Р РµР¶РёРј С‚РѕСЂРіРѕРІС‹С… РїРµСЂРёРѕРґРѕРІ Р»РѕРіРёРєРё: off | trading | non_trading.
-- РќРѕРІС‹Р№ text-РїР°СЂР°РјРµС‚СЂ non_trading_periods_mode; РїСЂРё РµРіРѕ РѕС‚СЃСѓС‚СЃС‚РІРёРё вЂ” РѕР±СЂР°С‚РЅР°СЏ
-- СЃРѕРІРјРµСЃС‚РёРјРѕСЃС‚СЊ СЃ boolean use_non_trading_periods (true в†’ trading, РёРЅР°С‡Рµ off).

CREATE OR REPLACE FUNCTION logic_ensure_security_market_price(p_logic_id INTEGER,
    p_security_id INTEGER,
    p_timeframe_id INTEGER)
RETURNS NUMERIC
LANGUAGE plpgsql AS $$
DECLARE
    v_price NUMERIC;
    v_tf_sec INTEGER;
    v_date_from DATE;
    v_date_to DATE;
    v_point_count INTEGER;
    v_closed_bar_dt TIMESTAMP;
    v_err TEXT;
BEGIN
    v_price := logic_security_latest_price(p_security_id, p_timeframe_id);
    IF v_price IS NOT NULL AND v_price > 0 THEN
        RETURN v_price;
    END IF;

    SELECT t.sec INTO v_tf_sec FROM timeframes t WHERE t.id = p_timeframe_id;
    v_closed_bar_dt := COALESCE(
        logic_last_closed_bar_dt(v_tf_sec),
        date_trunc('day', LOCALTIMESTAMP)::TIMESTAMP
    );
    v_point_count := logic_trade_sync_point_count(v_tf_sec);
    v_date_to := GREATEST(v_closed_bar_dt::date, CURRENT_DATE);
    v_date_from := logic_trade_load_date_from(v_tf_sec, v_point_count, v_closed_bar_dt);

    BEGIN
        CALL load_prices(p_security_id, p_timeframe_id, v_date_from, v_date_to);
        PERFORM logic_trade_log(
            p_logic_id,
            'trade.prices.loaded',
            format(
                'Р¦РµРЅС‹ РґР»СЏ Р·Р°РєСЂС‹С‚РёСЏ sec=%s TF=%s (%s .. %s)',
                p_security_id,
                p_timeframe_id,
                v_date_from,
                v_date_to
            ),
            jsonb_build_object(
                'security_id', p_security_id,
                'timeframe_id', p_timeframe_id,
                'date_from', v_date_from,
                'date_to', v_date_to,
                'reason', 'close_all_at_market'
            ),
            p_security_id,
            p_timeframe_id
        );
    EXCEPTION
        WHEN undefined_function THEN
            PERFORM logic_trade_log(
                p_logic_id,
                'trade.prices.error',
                'load_prices РЅРµРґРѕСЃС‚СѓРїРµРЅ (РЅРµС‚ HTTP-СЂР°СЃС€РёСЂРµРЅРёСЏ)',
                jsonb_build_object('security_id', p_security_id, 'reason', 'close_all_at_market'),
                p_security_id,
                p_timeframe_id
            );
        WHEN OTHERS THEN
            v_err := SQLERRM;
            PERFORM logic_trade_log(
                p_logic_id,
                'trade.prices.error',
                format('РћС€РёР±РєР° Р·Р°РіСЂСѓР·РєРё С†РµРЅ sec=%s: %s', p_security_id, v_err),
                jsonb_build_object(
                    'security_id', p_security_id,
                    'error', v_err,
                    'reason', 'close_all_at_market'
                ),
                p_security_id,
                p_timeframe_id
            );
    END;

    v_price := logic_security_latest_price(p_security_id, p_timeframe_id);
    IF v_price IS NOT NULL AND v_price > 0 THEN
        RETURN v_price;
    END IF;

    SELECT p.close_price
    INTO v_price
    FROM prices p
    WHERE p.security_id = p_security_id
    ORDER BY p.dt DESC
    LIMIT 1;

    RETURN v_price;
END;
$$;

COMMENT ON FUNCTION logic_ensure_security_market_price(INTEGER, INTEGER, INTEGER) IS
'РџРѕСЃР»РµРґРЅСЏСЏ С†РµРЅР° РґР»СЏ Р·Р°РєСЂС‹С‚РёСЏ: РёР· Р‘Р” РёР»Рё load_prices (T-Bank/MOEX), Р·Р°С‚РµРј fallback РїРѕ Р»СЋР±РѕРјСѓ TF';

-- Lookup fill from account_sell_all sold[] by figi (price / order / commission).

CREATE OR REPLACE FUNCTION logic_eod_session_end_dt(p_logic_id INTEGER,
    p_bar_dt TIMESTAMP)
RETURNS TIMESTAMP
LANGUAGE plpgsql STABLE AS $$
DECLARE
    v_dow SMALLINT;
    v_day DATE := p_bar_dt::DATE;
    v_from TIME;
BEGIN
    v_dow := EXTRACT(ISODOW FROM p_bar_dt)::SMALLINT;
    SELECT i.time_from
    INTO v_from
    FROM logic_non_trading_intervals i
    WHERE i.logic_id = p_logic_id
      AND i.is_active
      AND i.day_of_week = v_dow
      AND i.time_from >= TIME '12:00'
    ORDER BY i.time_from ASC
    LIMIT 1;

    IF v_from IS NULL THEN
        RETURN NULL;
    END IF;
    RETURN (v_day + v_from);
END;
$$;

COMMENT ON FUNCTION logic_eod_session_end_dt(INTEGER, TIMESTAMP) IS
'РќР°С‡Р°Р»Рѕ РІРµС‡РµСЂРЅРµРіРѕ РЅРµС‚РѕСЂРіРѕРІРѕРіРѕ РѕРєРЅР° (РїРѕСЃР»Рµ РѕСЃРЅРѕРІРЅРѕР№ СЃРµСЃСЃРёРё MOEX)';

-- РњРѕРјРµРЅС‚ EOD-СЃРµСЃСЃРёРё (РІРµС‡РµСЂРЅРµРµ РѕРєРЅРѕ / РїРѕСЃР»РµРґРЅСЏСЏ СЃРІРµС‡Р° РґРЅСЏ).
-- РќРµ Р·Р°РІРёСЃРёС‚ РѕС‚ use_non_trading_periods: СЂР°СЃРїРёСЃР°РЅРёРµ РѕРєРѕРЅ вЂ” С‚РѕР»СЊРєРѕ С‚Р°Р№РјРёРЅРі РєРѕРЅС†Р° РґРЅСЏ;
-- С‡РµРєР±РѕРєСЃ В«РЈС‡РёС‚С‹РІР°С‚СЊ РЅРµС‚РѕСЂРіРѕРІС‹Рµ РїРµСЂРёРѕРґС‹В» СЂРµР¶РµС‚ Р»РёС€СЊ РѕС‚РєСЂС‹С‚РёРµ СЃРёРіРЅР°Р»РѕРІ.

CREATE OR REPLACE FUNCTION logic_exposure_cycle_budget(p_logic_id INTEGER,
    p_timeframe_id INTEGER)
RETURNS NUMERIC
LANGUAGE plpgsql AS $$
DECLARE
    v_sizing NUMERIC;
    v_equity NUMERIC;
BEGIN
    v_sizing := GREATEST(0, COALESCE(logic_position_sizing_base(p_logic_id, p_timeframe_id), 0));
    v_equity := GREATEST(0, COALESCE(logic_account_net_equity(p_logic_id, p_timeframe_id), 0));
    IF v_sizing <= 0 OR v_equity <= 0 THEN
        RETURN 0;
    END IF;
    RETURN LEAST(v_sizing, v_equity);
END;
$$;

COMMENT ON FUNCTION logic_exposure_cycle_budget(INTEGER, INTEGER) IS
'Р‘Р°Р·Р° С†РёРєР»Р°: LEAST(sizing_base, net equity); equity<=0 в†’ 0 (РЅРµ С‚РѕСЂРіСѓРµРј РІСЃР»РµРїСѓСЋ, #844).';

-- РЎРІРµР¶Р°СЏ С†РµРЅР° Р±СѓРјР°РіРё РЅР° РјРѕРјРµРЅС‚ РїРѕСЃС‚Р°РЅРѕРІРєРё Open-Р·Р°СЏРІРєРё: СЃС‚РѕРї-РўР¤ (РѕР±С‹С‡РЅРѕ M5) СЃРІРµР¶РµРµ РўР¤ СЃРёРіРЅР°Р»Р°.
-- Р”РѕРіСЂСѓР¶Р°РµС‚ С†РµРЅС‹ РїСЂРё РѕС‚СЃСѓС‚СЃС‚РІРёРё (РѕРґРёРЅ HTTP РЅР° СЃРёРіРЅР°Р»), РІРѕР·РІСЂР°С‰Р°РµС‚ РїРѕСЃР»РµРґРЅСЋСЋ С†РµРЅСѓ + РµС‘ Р±Р°СЂ.

CREATE OR REPLACE FUNCTION logic_fresh_order_price(p_logic_id INTEGER,
    p_security_id INTEGER,
    p_timeframe_id INTEGER)
RETURNS TABLE (price NUMERIC, bar_dt TIMESTAMP)
LANGUAGE plpgsql AS $$
DECLARE
    v_stop_tf_text TEXT;
    v_tf_id INTEGER;
    v_res NUMERIC;
BEGIN
    v_stop_tf_text := upper(btrim(COALESCE(get_logic_param_text(p_logic_id, 'stop_loss_timeframe'), '')));
    IF v_stop_tf_text <> '' THEN
        SELECT t.id INTO v_tf_id FROM timeframes t WHERE upper(t.tf) = v_stop_tf_text LIMIT 1;
    END IF;
    IF v_tf_id IS NULL THEN
        v_tf_id := p_timeframe_id;
    END IF;

    v_res := logic_security_latest_price(p_security_id, v_tf_id);
    IF v_res IS NULL OR v_res <= 0 THEN
        BEGIN
            PERFORM logic_ensure_security_market_price(p_logic_id, p_security_id, v_tf_id);
            v_res := logic_security_latest_price(p_security_id, v_tf_id);
        EXCEPTION
            WHEN OTHERS THEN
                v_res := NULL;
        END;
    END IF;

    RETURN QUERY
    SELECT v_res, p.dt
    FROM prices p
    WHERE p.security_id = p_security_id
      AND p.timeframe_id = v_tf_id
      AND v_res IS NOT NULL AND v_res > 0
    ORDER BY p.dt DESC
    LIMIT 1;
END;
$$;

COMMENT ON FUNCTION logic_fresh_order_price(INTEGER, INTEGER, INTEGER) IS
'РЎРІРµР¶Р°СЏ С†РµРЅР°+Р±Р°СЂ РґР»СЏ РіСЌРї-РїСЂРѕРІРµСЂРєРё РІС…РѕРґР°: СЃС‚РѕРї-РўР¤ (fallback TF), РґРѕРіСЂСѓР·РєР° РїСЂРё РЅРµРѕР±С…РѕРґРёРјРѕСЃС‚Рё';

-- РќРѕРјРёРЅР°Р» СѓР¶Рµ РѕС‚РєСЂС‹С‚С‹С… long+short (С‡РµРјРїРёРѕРЅ / Р±РѕР№ РёР»Рё test; opt_lane РѕС‚РґРµР»СЏРµС‚ paper OPT).
