-- Window score: closed FinRes in (from, to] + MTM(to) - MTM(from).

CREATE OR REPLACE FUNCTION logic_opt_linreg_series_at(p_period INTEGER,
    p_std_dev NUMERIC,
    p_series TEXT,
    p_security_id INTEGER,
    p_tf_id INTEGER,
    p_bar_dt TIMESTAMP)
RETURNS NUMERIC
LANGUAGE plpgsql AS $$
DECLARE
    v_key TEXT;
    v_ser TEXT;
    v_mid NUMERIC;
    v_up NUMERIC;
    v_lo NUMERIC;
    v_lv RECORD;
BEGIN
    PERFORM logic_opt_ensure_linreg_cache();
    v_key := trim(to_char(round(COALESCE(p_std_dev, 2.0), 6), 'FM999999990.999999'));
    v_ser := upper(btrim(COALESCE(p_series, 'MIDDLE')));
    IF v_ser = 'VALUE' THEN
        v_ser := 'MIDDLE';
    END IF;

    SELECT c.middle, c.upper, c.lower
    INTO v_mid, v_up, v_lo
    FROM opt_linreg_cache c
    WHERE c.security_id = p_security_id
      AND c.timeframe_id = p_tf_id
      AND c.bar_dt = p_bar_dt
      AND c.period = GREATEST(COALESCE(p_period, 20), 3)
      AND c.std_dev_key = v_key;

    IF NOT FOUND THEN
        SELECT * INTO v_lv
        FROM calc_ind_linreg_levels_at(
            p_period, p_std_dev, p_security_id, p_tf_id, p_bar_dt
        );
        IF NOT FOUND THEN
            RETURN NULL;
        END IF;
        v_mid := v_lv.middle;
        v_up := v_lv.upper;
        v_lo := v_lv.lower;
        INSERT INTO opt_linreg_cache (
            security_id, timeframe_id, bar_dt, period, std_dev_key,
            middle, upper, lower
        ) VALUES (
            p_security_id, p_tf_id, p_bar_dt,
            GREATEST(COALESCE(p_period, 20), 3), v_key,
            v_mid, v_up, v_lo
        )
        ON CONFLICT DO NOTHING;
    END IF;

    RETURN CASE v_ser
        WHEN 'UPPER' THEN v_up
        WHEN 'LOWER' THEN v_lo
        ELSE v_mid
    END;
END;
$$;

CREATE OR REPLACE FUNCTION logic_opt_maybe_promote(p_logic_id INTEGER,
    p_tf_id INTEGER,
    p_closed_bar_dt TIMESTAMP,
    p_is_test BOOLEAN DEFAULT FALSE,
    p_run_id BIGINT DEFAULT NULL)
RETURNS BOOLEAN
LANGUAGE plpgsql AS $$
DECLARE
    v_n INTEGER;
    v_bars INTEGER := 0;
    v_last_raw TEXT;
    v_last_dt TIMESTAMP;
    v_tf_sec INTEGER;
    v_champ NUMERIC;
    v_best_lane TEXT := '';
    v_best_score NUMERIC;
    v_arm RECORD;
    v_score NUMERIC;
    v_sig RECORD;
    v_new_formula TEXT;
    v_winner JSONB;
    v_sec RECORD;
    v_prev_bases JSONB;
    v_is_test BOOLEAN := COALESCE(p_is_test, FALSE);
BEGIN
    -- Offline grid on the same test run: no mid-run promote (full-period ranking at finish).
    IF v_is_test AND p_run_id IS NOT NULL THEN
        IF EXISTS (
            SELECT 1
            FROM logic_backtest_runs r
            WHERE r.id = p_run_id
              AND r.opt_grid_arms IS NOT NULL
              AND jsonb_typeof(r.opt_grid_arms) = 'array'
              AND jsonb_array_length(r.opt_grid_arms) > 0
        ) THEN
            RETURN FALSE;
        END IF;
    END IF;

    IF NOT logic_opt_logic_has_opt(p_logic_id) THEN
        RETURN FALSE;
    END IF;

    v_n := GREATEST(1, COALESCE(get_logic_param_numeric(p_logic_id, 'opt_eval_candles', 200), 200)::INTEGER);

    IF v_is_test THEN
        IF p_run_id IS NULL THEN
            RETURN FALSE;
        END IF;
        SELECT r.last_opt_eval_bar_dt INTO v_last_dt
        FROM logic_backtest_runs r WHERE r.id = p_run_id;
    ELSE
        v_last_raw := btrim(COALESCE(get_logic_param_text(p_logic_id, 'last_opt_eval_bar_dt'), ''));
        IF v_last_raw <> '' THEN
            BEGIN
                v_last_dt := v_last_raw::TIMESTAMP;
            EXCEPTION WHEN OTHERS THEN
                v_last_dt := NULL;
            END;
        END IF;
    END IF;

    SELECT t.sec INTO v_tf_sec FROM timeframes t WHERE t.id = p_tf_id;
    IF v_tf_sec IS NULL THEN
        RETURN FALSE;
    END IF;

    IF v_last_dt IS NULL THEN
        IF v_is_test THEN
            UPDATE logic_backtest_runs
            SET last_opt_eval_bar_dt = p_closed_bar_dt
            WHERE id = p_run_id;
        ELSE
            -- РџРµСЂРІС‹Р№ live-РєСѓСЂСЃРѕСЂ: СЃРЅРёРјРѕРє РЅР°С‡Р°Р»СЊРЅС‹С… Р±Р°Р· РґР»СЏ Р±СѓРґСѓС‰РµРіРѕ В«РЎР±СЂРѕСЃ OPTВ».
            PERFORM logic_opt_snapshot_params(p_logic_id, NULL, p_closed_bar_dt);
            PERFORM logic_upsert_param(
                p_logic_id,
                'last_opt_eval_bar_dt',
                to_char(p_closed_bar_dt, 'YYYY-MM-DD"T"HH24:MI:SS'),
                'text'
            );
        END IF;
        RETURN FALSE;
    END IF;

    IF p_closed_bar_dt <= v_last_dt THEN
        RETURN FALSE;
    END IF;

    v_bars := GREATEST(
        1,
        floor(EXTRACT(EPOCH FROM (p_closed_bar_dt - v_last_dt)) / v_tf_sec)::INTEGER
    );
    IF v_bars < v_n THEN
        RETURN FALSE;
    END IF;

    v_champ := logic_opt_lane_finres(
        p_logic_id, '', v_last_dt, p_closed_bar_dt, v_is_test,
        CASE WHEN v_is_test THEN p_run_id ELSE NULL END,
        p_tf_id
    );
    v_best_score := v_champ;
    v_best_lane := '';
    v_winner := NULL;

    FOR v_arm IN SELECT * FROM logic_opt_build_arms(p_logic_id)
    LOOP
        v_score := logic_opt_lane_finres(
            p_logic_id, v_arm.lane, v_last_dt, p_closed_bar_dt, v_is_test,
            CASE WHEN v_is_test THEN p_run_id ELSE NULL END,
            p_tf_id
        );
        IF v_score > v_best_score THEN
            v_best_score := v_score;
            v_best_lane := v_arm.lane;
            v_winner := v_arm.values_json;
        END IF;
    END LOOP;

    IF v_winner IS NULL OR v_best_lane = '' THEN
        IF v_is_test THEN
            UPDATE logic_backtest_runs
            SET last_opt_eval_bar_dt = p_closed_bar_dt
            WHERE id = p_run_id;
        ELSE
            PERFORM logic_upsert_param(
                p_logic_id,
                'last_opt_eval_bar_dt',
                to_char(p_closed_bar_dt, 'YYYY-MM-DD"T"HH24:MI:SS'),
                'text'
            );
            PERFORM logic_trade_log(
                p_logic_id,
                'opt.window',
                format('РћРєРЅРѕ OPT %s СЃРІРµС‡РµР№: С‡РµРјРїРёРѕРЅ Р»СѓС‡С€Рµ РёР»Рё СЂР°РІРµРЅ (FinRes=%s)', v_n, v_champ),
                jsonb_build_object(
                    'champion_finres', v_champ,
                    'bars', v_bars,
                    'from_bar', v_last_dt,
                    'to_bar', p_closed_bar_dt
                ),
                NULL,
                p_tf_id
            );
        END IF;
        PERFORM logic_opt_close_open_lanes(
            p_logic_id, p_tf_id, p_closed_bar_dt, v_is_test, p_run_id
        );
        RETURN FALSE;
    END IF;

    SELECT COALESCE(jsonb_object_agg(s.key, s.base), '{}'::jsonb)
    INTO v_prev_bases
    FROM logic_opt_collect_specs(p_logic_id) s;

    FOR v_sig IN
        SELECT id, formula FROM logic_indicator_signals
        WHERE logic_id = p_logic_id AND is_active = TRUE
    LOOP
        v_new_formula := logic_opt_rewrite_formula_bases(v_sig.formula, v_winner);
        IF v_new_formula IS DISTINCT FROM v_sig.formula THEN
            UPDATE logic_indicator_signals
            SET formula = v_new_formula
            WHERE id = v_sig.id;
        END IF;
    END LOOP;

    PERFORM logic_opt_record_param_event(
        p_logic_id,
        CASE WHEN v_is_test THEN p_run_id ELSE NULL END,
        p_closed_bar_dt,
        'promote',
        v_best_lane,
        v_winner,
        v_prev_bases,
        v_champ,
        v_best_score
    );

    PERFORM logic_opt_close_open_lanes(
        p_logic_id, p_tf_id, p_closed_bar_dt, v_is_test, p_run_id
    );

    -- Live: apply series params. Test: champion eval via evaluate_at_opt (no full sync).
    IF NOT v_is_test THEN
        FOR v_sec IN
            SELECT security_id FROM logic_securities
            WHERE logic_id = p_logic_id AND is_active = TRUE
        LOOP
            CALL logic_apply_indicator_params_from_signals(p_logic_id, v_sec.security_id);
        END LOOP;
    END IF;

    IF v_is_test THEN
        UPDATE logic_backtest_runs
        SET last_opt_eval_bar_dt = p_closed_bar_dt
        WHERE id = p_run_id;
    ELSE
        PERFORM logic_upsert_param(
            p_logic_id,
            'last_opt_eval_bar_dt',
            to_char(p_closed_bar_dt, 'YYYY-MM-DD"T"HH24:MI:SS'),
            'text'
        );
        PERFORM logic_trade_log(
            p_logic_id,
            'opt.promote',
            format(
                'OPT promote: lane=%s FinRes=%s > champion=%s в†’ %s',
                v_best_lane, v_best_score, v_champ, v_winner::TEXT
            ),
            jsonb_build_object(
                'lane', v_best_lane,
                'winner', v_winner,
                'winner_finres', v_best_score,
                'champion_finres', v_champ,
                'bars', v_bars
            ),
            NULL,
            p_tf_id
        );
    END IF;
    RETURN TRUE;
END;
$$;

DROP FUNCTION IF EXISTS process_logic_opt_trades(INTEGER, INTEGER, TIMESTAMP);
DROP FUNCTION IF EXISTS process_logic_opt_trades(INTEGER, INTEGER, TIMESTAMP, BOOLEAN, BIGINT, NUMERIC);

CREATE OR REPLACE FUNCTION logic_opt_record_param_event(p_logic_id INTEGER,
    p_run_id BIGINT,
    p_bar_dt TIMESTAMP,
    p_event_kind TEXT,
    p_lane TEXT DEFAULT '',
    p_params JSONB DEFAULT NULL,
    p_params_prev JSONB DEFAULT NULL,
    p_champion_finres NUMERIC DEFAULT NULL,
    p_winner_finres NUMERIC DEFAULT NULL)
RETURNS BIGINT
LANGUAGE plpgsql AS $$
DECLARE
    v_state JSONB;
    v_params JSONB;
    v_id BIGINT;
BEGIN
    IF p_event_kind NOT IN ('snapshot', 'promote') THEN
        RAISE EXCEPTION 'logic_opt_record_param_event: bad event_kind %', p_event_kind;
    END IF;

    v_state := logic_opt_collect_formula_state(p_logic_id);
    v_params := COALESCE(p_params, v_state->'bases', '{}'::jsonb);

    INSERT INTO logic_opt_param_history (
        logic_id, run_id, bar_dt, event_kind, lane,
        params, params_prev, opt_specs, formulas,
        champion_finres, winner_finres
    )
    VALUES (
        p_logic_id, p_run_id, p_bar_dt, p_event_kind, COALESCE(p_lane, ''),
        v_params, p_params_prev,
        COALESCE(v_state->'opt', '{}'::jsonb),
        COALESCE(v_state->'formulas', '[]'::jsonb),
        p_champion_finres, p_winner_finres
    )
    RETURNING id INTO v_id;

    RETURN v_id;
END;
$$;

COMMENT ON FUNCTION logic_opt_record_param_event IS
'РџРёС€РµС‚ СЃРЅРёРјРѕРє РёР»Рё promote РІ logic_opt_param_history (РЅРµ Р·Р°РІРёСЃРёС‚ РѕС‚ tech log).';

CREATE OR REPLACE FUNCTION logic_opt_reset_to_initial(p_logic_id INTEGER)
RETURNS JSONB
LANGUAGE plpgsql AS $$
DECLARE
    v_formulas JSONB;
    v_bases JSONB;
    v_item JSONB;
    v_sid INTEGER;
    v_formula TEXT;
    v_sig RECORD;
    v_new_formula TEXT;
    v_restored INTEGER := 0;
    v_deleted INTEGER := 0;
    v_source TEXT := 'none';
    v_sec RECORD;
    v_after JSONB;
BEGIN
    IF p_logic_id IS NULL OR p_logic_id <= 0 THEN
        RETURN jsonb_build_object('ok', FALSE, 'error', 'invalid logic_id');
    END IF;

    IF NOT EXISTS (SELECT 1 FROM logics WHERE id = p_logic_id) THEN
        RETURN jsonb_build_object('ok', FALSE, 'error', 'logic not found');
    END IF;

    IF NOT logic_opt_logic_has_opt(p_logic_id) THEN
        RETURN jsonb_build_object(
            'ok', TRUE,
            'formulas_restored', 0,
            'opt_trades_deleted', 0,
            'source', 'none',
            'message', 'Р’ С„РѕСЂРјСѓР»Р°С… РЅРµС‚ OPT вЂ” СЃР±СЂРѕСЃ РЅРµ РЅСѓР¶РµРЅ'
        );
    END IF;

    -- РЎРЅР°С‡Р°Р»Р° РЅР°Р№С‚Рё РЅР°С‡Р°Р»СЊРЅС‹Рµ (РґРѕ Р»СЋР±С‹С… РЅРѕРІС‹С… snapshot).
    SELECT h.formulas
    INTO v_formulas
    FROM logic_opt_param_history h
    WHERE h.logic_id = p_logic_id
      AND h.event_kind = 'snapshot'
      AND h.run_id IS NULL
      AND COALESCE(h.lane, '') <> 'reset'
      AND jsonb_typeof(h.formulas) = 'array'
      AND jsonb_array_length(h.formulas) > 0
    ORDER BY h.id
    LIMIT 1;

    IF v_formulas IS NOT NULL THEN
        v_source := 'snapshot_live';
    ELSE
        SELECT h.formulas
        INTO v_formulas
        FROM logic_opt_param_history h
        WHERE h.logic_id = p_logic_id
          AND h.event_kind = 'snapshot'
          AND COALESCE(h.lane, '') <> 'reset'
          AND jsonb_typeof(h.formulas) = 'array'
          AND jsonb_array_length(h.formulas) > 0
        ORDER BY h.id
        LIMIT 1;
        IF v_formulas IS NOT NULL THEN
            v_source := 'snapshot';
        END IF;
    END IF;

    IF v_formulas IS NULL THEN
        SELECT h.params_prev
        INTO v_bases
        FROM logic_opt_param_history h
        WHERE h.logic_id = p_logic_id
          AND h.event_kind = 'promote'
          AND h.params_prev IS NOT NULL
          AND jsonb_typeof(h.params_prev) = 'object'
          AND h.params_prev <> '{}'::jsonb
        ORDER BY h.id
        LIMIT 1;
        IF v_bases IS NOT NULL THEN
            v_source := 'params_prev';
        END IF;
    END IF;

    -- Р’РѕСЃСЃС‚Р°РЅРѕРІРёС‚СЊ С„РѕСЂРјСѓР»С‹
    IF v_formulas IS NOT NULL THEN
        FOR v_item IN SELECT * FROM jsonb_array_elements(v_formulas)
        LOOP
            v_sid := NULLIF(v_item->>'signal_id', '')::INTEGER;
            v_formula := v_item->>'formula';
            IF v_sid IS NULL OR v_formula IS NULL OR btrim(v_formula) = '' THEN
                CONTINUE;
            END IF;
            UPDATE logic_indicator_signals
            SET formula = v_formula
            WHERE id = v_sid
              AND logic_id = p_logic_id
              AND formula IS DISTINCT FROM v_formula;
            IF FOUND THEN
                v_restored := v_restored + 1;
            END IF;
        END LOOP;
    ELSIF v_bases IS NOT NULL THEN
        FOR v_sig IN
            SELECT id, formula
            FROM logic_indicator_signals
            WHERE logic_id = p_logic_id AND is_active = TRUE
        LOOP
            v_new_formula := logic_opt_rewrite_formula_bases(v_sig.formula, v_bases);
            IF v_new_formula IS DISTINCT FROM v_sig.formula THEN
                UPDATE logic_indicator_signals
                SET formula = v_new_formula
                WHERE id = v_sig.id;
                v_restored := v_restored + 1;
            END IF;
        END LOOP;
    END IF;

    -- РћС‡РёСЃС‚РёС‚СЊ Р±СѓРјР°Р¶РЅСѓСЋ РєРЅРёРіСѓ OPT (live, РЅРµ test).
    DELETE FROM logic_trades lt
    WHERE lt.logic_id = p_logic_id
      AND COALESCE(lt.opt_lane, '') <> ''
      AND lt.is_test = FALSE;
    GET DIAGNOSTICS v_deleted = ROW_COUNT;

    -- РЎР±СЂРѕСЃРёС‚СЊ РєСѓСЂСЃРѕСЂ РѕРєРЅР° OPT вЂ” СЃР»РµРґСѓСЋС‰РёР№ С†РёРєР» РЅР°С‡РЅС‘С‚ Р·Р°РЅРѕРІРѕ.
    DELETE FROM logic_params
    WHERE logic_id = p_logic_id
      AND param_key = 'last_opt_eval_bar_dt';

    -- Offline grid: clear persisted Apply-best cache (and run snapshots of results).
    UPDATE logics
    SET
      last_opt_grid_results = NULL,
      last_opt_grid_run_id = NULL,
      last_opt_grid_at = NULL
    WHERE id = p_logic_id;

    UPDATE logic_backtest_runs
    SET opt_grid_results = NULL
    WHERE logic_id = p_logic_id
      AND opt_grid_results IS NOT NULL;

    FOR v_sec IN
        SELECT security_id
        FROM logic_securities
        WHERE logic_id = p_logic_id AND is_active = TRUE
    LOOP
        CALL logic_apply_indicator_params_from_signals(p_logic_id, v_sec.security_id);
    END LOOP;

    v_after := logic_opt_collect_formula_state(p_logic_id);
    PERFORM logic_opt_record_param_event(
        p_logic_id, NULL, CURRENT_TIMESTAMP::TIMESTAMP, 'snapshot',
        'reset',
        v_after->'bases',
        NULL, NULL, NULL
    );

    PERFORM logic_trade_log(
        p_logic_id,
        'opt.reset',
        format(
            'РЎР±СЂРѕСЃ OPT: source=%s, formulas=%s, deleted_opt_trades=%s',
            v_source, v_restored, v_deleted
        ),
        jsonb_build_object(
            'source', v_source,
            'formulas_restored', v_restored,
            'opt_trades_deleted', v_deleted
        ),
        NULL,
        NULL
    );

    RETURN jsonb_build_object(
        'ok', TRUE,
        'formulas_restored', v_restored,
        'opt_trades_deleted', v_deleted,
        'source', v_source,
        'message', CASE
            WHEN v_source = 'none' THEN
                'РљРЅРёРіР° OPT РѕС‡РёС‰РµРЅР°; РЅР°С‡Р°Р»СЊРЅС‹Рµ Р±Р°Р·С‹ РІ РёСЃС‚РѕСЂРёРё РЅРµ РЅР°Р№РґРµРЅС‹ вЂ” С„РѕСЂРјСѓР»С‹ РЅРµ РјРµРЅСЏР»РёСЃСЊ'
            ELSE
                format('OPT СЃР±СЂРѕС€РµРЅ Рє РЅР°С‡Р°Р»СЊРЅС‹Рј (%s)', v_source)
        END
    );
END;
$$;

COMMENT ON FUNCTION logic_opt_reset_to_initial(INTEGER) IS
'РЎР±СЂРѕСЃ OPT: РІРµСЂРЅСѓС‚СЊ РЅР°С‡Р°Р»СЊРЅС‹Рµ Р±Р°Р·С‹ С„РѕСЂРјСѓР», СѓРґР°Р»РёС‚СЊ live opt_lane, СЃР±СЂРѕСЃРёС‚СЊ last_opt_eval_bar_dt Рё last_opt_grid_* (РєСЌС€ Apply best).';

-- ---------------------------------------------------------------------------
-- РСЃС‚РѕСЂРёСЏ РїР°СЂР°РјРµС‚СЂРѕРІ OPT / С„РѕСЂРјСѓР» (РѕС‚С‡С‘С‚ С‚РµСЃС‚Р°)
-- ---------------------------------------------------------------------------

CREATE OR REPLACE FUNCTION logic_opt_restore_formulas_from_run(p_run_id BIGINT)
RETURNS INTEGER
LANGUAGE plpgsql AS $$
DECLARE
    v_formulas JSONB;
    v_item JSONB;
    v_n INTEGER := 0;
    v_sid INTEGER;
    v_formula TEXT;
BEGIN
    IF p_run_id IS NULL THEN
        RETURN 0;
    END IF;

    SELECT h.formulas
    INTO v_formulas
    FROM logic_opt_param_history h
    WHERE h.run_id = p_run_id
      AND h.event_kind = 'snapshot'
    ORDER BY h.id
    LIMIT 1;

    IF v_formulas IS NULL OR jsonb_typeof(v_formulas) <> 'array' THEN
        RETURN 0;
    END IF;

    FOR v_item IN SELECT * FROM jsonb_array_elements(v_formulas)
    LOOP
        v_sid := NULLIF(v_item->>'signal_id', '')::INTEGER;
        v_formula := v_item->>'formula';
        IF v_sid IS NULL OR v_formula IS NULL OR btrim(v_formula) = '' THEN
            CONTINUE;
        END IF;
        UPDATE logic_indicator_signals
        SET formula = v_formula
        WHERE id = v_sid
          AND formula IS DISTINCT FROM v_formula;
        IF FOUND THEN
            v_n := v_n + 1;
        END IF;
    END LOOP;

    RETURN v_n;
END;
$$;

COMMENT ON FUNCTION logic_opt_restore_formulas_from_run(BIGINT) IS
'РџРѕСЃР»Рµ С‚РµСЃС‚Р°: РІРµСЂРЅСѓС‚СЊ С„РѕСЂРјСѓР»С‹ СЃРёРіРЅР°Р»РѕРІ РёР· СЃС‚Р°СЂС‚РѕРІРѕРіРѕ СЃРЅРёРјРєР° OPT (promote РЅРµ РґРѕР»Р¶РµРЅ РѕСЃС‚Р°С‚СЊСЃСЏ РІ Р±РѕСЋ).';

-- РЎР±СЂРѕСЃ OPT Рє РЅР°С‡Р°Р»СЊРЅС‹Рј Р±Р°Р·Р°Рј: РѕС‡РёСЃС‚РёС‚СЊ Р±СѓРјР°Р¶РЅСѓСЋ РєРЅРёРіСѓ opt_lane + РІРµСЂРЅСѓС‚СЊ С„РѕСЂРјСѓР»С‹.
-- РСЃС‚РѕС‡РЅРёРє РЅР°С‡Р°Р»СЊРЅС‹С…: earliest live snapshot в†’ Р»СЋР±РѕР№ snapshot в†’ params_prev РїРµСЂРІРѕРіРѕ promote.

CREATE OR REPLACE FUNCTION logic_opt_rewrite_formula_bases(p_formula TEXT, p_values JSONB)
RETURNS TEXT
LANGUAGE plpgsql IMMUTABLE AS $$
DECLARE
    v_parsed RECORD;
    v_new_params TEXT;
    v_opts TEXT[] := ARRAY[]::TEXT[];
    v_spec RECORD;
BEGIN
    SELECT * INTO v_parsed FROM parse_signal_formula(p_formula);
    IF NOT COALESCE(v_parsed.valid, FALSE) THEN
        RETURN p_formula;
    END IF;
    FOR v_spec IN SELECT * FROM logic_opt_extract_specs(v_parsed.params)
    LOOP
        v_opts := v_opts || ('OPT(' || v_spec.key || ',' || trim(to_char(v_spec.pct, 'FM999999990.######')) || ')');
    END LOOP;
    v_new_params := logic_opt_expand_params(v_parsed.params, p_values);
    IF COALESCE(array_length(v_opts, 1), 0) > 0 THEN
        v_new_params := v_new_params || ',' || array_to_string(v_opts, ',');
    END IF;
    RETURN '@' || v_parsed.indicator_code || '(' || v_new_params || ') ' || v_parsed.condition;
END;
$$;

-- РљСЌС€ LINREG-РєР°РЅР°Р»Р° РЅР° РІСЂРµРјСЏ РѕРґРЅРѕРіРѕ process_logic_opt_trades (temp).

CREATE OR REPLACE FUNCTION logic_opt_snapshot_params(p_logic_id INTEGER,
    p_run_id BIGINT DEFAULT NULL,
    p_bar_dt TIMESTAMP DEFAULT NULL)
RETURNS BIGINT
LANGUAGE sql AS $$
    SELECT logic_opt_record_param_event(
        p_logic_id, p_run_id, p_bar_dt, 'snapshot', '', NULL, NULL, NULL, NULL
    );
$$;

COMMENT ON FUNCTION logic_opt_snapshot_params(INTEGER, BIGINT, TIMESTAMP) IS
'РЎРЅРёРјРѕРє С‚РµРєСѓС‰РёС… РїР°СЂР°РјРµС‚СЂРѕРІ С„РѕСЂРјСѓР»/OPT (СЃС‚Р°СЂС‚ С‚РµСЃС‚Р° РёР»Рё fallback РІ РѕС‚С‡С‘С‚Рµ).';

CREATE OR REPLACE FUNCTION logic_park_excess_cash(p_logic_id INTEGER)
RETURNS JSONB
LANGUAGE plpgsql AS $$
DECLARE
    v_logic RECORD;
    v_code TEXT;
    v_threshold NUMERIC;
    v_balance NUMERIC;
    v_park_amount NUMERIC;
    v_tf_id INTEGER;
    v_tf_sec INTEGER;
    v_closed_bar_dt TIMESTAMP;
    v_last_raw TEXT;
    v_last_dt TIMESTAMP;
    v_inst JSONB;
    v_figi TEXT;
    v_lot INTEGER;
    v_price NUMERIC;
    v_qty INTEGER;
    v_order JSONB;
    v_broker_order_id TEXT;
    v_status TEXT;
    v_note TEXT;
    v_security_id INTEGER;
    v_side_open_id INTEGER;
    v_action_long_id INTEGER;
    v_trade_id BIGINT;
    v_equity NUMERIC;
    v_fund_qty NUMERIC;
    v_fund_mtm NUMERIC;
    v_excess NUMERIC;
    v_short_notional NUMERIC := 0;
BEGIN
    SELECT l.id, l.account_id, a.account_type, a.is_active
    INTO v_logic
    FROM logics l
    JOIN accounts a ON a.id = l.account_id
    WHERE l.id = p_logic_id
      AND l.is_enabled = TRUE;

    IF NOT FOUND OR NOT COALESCE(v_logic.is_active, FALSE) THEN
        RETURN jsonb_build_object('skipped', TRUE, 'reason', 'logic_inactive');
    END IF;

    v_code := upper(btrim(COALESCE(get_logic_param_text(p_logic_id, 'cash_fund_code'), '')));
    IF v_code = '' OR v_code NOT IN ('TMON', 'LQDT', 'SBMM') THEN
        RETURN jsonb_build_object('skipped', TRUE, 'reason', 'no_fund');
    END IF;

    v_threshold := COALESCE(get_logic_param_numeric(p_logic_id, 'cash_fund_threshold', 1000000), 1000000);
    IF v_threshold < 0 THEN
        v_threshold := 0;
    END IF;

    v_balance := COALESCE(logic_ensure_balance(p_logic_id), 0);
    IF v_balance <= 0 THEN
        RETURN jsonb_build_object(
            'skipped', TRUE,
            'reason', 'no_cash',
            'balance', v_balance,
            'threshold', v_threshold
        );
    END IF;

    v_tf_id := logic_resolve_timeframe_id(p_logic_id);
    IF v_tf_id IS NULL THEN
        RETURN jsonb_build_object('skipped', TRUE, 'reason', 'no_timeframe');
    END IF;
    SELECT t.sec INTO v_tf_sec FROM timeframes t WHERE t.id = v_tf_id;
    v_closed_bar_dt := logic_last_closed_bar_dt(v_tf_sec);
    IF v_closed_bar_dt IS NULL THEN
        RETURN jsonb_build_object('skipped', TRUE, 'reason', 'no_closed_bar');
    END IF;

    v_last_raw := btrim(COALESCE(get_logic_param_text(p_logic_id, 'last_cash_fund_bar_dt'), ''));
    IF v_last_raw <> '' THEN
        BEGIN
            v_last_dt := v_last_raw::TIMESTAMP;
            IF v_closed_bar_dt <= v_last_dt THEN
                RETURN jsonb_build_object(
                    'skipped', TRUE,
                    'reason', 'bar_already_parked',
                    'closed_bar', v_closed_bar_dt
                );
            END IF;
        EXCEPTION
            WHEN OTHERS THEN
                NULL;
        END;
    END IF;

    -- РРґРµРјРїРѕС‚РµРЅС‚РЅРѕСЃС‚СЊ: РѕРґРЅР° РїРѕРїС‹С‚РєР° РЅР° Р·Р°РєСЂС‹С‚СѓСЋ СЃРІРµС‡Сѓ TF
    PERFORM logic_upsert_param(
        p_logic_id,
        'last_cash_fund_bar_dt',
        to_char(v_closed_bar_dt, 'YYYY-MM-DD"T"HH24:MI:SS'),
        'text'
    );

    -- Р¤РѕРЅРґ РІ РїРѕСЂС‚С„РµР»Рµ Р»РѕРіРёРєРё (СЃРІРµСЂС…Сѓ СЃРїРёСЃРєР° В«Р¦РµРЅРЅС‹Рµ Р±СѓРјР°РіРёВ»)
    PERFORM logic_ensure_cash_fund_security(p_logic_id, v_code);

    SELECT s.id
    INTO v_security_id
    FROM securities s
    JOIN security_prefixes sp ON sp.security_id = s.id
    WHERE upper(sp.prefix) = v_code
    ORDER BY sp.exchange_id
    LIMIT 1;

    v_inst := NULL;
    BEGIN
        v_inst := logic_resolve_cash_fund_instrument(v_code);
    EXCEPTION
        WHEN OTHERS THEN
            v_inst := NULL;
    END;

    v_figi := v_inst->>'figi';
    v_lot := GREATEST(
        1,
        COALESCE((v_inst->>'lot')::INTEGER, NULLIF(logic_security_lot_size(v_security_id), 0), 1)
    );
    v_price := COALESCE(
        NULLIF((v_inst->>'price')::NUMERIC, 0),
        CASE WHEN v_security_id IS NOT NULL
            THEN logic_cash_fund_price_at(v_security_id, v_tf_id, v_closed_bar_dt, v_code)
            ELSE NULL
        END,
        100
    );

    IF v_price <= 0 THEN
        RETURN jsonb_build_object('ok', FALSE, 'reason', 'bad_price', 'detail', v_inst);
    END IF;

    -- РР·Р±С‹С‚РѕРє = equity в€’ РїРѕСЂРѕРі; РґРѕРєСѓРїР°РµРј min(РєСЌС€, РёР·Р±С‹С‚РѕРє в€’ СѓР¶Рµ_РІ_С„РѕРЅРґРµ); С„РѕРЅРґ РЅРµ РїСЂРѕРґР°С‘Рј.
    -- РљСЌС€ СЂРµР°Р»СЊРЅРѕРіРѕ СЃС‡С‘С‚Р° СЂР°Р·РґСѓС‚ РІС‹СЂСѓС‡РєРѕР№ С€РѕСЂС‚РѕРІ вЂ” РІС‹С‡РёС‚Р°РµРј РЅРѕРјРёРЅР°Р» РѕС‚РєСЂС‹С‚С‹С… С€РѕСЂС‚РѕРІ,
    -- РёРЅР°С‡Рµ РїР°СЂРєРѕРІРєР° С‚СЂР°С‚РёС‚ В«Р·Р°С‘РјРЅС‹РµВ» РґРµРЅСЊРіРё Рё СѓРіР»СѓР±Р»СЏРµС‚ РїРѕР·РёС†РёСЋ РїРѕ Р·Р°Р№РјР°Рј.
    v_equity := COALESCE(logic_portfolio_equity(p_logic_id, v_tf_id), v_balance);
    SELECT GREATEST(0, COALESCE(SUM(rem.qty * lt.price), 0))
    INTO v_short_notional
    FROM logic_trades lt
    JOIN sides s ON s.id = lt.side_id
    JOIN actions a ON a.id = lt.action_id
    CROSS JOIN LATERAL (
        SELECT GREATEST(
            lt.quantity - COALESCE((
                SELECT SUM(l.quantity)
                FROM logic_trade_lots l
                WHERE l.open_trade_id = lt.id
            ), 0),
            0
        ) AS qty
    ) rem
    WHERE lt.logic_id = p_logic_id
      AND NOT lt.is_shadow
      AND lt.is_test = FALSE
      AND COALESCE(lt.opt_lane, '') = ''
      AND lt.status IN ('filled', 'submitted')
      AND s.name = 'Open'
      AND a.name = 'Short'
      AND rem.qty > 0;
    v_fund_qty := CASE
        WHEN v_security_id IS NOT NULL
            THEN logic_long_position_qty(p_logic_id, v_security_id, FALSE, FALSE)
        ELSE 0
    END;
    v_fund_mtm := COALESCE(v_fund_qty, 0) * v_price;
    v_excess := v_equity - v_threshold;
    v_park_amount := LEAST(
        GREATEST(0, v_balance - v_short_notional),
        GREATEST(0, v_excess - v_fund_mtm)
    );

    IF v_park_amount <= 0 THEN
        RETURN jsonb_build_object(
            'skipped', TRUE,
            'reason', 'below_threshold',
            'balance', v_balance,
            'balance_net', GREATEST(0, v_balance - v_short_notional),
            'short_notional', v_short_notional,
            'equity', v_equity,
            'fund_mtm', v_fund_mtm,
            'excess', v_excess,
            'threshold', v_threshold
        );
    END IF;

    v_qty := (floor(v_park_amount / v_price)::INTEGER / v_lot) * v_lot;
    IF v_qty < v_lot THEN
        PERFORM logic_trade_log(
            p_logic_id,
            'cash_fund.skip_qty',
            format('РЎСѓРјРјР° %s в‚Ѕ РјРµРЅСЊС€Рµ 1 Р»РѕС‚Р° %s РїРѕ С†РµРЅРµ %s', v_park_amount, v_code, v_price),
            jsonb_build_object(
                'fund', v_code,
                'park_amount', v_park_amount,
                'equity', v_equity,
                'fund_mtm', v_fund_mtm,
                'excess', v_excess,
                'price', v_price,
                'lot', v_lot
            ),
            v_security_id,
            v_tf_id
        );
        RETURN jsonb_build_object(
            'skipped', TRUE,
            'reason', 'qty_below_lot',
            'park_amount', v_park_amount,
            'equity', v_equity,
            'price', v_price,
            'lot', v_lot
        );
    END IF;

    -- Fake / РЅРµС‚ FIGI: СЃРёРјСѓР»РёСЂСѓРµРј BUY РІ Р±РѕРµРІРѕР№ РєРЅРёРіРµ (РєР°Рє РІ С‚РµСЃС‚Рµ).
    IF v_logic.account_type = 'fake' OR v_figi IS NULL OR btrim(v_figi) = '' THEN
        SELECT id INTO v_side_open_id FROM sides WHERE name = 'Open' LIMIT 1;
        SELECT id INTO v_action_long_id FROM actions WHERE name = 'Long' LIMIT 1;
        IF v_security_id IS NULL OR v_side_open_id IS NULL OR v_action_long_id IS NULL THEN
            RETURN jsonb_build_object('ok', FALSE, 'reason', 'no_security_or_sides');
        END IF;

        INSERT INTO logic_trades (
            logic_id, account_id, security_id, timeframe_id,
            side_id, action_id, position_event, signal_kind, signal_formula,
            quantity, price, bar_dt, executed_at, is_simulated, is_fictitious,
            is_shadow, is_test, trade_reason, status, opt_lane
        )
        VALUES (
            p_logic_id, v_logic.account_id, v_security_id, v_tf_id,
            v_side_open_id, v_action_long_id, 'open', 'cash_fund',
            format('cash_fund.park %s', v_code),
            v_qty, v_price, v_closed_bar_dt, v_closed_bar_dt, TRUE, FALSE,
            FALSE, FALSE, format('cash_fund.park:%s', v_code), 'filled', ''
        )
        ON CONFLICT (logic_id, security_id, position_event, action_id, bar_dt, is_test, is_shadow, opt_lane)
        DO NOTHING
        RETURNING id INTO v_trade_id;

        IF v_trade_id IS NOT NULL THEN
            PERFORM logic_trade_finalize(v_trade_id, v_balance);
            v_balance := v_balance - (v_qty * v_price);
            v_balance := logic_cash_set_param(p_logic_id, v_balance);
        END IF;

        PERFORM logic_trade_log(
            p_logic_id,
            CASE WHEN v_trade_id IS NOT NULL THEN 'cash_fund.sim_ok' ELSE 'cash_fund.sim_dup' END,
            format(
                'Р‘РѕР№ (sim): РїР°СЂРєРѕРІРєР° %s qty=%s price=%s bar=%s',
                v_code, v_qty, v_price, v_closed_bar_dt
            ),
            jsonb_build_object(
                'fund', v_code,
                'quantity', v_qty,
                'price', v_price,
                'park_amount', v_park_amount,
                'balance', v_balance,
                'threshold', v_threshold,
                'trade_id', v_trade_id,
                'closed_bar', v_closed_bar_dt,
                'simulated', TRUE
            ),
            v_security_id,
            v_tf_id
        );

        RETURN jsonb_build_object(
            'ok', v_trade_id IS NOT NULL,
            'simulated', TRUE,
            'fund', v_code,
            'quantity', v_qty,
            'price', v_price,
            'park_amount', v_park_amount,
            'trade_id', v_trade_id,
            'closed_bar', v_closed_bar_dt
        );
    END IF;

    v_status := 'rejected';
    v_note := NULL;
    v_broker_order_id := NULL;
    BEGIN
        v_order := tbank_post_order(
            v_logic.account_id, v_figi, v_qty, v_price, 'BUY',
            logic_order_execution(p_logic_id)
        );
        v_broker_order_id := COALESCE(
            v_order->>'orderId',
            v_order->>'order_id',
            v_order->'orderState'->>'orderId'
        );
        v_status := tbank_trade_status_from_post_order(v_order);
        IF v_status = 'rejected' THEN
            v_note := left(COALESCE(v_order::TEXT, 'empty order response'), 500);
        END IF;
    EXCEPTION
        WHEN undefined_function THEN
            v_note := 'tbank_post_order РЅРµРґРѕСЃС‚СѓРїРµРЅ (РЅРµС‚ HTTP-СЂР°СЃС€РёСЂРµРЅРёСЏ)';
        WHEN OTHERS THEN
            v_note := SQLERRM;
    END;

    PERFORM logic_trade_log(
        p_logic_id,
        CASE WHEN v_status IN ('submitted', 'filled') THEN 'cash_fund.order_ok' ELSE 'cash_fund.order_fail' END,
        format(
            'РџР°СЂРєРѕРІРєР° %s: qty=%s price=%s status=%s',
            v_code, v_qty, v_price, v_status
        ),
        jsonb_build_object(
            'fund', v_code,
            'figi', v_figi,
            'quantity', v_qty,
            'price', v_price,
            'park_amount', v_park_amount,
            'balance', v_balance,
            'threshold', v_threshold,
            'status', v_status,
            'broker_order_id', v_broker_order_id,
            'note', v_note,
            'closed_bar', v_closed_bar_dt
        ),
        v_security_id,
        v_tf_id
    );

    RETURN jsonb_build_object(
        'ok', v_status = 'submitted',
        'fund', v_code,
        'quantity', v_qty,
        'price', v_price,
        'park_amount', v_park_amount,
        'status', v_status,
        'broker_order_id', v_broker_order_id,
        'note', v_note,
        'closed_bar', v_closed_bar_dt
    );
END;
$$;

