-- instrumentId РґР»СЏ GetCandles: ShareBy РїРѕ С‚РёРєРµСЂСѓ (РёСЃРїСЂР°РІР»СЏРµС‚ СѓСЃС‚Р°СЂРµРІС€РёР№ tbank_figi)

CREATE OR REPLACE FUNCTION logic_portfolio_drawdown_pct(p_logic_id INTEGER,
    p_timeframe_id INTEGER)
RETURNS NUMERIC
LANGUAGE plpgsql STABLE AS $$
DECLARE
    v_initial NUMERIC;
    v_equity NUMERIC;
BEGIN
    v_initial := get_logic_param_numeric(p_logic_id, 'initial_balance', 0);
    IF v_initial IS NULL OR v_initial <= 0 THEN
        RETURN 0;
    END IF;
    v_equity := logic_portfolio_equity(p_logic_id, p_timeframe_id);
    IF v_equity IS NULL OR v_equity >= v_initial THEN
        RETURN 0;
    END IF;
    RETURN (v_initial - v_equity) / v_initial * 100.0;
END;
$$;

-- РџРёРє equity (РѕР±РЅРѕРІР»СЏРµС‚СЃСЏ, РїРѕРєР° РЅРµС‚ portfolio_resume pause).

CREATE OR REPLACE FUNCTION logic_portfolio_equity(p_logic_id INTEGER,
    p_timeframe_id INTEGER)
RETURNS NUMERIC
LANGUAGE plpgsql STABLE AS $$
DECLARE
    v_cash NUMERIC;
    v_sec RECORD;
    v_price NUMERIC;
    v_long_qty NUMERIC;
    v_short_qty NUMERIC;
    v_total NUMERIC := 0;
BEGIN
    -- РљР°Рє logic_backtest_portfolio_equity: cash + longГ—price в€’ shortГ—price.
    -- Р‘РµР· short MTM РїСЂРё РѕС‚РєСЂС‹С‚С‹С… С€РѕСЂС‚Р°С… cash СЂР°Р·РґСѓС‚ (РІС‹СЂСѓС‡РєР°), Р° РїРѕСЃР»Рµ mass-close
    -- track_beforeв€’track_after РІР·Р»РµС‚Р°РµС‚ РґРѕ РЅРѕС‚РёРѕРЅР°Р»Р° (~В«С†РµР»СЊ 26801В»).
    v_cash := logic_ensure_balance(p_logic_id);
    v_total := COALESCE(v_cash, 0);

    FOR v_sec IN
        SELECT ls.security_id
        FROM logic_securities ls
        WHERE ls.logic_id = p_logic_id AND ls.is_active = TRUE
    LOOP
        v_long_qty := logic_long_position_qty(p_logic_id, v_sec.security_id, FALSE);
        v_short_qty := logic_short_position_qty(p_logic_id, v_sec.security_id, FALSE);
        IF v_long_qty <= 0 AND v_short_qty <= 0 THEN
            CONTINUE;
        END IF;
        v_price := logic_ensure_security_market_price(p_logic_id, v_sec.security_id, p_timeframe_id);
        IF v_price IS NOT NULL AND v_price > 0 THEN
            v_total := v_total + v_long_qty * v_price - v_short_qty * v_price;
        END IF;
    END LOOP;

    RETURN v_total;
END;
$$;

CREATE OR REPLACE FUNCTION logic_portfolio_has_open_positions(p_logic_id INTEGER,
    p_is_test BOOLEAN DEFAULT FALSE)
RETURNS BOOLEAN
LANGUAGE plpgsql STABLE AS $$
DECLARE
    v_sec RECORD;
BEGIN
    FOR v_sec IN
        SELECT ls.security_id
        FROM logic_securities ls
        WHERE ls.logic_id = p_logic_id AND ls.is_active = TRUE
          AND NOT logic_is_cash_fund_security(ls.security_id)
    LOOP
        IF logic_long_position_qty(p_logic_id, v_sec.security_id, FALSE, p_is_test) > 0
           OR logic_short_position_qty(p_logic_id, v_sec.security_id, FALSE, p_is_test) > 0
        THEN
            RETURN TRUE;
        END IF;
    END LOOP;
    RETURN FALSE;
END;
$$;

-- Р‘РѕР№: Р»РёРЅРµР№РЅС‹Р№ TP РїРѕ РІСЃРµРјСѓ РїРѕСЂС‚С„РµР»СЋ

CREATE OR REPLACE FUNCTION logic_portfolio_peak_drawdown_pct(p_logic_id INTEGER,
    p_timeframe_id INTEGER)
RETURNS NUMERIC
LANGUAGE plpgsql AS $$
DECLARE
    v_peak NUMERIC;
    v_equity NUMERIC;
BEGIN
    v_peak := logic_update_portfolio_equity_peak(p_logic_id, p_timeframe_id);
    IF v_peak IS NULL OR v_peak <= 0 THEN
        RETURN 0;
    END IF;
    v_equity := logic_portfolio_equity(p_logic_id, p_timeframe_id);
    IF v_equity IS NULL OR v_equity >= v_peak THEN
        RETURN 0;
    END IF;
    RETURN (v_peak - v_equity) / v_peak * 100.0;
END;
$$;

-- РўРµРЅРµРІРѕР№ track РїРѕСЂС‚С„РµР»СЏ: sum(shadow financial_result) РїРѕСЃР»Рµ РїР°СѓР·С‹
-- (СЃ portfolio_stop_resume_at; Р±РµР· РґР°С‚С‹ вЂ” РІСЃРµ shadow, РєР°Рє СЂР°РЅСЊС€Рµ).

CREATE OR REPLACE FUNCTION logic_portfolio_shadow_pnl(p_logic_id INTEGER)
RETURNS NUMERIC
LANGUAGE sql STABLE AS $$
    SELECT COALESCE(SUM(lt.financial_result), 0)
    FROM logic_trades lt
    CROSS JOIN LATERAL (
        SELECT l.portfolio_stop_resume_at AS since_at
        FROM logics l
        WHERE l.id = p_logic_id
    ) pause
    WHERE lt.logic_id = p_logic_id
      AND NOT lt.is_test
      AND lt.is_shadow = TRUE
      AND lt.status IN ('filled', 'submitted')
      AND lt.financial_result IS NOT NULL
      AND (
        pause.since_at IS NULL
        OR COALESCE(lt.bar_dt, lt.executed_at) >= pause.since_at
      );
$$;

