CREATE OR REPLACE FUNCTION logic_security_position_cost(p_logic_id INTEGER,
    p_security_id INTEGER,
    p_is_shadow BOOLEAN,
    p_is_test BOOLEAN DEFAULT FALSE)
RETURNS NUMERIC
LANGUAGE plpgsql STABLE AS $$
DECLARE
    v_long_qty NUMERIC;
    v_short_qty NUMERIC;
    v_long_cost NUMERIC := 0;
    v_short_cost NUMERIC := 0;
    v_open RECORD;
    v_rem NUMERIC;
BEGIN
    v_long_qty := logic_long_position_qty(p_logic_id, p_security_id, p_is_shadow, p_is_test);
    v_short_qty := logic_short_position_qty(p_logic_id, p_security_id, p_is_shadow, p_is_test);

    IF v_long_qty > 0 THEN
        FOR v_open IN
            SELECT lt.id, lt.quantity, lt.price
            FROM logic_trades lt
            JOIN sides s ON s.id = lt.side_id
            JOIN actions a ON a.id = lt.action_id
            WHERE lt.logic_id = p_logic_id
              AND lt.security_id = p_security_id
              AND lt.is_shadow = p_is_shadow
              AND lt.is_test = p_is_test
              AND s.name = 'Open' AND a.name = 'Long'
              AND lt.status IN ('filled', 'submitted')
            ORDER BY lt.executed_at ASC, lt.id ASC
        LOOP
            v_rem := logic_trade_open_remaining_qty(v_open.id);
            IF v_rem > 0 THEN
                v_long_cost := v_long_cost + v_rem * v_open.price;
            END IF;
        END LOOP;
    END IF;

    IF v_short_qty > 0 THEN
        FOR v_open IN
            SELECT lt.id, lt.quantity, lt.price
            FROM logic_trades lt
            JOIN sides s ON s.id = lt.side_id
            JOIN actions a ON a.id = lt.action_id
            WHERE lt.logic_id = p_logic_id
              AND lt.security_id = p_security_id
              AND lt.is_shadow = p_is_shadow
              AND s.name = 'Open' AND a.name = 'Short'
              AND lt.status IN ('filled', 'submitted')
            ORDER BY lt.executed_at ASC, lt.id ASC
        LOOP
            v_rem := logic_trade_open_remaining_qty(v_open.id);
            IF v_rem > 0 THEN
                v_short_cost := v_short_cost + v_rem * v_open.price;
            END IF;
        END LOOP;
    END IF;

    RETURN COALESCE(v_long_cost, 0) + COALESCE(v_short_cost, 0);
END;
$$;

CREATE OR REPLACE FUNCTION logic_security_position_market(p_logic_id INTEGER,
    p_security_id INTEGER,
    p_timeframe_id INTEGER,
    p_is_shadow BOOLEAN)
RETURNS NUMERIC
LANGUAGE plpgsql STABLE AS $$
DECLARE
    v_long_qty NUMERIC;
    v_short_qty NUMERIC;
    v_price NUMERIC;
    v_market NUMERIC := 0;
BEGIN
    v_price := logic_ensure_security_market_price(p_logic_id, p_security_id, p_timeframe_id);
    IF v_price IS NULL OR v_price <= 0 THEN
        RETURN NULL;
    END IF;
    v_long_qty := logic_long_position_qty(p_logic_id, p_security_id, p_is_shadow);
    v_short_qty := logic_short_position_qty(p_logic_id, p_security_id, p_is_shadow);
    v_market := (COALESCE(v_long_qty, 0) + COALESCE(v_short_qty, 0)) * v_price;
    RETURN v_market;
END;
$$;

CREATE OR REPLACE FUNCTION logic_security_side_drawdown_pct(p_logic_id INTEGER,
    p_security_id INTEGER,
    p_timeframe_id INTEGER,
    p_is_shadow BOOLEAN,
    p_position_side TEXT)
RETURNS NUMERIC
LANGUAGE plpgsql STABLE AS $$
DECLARE
    v_side TEXT;
    v_action TEXT;
    v_price NUMERIC;
    v_qty NUMERIC;
    v_open RECORD;
    v_rem NUMERIC;
    v_loss NUMERIC := 0;
    v_base NUMERIC := 0;
BEGIN
    v_side := logic_normalize_position_side(p_position_side);
    IF v_side IS NULL THEN
        RETURN 0;
    END IF;
    v_action := CASE WHEN v_side = 'long' THEN 'Long' ELSE 'Short' END;

    v_price := logic_ensure_security_market_price(p_logic_id, p_security_id, p_timeframe_id);
    IF v_price IS NULL OR v_price <= 0 THEN
        RETURN 0;
    END IF;

    IF v_side = 'long' THEN
        v_qty := logic_long_position_qty(p_logic_id, p_security_id, p_is_shadow);
    ELSE
        v_qty := logic_short_position_qty(p_logic_id, p_security_id, p_is_shadow);
    END IF;
    IF COALESCE(v_qty, 0) <= 0 THEN
        RETURN 0;
    END IF;

    FOR v_open IN
        SELECT lt.id, lt.price
        FROM logic_trades lt
        JOIN sides s ON s.id = lt.side_id
        JOIN actions a ON a.id = lt.action_id
        WHERE lt.logic_id = p_logic_id
          AND lt.security_id = p_security_id
          AND lt.is_shadow = p_is_shadow
          AND NOT lt.is_test
          AND s.name = 'Open' AND a.name = v_action
          AND lt.status IN ('filled', 'submitted')
    LOOP
        v_rem := logic_trade_open_remaining_qty(v_open.id);
        IF v_rem <= 0 THEN
            CONTINUE;
        END IF;
        v_base := v_base + v_rem * v_open.price;
        IF v_side = 'long' AND v_open.price > v_price THEN
            v_loss := v_loss + v_rem * (v_open.price - v_price);
        ELSIF v_side = 'short' AND v_price > v_open.price THEN
            v_loss := v_loss + v_rem * (v_price - v_open.price);
        END IF;
    END LOOP;

    IF v_base <= 0 THEN
        RETURN 0;
    END IF;
    RETURN GREATEST(v_loss / v_base * 100.0, 0);
END;
$$;

-- Track (realized Close + unrealized Open) С‚РѕР»СЊРєРѕ РїРѕ РѕРґРЅРѕР№ СЃС‚РѕСЂРѕРЅРµ.

CREATE OR REPLACE FUNCTION logic_security_side_track_value(p_logic_id INTEGER,
    p_security_id INTEGER,
    p_timeframe_id INTEGER,
    p_is_shadow BOOLEAN,
    p_position_side TEXT)
RETURNS NUMERIC
LANGUAGE plpgsql STABLE AS $$
DECLARE
    v_side TEXT;
    v_action TEXT;
    v_realized NUMERIC := 0;
    v_unrealized NUMERIC := 0;
    v_price NUMERIC;
    v_open RECORD;
    v_rem NUMERIC;
BEGIN
    v_side := logic_normalize_position_side(p_position_side);
    IF v_side IS NULL THEN
        RETURN 0;
    END IF;
    v_action := CASE WHEN v_side = 'long' THEN 'Long' ELSE 'Short' END;

    SELECT COALESCE(SUM(lt.financial_result), 0)
    INTO v_realized
    FROM logic_trades lt
    JOIN sides s ON s.id = lt.side_id
    JOIN actions a ON a.id = lt.action_id
    WHERE lt.logic_id = p_logic_id
      AND lt.security_id = p_security_id
      AND lt.is_shadow = p_is_shadow
      AND NOT lt.is_test
      AND s.name = 'Close'
      AND a.name = v_action
      AND lt.status IN ('filled', 'submitted')
      AND lt.financial_result IS NOT NULL;

    v_price := logic_ensure_security_market_price(p_logic_id, p_security_id, p_timeframe_id);
    IF v_price IS NULL OR v_price <= 0 THEN
        RETURN COALESCE(v_realized, 0);
    END IF;

    FOR v_open IN
        SELECT lt.id, lt.price
        FROM logic_trades lt
        JOIN sides s ON s.id = lt.side_id
        JOIN actions a ON a.id = lt.action_id
        WHERE lt.logic_id = p_logic_id
          AND lt.security_id = p_security_id
          AND lt.is_shadow = p_is_shadow
          AND NOT lt.is_test
          AND s.name = 'Open'
          AND a.name = v_action
          AND lt.status IN ('filled', 'submitted')
    LOOP
        v_rem := logic_trade_open_remaining_qty(v_open.id);
        IF v_rem <= 0 THEN
            CONTINUE;
        END IF;
        IF v_side = 'long' THEN
            v_unrealized := v_unrealized + v_rem * (v_price - v_open.price);
        ELSE
            v_unrealized := v_unrealized + v_rem * (v_open.price - v_price);
        END IF;
    END LOOP;

    RETURN COALESCE(v_realized, 0) + COALESCE(v_unrealized, 0);
END;
$$;

CREATE OR REPLACE FUNCTION logic_security_track_value(p_logic_id INTEGER,
    p_security_id INTEGER,
    p_timeframe_id INTEGER,
    p_is_shadow BOOLEAN)
RETURNS NUMERIC
LANGUAGE plpgsql STABLE AS $$
DECLARE
    v_realized NUMERIC := 0;
    v_unrealized NUMERIC := 0;
    v_price NUMERIC;
    v_open RECORD;
    v_rem NUMERIC;
BEGIN
    SELECT COALESCE(SUM(lt.financial_result), 0)
    INTO v_realized
    FROM logic_trades lt
    JOIN sides s ON s.id = lt.side_id
    WHERE lt.logic_id = p_logic_id
      AND lt.security_id = p_security_id
      AND lt.is_shadow = p_is_shadow
      AND s.name = 'Close'
      AND lt.status IN ('filled', 'submitted')
      AND lt.financial_result IS NOT NULL;

    v_price := logic_ensure_security_market_price(p_logic_id, p_security_id, p_timeframe_id);
    IF v_price IS NULL OR v_price <= 0 THEN
        RETURN v_realized;
    END IF;

    FOR v_open IN
        SELECT lt.id, lt.price, a.name AS action_name
        FROM logic_trades lt
        JOIN sides s ON s.id = lt.side_id
        JOIN actions a ON a.id = lt.action_id
        WHERE lt.logic_id = p_logic_id
          AND lt.security_id = p_security_id
          AND lt.is_shadow = p_is_shadow
          AND s.name = 'Open'
          AND lt.status IN ('filled', 'submitted')
    LOOP
        v_rem := logic_trade_open_remaining_qty(v_open.id);
        IF v_rem <= 0 THEN
            CONTINUE;
        END IF;
        IF v_open.action_name = 'Long' THEN
            v_unrealized := v_unrealized + v_rem * (v_price - v_open.price);
        ELSE
            v_unrealized := v_unrealized + v_rem * (v_open.price - v_price);
        END IF;
    END LOOP;

    RETURN COALESCE(v_realized, 0) + COALESCE(v_unrealized, 0);
END;
$$;

-- РќРѕСЂРјР°Р»РёР·Р°С†РёСЏ СЃС‚РѕСЂРѕРЅС‹: long|short (NULL/РїСѓСЃС‚Рѕ в†’ NULL).

CREATE OR REPLACE FUNCTION logic_selected_cash_fund_mtm(p_logic_id INTEGER,
    p_timeframe_id INTEGER)
RETURNS NUMERIC
LANGUAGE plpgsql AS $$
DECLARE
    v_code TEXT;
    v_sec RECORD;
    v_price NUMERIC;
    v_qty NUMERIC;
    v_mtm NUMERIC := 0;
BEGIN
    v_code := upper(btrim(COALESCE(
        get_logic_param_text(p_logic_id, 'cash_fund_code'),
        ''
    )));
    IF v_code = '' OR v_code NOT IN ('TMON', 'LQDT', 'SBMM') THEN
        RETURN 0;
    END IF;

    FOR v_sec IN
        SELECT ls.security_id
        FROM logic_securities ls
        JOIN security_prefixes sp ON sp.security_id = ls.security_id
        WHERE ls.logic_id = p_logic_id
          AND ls.is_active = TRUE
          AND upper(sp.prefix) = v_code
    LOOP
        v_qty := logic_long_position_qty(p_logic_id, v_sec.security_id, FALSE);
        IF v_qty <= 0 THEN
            CONTINUE;
        END IF;
        v_price := logic_ensure_security_market_price(
            p_logic_id, v_sec.security_id, p_timeframe_id
        );
        IF v_price IS NOT NULL AND v_price > 0 THEN
            v_mtm := v_mtm + v_qty * v_price;
        END IF;
    END LOOP;

    RETURN GREATEST(0, v_mtm);
END;
$$;

