CREATE OR REPLACE FUNCTION logic_signal_annualized_move_pct(p_move_pct NUMERIC,
    p_tf_sec INTEGER)
RETURNS NUMERIC
LANGUAGE sql IMMUTABLE AS $$
    SELECT COALESCE(p_move_pct, 0)
         * ((365.25 * 24 * 3600) / GREATEST(COALESCE(p_tf_sec, 900), 1)::NUMERIC);
$$;

