CREATE OR REPLACE FUNCTION logic_signal_eval_point(p_formula TEXT,
    p_logic_tf_id INTEGER,
    p_logic_bar_dt TIMESTAMP)
RETURNS TABLE (tf_id INTEGER, bar_dt TIMESTAMP)
LANGUAGE plpgsql IMMUTABLE AS $$
DECLARE
    v_parsed RECORD;
    v_expr TEXT;
    v_logic_sec INTEGER;
    v_sig_sec INTEGER;
    v_limit_epoch DOUBLE PRECISION;
    v_n DOUBLE PRECISION;
BEGIN
    SELECT t.sec INTO v_logic_sec FROM timeframes t WHERE t.id = p_logic_tf_id;
    IF v_logic_sec IS NULL OR v_logic_sec < 60 THEN
        tf_id := p_logic_tf_id;
        bar_dt := p_logic_bar_dt;
        RETURN NEXT;
        RETURN;
    END IF;

    SELECT * INTO v_parsed FROM parse_signal_formula(p_formula);
    v_expr := CASE WHEN COALESCE(v_parsed.valid, FALSE)
        THEN signal_param_value(v_parsed.params, 'tf')
        ELSE NULL END;

    v_sig_sec := signal_tf_parse_sec(v_expr);
    IF v_sig_sec IS NULL THEN
        -- РќР°СЃР»РµРґРѕРІР°РЅРёРµ: РўР¤ Р»РѕРіРёРєРё, Р±Р°СЂ РєР°Рє РїРµСЂРµРґР°РЅ
        tf_id := p_logic_tf_id;
        bar_dt := p_logic_bar_dt;
        RETURN NEXT;
        RETURN;
    END IF;

    tf_id := signal_tf_id_for_sec(v_sig_sec, p_logic_tf_id);

    v_limit_epoch := EXTRACT(EPOCH FROM (p_logic_bar_dt + make_interval(secs => v_logic_sec)));
    v_n := floor(v_limit_epoch / v_sig_sec);
    IF v_n < 1 THEN
        tf_id := NULL;
        bar_dt := NULL;
        RETURN NEXT;
        RETURN;
    END IF;
    bar_dt := TIMESTAMP '1970-01-01 00:00:00'
        + make_interval(secs => ((v_n - 1) * v_sig_sec)::INTEGER);
    RETURN NEXT;
END;
$$;

COMMENT ON FUNCTION logic_signal_eval_point(TEXT, INTEGER, TIMESTAMP) IS
'РўРѕС‡РєР° РѕС†РµРЅРєРё СЃРёРіРЅР°Р»Р° РїРѕ РµРіРѕ tf= РїР°СЂР°РјРµС‚СЂСѓ: (id РўР¤, РїРѕСЃР»РµРґРЅРёР№ Р·Р°РєСЂС‹С‚С‹Р№ Р±Р°СЂ СЌС‚РѕРіРѕ РўР¤ РґРѕ close Р±Р°СЂР° Р»РѕРіРёРєРё); NULL = РґР°РЅРЅС‹С… РµС‰С‘ РЅРµС‚';

-- Р Р°Р·Р»РёС‡РЅС‹Рµ РўР¤ РІСЃРµС… Р°РєС‚РёРІРЅС‹С… СЃРёРіРЅР°Р»РѕРІ Р»РѕРіРёРєРё (+ Р±Р°Р·РѕРІС‹Р№) вЂ” РґР»СЏ РґРѕРіСЂСѓР·РєРё С†РµРЅ/СЃРµСЂРёР№.

CREATE OR REPLACE FUNCTION logic_signal_eval_security_id(p_signal_id INTEGER,
    p_trade_security_id INTEGER)
RETURNS INTEGER
LANGUAGE plpgsql AS $$
DECLARE
    v_acts TEXT;
BEGIN
    SELECT COALESCE(NULLIF(btrim(lis.signal_acts_on), ''), 'security')
    INTO v_acts
    FROM logic_indicator_signals lis
    WHERE lis.id = p_signal_id;

    IF v_acts IS NULL THEN
        RETURN NULL;
    END IF;
    RETURN logic_signal_resolve_eval_security(v_acts, p_trade_security_id);
END;
$$;

COMMENT ON FUNCTION logic_signal_eval_security_id(INTEGER, INTEGER) IS
'signal_acts_on в†’ security | base_asset | contango eval security_id';

CREATE OR REPLACE FUNCTION logic_signal_evaluate_at(p_signal_id INTEGER,
    p_security_id INTEGER,
    p_tf_id INTEGER,
    p_bar_dt TIMESTAMP,
    p_invert BOOLEAN DEFAULT FALSE)
RETURNS TABLE (
    ok BOOLEAN,
    close_price NUMERIC,
    ind_value NUMERIC,
    bar_dt TIMESTAMP,
    formula TEXT,
    position_event TEXT,
    position_side TEXT,
    signal_kind TEXT,
    indicator_id INTEGER
)
LANGUAGE plpgsql STABLE AS $$
DECLARE
    v_sig RECORD;
    v_parsed RECORD;
    v_series TEXT;
    v_bar RECORD;
    v_condition TEXT;
    v_eval_sec INTEGER;
BEGIN
    ok := FALSE;
    SELECT lis.id, lis.formula, lis.position_event, lis.position_side, lis.signal_kind, lis.indicator_id
    INTO v_sig
    FROM logic_indicator_signals lis
    WHERE lis.id = p_signal_id AND lis.is_active = TRUE;
    IF NOT FOUND THEN
        RETURN NEXT;
        RETURN;
    END IF;

    formula := v_sig.formula;
    position_event := v_sig.position_event;
    position_side := v_sig.position_side;
    signal_kind := v_sig.signal_kind;
    indicator_id := v_sig.indicator_id;

    v_eval_sec := logic_signal_eval_security_id(p_signal_id, p_security_id);
    IF v_eval_sec IS NULL THEN
        RETURN NEXT;
        RETURN;
    END IF;

    SELECT * INTO v_parsed FROM parse_signal_formula(v_sig.formula);
    IF NOT COALESCE(v_parsed.valid, FALSE) THEN
        RETURN NEXT;
        RETURN;
    END IF;
    v_series := parse_signal_series(v_parsed.params);
    SELECT * INTO v_bar FROM logic_bar_data_at(
        v_eval_sec, p_tf_id, v_sig.indicator_id, v_series, p_bar_dt
    );
    IF NOT FOUND THEN
        RETURN NEXT;
        RETURN;
    END IF;
    close_price := v_bar.close_price;
    ind_value := v_bar.ind_value;
    bar_dt := v_bar.bar_dt;
    v_condition := v_parsed.condition;
    IF COALESCE(p_invert, FALSE) THEN
        v_condition := logic_invert_comparison_condition(v_condition);
    END IF;
    ok := evaluate_signal_condition(v_condition, v_bar.close_price, v_bar.ind_value);
    RETURN NEXT;
END;
$$;

CREATE OR REPLACE FUNCTION logic_signal_evaluate_at_opt(p_signal_id INTEGER,
    p_security_id INTEGER,
    p_tf_id INTEGER,
    p_bar_dt TIMESTAMP,
    p_invert BOOLEAN DEFAULT FALSE,
    p_opt_values JSONB DEFAULT NULL)
RETURNS TABLE (
    ok BOOLEAN,
    close_price NUMERIC,
    ind_value NUMERIC,
    bar_dt TIMESTAMP,
    formula TEXT,
    position_event TEXT,
    position_side TEXT,
    signal_kind TEXT,
    indicator_id INTEGER
)
LANGUAGE plpgsql AS $$
DECLARE
    v_sig RECORD;
    v_parsed RECORD;
    v_params TEXT;
    v_condition TEXT;
    v_pp NUMERIC;
    v_ind NUMERIC;
    v_eval_sec INTEGER;
BEGIN
    ok := FALSE;
    SELECT lis.id, lis.formula, lis.position_event, lis.position_side, lis.signal_kind, lis.indicator_id
    INTO v_sig
    FROM logic_indicator_signals lis
    WHERE lis.id = p_signal_id AND lis.is_active = TRUE;
    IF NOT FOUND THEN
        RETURN NEXT;
        RETURN;
    END IF;

    formula := v_sig.formula;
    position_event := v_sig.position_event;
    position_side := v_sig.position_side;
    signal_kind := v_sig.signal_kind;
    indicator_id := v_sig.indicator_id;

    v_eval_sec := logic_signal_eval_security_id(p_signal_id, p_security_id);
    IF v_eval_sec IS NULL THEN
        RETURN NEXT;
        RETURN;
    END IF;

    SELECT * INTO v_parsed FROM parse_signal_formula(v_sig.formula);
    IF NOT COALESCE(v_parsed.valid, FALSE) THEN
        RETURN NEXT;
        RETURN;
    END IF;

    v_params := logic_opt_expand_params(v_parsed.params, p_opt_values);
    v_condition := v_parsed.condition;
    IF COALESCE(p_invert, FALSE) THEN
        v_condition := logic_invert_comparison_condition(v_condition);
    END IF;

    SELECT p.close_price INTO v_pp
    FROM prices p
    WHERE p.security_id = v_eval_sec
      AND p.timeframe_id = p_tf_id
      AND p.dt = p_bar_dt
    LIMIT 1;
    IF v_pp IS NULL OR v_pp <= 0 THEN
        RETURN NEXT;
        RETURN;
    END IF;

    v_ind := logic_opt_calc_ind_at(
        v_sig.indicator_id, v_params, v_eval_sec, p_tf_id, p_bar_dt
    );
    IF v_ind IS NULL THEN
        RETURN NEXT;
        RETURN;
    END IF;

    close_price := v_pp;
    ind_value := v_ind;
    bar_dt := p_bar_dt;
    ok := evaluate_signal_condition(v_condition, v_pp, v_ind);
    RETURN NEXT;
END;
$$;

