CREATE OR REPLACE FUNCTION logic_signal_extra_tf_ids(p_logic_id INTEGER,
    p_base_tf_id INTEGER)
RETURNS TABLE (tf_id INTEGER)
LANGUAGE plpgsql AS $$
DECLARE
    r RECORD;
    v_expr TEXT;
    v_parsed RECORD;
    v_sec INTEGER;
    v_tid INTEGER;
    v_seen INTEGER[] := ARRAY[p_base_tf_id];
BEGIN
    FOR r IN
        SELECT lis.formula
        FROM logic_indicator_signals lis
        WHERE lis.logic_id = p_logic_id AND lis.is_active = TRUE
    LOOP
        SELECT * INTO v_parsed FROM parse_signal_formula(r.formula);
        IF NOT COALESCE(v_parsed.valid, FALSE) THEN
            CONTINUE;
        END IF;
        v_expr := signal_param_value(v_parsed.params, 'tf');
        v_sec := signal_tf_parse_sec(v_expr);
        IF v_sec IS NULL THEN
            CONTINUE;
        END IF;
        v_tid := signal_tf_id_for_sec(v_sec, p_base_tf_id);
        IF NOT (v_tid = ANY(v_seen)) THEN
            v_seen := array_append(v_seen, v_tid);
            tf_id := v_tid;
            RETURN NEXT;
        END IF;
    END LOOP;
END;
$$;

COMMENT ON FUNCTION logic_signal_extra_tf_ids(INTEGER, INTEGER) IS
'Р Р°Р·Р»РёС‡РЅС‹Рµ РґРѕРїРѕР»РЅРёС‚РµР»СЊРЅС‹Рµ РўР¤ Р°РєС‚РёРІРЅС‹С… СЃРёРіРЅР°Р»РѕРІ Р»РѕРіРёРєРё (РєСЂРѕРјРµ Р±Р°Р·РѕРІРѕРіРѕ) вЂ” РґР»СЏ Р·Р°РіСЂСѓР·РєРё С†РµРЅ/СЃРµСЂРёР№';

-- Р•СЃР»Рё РёСЃС‚РѕСЂРёСЏ СѓР¶Рµ РµСЃС‚СЊ вЂ” РґРѕРіСЂСѓР¶Р°РµРј С‚РѕР»СЊРєРѕ РґРµРЅСЊ Р·Р°РєСЂС‹С‚РѕРіРѕ Р±Р°СЂР° (1 HTTP), РЅРµ РІРµСЃСЊ lookback.

CREATE OR REPLACE FUNCTION logic_signal_move_success(p_position_side TEXT,
    p_signal_kind TEXT,
    p_price_from NUMERIC,
    p_price_to NUMERIC,
    p_tf_sec INTEGER,
    p_base_annual_pct NUMERIC)
RETURNS BOOLEAN
LANGUAGE plpgsql IMMUTABLE AS $$
DECLARE
    v_raw_pct NUMERIC;
    v_dir_pct NUMERIC;
    v_annual NUMERIC;
BEGIN
    IF p_price_from IS NULL OR p_price_to IS NULL OR p_price_from <= 0 THEN
        RETURN FALSE;
    END IF;
    v_raw_pct := ((p_price_to - p_price_from) / p_price_from) * 100.0;

    -- РћР¶РёРґР°РµРјРѕРµ РЅР°РїСЂР°РІР»РµРЅРёРµ: long/trend Рё short/counter вЂ” СЂРѕСЃС‚; РёРЅР°С‡Рµ вЂ” РїР°РґРµРЅРёРµ
    IF lower(p_position_side) = 'long' THEN
        IF lower(p_signal_kind) = 'trend' THEN
            v_dir_pct := v_raw_pct;
        ELSE
            v_dir_pct := -v_raw_pct;
        END IF;
    ELSE
        IF lower(p_signal_kind) = 'trend' THEN
            v_dir_pct := -v_raw_pct;
        ELSE
            v_dir_pct := v_raw_pct;
        END IF;
    END IF;

    v_annual := logic_signal_annualized_move_pct(v_dir_pct, p_tf_sec);
    RETURN v_annual >= COALESCE(p_base_annual_pct, 20);
END;
$$;

COMMENT ON FUNCTION logic_signal_move_success(TEXT, TEXT, NUMERIC, NUMERIC, INTEGER, NUMERIC) IS
'РЈСЃРїРµС… СЃРёРіРЅР°Р»Р°: (С…РѕРґ Рє СЃР»РµРґСѓСЋС‰РµР№ СЃРІРµС‡Рµ в†’ % РіРѕРґРѕРІС‹С… РІ СЃС‚РѕСЂРѕРЅСѓ СЃРёРіРЅР°Р»Р°) >= base_annual_rate_pct';

-- Р‘Р°Р·РѕРІС‹Р№ Р°РєС‚РёРІ С„СЊСЋС‡РµСЂСЃР° (security_prefixes.underlying_security_id).

CREATE OR REPLACE FUNCTION logic_signal_rate_bar(p_logic_id INTEGER,
    p_tf_id INTEGER,
    p_bar_dt TIMESTAMP,
    p_is_test BOOLEAN DEFAULT FALSE,
    p_run_id BIGINT DEFAULT NULL)
RETURNS INTEGER
LANGUAGE plpgsql AS $$
DECLARE
    v_sec RECORD;
    v_sig RECORD;
    v_eval RECORD;
    v_fires INTEGER := 0;
BEGIN
    IF p_run_id IS NOT NULL AND logic_backtest_cancel_requested(p_run_id) THEN
        RETURN 0;
    END IF;

    PERFORM logic_signal_rating_resolve_pending(
        p_logic_id, p_tf_id, p_bar_dt, COALESCE(p_is_test, FALSE), p_run_id
    );

    IF p_run_id IS NOT NULL AND logic_backtest_cancel_requested(p_run_id) THEN
        RETURN v_fires;
    END IF;

    FOR v_sec IN
        SELECT ls.security_id
        FROM logic_securities ls
        WHERE ls.logic_id = p_logic_id AND ls.is_active = TRUE
    LOOP
        IF p_run_id IS NOT NULL AND logic_backtest_cancel_requested(p_run_id) THEN
            RETURN v_fires;
        END IF;

        FOR v_sig IN
            SELECT lis.id, lis.position_side, lis.signal_kind
            FROM logic_indicator_signals lis
            WHERE lis.logic_id = p_logic_id AND lis.is_active = TRUE
            ORDER BY lis.display_order, lis.id
        LOOP
            SELECT * INTO v_eval
            FROM logic_signal_evaluate_at(
                v_sig.id, v_sec.security_id, p_tf_id, p_bar_dt
            );
            IF COALESCE(v_eval.ok, FALSE) AND v_eval.close_price IS NOT NULL THEN
                PERFORM logic_signal_record_fire(
                    v_sig.id, p_logic_id, v_sec.security_id, p_tf_id,
                    v_eval.bar_dt, v_eval.close_price,
                    v_sig.position_side, v_sig.signal_kind,
                    COALESCE(p_is_test, FALSE), p_run_id
                );
                v_fires := v_fires + 1;
            END IF;
        END LOOP;
    END LOOP;

    RETURN v_fires;
END;
$$;

COMMENT ON FUNCTION logic_signal_rate_bar(INTEGER, INTEGER, TIMESTAMP, BOOLEAN, BIGINT) IS
'РџРѕ РѕРґРЅРѕР№ СЃРІРµС‡Рµ TF: resolve pending В±1 + record_fire РґР»СЏ РІСЃРµС… СЃРёРіРЅР°Р»РѕРІГ—Р±СѓРјР°Рі (Р±РѕР№/С‚РµСЃС‚)';

CREATE OR REPLACE FUNCTION logic_signal_rating_reset_live(p_logic_id INTEGER)
RETURNS VOID
LANGUAGE plpgsql AS $$
BEGIN
    UPDATE logic_indicator_signals
    SET rating = 0
    WHERE logic_id = p_logic_id;

    DELETE FROM logic_signal_rating_pending
    WHERE logic_id = p_logic_id AND is_test = FALSE;

    DELETE FROM logic_signal_rating_history
    WHERE logic_id = p_logic_id AND is_test = FALSE;
END;
$$;

COMMENT ON FUNCTION logic_signal_rating_reset_live(INTEGER) IS
'РЎР±СЂРѕСЃ Р±РѕРµРІРѕРіРѕ СЂРµР№С‚РёРЅРіР° Рё РёСЃС‚РѕСЂРёРё РїРµСЂРµРґ РїСЂРµРґСЂР°СЃС‡С‘С‚РѕРј РїСЂРё РІРєР»СЋС‡РµРЅРёРё Р»РѕРіРёРєРё';

-- РџРѕРґРіРѕС‚РѕРІРєР° РґР°РЅРЅС‹С… РѕРєРЅР° РїСЂРµРґСЂР°СЃС‡С‘С‚Р°: С†РµРЅС‹ + РёРЅРґРёРєР°С‚РѕСЂС‹ СЃРёРіРЅР°Р»РѕРІ Р»РѕРіРёРєРё

CREATE OR REPLACE FUNCTION logic_signal_rating_resolve_pending(p_logic_id INTEGER,
    p_tf_id INTEGER,
    p_asof_bar_dt TIMESTAMP DEFAULT NULL,
    p_is_test BOOLEAN DEFAULT FALSE,
    p_run_id BIGINT DEFAULT NULL)
RETURNS INTEGER
LANGUAGE plpgsql AS $$
DECLARE
    v_tf_sec INTEGER;
    v_annual NUMERIC;
    v_pend RECORD;
    v_next_dt TIMESTAMP;
    v_next_close NUMERIC;
    v_ok BOOLEAN;
    v_delta INTEGER;
    v_new_rating INTEGER;
    v_sec_rating INTEGER;
    v_resolved INTEGER := 0;
BEGIN
    SELECT t.sec INTO v_tf_sec FROM timeframes t WHERE t.id = p_tf_id;
    v_annual := get_logic_param_numeric(p_logic_id, 'base_annual_rate_pct', 20);

    FOR v_pend IN
        SELECT p.*
        FROM logic_signal_rating_pending p
        WHERE p.logic_id = p_logic_id
          AND p.timeframe_id = p_tf_id
          AND p.is_test = COALESCE(p_is_test, FALSE)
          AND (p_run_id IS NULL OR p.run_id IS NULL OR p.run_id = p_run_id)
          AND (p_asof_bar_dt IS NULL OR p.bar_dt < p_asof_bar_dt)
        ORDER BY p.bar_dt, p.id
    LOOP
        IF p_run_id IS NOT NULL
           AND v_resolved > 0
           AND (v_resolved % 50) = 0
           AND logic_backtest_cancel_requested(p_run_id) THEN
            RETURN v_resolved;
        END IF;

        SELECT p.dt, p.close_price
        INTO v_next_dt, v_next_close
        FROM prices p
        WHERE p.security_id = v_pend.security_id
          AND p.timeframe_id = p_tf_id
          AND p.dt > v_pend.bar_dt
          AND (p_asof_bar_dt IS NULL OR p.dt <= p_asof_bar_dt)
        ORDER BY p.dt
        LIMIT 1;

        IF v_next_dt IS NULL THEN
            CONTINUE;
        END IF;

        v_ok := logic_signal_move_success(
            v_pend.position_side, v_pend.signal_kind,
            v_pend.price, v_next_close, v_tf_sec, v_annual
        );
        v_delta := CASE WHEN v_ok THEN 1 ELSE -1 END;

        -- Р“Р»РѕР±Р°Р»СЊРЅС‹Р№ СЂРµР№С‚РёРЅРі СЃРёРіРЅР°Р»Р° (СЃСѓРјРјР° РїРѕ РІСЃРµРј Р±СѓРјР°РіР°Рј), РјРѕР¶РµС‚ Р±С‹С‚СЊ < 0
        IF COALESCE(p_is_test, FALSE) THEN
            UPDATE logic_indicator_signals lis
            SET rating_test = lis.rating_test + v_delta
            WHERE lis.id = v_pend.signal_id
            RETURNING rating_test INTO v_new_rating;
        ELSE
            UPDATE logic_indicator_signals lis
            SET rating = lis.rating + v_delta
            WHERE lis.id = v_pend.signal_id
            RETURNING rating INTO v_new_rating;
        END IF;

        -- Р РµР№С‚РёРЅРі РЅР° Р±СѓРјР°РіРµ РґР»СЏ РіСЂР°С„РёРєР°
        SELECT COALESCE((
            SELECT h.rating
            FROM logic_signal_rating_history h
            WHERE h.signal_id = v_pend.signal_id
              AND h.security_id = v_pend.security_id
              AND h.is_test = COALESCE(p_is_test, FALSE)
              AND (p_run_id IS NULL OR h.run_id IS NULL OR h.run_id = p_run_id OR h.run_id = v_pend.run_id)
            ORDER BY h.bar_dt DESC, h.id DESC
            LIMIT 1
        ), 0) + v_delta
        INTO v_sec_rating;

        INSERT INTO logic_signal_rating_history (
            signal_id, logic_id, security_id, run_id, bar_dt, rating, delta, is_test
        )
        VALUES (
            v_pend.signal_id, p_logic_id, v_pend.security_id,
            COALESCE(p_run_id, v_pend.run_id),
            v_next_dt, v_sec_rating, v_delta,
            COALESCE(p_is_test, FALSE)
        );

        DELETE FROM logic_signal_rating_pending WHERE id = v_pend.id;
        v_resolved := v_resolved + 1;
    END LOOP;

    RETURN v_resolved;
END;
$$;

COMMENT ON FUNCTION logic_signal_rating_resolve_pending(INTEGER, INTEGER, TIMESTAMP, BOOLEAN, BIGINT) IS
'РќР° СЃР»РµРґСѓСЋС‰РµР№ СЃРІРµС‡Рµ: РіРѕРґРѕРІР°СЏ СЃС‚Р°РІРєР° С…РѕРґР° vs base_annual_rate_pct в†’ В±1; history РїРѕ Р±СѓРјР°РіРµ';

-- РћР±С‰РёР№ РїСЂРѕС…РѕРґ РїРѕ Р±Р°СЂСѓ: resolve pending + Р·Р°РїРёСЃСЊ СЃСЂР°Р±Р°С‚С‹РІР°РЅРёР№ (Р±РѕР№ РёР»Рё С‚РµСЃС‚)

CREATE OR REPLACE FUNCTION logic_signal_resolve_eval_security(p_acts_on TEXT,
    p_trade_security_id INTEGER)
RETURNS INTEGER
LANGUAGE plpgsql AS $$
DECLARE
    v_acts TEXT := lower(btrim(COALESCE(p_acts_on, 'security')));
BEGIN
    IF p_trade_security_id IS NULL THEN
        RETURN NULL;
    END IF;
    IF v_acts = 'base_asset' THEN
        RETURN logic_future_underlying_security_id(p_trade_security_id);
    END IF;
    IF v_acts = 'contango' THEN
        RETURN logic_contango_security_id(p_trade_security_id);
    END IF;
    RETURN p_trade_security_id;
END;
$$;

COMMENT ON FUNCTION logic_signal_resolve_eval_security(TEXT, INTEGER) IS
'security | base_asset | contango в†’ security_id РґР»СЏ С†РµРЅ/РёРЅРґРёРєР°С‚РѕСЂРѕРІ';

-- РќР° РєР°РєРѕР№ security_id СЃС‡РёС‚Р°С‚СЊ СЃРёРіРЅР°Р»: С‚РѕСЂРіСѓРµРјР°СЏ Р±СѓРјР°РіР°, underlying РёР»Рё contango.

CREATE OR REPLACE FUNCTION logic_skip_signal_by_periods(p_logic_id INTEGER,
    p_dt TIMESTAMP)
RETURNS BOOLEAN
LANGUAGE plpgsql STABLE AS $$
DECLARE
    v_mode TEXT;
    v_in_non_trading BOOLEAN;
BEGIN
    v_mode := get_non_trading_periods_mode(p_logic_id);
    IF v_mode = 'off' THEN
        RETURN FALSE;
    END IF;
    v_in_non_trading := logic_is_non_trading_dt(p_logic_id, p_dt);
    IF v_mode = 'non_trading' THEN
        RETURN NOT v_in_non_trading;
    END IF;
    RETURN v_in_non_trading;
END;
$$;

