CREATE OR REPLACE FUNCTION logic_sync_all_real_account_balances()
RETURNS INTEGER
LANGUAGE plpgsql AS $$
DECLARE
    r RECORD;
    v_n INTEGER := 0;
BEGIN
    FOR r IN
        SELECT l.id
        FROM logics l
        JOIN accounts a ON a.id = l.account_id
        WHERE lower(COALESCE(a.account_type, 'fake')) <> 'fake'
    LOOP
        PERFORM logic_apply_real_account_balances(r.id, TRUE);
        v_n := v_n + 1;
    END LOOP;
    RETURN v_n;
END;
$$;

COMMENT ON FUNCTION logic_sync_all_real_account_balances() IS
'Upgrade/install: РґР»СЏ РІСЃРµС… real-Р»РѕРіРёРє РІС‹СЃС‚Р°РІРёС‚СЊ РѕСЃС‚Р°С‚РєРё СЃ Р±СЂРѕРєРµСЂР° (РёР»Рё 0).';

CREATE OR REPLACE FUNCTION logic_sync_real_trade_broker_fees(p_logic_id INTEGER DEFAULT NULL)
RETURNS JSONB
LANGUAGE plpgsql AS $$
DECLARE
    v_tr RECORD;
    v_order JSONB;
    v_comm NUMERIC;
    v_price NUMERIC;
    v_updated INTEGER := 0;
    v_not_found INTEGER := 0;
    v_refinalized INTEGER := 0;
    v_rebuild_error TEXT := NULL;
    v_errors JSONB := '[]'::JSONB;
BEGIN
    FOR v_tr IN
        SELECT lt.id, lt.account_id, lt.broker_order_id, lt.price, lt.commission,
               lt.logic_id, lt.side_id, lt.is_simulated
        FROM logic_trades lt
        JOIN logics l ON l.id = lt.logic_id
        JOIN accounts a ON a.id = l.account_id
        WHERE COALESCE(lt.is_simulated, FALSE) = FALSE
          AND COALESCE(lt.is_test, FALSE) = FALSE
          AND COALESCE(lt.is_shadow, FALSE) = FALSE
          AND lt.broker_order_id IS NOT NULL
          AND btrim(lt.broker_order_id) <> ''
          -- РћРїСЂР°С€РёРІР°РµРј С‚РѕР»СЊРєРѕ РќР• С„РёРЅР°Р»СЊРЅС‹Рµ Р·Р°СЏРІРєРё: 'filled' СѓР¶Рµ РїСЂРёС€С‘Р» РѕС‚ Р±СЂРѕРєРµСЂР°
          -- РєР°Рє РїРѕР»РЅРѕРµ РёСЃРїРѕР»РЅРµРЅРёРµ Рё РёР·РјРµРЅРёС‚СЊСЃСЏ РЅРµ РјРѕР¶РµС‚. Р—Р°СЏРІРєРё, РїРѕ РєРѕС‚РѕСЂС‹Рј T-Bank
          -- РІРµСЂРЅСѓР» 404 (broker_order_missing), Р±РѕР»СЊС€Рµ РЅРµ С‚СЂРѕРіР°РµРј.
          AND COALESCE(lt.broker_order_missing, FALSE) = FALSE
          AND lt.status = 'submitted'
          AND (p_logic_id IS NULL OR lt.logic_id = p_logic_id)
          AND a.account_type = 'real'
          AND a.broker_id IN (SELECT id FROM brokers WHERE code = 'T-BANK')
        ORDER BY lt.id
    LOOP
        BEGIN
            v_order := tbank_get_order_state(v_tr.account_id, v_tr.broker_order_id);
            v_comm := tbank_order_commission(v_order);
            v_price := tbank_order_unit_price(v_order);

            IF v_comm > 0 OR (v_price IS NOT NULL AND v_price > 0) THEN
                UPDATE logic_trades
                SET
                    commission = CASE WHEN v_comm > 0 THEN v_comm ELSE commission END,
                    price = CASE
                        WHEN v_price IS NOT NULL AND v_price > 0 THEN v_price
                        ELSE price
                    END,
                    status = CASE
                        WHEN tbank_trade_status_from_post_order(v_order) = 'filled'
                        THEN 'filled'
                        ELSE status
                    END
                WHERE id = v_tr.id;
                v_updated := v_updated + 1;

                -- Р¤РёРЅР°Р»СЊРЅР°СЏ С†РµРЅР°/РєРѕРјРёСЃСЃРёСЏ РёР·РјРµРЅРёР»Рё РІС…РѕРґС‹ PnL: РїРµСЂРµСЃРѕР±СЂР°С‚СЊ РїР°РєРµС‚С‹
                -- Рё financial_result СЌС‚РѕР№ СЃРґРµР»РєРё РЎР РђР—РЈ (РЅРµ Р¶РґР°С‚СЊ РїРѕР»РЅРѕРіРѕ rebuild).
                IF v_price IS NOT NULL AND v_price > 0
                   AND COALESCE(v_price, 0) IS DISTINCT FROM v_tr.price THEN
                    PERFORM logic_trade_finalize(v_tr.id, NULL);
                    v_refinalized := v_refinalized + 1;
                END IF;
            END IF;
        EXCEPTION
            WHEN OTHERS THEN
                -- T-Bank Р±РѕР»СЊС€Рµ РЅРµ Р·РЅР°РµС‚ Р·Р°СЏРІРєСѓ (СЃС‚Р°СЂР°СЏ/С‡СѓР¶РѕР№ РєРѕРЅС‚СѓСЂ) в†’ РїРѕРјРµС‡Р°РµРј
                -- РµС‘ РЅРµРґРѕСЃС‚СѓРїРЅРѕР№ Рё РІС‹РІРѕРґРёРј РёР· СЃРёРЅРєР°, С‡С‚РѕР±С‹ РЅРµ РґРѕР»Р±РёС‚СЊ 404 РєР°Р¶РґС‹Рµ 5 РјРёРЅСѓС‚.
                IF SQLERRM ILIKE '%order not found%'
                   OR SQLERRM ILIKE '%not found%'
                   OR SQLERRM LIKE '%HTTP 404%' THEN
                    UPDATE logic_trades
                    SET broker_order_missing = TRUE
                    WHERE id = v_tr.id;
                    v_not_found := v_not_found + 1;
                ELSE
                    v_errors := v_errors || jsonb_build_array(jsonb_build_object(
                        'trade_id', v_tr.id,
                        'order_id', v_tr.broker_order_id,
                        'error', SQLERRM
                    ));
                END IF;
        END;
    END LOOP;

    -- РџРѕР»РЅС‹Р№ СЂРµР±РёР»Рґ РёСЃС‚РѕСЂРёРё: РіР°СЂР°РЅС‚РёСЂСѓРµС‚ СЃРѕРіР»Р°СЃРѕРІР°РЅРЅРѕСЃС‚СЊ РїР°РєРµС‚РѕРІ/PnL.
    -- РћС€РёР±РєР° rebuild РЅРµ РґРѕР»Р¶РЅР° С‚РµСЂСЏС‚СЊСЃСЏ РјРѕР»С‡Р° вЂ” РїРѕРїР°РґР°РµС‚ РІ СЂРµР·СѓР»СЊС‚Р°С‚ Рё warning.
    BEGIN
        IF p_logic_id IS NOT NULL THEN
            PERFORM logic_trade_rebuild_pnl(p_logic_id);
        ELSE
            PERFORM logic_trade_rebuild_pnl(l.id)
            FROM logics l
            JOIN accounts a ON a.id = l.account_id
            WHERE a.account_type = 'real';
        END IF;
    EXCEPTION
        WHEN OTHERS THEN
            v_rebuild_error := SQLERRM;
            RAISE WARNING 'logic_sync_real_trade_broker_fees: rebuild_pnl failed: %', SQLERRM;
    END;

    RETURN jsonb_build_object(
        'ok', TRUE,
        'updated', v_updated,
        'order_not_found', v_not_found,
        'refinalized', v_refinalized,
        'rebuild_error', v_rebuild_error,
        'errors', v_errors,
        'logic_id', p_logic_id
    );
END;
$$;

COMMENT ON FUNCTION logic_sync_real_trade_broker_fees(INTEGER) IS
'РџРѕРґС‚СЏРЅСѓС‚СЊ РєРѕРјРёСЃСЃРёСЋ/С†РµРЅСѓ РёСЃРїРѕР»РЅРµРЅРёСЏ СЃ T-Bank GetOrderState РґР»СЏ РµС‰С‘ РќР• С„РёРЅР°Р»СЊРЅС‹С… (status=submitted) Р±РѕРµРІС‹С… Р·Р°СЏРІРѕРє; РїСЂРё РёР·РјРµРЅРµРЅРёРё С†РµРЅС‹ Р·Р°РєСЂС‹С‚РёСЏ вЂ” СЃСЂР°Р·Сѓ РїРµСЂРµСЃРѕР±СЂР°С‚СЊ РµС‘ РїР°РєРµС‚С‹/PnL; Р·Р°СЏРІРєРё СЃ РѕС‚РІРµС‚РѕРј 404 Order not found РїРѕРјРµС‡Р°СЋС‚СЃСЏ broker_order_missing Рё Р±РѕР»СЊС€Рµ РЅРµ РѕРїСЂР°С€РёРІР°СЋС‚СЃСЏ; РІ РєРѕРЅС†Рµ РїРѕР»РЅС‹Р№ rebuild_pnl';

-- Р СѓС‡РЅС‹Рµ СЃРґРµР»РєРё С‚РµСЂРјРёРЅР°Р»Р° РїРѕ СЂРµР°Р»СЊРЅРѕРјСѓ СЃС‡С‘С‚Сѓ: PostOrder Сѓ РјР°СЂРєРµС‚-Р·Р°СЏРІРєРё РєРѕРјРёСЃСЃРёСЋ
-- РѕР±С‹С‡РЅРѕ РЅРµ РІРѕР·РІСЂР°С‰Р°РµС‚, Р° С„Р°РєС‚РёС‡РµСЃРєРё РёСЃРїРѕР»РЅРёР»РѕСЃСЊ Р¦Р•Р›РћР• С‡РёСЃР»Рѕ Р»РѕС‚РѕРІ (РЅРµ Р·Р°РїСЂРѕС€РµРЅРЅРѕРµ).
-- Р”РѕС‚СЏРіРёРІР°РµРј РєРѕРјРёСЃСЃРёСЋ Рё С„Р°РєС‚РёС‡РµСЃРєСѓСЋ С†РµРЅСѓ/РєРѕР»РёС‡РµСЃС‚РІРѕ СЃ GetOrderState. РЈ С‚РµСЂРјРёРЅР°Р»Р°
-- status СЃСЂР°Р·Сѓ 'filled', РїРѕСЌС‚РѕРјСѓ С„РёР»СЊС‚СЂ вЂ” РїРѕ РєРѕРјРёСЃСЃРёРё (commission <= 0 = РµС‰С‘ РЅРµ СЃРёРЅРєР°Р»Рё).

CREATE OR REPLACE FUNCTION logic_trade_build_lots(p_close_trade_id BIGINT)
RETURNS VOID
LANGUAGE plpgsql AS $$
DECLARE
    v_close RECORD;
    v_method TEXT;
    v_remaining NUMERIC;
    v_open RECORD;
    v_alloc NUMERIC;
    v_open_rem NUMERIC;
    v_close_comm_part NUMERIC;
    v_open_comm_part NUMERIC;
    v_close_amt NUMERIC;
    v_open_amt NUMERIC;
    v_pnl NUMERIC;
    v_total_pnl NUMERIC := 0;
    v_avg_price NUMERIC;
    v_total_open_qty NUMERIC;
    v_total_open_cost NUMERIC;
    v_total_open_comm NUMERIC;
BEGIN
    SELECT lt.*, sd.name AS side_name, ac.name AS action_name
    INTO v_close
    FROM logic_trades lt
    JOIN sides sd ON sd.id = lt.side_id
    JOIN actions ac ON ac.id = lt.action_id
    WHERE lt.id = p_close_trade_id;

    IF NOT FOUND OR v_close.side_name <> 'Close' THEN
        RETURN;
    END IF;
    IF v_close.status NOT IN ('filled', 'submitted') THEN
        RETURN;
    END IF;

    DELETE FROM logic_trade_lots WHERE close_trade_id = p_close_trade_id;

    v_method := upper(btrim(COALESCE(get_logic_param_text(v_close.logic_id, 'cost_method'), 'FIFO')));
    IF v_method NOT IN ('FIFO', 'AVERAGE') THEN
        v_method := 'FIFO';
    END IF;

    v_remaining := v_close.quantity;

    IF v_method = 'AVERAGE' THEN
        SELECT
            COALESCE(SUM(logic_trade_open_remaining_qty(lt.id)), 0),
            COALESCE(SUM(logic_trade_open_remaining_qty(lt.id) * lt.price), 0),
            COALESCE(SUM(
                CASE WHEN lt.quantity > 0
                    THEN COALESCE(lt.commission, 0) * logic_trade_open_remaining_qty(lt.id) / lt.quantity
                    ELSE 0
                END
            ), 0)
        INTO v_total_open_qty, v_total_open_cost, v_total_open_comm
        FROM logic_trades lt
        JOIN sides sd ON sd.id = lt.side_id
        JOIN actions ac ON ac.id = lt.action_id
        WHERE lt.logic_id = v_close.logic_id
          AND lt.security_id = v_close.security_id
          AND sd.name = 'Open'
          AND ac.name = v_close.action_name
          AND lt.status IN ('filled', 'submitted')
          AND lt.executed_at <= v_close.executed_at
          AND COALESCE(lt.is_shadow, FALSE) = COALESCE(v_close.is_shadow, FALSE)
          AND logic_trade_open_remaining_qty(lt.id) > 0;

        IF v_total_open_qty <= 0 THEN
            RETURN;
        END IF;

        v_avg_price := v_total_open_cost / v_total_open_qty;

        FOR v_open IN
            SELECT lt.id, lt.quantity, lt.commission
            FROM logic_trades lt
            JOIN sides sd ON sd.id = lt.side_id
            JOIN actions ac ON ac.id = lt.action_id
            WHERE lt.logic_id = v_close.logic_id
              AND lt.security_id = v_close.security_id
              AND sd.name = 'Open'
              AND ac.name = v_close.action_name
              AND lt.status IN ('filled', 'submitted')
              AND lt.executed_at <= v_close.executed_at
              AND COALESCE(lt.is_shadow, FALSE) = COALESCE(v_close.is_shadow, FALSE)
            ORDER BY lt.executed_at ASC, lt.id ASC
        LOOP
            EXIT WHEN v_remaining <= 0;
            v_open_rem := logic_trade_open_remaining_qty(v_open.id);
            IF v_open_rem <= 0 THEN
                CONTINUE;
            END IF;
            v_alloc := LEAST(v_remaining, v_open_rem);
            v_close_amt := v_alloc * v_close.price;
            v_open_amt := v_alloc * v_avg_price;
            v_close_comm_part := CASE WHEN v_close.quantity > 0
                THEN COALESCE(v_close.commission, 0) * v_alloc / v_close.quantity ELSE 0 END;
            v_open_comm_part := CASE WHEN v_total_open_qty > 0
                THEN v_total_open_comm * v_alloc / v_total_open_qty ELSE 0 END;

            IF v_close.action_name = 'Long' THEN
                v_pnl := v_close_amt - v_open_amt - v_close_comm_part - v_open_comm_part;
            ELSE
                v_pnl := v_open_amt - v_close_amt - v_close_comm_part - v_open_comm_part;
            END IF;

            INSERT INTO logic_trade_lots (
                logic_id, close_trade_id, open_trade_id,
                quantity, close_amount, open_amount,
                close_commission, open_commission, financial_result,
                action_id, cost_method
            )
            VALUES (
                v_close.logic_id, p_close_trade_id, v_open.id,
                v_alloc, v_close_amt, v_open_amt,
                v_close_comm_part, v_open_comm_part, v_pnl,
                v_close.action_id, 'AVERAGE'
            );
            v_total_pnl := v_total_pnl + v_pnl;
            v_remaining := v_remaining - v_alloc;
        END LOOP;
    ELSE
        FOR v_open IN
            SELECT lt.id, lt.quantity, lt.price, lt.commission, lt.executed_at
            FROM logic_trades lt
            JOIN sides sd ON sd.id = lt.side_id
            JOIN actions ac ON ac.id = lt.action_id
            WHERE lt.logic_id = v_close.logic_id
              AND lt.security_id = v_close.security_id
              AND sd.name = 'Open'
              AND ac.name = v_close.action_name
              AND lt.status IN ('filled', 'submitted')
              AND lt.executed_at <= v_close.executed_at
              AND COALESCE(lt.is_shadow, FALSE) = COALESCE(v_close.is_shadow, FALSE)
            ORDER BY lt.executed_at ASC, lt.id ASC
        LOOP
            EXIT WHEN v_remaining <= 0;
            v_open_rem := logic_trade_open_remaining_qty(v_open.id);
            IF v_open_rem <= 0 THEN
                CONTINUE;
            END IF;
            v_alloc := LEAST(v_remaining, v_open_rem);
            v_close_amt := v_alloc * v_close.price;
            v_open_amt := v_alloc * v_open.price;
            v_close_comm_part := CASE WHEN v_close.quantity > 0
                THEN COALESCE(v_close.commission, 0) * v_alloc / v_close.quantity ELSE 0 END;
            v_open_comm_part := CASE WHEN v_open.quantity > 0
                THEN COALESCE(v_open.commission, 0) * v_alloc / v_open.quantity ELSE 0 END;

            IF v_close.action_name = 'Long' THEN
                v_pnl := v_close_amt - v_open_amt - v_close_comm_part - v_open_comm_part;
            ELSE
                v_pnl := v_open_amt - v_close_amt - v_close_comm_part - v_open_comm_part;
            END IF;

            INSERT INTO logic_trade_lots (
                logic_id, close_trade_id, open_trade_id,
                quantity, close_amount, open_amount,
                close_commission, open_commission, financial_result,
                action_id, cost_method
            )
            VALUES (
                v_close.logic_id, p_close_trade_id, v_open.id,
                v_alloc, v_close_amt, v_open_amt,
                v_close_comm_part, v_open_comm_part, v_pnl,
                v_close.action_id, 'FIFO'
            );
            v_total_pnl := v_total_pnl + v_pnl;
            v_remaining := v_remaining - v_alloc;
        END LOOP;
    END IF;

    UPDATE logic_trades
    SET financial_result = CASE WHEN v_total_pnl <> 0 THEN v_total_pnl ELSE NULL END
    WHERE id = p_close_trade_id;
END;
$$;

COMMENT ON FUNCTION logic_trade_build_lots(BIGINT) IS
'РџР°РєРµС‚С‹ Р·Р°РєСЂС‹С‚РёСЏ: FIFO РёР»Рё СЃСЂРµРґРЅСЏСЏ; financial_result С‚РѕР»СЊРєРѕ РЅР° Р·Р°РєСЂС‹РІР°СЋС‰РµР№ СЃРґРµР»РєРµ';

CREATE OR REPLACE FUNCTION logic_trade_calc_commission(p_logic_id INTEGER,
    p_notional NUMERIC)
RETURNS NUMERIC
LANGUAGE plpgsql STABLE AS $$
DECLARE
    v_pct NUMERIC;
    v_base NUMERIC;
BEGIN
    v_pct := get_logic_param_numeric(p_logic_id, 'commission_pct', 0);
    IF v_pct IS NULL OR v_pct <= 0 THEN
        RETURN 0;
    END IF;
    -- % РѕС‚ РЅРѕРјРёРЅР°Р»Р° СЃРґРµР»РєРё (С†РµРЅР° Г— РєРѕР»РёС‡РµСЃС‚РІРѕ), РЅРµ РѕС‚ РґРµРїРѕР·РёС‚Р°
    v_base := COALESCE(p_notional, 0);
    IF v_base <= 0 THEN
        RETURN 0;
    END IF;
    RETURN round(v_base * v_pct / 100.0, 6);
END;
$$;

COMMENT ON FUNCTION logic_trade_calc_commission(INTEGER, NUMERIC) IS
'РљРѕРјРёСЃСЃРёСЏ С„РµР№РєРѕРІРѕРіРѕ СЃС‡С‘С‚Р°: commission_pct % РѕС‚ РЅРѕРјРёРЅР°Р»Р° СЃРґРµР»РєРё (price Г— quantity)';

CREATE OR REPLACE FUNCTION logic_trade_finalize(p_trade_id BIGINT, p_balance NUMERIC)
RETURNS NUMERIC
LANGUAGE plpgsql AS $$
DECLARE
    v_trade RECORD;
    v_comm NUMERIC := 0;
    v_new_balance NUMERIC := p_balance;
    v_side_name TEXT;
BEGIN
    SELECT lt.*, sd.name AS side_name
    INTO v_trade
    FROM logic_trades lt
    JOIN sides sd ON sd.id = lt.side_id
    WHERE lt.id = p_trade_id;

    IF NOT FOUND THEN
        RETURN p_balance;
    END IF;

    v_side_name := v_trade.side_name;

    IF v_trade.is_simulated THEN
        v_comm := logic_trade_calc_commission(
            v_trade.logic_id,
            COALESCE(v_trade.price, 0) * COALESCE(v_trade.quantity, 0)
        );
    ELSE
        v_comm := COALESCE(v_trade.commission, 0);
    END IF;

    UPDATE logic_trades SET commission = COALESCE(v_comm, 0) WHERE id = p_trade_id;

    IF v_side_name = 'Close' AND v_trade.status IN ('filled', 'submitted') THEN
        PERFORM logic_trade_build_lots(p_trade_id);
    END IF;

    IF v_trade.is_simulated AND v_new_balance IS NOT NULL AND v_comm > 0 THEN
        v_new_balance := v_new_balance - v_comm;
    END IF;

    RETURN v_new_balance;
END;
$$;

COMMENT ON FUNCTION logic_trade_finalize(BIGINT, NUMERIC) IS
'РљРѕРјРёСЃСЃРёСЏ РЅР° СЃРґРµР»РєРµ; РїР°РєРµС‚С‹ Рё PnL РїСЂРё Р·Р°РєСЂС‹С‚РёРё; РІРѕР·РІСЂР°С‰Р°РµС‚ Р±Р°Р»Р°РЅСЃ РїРѕСЃР»Рµ РєРѕРјРёСЃСЃРёРё';

CREATE OR REPLACE FUNCTION logic_trade_load_date_from(p_tf_sec INTEGER,
    p_point_count INTEGER,
    p_closed_bar_dt TIMESTAMP)
RETURNS DATE
LANGUAGE plpgsql IMMUTABLE AS $$
DECLARE
    v_date_to DATE;
    v_need_days INTEGER;
    v_max_days INTEGER;
    v_span INTEGER;
BEGIN
    v_date_to := GREATEST(p_closed_bar_dt::date, CURRENT_DATE);
    v_need_days := GREATEST(1, CEIL(GREATEST(COALESCE(p_point_count, 100), 30) * COALESCE(NULLIF(p_tf_sec, 0), 900) / 86400.0)::INTEGER);

    v_max_days := CASE
        WHEN COALESCE(p_tf_sec, 0) <= 120 THEN 0
        WHEN p_tf_sec <= 600 THEN 3
        WHEN p_tf_sec <= 1800 THEN 7
        WHEN p_tf_sec <= 3600 THEN 14
        ELSE 30
    END;

    IF v_max_days = 0 THEN
        RETURN v_date_to;
    END IF;

    v_span := LEAST(GREATEST(v_need_days, 1), v_max_days);
    RETURN v_date_to - v_span;
END;
$$;

COMMENT ON FUNCTION logic_trade_load_date_from(INTEGER, INTEGER, TIMESTAMP) IS
'date_from РґР»СЏ load_prices СЃ СѓС‡С‘С‚РѕРј Р»РёРјРёС‚РѕРІ T-Bank РїРѕ TF (M1/M2 вЂ” С‚РѕР»СЊРєРѕ С‚РµРєСѓС‰РёР№ РґРµРЅСЊ)';

CREATE OR REPLACE FUNCTION logic_trade_open_remaining_qty(p_open_trade_id BIGINT)
RETURNS NUMERIC
LANGUAGE sql STABLE AS $$
    SELECT GREATEST(
        lt.quantity - COALESCE((
            SELECT SUM(l.quantity)
            FROM logic_trade_lots l
            WHERE l.open_trade_id = lt.id
        ), 0),
        0
    )
    FROM logic_trades lt
    WHERE lt.id = p_open_trade_id;
$$;

COMMENT ON FUNCTION logic_trade_open_remaining_qty(BIGINT) IS
'РћСЃС‚Р°С‚РѕРє Р»РѕС‚Р° РѕС‚РєСЂС‹РІР°СЋС‰РµР№ СЃРґРµР»РєРё (qty РјРёРЅСѓСЃ СѓР¶Рµ Р·Р°РєСЂС‹С‚Рѕ РїР°РєРµС‚Р°РјРё)';

CREATE OR REPLACE FUNCTION logic_trade_rebuild_pnl(p_logic_id INTEGER DEFAULT NULL)
RETURNS INTEGER
LANGUAGE plpgsql AS $$
DECLARE
    v_logic RECORD;
    v_trade RECORD;
    v_balance NUMERIC;
    v_notional NUMERIC;
    v_count INTEGER := 0;
BEGIN
    FOR v_logic IN
        SELECT l.id
        FROM logics l
        WHERE p_logic_id IS NULL OR l.id = p_logic_id
        ORDER BY l.id
    LOOP
        v_balance := logic_ensure_balance(v_logic.id);

        FOR v_trade IN
            SELECT
                lt.id,
                lt.quantity,
                lt.price,
                lt.is_simulated,
                lt.status,
                sd.name AS side_name,
                ac.name AS action_name
            FROM logic_trades lt
            JOIN sides sd ON sd.id = lt.side_id
            JOIN actions ac ON ac.id = lt.action_id
            WHERE lt.logic_id = v_logic.id
              AND lt.status IN ('filled', 'submitted')
            ORDER BY lt.executed_at ASC, lt.id ASC
        LOOP
            IF v_trade.is_simulated THEN
                v_balance := logic_trade_finalize(v_trade.id, v_balance);
                v_notional := v_trade.quantity * v_trade.price;
                IF v_trade.action_name = 'Long' THEN
                    IF v_trade.side_name = 'Open' THEN
                        v_balance := v_balance - v_notional;
                    ELSE
                        v_balance := v_balance + v_notional;
                    END IF;
                ELSIF v_trade.action_name = 'Short' THEN
                    IF v_trade.side_name = 'Open' THEN
                        v_balance := v_balance + v_notional;
                    ELSE
                        v_balance := v_balance - v_notional;
                    END IF;
                END IF;
            ELSE
                PERFORM logic_trade_finalize(v_trade.id, NULL);
            END IF;
            v_count := v_count + 1;
        END LOOP;

        PERFORM logic_upsert_param(v_logic.id, 'current_balance', v_balance::TEXT, 'money');
    END LOOP;

    RETURN v_count;
END;
$$;

COMMENT ON FUNCTION logic_trade_rebuild_pnl(INTEGER) IS
'РџРµСЂРµСЃС‡С‘С‚ РєРѕРјРёСЃСЃРёРё, РїР°РєРµС‚РѕРІ Рё PnL РїРѕ РёСЃС‚РѕСЂРёРё СЃРґРµР»РѕРє Р»РѕРіРёРєРё (NULL = РІСЃРµ Р»РѕРіРёРєРё)';

