-- Р’РµС‡РЅС‹Рµ С„СЊСЋС‡РµСЂСЃС‹ MOEX (CNYRUBF, USDRUBF вЂ¦) вЂ” Р±РµР· rollover РїРѕ РєРѕРЅС‚СЂР°РєС‚Р°Рј

CREATE OR REPLACE FUNCTION parse_signal_formula(p_formula TEXT)
RETURNS TABLE (
    valid BOOLEAN,
    indicator_code TEXT,
    params TEXT,
    condition TEXT
)
LANGUAGE plpgsql IMMUTABLE AS $$
DECLARE
    v_text TEXT;
    v_at INTEGER;
    v_open INTEGER;
    v_depth INTEGER := 0;
    v_i INTEGER;
    v_code TEXT;
    v_close INTEGER;
BEGIN
    valid := FALSE;
    indicator_code := NULL;
    params := NULL;
    condition := NULL;

    v_text := btrim(COALESCE(p_formula, ''));
    v_at := position('@' IN v_text);
    IF v_at <= 0 THEN
        RETURN NEXT;
        RETURN;
    END IF;
    v_open := position('(' IN substr(v_text, v_at));
    IF v_open <= 0 THEN
        RETURN NEXT;
        RETURN;
    END IF;
    v_open := v_at + v_open - 1;
    v_code := upper(btrim(substr(v_text, v_at + 1, v_open - v_at - 1)));
    IF v_code = '' OR v_code !~ '^[A-Z0-9_]+$' THEN
        RETURN NEXT;
        RETURN;
    END IF;

    v_close := NULL;
    FOR v_i IN v_open..length(v_text) LOOP
        IF substr(v_text, v_i, 1) = '(' THEN
            v_depth := v_depth + 1;
        ELSIF substr(v_text, v_i, 1) = ')' THEN
            v_depth := v_depth - 1;
            IF v_depth = 0 THEN
                v_close := v_i;
                EXIT;
            END IF;
        END IF;
    END LOOP;
    IF v_close IS NULL THEN
        RETURN NEXT;
        RETURN;
    END IF;

    valid := TRUE;
    indicator_code := v_code;
    params := btrim(substr(v_text, v_open + 1, v_close - v_open - 1));
    condition := btrim(substr(v_text, v_close + 1));
    RETURN NEXT;
END;
$$;

CREATE OR REPLACE FUNCTION parse_signal_param_num(p_params TEXT, p_key TEXT)
RETURNS NUMERIC
LANGUAGE plpgsql IMMUTABLE AS $$
DECLARE
    v_part TEXT;
    v_key TEXT;
    v_val TEXT;
    v_canon_key TEXT;
    v_canon_want TEXT;
BEGIN
    IF p_params IS NULL OR btrim(p_params) = '' OR p_key IS NULL THEN
        RETURN NULL;
    END IF;
    v_canon_want := CASE lower(btrim(p_key))
        WHEN 'std' THEN 'std_dev'
        WHEN 'fast' THEN 'fast_period'
        WHEN 'slow' THEN 'slow_period'
        WHEN 'signal' THEN 'signal_period'
        WHEN 'k' THEN 'k_period'
        WHEN 'd' THEN 'd_period'
        ELSE lower(btrim(p_key))
    END;
    FOREACH v_part IN ARRAY signal_split_params_top_level(p_params)
    LOOP
        IF v_part ~* '^OPT\s*\(' THEN
            CONTINUE;
        END IF;
        IF position('=' IN v_part) > 0 THEN
            v_key := lower(btrim(split_part(v_part, '=', 1)));
            v_canon_key := CASE v_key
                WHEN 'std' THEN 'std_dev'
                WHEN 'fast' THEN 'fast_period'
                WHEN 'slow' THEN 'slow_period'
                WHEN 'signal' THEN 'signal_period'
                WHEN 'k' THEN 'k_period'
                WHEN 'd' THEN 'd_period'
                ELSE v_key
            END;
            v_val := btrim(substr(v_part, position('=' IN v_part) + 1));
            IF v_canon_key = v_canon_want AND v_val <> '' AND v_val !~* '^OPT\s*\(' THEN
                BEGIN
                    RETURN replace(v_val, ',', '.')::NUMERIC;
                EXCEPTION WHEN OTHERS THEN
                    RETURN NULL;
                END;
            END IF;
        END IF;
    END LOOP;
    RETURN NULL;
END;
$$;

CREATE OR REPLACE FUNCTION parse_signal_series(p_params TEXT)
RETURNS TEXT
LANGUAGE plpgsql IMMUTABLE AS $$
DECLARE
    v_part TEXT;
    v_key TEXT;
    v_val TEXT;
BEGIN
    IF p_params IS NULL OR btrim(p_params) = '' THEN
        RETURN 'VALUE';
    END IF;
    FOREACH v_part IN ARRAY signal_split_params_top_level(p_params)
    LOOP
        IF v_part ~* '^OPT\s*\(' THEN
            CONTINUE;
        END IF;
        IF position('=' IN v_part) > 0 THEN
            v_key := lower(btrim(split_part(v_part, '=', 1)));
            v_val := btrim(substr(v_part, position('=' IN v_part) + 1));
            IF v_key = 'series' AND v_val <> '' THEN
                RETURN upper(v_val);
            END IF;
        END IF;
    END LOOP;
    RETURN 'VALUE';
END;
$$;

CREATE OR REPLACE FUNCTION parse_tbank_quotation(p_value JSONB)
RETURNS NUMERIC(18,6) AS $$
DECLARE
    v_units BIGINT;
    v_nano INTEGER;
BEGIN
    IF p_value IS NULL OR p_value = 'null'::JSONB THEN
        RETURN NULL;
    END IF;

    IF jsonb_typeof(p_value) = 'number' THEN
        RETURN p_value::TEXT::NUMERIC(18,6);
    END IF;

    IF jsonb_typeof(p_value) = 'string' THEN
        RETURN (p_value #>> '{}')::NUMERIC(18,6);
    END IF;

    v_units := COALESCE((p_value->>'units')::BIGINT, 0);
    v_nano := COALESCE((p_value->>'nano')::INTEGER, 0);
    RETURN v_units + (v_nano / 1000000000.0);
END;
$$ LANGUAGE plpgsql IMMUTABLE;

COMMENT ON FUNCTION parse_tbank_quotation(JSONB) IS
'РџСЂРµРѕР±СЂР°Р·СѓРµС‚ Quotation T-Bank API (units+nano) РёР»Рё С‡РёСЃР»Рѕ РІ NUMERIC';

