CREATE OR REPLACE FUNCTION poly_add(p_a NUMERIC[], p_b NUMERIC[])
RETURNS NUMERIC[]
LANGUAGE plpgsql IMMUTABLE AS $$
DECLARE
    v_row RECORD;
    v_i INTEGER;
    v_out NUMERIC[];
BEGIN
    SELECT * INTO v_row FROM poly_align2(p_a, p_b);
    v_out := ARRAY[]::NUMERIC[];
    FOR v_i IN 1 .. poly_len(v_row.a) LOOP
        v_out := array_append(v_out, COALESCE(v_row.a[v_i], 0) + COALESCE(v_row.b[v_i], 0));
    END LOOP;
    RETURN v_out;
END;
$$;

CREATE OR REPLACE FUNCTION poly_align2(p_a NUMERIC[],
    p_b NUMERIC[])
RETURNS TABLE (a NUMERIC[], b NUMERIC[])
LANGUAGE plpgsql IMMUTABLE AS $$
DECLARE
    v_len INTEGER;
BEGIN
    v_len := GREATEST(poly_len(p_a), poly_len(p_b));
    a := poly_extend(p_a, v_len);
    b := poly_extend(p_b, v_len);
    RETURN NEXT;
END;
$$;

CREATE OR REPLACE FUNCTION poly_build_ema_kernel(p_period INTEGER)
RETURNS NUMERIC[]
LANGUAGE plpgsql IMMUTABLE AS $$
DECLARE
    v_n INTEGER := GREATEST(COALESCE(p_period, 20), 2);
    v_alpha NUMERIC := 2.0 / (v_n + 1);
    v_len INTEGER := GREATEST(v_n * 4, 24);
    v_out NUMERIC[] := ARRAY[]::NUMERIC[];
    i INTEGER;
BEGIN
    FOR i IN 0 .. v_len - 1 LOOP
        v_out := array_append(v_out, v_alpha * power(1 - v_alpha, i));
    END LOOP;
    RETURN v_out;
END;
$$;

CREATE OR REPLACE FUNCTION poly_build_sma_kernel(p_period INTEGER)
RETURNS NUMERIC[]
LANGUAGE plpgsql IMMUTABLE AS $$
DECLARE
    v_n INTEGER := GREATEST(COALESCE(p_period, 20), 1);
    v_out NUMERIC[] := ARRAY[]::NUMERIC[];
    i INTEGER;
BEGIN
    FOR i IN 1 .. v_n LOOP
        v_out := array_append(v_out, 1.0 / v_n);
    END LOOP;
    RETURN v_out;
END;
$$;

CREATE OR REPLACE FUNCTION poly_comp_div(p_a NUMERIC[], p_b NUMERIC[])
RETURNS NUMERIC[]
LANGUAGE plpgsql IMMUTABLE AS $$
DECLARE
    v_row RECORD;
    v_i INTEGER;
    v_out NUMERIC[];
    v_den NUMERIC;
BEGIN
    SELECT * INTO v_row FROM poly_align2(p_a, p_b);
    v_out := ARRAY[]::NUMERIC[];
    FOR v_i IN 1 .. poly_len(v_row.a) LOOP
        v_den := COALESCE(v_row.b[v_i], 0);
        IF v_den = 0 THEN
            v_out := array_append(v_out, NULL);
        ELSE
            v_out := array_append(v_out, COALESCE(v_row.a[v_i], 0) / v_den);
        END IF;
    END LOOP;
    RETURN v_out;
END;
$$;

DROP FUNCTION IF EXISTS poly_convolve(NUMERIC[], NUMERIC[]);

CREATE OR REPLACE FUNCTION poly_comp_mul(p_a NUMERIC[], p_b NUMERIC[])
RETURNS NUMERIC[]
LANGUAGE plpgsql IMMUTABLE AS $$
DECLARE
    v_row RECORD;
    v_i INTEGER;
    v_out NUMERIC[];
BEGIN
    SELECT * INTO v_row FROM poly_align2(p_a, p_b);
    v_out := ARRAY[]::NUMERIC[];
    FOR v_i IN 1 .. poly_len(v_row.a) LOOP
        v_out := array_append(v_out, COALESCE(v_row.a[v_i], 0) * COALESCE(v_row.b[v_i], 0));
    END LOOP;
    RETURN v_out;
END;
$$;

CREATE OR REPLACE FUNCTION poly_convolve(p_a NUMERIC[],
    p_b NUMERIC[],
    p_max_lag INTEGER DEFAULT NULL)
RETURNS NUMERIC[]
LANGUAGE plpgsql IMMUTABLE AS $$
DECLARE
    v_na INTEGER := poly_len(p_a);
    v_nb INTEGER := poly_len(p_b);
    v_out NUMERIC[];
    v_normalize BOOLEAN;
    v_lag_cap INTEGER;
    i INTEGER;
    j INTEGER;
    v_sum NUMERIC;
    v_weight NUMERIC;
BEGIN
    IF v_na = 0 OR v_nb = 0 THEN RETURN ARRAY[]::NUMERIC[]; END IF;
    -- Р”РІР° СЂСЏРґР° РѕРґРёРЅР°РєРѕРІРѕР№ РґР»РёРЅС‹ (sma*smaвЂ¦): РІР·РІРµС€РµРЅРЅР°СЏ СЃРІС‘СЂС‚РєР°, С€РєР°Р»Р° ~ С†РµРЅР°.
    -- p_max_lag РѕРіСЂР°РЅРёС‡РёРІР°РµС‚ РіР»СѓР±РёРЅСѓ (period): Р·РЅР°С‡РµРЅРёРµ РЅРµ Р·Р°РІРёСЃРёС‚ РѕС‚ РґР»РёРЅС‹ РІСЃРµРіРѕ РјР°СЃСЃРёРІР°.
    -- РљРѕСЂРѕС‚РєРѕРµ СЏРґСЂРѕ (ww, PACC): Р±РµР· РґРµР»РµРЅРёСЏ вЂ” РєР°Рє СЂР°РЅСЊС€Рµ.
    v_normalize := (v_na = v_nb AND v_na > 8);
    v_lag_cap := CASE
        WHEN v_normalize AND p_max_lag IS NOT NULL AND p_max_lag > 0 THEN p_max_lag
        ELSE v_nb
    END;
    v_out := array_fill(0::NUMERIC, ARRAY[v_na]);
    FOR i IN 1 .. v_na LOOP
        v_sum := 0;
        v_weight := 0;
        FOR j IN 1 .. LEAST(v_nb, v_lag_cap) LOOP
            IF i - j + 1 >= 1 AND i - j + 1 <= v_na THEN
                v_sum := v_sum + p_a[i - j + 1] * p_b[j];
                IF v_normalize THEN
                    v_weight := v_weight + p_b[j];
                END IF;
            END IF;
        END LOOP;
        IF v_normalize AND ABS(v_weight) > 1e-12 THEN
            v_out[i] := v_sum / v_weight;
        ELSE
            v_out[i] := v_sum;
        END IF;
    END LOOP;
    RETURN v_out;
END;
$$;

COMMENT ON FUNCTION poly_convolve(NUMERIC[], NUMERIC[], INTEGER) IS
'РЎРІС‘СЂС‚РєР° СЂСЏРґРѕРІ; РїСЂРё СЂР°РІРЅРѕР№ РґР»РёРЅРµ >8 вЂ” РЅРѕСЂРјР°Р»РёР·Р°С†РёСЏ; p_max_lag=period РґР»СЏ Р»РѕРєР°Р»СЊРЅРѕР№ sma*sma';

CREATE OR REPLACE FUNCTION poly_ctx_period(p_ctx JSONB)
RETURNS INTEGER
LANGUAGE sql IMMUTABLE AS $$
    SELECT GREATEST(COALESCE(NULLIF(p_ctx ->> 'param_period', '')::INTEGER, 20), 2);
$$;

CREATE OR REPLACE FUNCTION poly_delta_kernel(p_k INTEGER)
RETURNS NUMERIC[]
LANGUAGE plpgsql IMMUTABLE AS $$
DECLARE
    v_out NUMERIC[];
    i INTEGER;
BEGIN
    IF p_k < 0 THEN
        RAISE EXCEPTION 'poly_delta_kernel: k must be >= 0, got %', p_k;
    END IF;
    v_out := array_fill(0::NUMERIC, ARRAY[p_k + 1]);
    v_out[p_k + 1] := 1;
    RETURN v_out;
END;
$$;

CREATE OR REPLACE FUNCTION poly_eval_node(p_node JSONB,
    p_ctx JSONB)
RETURNS NUMERIC[]
LANGUAGE plpgsql STABLE AS $$
DECLARE
    v_op TEXT;
    v_var TEXT;
    v_num NUMERIC;
    v_vec NUMERIC[];
    v_left NUMERIC[];
    v_right NUMERIC[];
    v_ind JSONB;
    v_code TEXT;
    v_series TEXT;
    v_fn TEXT;
    v_period INTEGER;
    i INTEGER;
BEGIN
    IF p_node ? 'num' THEN
        RETURN ARRAY[(p_node ->> 'num')::NUMERIC];
    END IF;

    IF p_node ? 'vec' THEN
        v_vec := ARRAY[]::NUMERIC[];
        FOR i IN 0 .. jsonb_array_length(p_node -> 'vec') - 1 LOOP
            v_vec := array_append(v_vec, ((p_node -> 'vec' ->> i)::NUMERIC));
        END LOOP;
        RETURN v_vec;
    END IF;

    IF p_node ? 'dd' THEN
        RETURN poly_delta_kernel((p_node ->> 'dd')::INTEGER);
    END IF;

    IF p_node ? 'fn' THEN
        v_fn := lower(p_node ->> 'fn');
        PERFORM poly_fn_validate_args(v_fn, COALESCE(p_node -> 'args', poly_fn_empty_args()));
        v_period := poly_fn_resolve_period(p_node, p_ctx);
        v_series := poly_fn_resolve_series(p_node, 'VALUE');
        CASE v_fn
            WHEN 'ww' THEN
                RETURN poly_build_sma_kernel(v_period);
            WHEN 'sma' THEN
                RETURN poly_convolve(
                    poly_pp_from_ctx(p_ctx),
                    poly_build_sma_kernel(v_period)
                );
            WHEN 'ema' THEN
                RETURN poly_convolve(
                    poly_pp_from_ctx(p_ctx),
                    poly_build_ema_kernel(v_period)
                );
            ELSE
                RAISE EXCEPTION 'poly_eval: unknown function %', v_fn;
        END CASE;
    END IF;

    IF p_node ? 'var' THEN
        v_var := p_node ->> 'var';
        IF p_ctx ? ('m_' || v_var) THEN
            v_vec := ARRAY(SELECT jsonb_array_elements_text(p_ctx -> ('m_' || v_var))::NUMERIC);
            RETURN v_vec;
        END IF;
        RAISE EXCEPTION 'poly_eval: unknown market variable %', v_var;
    END IF;

    IF p_node ? 'ind' THEN
        v_ind := p_node -> 'ind';
        v_code := v_ind ->> 'code';
        v_series := v_ind ->> 'series';
        RETURN poly_load_indicator_array(
            v_code, v_series,
            (p_ctx ->> 'security_id')::INTEGER,
            (p_ctx ->> 'timeframe_id')::INTEGER,
            (p_ctx ->> 'end_dt')::TIMESTAMP,
            (p_ctx ->> 'bars')::INTEGER,
            NULLIF(p_ctx ->> 'param_period', '')::INTEGER,
            NULLIF(p_ctx ->> 'param_fast_period', '')::INTEGER,
            NULLIF(p_ctx ->> 'param_slow_period', '')::INTEGER,
            NULLIF(p_ctx ->> 'param_signal_period', '')::INTEGER,
            NULLIF(p_ctx ->> 'param_std_dev', '')::NUMERIC,
            NULLIF(p_ctx ->> 'param_k_period', '')::INTEGER,
            NULLIF(p_ctx ->> 'param_d_period', '')::INTEGER,
            NULLIF(p_ctx ->> 'param_smooth', '')::INTEGER,
            ARRAY(SELECT jsonb_array_elements_text(p_ctx -> 'dts')::TIMESTAMP)
        );
    END IF;

    IF p_node ? 'op' THEN
        v_op := p_node ->> 'op';
        IF v_op = 'neg' THEN
            RETURN poly_neg(poly_eval_node(p_node -> 'arg', p_ctx));
        END IF;
        v_left := poly_eval_node(p_node -> 'left', p_ctx);
        v_right := poly_eval_node(p_node -> 'right', p_ctx);
        CASE v_op
            WHEN 'add' THEN RETURN poly_add(v_left, v_right);
            WHEN 'sub' THEN RETURN poly_sub(v_left, v_right);
            WHEN 'conv' THEN RETURN poly_convolve(v_left, v_right, poly_ctx_period(p_ctx));
            WHEN 'cmul' THEN RETURN poly_comp_mul(v_left, v_right);
            WHEN 'cdiv' THEN RETURN poly_comp_div(v_left, v_right);
            ELSE RAISE EXCEPTION 'poly_eval: unknown op %', v_op;
        END CASE;
    END IF;

    RAISE EXCEPTION 'poly_eval: invalid node %', p_node;
END;
$$;

CREATE OR REPLACE FUNCTION poly_extend(p_arr NUMERIC[], p_len INTEGER)
RETURNS NUMERIC[]
LANGUAGE plpgsql IMMUTABLE AS $$
DECLARE
    v_n INTEGER := poly_len(p_arr);
    v_out NUMERIC[];
    i INTEGER;
BEGIN
    IF p_len <= 0 THEN RETURN ARRAY[]::NUMERIC[]; END IF;
    IF v_n = 0 THEN RETURN array_fill(0::NUMERIC, ARRAY[p_len]); END IF;
    IF v_n = 1 THEN RETURN array_fill(p_arr[1], ARRAY[p_len]); END IF;
    IF v_n >= p_len THEN RETURN p_arr[1:p_len]; END IF;
    v_out := p_arr;
    FOR i IN v_n + 1 .. p_len LOOP
        v_out := array_append(v_out, 0::NUMERIC);
    END LOOP;
    RETURN v_out;
END;
$$;

CREATE OR REPLACE FUNCTION poly_fn_empty_args()
RETURNS JSONB
LANGUAGE sql IMMUTABLE AS $$
    SELECT jsonb_build_object('named', '{}'::JSONB, 'positional', '[]'::JSONB);
$$;

CREATE OR REPLACE FUNCTION poly_fn_resolve_period(p_node JSONB, p_ctx JSONB)
RETURNS INTEGER
LANGUAGE plpgsql IMMUTABLE AS $$
DECLARE
    v_args JSONB;
    v_named JSONB;
    v_pos JSONB;
    v_i INTEGER;
    v_n INTEGER;
BEGIN
    v_args := COALESCE(p_node -> 'args', poly_fn_empty_args());
    v_named := COALESCE(v_args -> 'named', '{}'::JSONB);
    v_pos := COALESCE(v_args -> 'positional', '[]'::JSONB);

    IF v_named ? 'period' THEN
        RETURN GREATEST((v_named ->> 'period')::INTEGER, 1);
    END IF;

    v_n := COALESCE(jsonb_array_length(v_pos), 0);
    FOR v_i IN 0 .. GREATEST(v_n - 1, 0) LOOP
        IF jsonb_typeof(v_pos -> v_i) = 'number' THEN
            RETURN GREATEST((v_pos ->> v_i)::INTEGER, 1);
        END IF;
    END LOOP;

    RETURN poly_ctx_period(p_ctx);
END;
$$;

CREATE OR REPLACE FUNCTION poly_fn_resolve_series(p_node JSONB, p_default TEXT DEFAULT 'VALUE')
RETURNS TEXT
LANGUAGE plpgsql IMMUTABLE AS $$
DECLARE
    v_args JSONB;
    v_named JSONB;
    v_pos JSONB;
    v_n INTEGER;
BEGIN
    v_args := COALESCE(p_node -> 'args', poly_fn_empty_args());
    v_named := COALESCE(v_args -> 'named', '{}'::JSONB);
    v_pos := COALESCE(v_args -> 'positional', '[]'::JSONB);

    IF v_named ? 'series' THEN
        RETURN upper(v_named ->> 'series');
    END IF;

    v_n := COALESCE(jsonb_array_length(v_pos), 0);
    IF v_n > 0 AND jsonb_typeof(v_pos -> (v_n - 1)) = 'string' THEN
        RETURN upper(v_pos ->> (v_n - 1));
    END IF;

    RETURN upper(COALESCE(p_default, 'VALUE'));
END;
$$;

CREATE OR REPLACE FUNCTION poly_fn_validate_args(p_fn TEXT, p_args JSONB)
RETURNS VOID
LANGUAGE plpgsql IMMUTABLE AS $$
DECLARE
    v_pos JSONB;
    v_n INTEGER;
    v_i INTEGER;
    v_s TEXT;
    v_has_num BOOLEAN := FALSE;
BEGIN
    v_pos := COALESCE(p_args -> 'positional', '[]'::JSONB);
    v_n := COALESCE(jsonb_array_length(v_pos), 0);
    FOR v_i IN 0 .. GREATEST(v_n - 1, 0) LOOP
        IF jsonb_typeof(v_pos -> v_i) = 'string' THEN
            v_s := lower(v_pos ->> v_i);
            IF v_s IN ('pp', 'oo', 'hh', 'll', 'vv') THEN
                RAISE EXCEPTION 'poly_fn: use bare % for close; () does not take market columns', p_fn;
            END IF;
            IF v_i < v_n - 1 THEN
                RAISE EXCEPTION 'poly_fn: series must be the last positional argument in %()', p_fn;
            END IF;
        ELSIF jsonb_typeof(v_pos -> v_i) = 'number' THEN
            v_has_num := TRUE;
        END IF;
    END LOOP;

    IF v_n = 1 AND jsonb_typeof(v_pos -> 0) = 'string' AND NOT v_has_num THEN
        IF lower(p_fn) IN ('sma', 'ema', 'ww') AND lower(v_pos ->> 0) NOT IN ('value') THEN
            RAISE EXCEPTION 'poly_fn: %() needs period before series; use % or %(period=N)', p_fn, p_fn, p_fn;
        END IF;
    END IF;
END;
$$;

CREATE OR REPLACE FUNCTION poly_formula_conv_depth(p_formula TEXT)
RETURNS INTEGER
LANGUAGE sql IMMUTABLE AS $$
    SELECT GREATEST(
        (length(btrim(COALESCE(p_formula, ''))) - length(replace(btrim(COALESCE(p_formula, '')), '*', ''))),
        0
    );
$$;

CREATE OR REPLACE FUNCTION poly_is_formula(p_formula TEXT)
RETURNS BOOLEAN
LANGUAGE sql IMMUTABLE AS $$
    SELECT COALESCE(btrim(p_formula), '') <> ''
       AND btrim(p_formula) !~* '^calc_';
$$;

CREATE OR REPLACE FUNCTION poly_len(p_arr NUMERIC[])
RETURNS INTEGER
LANGUAGE sql IMMUTABLE AS $$
    SELECT COALESCE(array_length(p_arr, 1), 0);
$$;

CREATE OR REPLACE FUNCTION poly_load_indicator_array(p_indicator_code TEXT,
    p_series TEXT,
    p_security_id INTEGER,
    p_timeframe_id INTEGER,
    p_end_dt TIMESTAMP,
    p_bars INTEGER,
    p_period INTEGER DEFAULT NULL,
    p_fast_period INTEGER DEFAULT NULL,
    p_slow_period INTEGER DEFAULT NULL,
    p_signal_period INTEGER DEFAULT NULL,
    p_std_dev NUMERIC DEFAULT NULL,
    p_k_period INTEGER DEFAULT NULL,
    p_d_period INTEGER DEFAULT NULL,
    p_smooth INTEGER DEFAULT NULL,
    p_target_dts TIMESTAMP[] DEFAULT NULL)
RETURNS NUMERIC[]
LANGUAGE plpgsql STABLE AS $$
DECLARE
    v_series TEXT := COALESCE(NULLIF(btrim(p_series), ''), 'VALUE');
    v_map JSONB := '{}'::JSONB;
    v_arr NUMERIC[] := ARRAY[]::NUMERIC[];
    v_dt TIMESTAMP;
    v_val NUMERIC;
    i INTEGER;
BEGIN
    FOR v_dt, v_val IN
        SELECT t.dt, t.value
        FROM calc_indicator_series_array(
            p_indicator_code, v_series,
            p_security_id, p_timeframe_id, p_bars, p_end_dt,
            p_period, p_fast_period, p_slow_period, p_signal_period,
            p_std_dev, p_k_period, p_d_period, p_smooth
        ) t
    LOOP
        v_map := v_map || jsonb_build_object(to_char(v_dt, 'YYYY-MM-DD HH24:MI:SS'), to_jsonb(v_val));
    END LOOP;

    IF p_target_dts IS NULL THEN
        SELECT COALESCE(array_agg((v_map ->> to_char(d, 'YYYY-MM-DD HH24:MI:SS'))::NUMERIC ORDER BY ord), ARRAY[]::NUMERIC[])
        INTO v_arr
        FROM unnest(
            (SELECT poly_load_market_dts(p_security_id, p_timeframe_id, p_end_dt, p_bars))
        ) WITH ORDINALITY AS t(d, ord);
        RETURN v_arr;
    END IF;

    FOR i IN 1 .. COALESCE(array_length(p_target_dts, 1), 0) LOOP
        v_dt := p_target_dts[i];
        v_val := (v_map ->> to_char(v_dt, 'YYYY-MM-DD HH24:MI:SS'))::NUMERIC;
        v_arr := array_append(v_arr, v_val);
    END LOOP;
    RETURN v_arr;
END;
$$;

CREATE OR REPLACE FUNCTION poly_neg(p_a NUMERIC[])
RETURNS NUMERIC[]
LANGUAGE plpgsql IMMUTABLE AS $$
DECLARE
    v_i INTEGER;
    v_out NUMERIC[] := ARRAY[]::NUMERIC[];
BEGIN
    FOR v_i IN 1 .. poly_len(p_a) LOOP
        v_out := array_append(v_out, -p_a[v_i]);
    END LOOP;
    RETURN v_out;
END;
$$;

CREATE OR REPLACE FUNCTION poly_parse(p_formula TEXT)
RETURNS JSONB
LANGUAGE plpgsql STABLE AS $$
DECLARE
    v_tokens TEXT[];
    v_pos INTEGER := 1;
    v_step JSONB;
BEGIN
    v_tokens := poly_tokenize(p_formula);
    IF COALESCE(array_length(v_tokens, 1), 0) = 0 THEN
        RAISE EXCEPTION 'poly_parse: empty formula';
    END IF;
    v_step := poly_parse_add(v_tokens, v_pos);
    v_pos := (v_step ->> 'p')::INTEGER;
    IF v_pos <= COALESCE(array_length(v_tokens, 1), 0) THEN
        RAISE EXCEPTION 'poly_parse: trailing tokens at position % (%)', v_pos, v_tokens[v_pos];
    END IF;
    RETURN v_step -> 'n';
END;
$$;

CREATE OR REPLACE FUNCTION poly_parse_add(p_tokens TEXT[],
    p_pos INTEGER)
RETURNS JSONB
LANGUAGE plpgsql IMMUTABLE AS $$
DECLARE
    v_left JSONB;
    v_right JSONB;
    v_op TEXT;
    v_pos INTEGER;
BEGIN
    v_left := poly_parse_conv(p_tokens, p_pos);
    v_pos := (v_left ->> 'p')::INTEGER;
    v_left := v_left -> 'n';

    WHILE poly_peek_token(p_tokens, v_pos) IN ('OP:+', 'OP:-') LOOP
        v_op := substr(poly_peek_token(p_tokens, v_pos), 4);
        v_pos := v_pos + 1;
        v_right := poly_parse_conv(p_tokens, v_pos);
        v_pos := (v_right ->> 'p')::INTEGER;
        IF v_op = '+' THEN
            v_left := jsonb_build_object('op', 'add', 'left', v_left, 'right', v_right -> 'n');
        ELSE
            v_left := jsonb_build_object('op', 'sub', 'left', v_left, 'right', v_right -> 'n');
        END IF;
    END LOOP;

    RETURN jsonb_build_object('n', v_left, 'p', v_pos);
END;
$$;

CREATE OR REPLACE FUNCTION poly_parse_atom(p_tokens TEXT[],
    p_pos INTEGER)
RETURNS JSONB
LANGUAGE plpgsql IMMUTABLE AS $$
DECLARE
    v_t TEXT;
    v_parts TEXT[];
    v_vec NUMERIC[];
    v_inner JSONB;
    v_args JSONB;
    v_fn TEXT;
    i INTEGER;
    v_pos INTEGER := p_pos;
BEGIN
    v_t := poly_peek_token(p_tokens, v_pos);
    IF v_t IS NULL THEN
        RAISE EXCEPTION 'poly_parse: unexpected end of formula';
    END IF;

    IF v_t = 'LP' THEN
        v_pos := v_pos + 1;
        v_inner := poly_parse_add(p_tokens, v_pos);
        v_pos := (v_inner ->> 'p')::INTEGER;
        IF poly_peek_token(p_tokens, v_pos) <> 'RP' THEN
            RAISE EXCEPTION 'poly_parse: expected )';
        END IF;
        RETURN jsonb_build_object('n', v_inner -> 'n', 'p', v_pos + 1);
    END IF;

    IF v_t LIKE 'ID:%' AND lower(substr(v_t, 4)) IN ('sma', 'ema', 'ww') THEN
        v_fn := lower(substr(v_t, 4));
        IF poly_peek_token(p_tokens, v_pos + 1) IS DISTINCT FROM 'LP' THEN
            RETURN jsonb_build_object(
                'n', jsonb_build_object('fn', v_fn, 'args', poly_fn_empty_args()),
                'p', v_pos + 1
            );
        END IF;
        v_pos := v_pos + 2;
        v_args := poly_parse_fn_args(p_tokens, v_pos);
        v_pos := (v_args ->> 'p')::INTEGER;
        PERFORM poly_fn_validate_args(
            v_fn,
            jsonb_build_object(
                'named', COALESCE(v_args -> 'named', '{}'::JSONB),
                'positional', COALESCE(v_args -> 'positional', '[]'::JSONB)
            )
        );
        RETURN jsonb_build_object(
            'n', jsonb_build_object(
                'fn', v_fn,
                'args', jsonb_build_object(
                    'named', COALESCE(v_args -> 'named', '{}'::JSONB),
                    'positional', COALESCE(v_args -> 'positional', '[]'::JSONB)
                )
            ),
            'p', v_pos
        );
    END IF;

    IF v_t LIKE 'ID:%' THEN
        RETURN jsonb_build_object('n', jsonb_build_object('var', substr(v_t, 4)), 'p', v_pos + 1);
    END IF;

    IF v_t LIKE 'NUM:%' THEN
        RETURN jsonb_build_object('n', jsonb_build_object('num', substr(v_t, 5)::NUMERIC), 'p', v_pos + 1);
    END IF;

    IF v_t LIKE 'VEC:%' THEN
        v_parts := string_to_array(substr(v_t, 5), ',');
        v_vec := ARRAY[]::NUMERIC[];
        FOR i IN 1 .. COALESCE(array_length(v_parts, 1), 0) LOOP
            v_vec := array_append(v_vec, btrim(v_parts[i])::NUMERIC);
        END LOOP;
        RETURN jsonb_build_object('n', jsonb_build_object('vec', to_jsonb(v_vec)), 'p', v_pos + 1);
    END IF;

    IF v_t LIKE 'DD:%' THEN
        RETURN jsonb_build_object('n', jsonb_build_object('dd', (substr(v_t, 4))::INTEGER), 'p', v_pos + 1);
    END IF;

    IF v_t LIKE 'IND:%' THEN
        v_parts := string_to_array(substr(v_t, 5), ':');
        IF array_length(v_parts, 1) = 1 THEN
            RETURN jsonb_build_object(
                'n', jsonb_build_object('ind', jsonb_build_object('code', v_parts[1], 'series', NULL)),
                'p', v_pos + 1
            );
        END IF;
        RETURN jsonb_build_object(
            'n', jsonb_build_object('ind', jsonb_build_object('code', v_parts[1], 'series', v_parts[2])),
            'p', v_pos + 1
        );
    END IF;

    RAISE EXCEPTION 'poly_parse: unexpected token %', v_t;
END;
$$;

CREATE OR REPLACE FUNCTION poly_parse_comp(p_tokens TEXT[],
    p_pos INTEGER)
RETURNS JSONB
LANGUAGE plpgsql IMMUTABLE AS $$
DECLARE
    v_left JSONB;
    v_right JSONB;
    v_op TEXT;
    v_pos INTEGER;
BEGIN
    v_left := poly_parse_unary(p_tokens, p_pos);
    v_pos := (v_left ->> 'p')::INTEGER;
    v_left := v_left -> 'n';

    WHILE poly_peek_token(p_tokens, v_pos) IN ('OP:#', 'OP:/#') LOOP
        v_op := substr(poly_peek_token(p_tokens, v_pos), 4);
        v_pos := v_pos + 1;
        v_right := poly_parse_unary(p_tokens, v_pos);
        v_pos := (v_right ->> 'p')::INTEGER;
        IF v_op = '#' THEN
            v_left := jsonb_build_object('op', 'cmul', 'left', v_left, 'right', v_right -> 'n');
        ELSE
            v_left := jsonb_build_object('op', 'cdiv', 'left', v_left, 'right', v_right -> 'n');
        END IF;
    END LOOP;

    RETURN jsonb_build_object('n', v_left, 'p', v_pos);
END;
$$;

CREATE OR REPLACE FUNCTION poly_parse_conv(p_tokens TEXT[],
    p_pos INTEGER)
RETURNS JSONB
LANGUAGE plpgsql IMMUTABLE AS $$
DECLARE
    v_left JSONB;
    v_right JSONB;
    v_pos INTEGER;
BEGIN
    v_left := poly_parse_comp(p_tokens, p_pos);
    v_pos := (v_left ->> 'p')::INTEGER;
    v_left := v_left -> 'n';

    WHILE poly_peek_token(p_tokens, v_pos) = 'OP:*' LOOP
        v_pos := v_pos + 1;
        v_right := poly_parse_comp(p_tokens, v_pos);
        v_pos := (v_right ->> 'p')::INTEGER;
        v_left := jsonb_build_object('op', 'conv', 'left', v_left, 'right', v_right -> 'n');
    END LOOP;

    RETURN jsonb_build_object('n', v_left, 'p', v_pos);
END;
$$;

CREATE OR REPLACE FUNCTION poly_parse_fn_args(p_tokens TEXT[],
    p_pos INTEGER)
RETURNS JSONB
LANGUAGE plpgsql IMMUTABLE AS $$
DECLARE
    v_pos INTEGER := p_pos;
    v_t TEXT;
    v_name TEXT;
    v_named JSONB := '{}'::JSONB;
    v_positional JSONB := '[]'::JSONB;
BEGIN
    IF poly_peek_token(p_tokens, v_pos) = 'RP' THEN
        RETURN jsonb_build_object('named', v_named, 'positional', v_positional, 'p', v_pos);
    END IF;

    LOOP
        v_t := poly_peek_token(p_tokens, v_pos);
        EXIT WHEN v_t IS NULL OR v_t = 'RP';

        IF v_t LIKE 'ID:%' THEN
            v_name := lower(substr(v_t, 4));
            IF poly_peek_token(p_tokens, v_pos + 1) = 'OP:=' THEN
                v_pos := v_pos + 2;
                v_t := poly_peek_token(p_tokens, v_pos);
                IF v_t LIKE 'NUM:%' THEN
                    v_named := v_named || jsonb_build_object(v_name, (substr(v_t, 5))::NUMERIC);
                    v_pos := v_pos + 1;
                ELSIF v_t LIKE 'ID:%' THEN
                    v_named := v_named || jsonb_build_object(v_name, to_jsonb(upper(substr(v_t, 4))));
                    v_pos := v_pos + 1;
                ELSE
                    RAISE EXCEPTION 'poly_parse_fn_args: expected value after %=%', v_name, v_name;
                END IF;
            ELSE
                v_positional := v_positional || jsonb_build_array(to_jsonb(upper(substr(v_t, 4))));
                v_pos := v_pos + 1;
            END IF;
        ELSIF v_t LIKE 'NUM:%' THEN
            v_positional := v_positional || jsonb_build_array(to_jsonb((substr(v_t, 5))::NUMERIC));
            v_pos := v_pos + 1;
        ELSE
            RAISE EXCEPTION 'poly_parse_fn_args: unexpected token %', v_t;
        END IF;

        IF poly_peek_token(p_tokens, v_pos) = 'COMMA' THEN
            v_pos := v_pos + 1;
            CONTINUE;
        END IF;
        EXIT WHEN poly_peek_token(p_tokens, v_pos) = 'RP';
    END LOOP;

    IF poly_peek_token(p_tokens, v_pos) <> 'RP' THEN
        RAISE EXCEPTION 'poly_parse_fn_args: expected )';
    END IF;

    RETURN jsonb_build_object('named', v_named, 'positional', v_positional, 'p', v_pos + 1);
END;
$$;

CREATE OR REPLACE FUNCTION poly_parse_unary(p_tokens TEXT[],
    p_pos INTEGER)
RETURNS JSONB
LANGUAGE plpgsql IMMUTABLE AS $$
DECLARE
    v_inner JSONB;
BEGIN
    IF poly_peek_token(p_tokens, p_pos) = 'OP:-' THEN
        v_inner := poly_parse_unary(p_tokens, p_pos + 1);
        RETURN jsonb_build_object(
            'n', jsonb_build_object('op', 'neg', 'arg', v_inner -> 'n'),
            'p', (v_inner ->> 'p')::INTEGER
        );
    END IF;
    RETURN poly_parse_atom(p_tokens, p_pos);
END;
$$;

CREATE OR REPLACE FUNCTION poly_peek_token(p_tokens TEXT[], p_pos INTEGER)
RETURNS TEXT
LANGUAGE sql IMMUTABLE AS $$
    SELECT CASE WHEN p_pos >= 1 AND p_pos <= COALESCE(array_length(p_tokens, 1), 0)
                THEN p_tokens[p_pos] ELSE NULL END;
$$;

CREATE OR REPLACE FUNCTION poly_pp_from_ctx(p_ctx JSONB)
RETURNS NUMERIC[]
LANGUAGE plpgsql IMMUTABLE AS $$
BEGIN
    IF p_ctx ? 'm_pp' THEN
        RETURN ARRAY(SELECT jsonb_array_elements_text(p_ctx -> 'm_pp')::NUMERIC);
    END IF;
    RAISE EXCEPTION 'poly_eval: pp not loaded in context';
END;
$$;

CREATE OR REPLACE FUNCTION poly_sub(p_a NUMERIC[], p_b NUMERIC[])
RETURNS NUMERIC[]
LANGUAGE plpgsql IMMUTABLE AS $$
DECLARE
    v_row RECORD;
    v_i INTEGER;
    v_out NUMERIC[];
BEGIN
    SELECT * INTO v_row FROM poly_align2(p_a, p_b);
    v_out := ARRAY[]::NUMERIC[];
    FOR v_i IN 1 .. poly_len(v_row.a) LOOP
        v_out := array_append(v_out, COALESCE(v_row.a[v_i], 0) - COALESCE(v_row.b[v_i], 0));
    END LOOP;
    RETURN v_out;
END;
$$;

CREATE OR REPLACE FUNCTION poly_tokenize(p_formula TEXT)
RETURNS TEXT[]
LANGUAGE plpgsql IMMUTABLE AS $$
DECLARE
    v_src TEXT := COALESCE(p_formula, '');
    v_len INTEGER := length(v_src);
    v_i INTEGER := 1;
    v_c TEXT;
    v_tokens TEXT[] := ARRAY[]::TEXT[];
    v_buf TEXT;
    v_num TEXT;
    v_peek TEXT;
    v_j INTEGER;
BEGIN
    WHILE v_i <= v_len LOOP
        v_c := substr(v_src, v_i, 1);
        IF v_c ~ '\s' THEN
            v_i := v_i + 1;
            CONTINUE;
        END IF;

        IF v_c = '(' THEN
            v_j := v_i + 1;
            WHILE v_j <= v_len AND substr(v_src, v_j, 1) ~ '\s' LOOP v_j := v_j + 1; END LOOP;
            IF v_j <= v_len AND substr(v_src, v_j, 1) ~ '[0-9.\-+]' THEN
                v_buf := '';
                v_j := v_i + 1;
                WHILE v_j <= v_len LOOP
                    v_peek := substr(v_src, v_j, 1);
                    IF v_peek ~ '[0-9.\-+eE,; ]' THEN
                        IF v_peek !~ '\s' THEN v_buf := v_buf || v_peek; END IF;
                        v_j := v_j + 1;
                    ELSE
                        EXIT;
                    END IF;
                END LOOP;
                IF v_j <= v_len AND substr(v_src, v_j, 1) = ')'
                   AND (position(';' IN v_buf) > 0 OR position(',' IN v_buf) > 0) THEN
                    v_buf := replace(replace(v_buf, ';', ','), ' ', '');
                    v_tokens := array_append(v_tokens, 'VEC:' || v_buf);
                    v_i := v_j + 1;
                    CONTINUE;
                END IF;
            END IF;
            v_tokens := array_append(v_tokens, 'LP');
            v_i := v_i + 1;
            CONTINUE;
        END IF;

        IF v_c = ')' THEN
            v_tokens := array_append(v_tokens, 'RP');
            v_i := v_i + 1;
            CONTINUE;
        END IF;

        IF v_c = '@' THEN
            v_buf := '';
            v_i := v_i + 1;
            WHILE v_i <= v_len LOOP
                v_peek := substr(v_src, v_i, 1);
                EXIT WHEN v_peek !~ '[A-Za-z0-9_]';
                v_buf := v_buf || v_peek;
                v_i := v_i + 1;
            END LOOP;
            IF v_buf = '' THEN
                RAISE EXCEPTION 'poly_tokenize: empty indicator reference at position %', v_i;
            END IF;
            IF v_i <= v_len AND substr(v_src, v_i, 1) = ':' THEN
                v_i := v_i + 1;
                v_num := '';
                WHILE v_i <= v_len LOOP
                    v_peek := substr(v_src, v_i, 1);
                    EXIT WHEN v_peek !~ '[A-Za-z0-9_]';
                    v_num := v_num || v_peek;
                    v_i := v_i + 1;
                END LOOP;
                v_tokens := array_append(v_tokens, 'IND:' || upper(v_buf) || ':' || upper(v_num));
            ELSE
                v_tokens := array_append(v_tokens, 'IND:' || upper(v_buf));
            END IF;
            CONTINUE;
        END IF;

        IF v_c ~ '[A-Za-z]' THEN
            v_buf := v_c;
            v_i := v_i + 1;
            WHILE v_i <= v_len LOOP
                v_peek := substr(v_src, v_i, 1);
                EXIT WHEN v_peek !~ '[A-Za-z0-9_]';
                v_buf := v_buf || v_peek;
                v_i := v_i + 1;
            END LOOP;
            IF lower(v_buf) IN ('dd', 'delta') THEN
                WHILE v_i <= v_len AND substr(v_src, v_i, 1) ~ '\s' LOOP v_i := v_i + 1; END LOOP;
                IF v_i > v_len OR substr(v_src, v_i, 1) <> '(' THEN
                    RAISE EXCEPTION 'poly_tokenize: expected ( after %', v_buf;
                END IF;
                v_i := v_i + 1;
                v_num := '';
                WHILE v_i <= v_len LOOP
                    v_peek := substr(v_src, v_i, 1);
                    IF v_peek ~ '[0-9]' THEN
                        v_num := v_num || v_peek;
                        v_i := v_i + 1;
                    ELSIF v_peek ~ '\s' THEN
                        v_i := v_i + 1;
                    ELSE
                        EXIT;
                    END IF;
                END LOOP;
                IF v_i > v_len OR substr(v_src, v_i, 1) <> ')' OR v_num = '' THEN
                    RAISE EXCEPTION 'poly_tokenize: invalid dd(k) at position %', v_i;
                END IF;
                v_tokens := array_append(v_tokens, 'DD:' || v_num);
                v_i := v_i + 1;
                CONTINUE;
            END IF;
            v_tokens := array_append(v_tokens, 'ID:' || lower(v_buf));
            CONTINUE;
        END IF;

        IF v_c ~ '[0-9.]' OR (v_c = '-' AND v_i < v_len AND substr(v_src, v_i + 1, 1) ~ '[0-9.]') THEN
            v_num := v_c;
            v_i := v_i + 1;
            WHILE v_i <= v_len AND substr(v_src, v_i, 1) ~ '[0-9.eE+-]' LOOP
                v_num := v_num || substr(v_src, v_i, 1);
                v_i := v_i + 1;
            END LOOP;
            v_tokens := array_append(v_tokens, 'NUM:' || v_num);
            CONTINUE;
        END IF;

        IF v_c = '/' AND v_i < v_len AND substr(v_src, v_i + 1, 1) = '#' THEN
            v_tokens := array_append(v_tokens, 'OP:/#');
            v_i := v_i + 2;
            CONTINUE;
        END IF;

        IF v_c = '=' THEN
            v_tokens := array_append(v_tokens, 'OP:=');
            v_i := v_i + 1;
            CONTINUE;
        END IF;

        IF v_c = ',' THEN
            v_tokens := array_append(v_tokens, 'COMMA');
            v_i := v_i + 1;
            CONTINUE;
        END IF;

        IF v_c IN ('+', '-', '*', '#') THEN
            v_tokens := array_append(v_tokens, 'OP:' || v_c);
            v_i := v_i + 1;
            CONTINUE;
        END IF;

        RAISE EXCEPTION 'poly_tokenize: unexpected character % at position %', v_c, v_i;
    END LOOP;
    RETURN v_tokens;
END;
$$;

CREATE OR REPLACE FUNCTION price_load_use_moex_fallback()
RETURNS BOOLEAN
LANGUAGE sql STABLE AS $$
    SELECT TRUE;
$$;

COMMENT ON FUNCTION price_load_use_moex_fallback() IS
'MOEX СЂР°Р·СЂРµС€С‘РЅ РєР°Рє fallback РїРѕСЃР»Рµ РЅРµСѓРґР°С‡Рё T-Bank (РѕС€РёР±РєР° РёР»Рё 0 СЃРІРµС‡РµР№)';

CREATE OR REPLACE FUNCTION prices_topup_date_from(p_security_id INTEGER,
    p_timeframe_id INTEGER,
    p_closed_bar_dt TIMESTAMP,
    p_fallback_from DATE)
RETURNS DATE
LANGUAGE plpgsql STABLE AS $$
BEGIN
    IF EXISTS (
        SELECT 1
        FROM prices p
        WHERE p.security_id = p_security_id
          AND p.timeframe_id = p_timeframe_id
          AND p.dt >= (p_closed_bar_dt - INTERVAL '5 days')
        LIMIT 1
    ) THEN
        RETURN p_closed_bar_dt::date;
    END IF;
    RETURN p_fallback_from;
END;
$$;

COMMENT ON FUNCTION prices_topup_date_from(INTEGER, INTEGER, TIMESTAMP, DATE) IS
'date_from РґР»СЏ load_prices: РґРµРЅСЊ closed bar, РµСЃР»Рё РІ Р‘Р” СѓР¶Рµ РµСЃС‚СЊ РЅРµРґР°РІРЅРёРµ СЃРІРµС‡Рё';

CREATE OR REPLACE FUNCTION process_logic_opt_trades(p_logic_id INTEGER,
    p_tf_id INTEGER,
    p_closed_bar_dt TIMESTAMP,
    p_is_test BOOLEAN DEFAULT FALSE,
    p_run_id BIGINT DEFAULT NULL,
    p_sizing_base NUMERIC DEFAULT NULL)
RETURNS INTEGER
LANGUAGE plpgsql AS $$
DECLARE
    v_logic RECORD;
    v_arm RECORD;
    v_sec RECORD;
    v_grp RECORD;
    v_sig RECORD;
    v_eval RECORD;
    v_pt RECORD;
    v_created INTEGER := 0;
    v_all_ok BOOLEAN;
    v_formulas TEXT;
    v_signal_kind TEXT;
    v_pp NUMERIC;
    v_ind_dt TIMESTAMP;
    v_held_long NUMERIC;
    v_held_short NUMERIC;
    v_is_open_event BOOLEAN;
    v_quantity INTEGER;
    v_side_id INTEGER;
    v_action_id INTEGER;
    v_side_open_id INTEGER;
    v_side_close_id INTEGER;
    v_action_long_id INTEGER;
    v_action_short_id INTEGER;
    v_eff_side TEXT;
    v_eff_inversion BOOLEAN;
    v_inversion BOOLEAN;
    v_lot_size INTEGER;
    v_is_futures BOOLEAN;
    v_position_size_pct NUMERIC;
    v_max_order_amount NUMERIC;
    v_sizing_base NUMERIC;
    v_cycle_budget NUMERIC;
    v_max_exposure NUMERIC;
    v_spent_notional NUMERIC;
    v_room NUMERIC;
    v_order_notional NUMERIC;
    v_equity_cap NUMERIC;
    v_trade_id BIGINT;
    v_comm NUMERIC;
    v_max_positions INTEGER;
    v_open_lane INTEGER;
    v_is_test BOOLEAN := COALESCE(p_is_test, FALSE);
    v_grid_arms JSONB := NULL;
    v_use_grid BOOLEAN := FALSE;
BEGIN
    -- Same backtest run: formula OPT() arms OR offline grid arms stored on the run.
    IF v_is_test AND p_run_id IS NOT NULL THEN
        SELECT r.opt_grid_arms
        INTO v_grid_arms
        FROM logic_backtest_runs r
        WHERE r.id = p_run_id;
        IF v_grid_arms IS NOT NULL
           AND jsonb_typeof(v_grid_arms) = 'array'
           AND jsonb_array_length(v_grid_arms) > 0 THEN
            v_use_grid := TRUE;
        END IF;
    END IF;

    IF NOT v_use_grid AND NOT logic_opt_logic_has_opt(p_logic_id) THEN
        RETURN 0;
    END IF;

    IF v_is_test THEN
        -- РўРµСЃС‚: Р»РѕРіРёРєР° РјРѕР¶РµС‚ Р±С‹С‚СЊ РІС‹РєР»СЋС‡РµРЅР°; СЃС‡С‘С‚ РІСЃС‘ СЂР°РІРЅРѕ РЅСѓР¶РµРЅ.
        SELECT l.id, l.account_id
        INTO v_logic
        FROM logics l
        WHERE l.id = p_logic_id;
        IF NOT FOUND THEN
            RETURN 0;
        END IF;
    ELSE
        SELECT l.id, l.account_id
        INTO v_logic
        FROM logics l
        JOIN accounts a ON a.id = l.account_id
        WHERE l.id = p_logic_id AND l.is_enabled = TRUE AND a.is_active = TRUE;
        IF NOT FOUND THEN
            RETURN 0;
        END IF;
    END IF;

    SELECT id INTO v_side_open_id FROM sides WHERE name = 'Open' LIMIT 1;
    SELECT id INTO v_side_close_id FROM sides WHERE name = 'Close' LIMIT 1;
    SELECT id INTO v_action_long_id FROM actions WHERE name = 'Long' LIMIT 1;
    SELECT id INTO v_action_short_id FROM actions WHERE name = 'Short' LIMIT 1;
    IF v_side_open_id IS NULL OR v_side_close_id IS NULL THEN
        RETURN 0;
    END IF;

    v_position_size_pct := get_logic_param_numeric(p_logic_id, 'position_size_pct', 10);
    v_max_positions := GREATEST(1, get_logic_param_numeric(p_logic_id, 'max_open_positions', 10)::INTEGER);
    v_max_order_amount := get_logic_param_numeric(p_logic_id, 'max_order_amount', NULL);
    v_inversion := get_logic_param_boolean(p_logic_id, 'inversion', FALSE);

    -- РљР°Рє Сѓ С‡РµРјРїРёРѕРЅР°: Р±Р°Р·Р° С†РёРєР»Р° в‰¤ equity. Р Р°РЅСЊС€Рµ OPT Р±СЂР°Р» СЃС‹СЂРѕР№ free_cash / 1e6
    -- в†’ paper-Р»РѕС‚С‹ ~100k РїСЂРё cash_amount РїРѕСЃР»Рµ С€РѕСЂС‚РѕРІ (РїСѓС‚Р°С‚СЊ СЃ РјР°СЂР¶РѕР№ Р±СЂРѕРєРµСЂР°).
    IF v_is_test THEN
        v_cycle_budget := COALESCE(NULLIF(p_sizing_base, 0), NULL);
        IF v_cycle_budget IS NULL OR v_cycle_budget <= 0 THEN
            IF p_run_id IS NOT NULL THEN
                SELECT COALESCE(NULLIF(r.test_balance, 0), 1000000)
                INTO v_cycle_budget
                FROM logic_backtest_runs r WHERE r.id = p_run_id;
            END IF;
            v_cycle_budget := COALESCE(NULLIF(v_cycle_budget, 0), 1000000);
        END IF;
        BEGIN
            v_equity_cap := logic_backtest_portfolio_equity(
                p_logic_id, p_tf_id, p_closed_bar_dt, v_cycle_budget
            );
            IF v_equity_cap IS NOT NULL AND v_equity_cap > 0 THEN
                v_cycle_budget := LEAST(v_cycle_budget, v_equity_cap);
            END IF;
        EXCEPTION
            WHEN undefined_function THEN
                NULL;
            WHEN OTHERS THEN
                NULL;
        END;
    ELSE
        v_cycle_budget := COALESCE(
            NULLIF(p_sizing_base, 0),
            logic_exposure_cycle_budget(p_logic_id, p_tf_id)
        );
        IF v_cycle_budget IS NULL OR v_cycle_budget <= 0 THEN
            v_cycle_budget := COALESCE(
                NULLIF(logic_position_sizing_base(p_logic_id, p_tf_id), 0),
                1000000
            );
        END IF;
    END IF;
    v_sizing_base := v_cycle_budget;
    v_max_exposure := v_cycle_budget
        * (GREATEST(0, COALESCE(v_position_size_pct, 0)) / 100.0)
        * v_max_positions;

    -- РљСЌС€ РєР°РЅР°Р»Р° РЅР° Р±Р°СЂ: 34 Р±СѓРјР°РіРё Г— 2 std_dev Г— 4 СЃРёРіРЅР°Р»Р° в†’ Р±С‹Р»Рѕ 272 calc, СЃС‚Р°РЅРµС‚ ~68
    PERFORM logic_opt_ensure_linreg_cache();
    TRUNCATE opt_linreg_cache;

    FOR v_arm IN
        SELECT a->>'lane' AS lane, a->'values' AS values_json
        FROM jsonb_array_elements(v_grid_arms) AS a
        WHERE v_use_grid
        UNION ALL
        SELECT b.lane, b.values_json
        FROM logic_opt_build_arms(p_logic_id) AS b
        WHERE NOT v_use_grid
    LOOP
        -- РћРґРёРЅ СЂР°Р· РЅР° РІРµС‚РєСѓ: С‡РёСЃР»Рѕ Р±СѓРјР°Рі СЃ РѕС‚РєСЂС‹С‚РѕР№ РїРѕР·РёС†РёРµР№ (СЂР°РЅСЊС€Рµ вЂ” РЅР° РєР°Р¶РґСѓСЋ Р±СѓРјР°РіСѓ).
        SELECT COUNT(*)::INTEGER INTO v_open_lane
        FROM (
            SELECT lt.security_id
            FROM logic_trades lt
            JOIN sides s ON s.id = lt.side_id
            JOIN actions a ON a.id = lt.action_id
            WHERE lt.logic_id = p_logic_id
              AND COALESCE(lt.opt_lane, '') = v_arm.lane
              AND NOT lt.is_shadow
              AND lt.is_test = v_is_test
              AND (NOT v_is_test OR p_run_id IS NULL OR lt.run_id = p_run_id)
              AND lt.status IN ('filled', 'submitted')
            GROUP BY lt.security_id
            HAVING COALESCE(SUM(
                CASE
                    WHEN s.name = 'Open' AND a.name = 'Long' THEN lt.quantity
                    WHEN s.name = 'Close' AND a.name = 'Long' THEN -lt.quantity
                    WHEN s.name = 'Open' AND a.name = 'Short' THEN lt.quantity
                    WHEN s.name = 'Close' AND a.name = 'Short' THEN -lt.quantity
                    ELSE 0
                END
            ), 0) > 0
        ) q;

        v_spent_notional := logic_open_notional_exposure(
            p_logic_id, v_is_test, v_arm.lane, CASE WHEN v_is_test THEN p_run_id ELSE NULL END
        );

        -- РљР°Рє Сѓ С‡РµРјРїРёРѕРЅР°: Р»СѓС‡С€РёР№ PnL РІРµС‚РєРё; РѕРґРёРЅ GROUP BY РЅР° Р±Р°СЂ (РЅРµ N РєРѕСЂСЂРµР»РёСЂРѕРІР°РЅРЅС‹С… SUM).
        FOR v_sec IN
            SELECT
                ls.security_id,
                COALESCE(ls.real_trading_inverted, FALSE) AS real_trading_inverted
            FROM logic_securities ls
            LEFT JOIN (
                SELECT lt.security_id,
                       COALESCE(SUM(lt.financial_result), 0) AS pnl
                FROM logic_trades lt
                JOIN sides s ON s.id = lt.side_id
                WHERE lt.logic_id = p_logic_id
                  AND lt.is_test = v_is_test
                  AND NOT lt.is_shadow
                  AND COALESCE(lt.opt_lane, '') = v_arm.lane
                  AND (NOT v_is_test OR lt.run_id = p_run_id)
                  AND s.name = 'Close'
                  AND lt.status IN ('filled', 'submitted')
                GROUP BY lt.security_id
            ) pnl ON pnl.security_id = ls.security_id
            WHERE ls.logic_id = p_logic_id AND ls.is_active = TRUE
              AND NOT logic_is_cash_fund_security(ls.security_id)
            ORDER BY COALESCE(pnl.pnl, 0) DESC,
                     ls.display_order NULLS LAST,
                     ls.id
        LOOP
            v_eff_inversion := (v_inversion <> COALESCE(v_sec.real_trading_inverted, FALSE));
            v_lot_size := logic_security_lot_size(v_sec.security_id);
            v_is_futures := logic_security_is_futures(v_sec.security_id);

            FOR v_grp IN
                SELECT lis.position_event, lis.position_side
                FROM logic_indicator_signals lis
                WHERE lis.logic_id = p_logic_id AND lis.is_active = TRUE
                GROUP BY lis.position_event, lis.position_side
                ORDER BY lis.position_event, lis.position_side
            LOOP
                v_all_ok := TRUE;
                v_formulas := NULL;
                v_signal_kind := NULL;
                v_pp := NULL;
                v_ind_dt := NULL;

                FOR v_sig IN
                    SELECT lis.id, lis.position_event, lis.position_side, lis.signal_kind, lis.formula
                    FROM logic_indicator_signals lis
                    WHERE lis.logic_id = p_logic_id
                      AND lis.is_active = TRUE
                      AND lis.position_event = v_grp.position_event
                      AND lis.position_side = v_grp.position_side
                    ORDER BY lis.display_order, lis.id
                LOOP
                    -- РўР¤ СЃРёРіРЅР°Р»Р° (tf=) Рё РµРіРѕ Р·Р°РєСЂС‹С‚С‹Р№ Р±Р°СЂ РґРѕ close Р±Р°СЂР° Р»РѕРіРёРєРё.
                    SELECT * INTO v_pt
                    FROM logic_signal_eval_point(v_sig.formula, p_tf_id, p_closed_bar_dt);
                    IF v_pt.tf_id IS NULL OR v_pt.bar_dt IS NULL THEN
                        v_all_ok := FALSE;
                        CONTINUE;
                    END IF;

                    SELECT * INTO v_eval
                    FROM logic_signal_evaluate_at_opt(
                        -- Inversion flips sides only; keep original band/SMA conditions.
                        v_sig.id, v_sec.security_id, v_pt.tf_id, v_pt.bar_dt,
                        FALSE, v_arm.values_json
                    );
                    IF v_eval.close_price IS NULL THEN
                        v_all_ok := FALSE;
                        CONTINUE;
                    END IF;
                    IF v_signal_kind IS NULL THEN
                        v_signal_kind := v_sig.signal_kind;
                        v_pp := v_eval.close_price;
                        v_ind_dt := v_eval.bar_dt;
                    END IF;
                    v_formulas := CASE
                        WHEN v_formulas IS NULL THEN v_sig.formula
                        ELSE v_formulas || ' AND ' || v_sig.formula
                    END;
                    IF NOT COALESCE(v_eval.ok, FALSE) THEN
                        v_all_ok := FALSE;
                    END IF;
                END LOOP;

                IF NOT v_all_ok OR v_pp IS NULL OR v_formulas IS NULL THEN
                    CONTINUE;
                END IF;

                v_eff_side := lower(COALESCE(v_grp.position_side, 'long'));
                IF v_eff_inversion THEN
                    v_eff_side := CASE WHEN v_eff_side = 'long' THEN 'short' ELSE 'long' END;
                END IF;

                v_held_long := CASE
                    WHEN v_eff_side = 'long'
                    THEN logic_long_position_qty(
                        p_logic_id, v_sec.security_id, FALSE, v_is_test, v_arm.lane
                    )
                    ELSE 0
                END;
                v_held_short := CASE
                    WHEN v_eff_side = 'short'
                    THEN logic_short_position_qty(
                        p_logic_id, v_sec.security_id, FALSE, v_is_test, v_arm.lane
                    )
                    ELSE 0
                END;
                v_is_open_event := COALESCE(v_grp.position_event, 'open') = 'open';

                IF v_eff_side = 'long' THEN
                    IF v_is_open_event THEN
                        IF v_held_long > 0 OR v_open_lane >= v_max_positions THEN
                            CONTINUE;
                        END IF;
                        v_room := GREATEST(0, v_max_exposure - v_spent_notional);
                        IF v_max_order_amount IS NOT NULL AND v_max_order_amount > 0 THEN
                            v_room := LEAST(v_room, v_max_order_amount);
                        END IF;
                        v_quantity := logic_calc_open_quantity(
                            v_cycle_budget, v_position_size_pct, v_pp, v_lot_size, v_room
                        );
                        IF v_quantity < v_lot_size THEN
                            IF v_is_futures AND v_cycle_budget IS NOT NULL AND v_cycle_budget > 0
                               AND v_lot_size * v_pp <= v_room THEN
                                v_quantity := v_lot_size;
                            ELSE
                                CONTINUE;
                            END IF;
                        END IF;
                        v_order_notional := v_quantity * v_pp;
                        IF v_order_notional > v_room + 0.000001 THEN
                            CONTINUE;
                        END IF;
                        v_side_id := v_side_open_id;
                        v_action_id := v_action_long_id;
                    ELSE
                        IF v_held_long <= 0 THEN
                            CONTINUE;
                        END IF;
                        v_quantity := v_held_long::INTEGER;
                        v_side_id := v_side_close_id;
                        v_action_id := v_action_long_id;
                    END IF;
                ELSIF v_is_open_event THEN
                    IF v_held_short > 0 OR v_open_lane >= v_max_positions THEN
                        CONTINUE;
                    END IF;
                    v_room := GREATEST(0, v_max_exposure - v_spent_notional);
                    IF v_max_order_amount IS NOT NULL AND v_max_order_amount > 0 THEN
                        v_room := LEAST(v_room, v_max_order_amount);
                    END IF;
                    v_quantity := logic_calc_open_quantity(
                        v_cycle_budget, v_position_size_pct, v_pp, v_lot_size, v_room
                    );
                    IF v_quantity < v_lot_size THEN
                        IF v_is_futures AND v_cycle_budget IS NOT NULL AND v_cycle_budget > 0
                           AND v_lot_size * v_pp <= v_room THEN
                            v_quantity := v_lot_size;
                        ELSE
                            CONTINUE;
                        END IF;
                    END IF;
                    v_order_notional := v_quantity * v_pp;
                    IF v_order_notional > v_room + 0.000001 THEN
                        CONTINUE;
                    END IF;
                    v_side_id := v_side_open_id;
                    v_action_id := v_action_short_id;
                ELSE
                    IF v_held_short <= 0 THEN
                        CONTINUE;
                    END IF;
                    v_quantity := v_held_short::INTEGER;
                    v_side_id := v_side_close_id;
                    v_action_id := v_action_short_id;
                END IF;

                v_comm := logic_trade_calc_commission(p_logic_id, v_quantity * v_pp);
                INSERT INTO logic_trades (
                    logic_id, account_id, security_id, timeframe_id,
                    side_id, action_id, position_event, signal_kind, signal_formula,
                    quantity, price, commission, bar_dt, is_simulated, is_fictitious, is_shadow, is_test,
                    opt_lane, run_id, status, note, trade_reason
                )
                VALUES (
                    p_logic_id, v_logic.account_id, v_sec.security_id, p_tf_id,
                    v_side_id, v_action_id, v_grp.position_event, v_signal_kind, v_formulas,
                    v_quantity, v_pp, COALESCE(v_comm, 0), v_ind_dt, TRUE, FALSE, FALSE, v_is_test,
                    v_arm.lane,
                    CASE WHEN v_is_test THEN p_run_id ELSE NULL END,
                    'filled', 'opt paper', 'opt:' || v_arm.lane
                )
                ON CONFLICT (logic_id, security_id, position_event, action_id, bar_dt, is_test, is_shadow, opt_lane)
                    DO NOTHING
                RETURNING id INTO v_trade_id;

                IF v_trade_id IS NOT NULL THEN
                    PERFORM logic_trade_finalize(v_trade_id, NULL);
                    v_created := v_created + 1;
                    IF v_is_open_event THEN
                        v_open_lane := v_open_lane + 1;
                        v_spent_notional := v_spent_notional + (v_quantity * v_pp);
                    ELSE
                        v_open_lane := GREATEST(0, v_open_lane - 1);
                        v_spent_notional := GREATEST(
                            0, v_spent_notional - (v_quantity * v_pp)
                        );
                    END IF;
                    -- Tech log С‚РѕР»СЊРєРѕ РІ Р±РѕСЋ вЂ” РІ С‚РµСЃС‚Рµ С‚С‹СЃСЏС‡Рё СЃС‚СЂРѕРє СЃРёР»СЊРЅРѕ С‚РѕСЂРјРѕР·СЏС‚.
                    IF NOT v_is_test THEN
                        PERFORM logic_trade_log(
                            p_logic_id,
                            'opt.trade',
                            format('OPT %s СЃРґРµР»РєР° #%s qty=%s', v_arm.lane, v_trade_id, v_quantity),
                            jsonb_build_object(
                                'opt_lane', v_arm.lane,
                                'trade_id', v_trade_id,
                                'values', v_arm.values_json,
                                'bar_dt', v_ind_dt
                            ),
                            v_sec.security_id,
                            p_tf_id
                        );
                    END IF;
                END IF;
            END LOOP;
        END LOOP;
    END LOOP;

    RETURN v_created;
END;
$$;

COMMENT ON FUNCTION process_logic_opt_trades(INTEGER, INTEGER, TIMESTAMP, BOOLEAN, BIGINT, NUMERIC) IS
'Р‘СѓРјР°Р¶РЅС‹Рµ СЃРґРµР»РєРё OPT-РІРµС‚РѕРє (opt_lane): Р±Р°Р·Р° = exposure_cycle_budget (в‰¤ equity), РїРѕС‚РѕР»РѕРє %Г—РјР°РєСЃ.РїРѕР· РєР°Рє Сѓ С‡РµРјРїРёРѕРЅР°.';

COMMENT ON FUNCTION logic_opt_maybe_promote(INTEGER, INTEGER, TIMESTAMP, BOOLEAN, BIGINT) IS
'РљР°Р¶РґС‹Рµ opt_eval_candles: FinRes С‡РµРјРїРёРѕРЅР° vs РІРµС‚РєРё; promote + history (run_id РІ С‚РµСЃС‚Рµ).';

CREATE OR REPLACE FUNCTION process_logic_stops(p_logic_id INTEGER)
RETURNS INTEGER
LANGUAGE plpgsql AS $$
DECLARE
    v_logic RECORD;
    v_stop RECORD;
    v_tp RECORD;
    v_tf_id INTEGER;
    v_tf_sec INTEGER;
    v_closed_bar_dt TIMESTAMP;
    v_last_bar_raw TEXT;
    v_last_bar_dt TIMESTAMP;
    v_sec RECORD;
    v_drawdown NUMERIC;
    v_port_dd NUMERIC;
    v_actions INTEGER := 0;
    v_track_before NUMERIC;
    v_track_after NUMERIC;
    v_closed INTEGER;
    v_skip_http BOOLEAN := FALSE;
    v_date_from DATE;
    v_date_to DATE;
    v_price NUMERIC;
BEGIN
    SELECT l.id, l.is_enabled
    INTO v_logic
    FROM logics l
    JOIN accounts a ON a.id = l.account_id
    WHERE l.id = p_logic_id
      AND l.is_enabled = TRUE
      AND a.is_active = TRUE;

    IF NOT FOUND THEN
        RETURN 0;
    END IF;

    v_tf_id := logic_resolve_stop_timeframe_id(p_logic_id);
    IF v_tf_id IS NULL THEN
        RETURN 0;
    END IF;

    SELECT t.sec INTO v_tf_sec FROM timeframes t WHERE t.id = v_tf_id;
    v_closed_bar_dt := logic_last_closed_bar_dt(v_tf_sec);
    IF v_closed_bar_dt IS NULL THEN
        RETURN 0;
    END IF;

    v_last_bar_raw := btrim(COALESCE(get_logic_param_text(p_logic_id, 'last_stop_bar_dt'), ''));
    IF v_last_bar_raw <> '' THEN
        BEGIN
            v_last_bar_dt := v_last_bar_raw::TIMESTAMP;
            IF v_closed_bar_dt <= v_last_bar_dt THEN
                IF logic_check_portfolio_resume(p_logic_id, v_tf_id) THEN
                    v_actions := v_actions + 1;
                END IF;
                FOR v_sec IN
                    SELECT ls.security_id
                    FROM logic_securities ls
                    WHERE ls.logic_id = p_logic_id
                      AND ls.is_active = TRUE
                      AND (
                          ls.real_trading_paused = TRUE
                          OR ls.real_trading_paused_long = TRUE
                          OR ls.real_trading_paused_short = TRUE
                          OR ls.real_trading_inverted = TRUE
                      )
                LOOP
                    IF logic_check_security_inversion(p_logic_id, v_sec.security_id, v_tf_id) THEN
                        v_actions := v_actions + 1;
                    ELSIF logic_check_security_resume(p_logic_id, v_sec.security_id, v_tf_id) THEN
                        v_actions := v_actions + 1;
                    END IF;
                END LOOP;
                RETURN v_actions;
            END IF;
        EXCEPTION
            WHEN OTHERS THEN
                NULL;
        END;
    END IF;

    SELECT * INTO v_stop
    FROM logic_stops ls
    WHERE ls.logic_id = p_logic_id
      AND ls.rule_kind = 'stop_loss'
      AND ls.is_active = TRUE
    ORDER BY ls.display_order, ls.id
    LIMIT 1;

    -- РќРµ РіСЂСѓР·РёРј РІСЃРµ 34 Р±СѓРјР°РіРё С‡РµСЂРµР· HTTP РЅР° РєР°Р¶РґРѕРј Р±Р°СЂРµ: СЌС‚Рѕ Р±Р»РѕРєРёСЂСѓРµС‚ РїСѓР» Рё UI
    -- (СЂР°СЃРєСЂС‹С‚РёРµ Р±СѓРјР°РіРё / РіСЂР°С„РёРє). РўРѕР»СЊРєРѕ РїРѕР·РёС†РёРё / pause + skip РµСЃР»Рё СЃРІРµС‡Р° СѓР¶Рµ РµСЃС‚СЊ.
    SELECT EXISTS (
        SELECT 1
        FROM logic_backtest_runs r
        WHERE r.status IN ('pending', 'loading_prices', 'loading_indicators', 'running')
    ) INTO v_skip_http;

    v_date_to := GREATEST(v_closed_bar_dt::date, CURRENT_DATE);
    v_date_from := logic_trade_load_date_from(
        v_tf_sec, logic_trade_sync_point_count(v_tf_sec), v_closed_bar_dt
    );

    FOR v_sec IN
        SELECT DISTINCT q.security_id
        FROM (
            SELECT lt.security_id
            FROM logic_trades lt
            WHERE lt.logic_id = p_logic_id
              AND NOT lt.is_test
              AND NOT lt.is_shadow
              AND lt.status IN ('filled', 'submitted')
            UNION
            SELECT ls.security_id
            FROM logic_securities ls
            WHERE ls.logic_id = p_logic_id
              AND ls.is_active = TRUE
              AND (
                  ls.real_trading_paused = TRUE
                  OR ls.real_trading_paused_long = TRUE
                  OR ls.real_trading_paused_short = TRUE
                  OR ls.real_trading_inverted = TRUE
              )
        ) q
    LOOP
        IF NOT v_skip_http
           AND NOT prices_have_closed_bar(v_sec.security_id, v_tf_id, v_closed_bar_dt) THEN
            BEGIN
                CALL load_prices(
                    v_sec.security_id,
                    v_tf_id,
                    prices_topup_date_from(
                        v_sec.security_id, v_tf_id, v_closed_bar_dt, v_date_from
                    ),
                    v_date_to
                );
            EXCEPTION
                WHEN OTHERS THEN
                    NULL;
            END;
        END IF;

        IF logic_check_security_inversion(p_logic_id, v_sec.security_id, v_tf_id) THEN
            v_actions := v_actions + 1;
        ELSIF logic_check_security_resume(p_logic_id, v_sec.security_id, v_tf_id) THEN
            v_actions := v_actions + 1;
        END IF;
    END LOOP;

    IF logic_check_portfolio_resume(p_logic_id, v_tf_id) THEN
        v_actions := v_actions + 1;
    END IF;

    -- SL РјРѕР¶РµС‚ РѕС‚СЃСѓС‚СЃС‚РІРѕРІР°С‚СЊ вЂ” Р»РёРЅРµР№РЅС‹Р№ TP РІСЃС‘ СЂР°РІРЅРѕ РѕР±СЂР°Р±Р°С‚С‹РІР°РµРј РЅРёР¶Рµ
    IF v_stop.id IS NOT NULL AND v_stop.value_unit <> 'percent' THEN
        PERFORM logic_trade_log(
            p_logic_id, 'stop.skip',
            format('РЎС‚РѕРї-Р»РѕСЃСЃ: РµРґРёРЅРёС†Р° %s РїРѕРєР° РЅРµ РїРѕРґРґРµСЂР¶РёРІР°РµС‚СЃСЏ (С‚РѕР»СЊРєРѕ percent)', v_stop.value_unit),
            NULL, NULL, v_tf_id
        );
    ELSIF v_stop.id IS NOT NULL AND v_stop.scope_type = 'portfolio' THEN
        v_port_dd := logic_portfolio_drawdown_pct(p_logic_id, v_tf_id);
        IF v_port_dd >= v_stop.value THEN
            PERFORM logic_trade_log(
                p_logic_id, 'stop.trigger',
                format('РџРѕСЂС‚С„РµР»СЊРЅС‹Р№ SL: РїСЂРѕСЃР°РґРєР° %s%% >= %s%%', round(v_port_dd, 4), v_stop.value),
                jsonb_build_object('drawdown_pct', v_port_dd, 'threshold', v_stop.value),
                NULL, v_tf_id
            );
            FOR v_sec IN
                SELECT DISTINCT lt.security_id
                FROM logic_trades lt
                WHERE lt.logic_id = p_logic_id
                  AND NOT lt.is_shadow
                  AND NOT lt.is_test
                  AND lt.status IN ('filled', 'submitted')
                  AND NOT logic_is_cash_fund_security(lt.security_id)
            LOOP
                v_closed := logic_close_security_positions_market(
                    p_logic_id, v_sec.security_id, FALSE
                );
                v_actions := v_actions + v_closed;
            END LOOP;
        END IF;
    ELSIF v_stop.id IS NOT NULL AND v_stop.scope_type = 'portfolio_resume' THEN
        -- РЈР¶Рµ РІ РїР°СѓР·Рµ вЂ” С‚РѕР»СЊРєРѕ РїСЂРѕРІРµСЂРєР° РІРѕР·РѕР±РЅРѕРІР»РµРЅРёСЏ (РІС‹С€Рµ); РЅРµ С‚СЂРёРіРіРµСЂРёРј РїРѕРІС‚РѕСЂРЅРѕ.
        IF EXISTS (
            SELECT 1 FROM logics l
            WHERE l.id = p_logic_id AND COALESCE(l.portfolio_trading_paused, FALSE)
        ) THEN
            NULL;
        ELSE
            v_port_dd := logic_portfolio_peak_drawdown_pct(p_logic_id, v_tf_id);
            IF v_port_dd >= v_stop.value THEN
                v_track_before := logic_portfolio_equity(p_logic_id, v_tf_id);
                PERFORM logic_trade_log(
                    p_logic_id, 'stop.trigger',
                    format(
                        'РџРѕСЂС‚С„РµР»СЊРЅС‹Р№ SL СЃ РІРѕР·РѕР±РЅРѕРІР»РµРЅРёРµРј: РїСЂРѕСЃР°РґРєР° РѕС‚ РїРёРєР° %s%% >= %s%%, equity=%s',
                        round(v_port_dd, 4), v_stop.value, round(COALESCE(v_track_before, 0), 2)
                    ),
                    jsonb_build_object(
                        'drawdown_pct', v_port_dd,
                        'threshold', v_stop.value,
                        'scope', 'portfolio_resume',
                        'equity_before', v_track_before
                    ),
                    NULL, v_tf_id
                );
                FOR v_sec IN
                    SELECT DISTINCT lt.security_id
                    FROM logic_trades lt
                    WHERE lt.logic_id = p_logic_id
                      AND NOT lt.is_shadow
                      AND NOT lt.is_test
                      AND lt.status IN ('filled', 'submitted')
                      AND NOT logic_is_cash_fund_security(lt.security_id)
                LOOP
                    v_closed := logic_close_security_positions_market(
                        p_logic_id, v_sec.security_id, FALSE
                    );
                    v_actions := v_actions + v_closed;
                END LOOP;
                v_track_after := logic_portfolio_equity(p_logic_id, v_tf_id);
                UPDATE logics
                SET portfolio_trading_paused = TRUE,
                    portfolio_stop_resume_equity = v_track_before,
                    portfolio_stop_resume_baseline = v_track_after,
                    portfolio_stop_resume_at = CURRENT_TIMESTAMP
                WHERE id = p_logic_id;
                v_actions := v_actions + 1;
            END IF;
        END IF;
    ELSIF v_stop.id IS NOT NULL THEN
        FOR v_sec IN
            SELECT ls.security_id
            FROM logic_securities ls
            WHERE ls.logic_id = p_logic_id AND ls.is_active = TRUE
              AND NOT logic_is_cash_fund_security(ls.security_id)
        LOOP
            IF v_stop.scope_type = 'security_resume' THEN
                -- РџСЂРѕСЃР°РґРєР° Рё РїР°СѓР·Р° РїРѕ СЃС‚РѕСЂРѕРЅРµ (long/short) РЅРµР·Р°РІРёСЃРёРјРѕ.
                DECLARE
                    v_side_name TEXT;
                    v_side_paused BOOLEAN;
                    v_hwm NUMERIC;
                    v_target NUMERIC;
                    v_no_reduce BOOLEAN;
                BEGIN
                    v_no_reduce := COALESCE(
                        get_logic_param_boolean(p_logic_id, 'resume_sl_no_reduce', FALSE),
                        FALSE
                    );
                    FOREACH v_side_name IN ARRAY ARRAY['long', 'short']
                    LOOP
                        SELECT CASE
                            WHEN v_side_name = 'long'
                                THEN COALESCE(ls.real_trading_paused_long, FALSE)
                            ELSE COALESCE(ls.real_trading_paused_short, FALSE)
                        END,
                        CASE
                            WHEN v_side_name = 'long' THEN ls.stop_resume_hwm_long
                            ELSE ls.stop_resume_hwm_short
                        END
                        INTO v_side_paused, v_hwm
                        FROM logic_securities ls
                        WHERE ls.logic_id = p_logic_id
                          AND ls.security_id = v_sec.security_id;

                        IF COALESCE(v_side_paused, FALSE) THEN
                            CONTINUE;
                        END IF;

                        v_drawdown := logic_security_side_drawdown_pct(
                            p_logic_id, v_sec.security_id, v_tf_id, FALSE, v_side_name
                        );
                        IF v_drawdown < v_stop.value THEN
                            CONTINUE;
                        END IF;

                        v_track_before := logic_security_side_track_value(
                            p_logic_id, v_sec.security_id, v_tf_id, FALSE, v_side_name
                        );
                        v_target := logic_resume_sl_peak_target(
                            p_logic_id, v_track_before, v_hwm
                        );
                        PERFORM logic_trade_log(
                            p_logic_id, 'stop.trigger',
                            format(
                                'SL СЃ РІРѕР·РѕР±РЅРѕРІР»РµРЅРёРµРј sec=%s side=%s: РїСЂРѕСЃР°РґРєР° %s%% >= %s%%, track=%s target=%s',
                                v_sec.security_id, v_side_name,
                                round(v_drawdown, 4), v_stop.value, v_track_before, v_target
                            ),
                            jsonb_build_object(
                                'security_id', v_sec.security_id,
                                'position_side', v_side_name,
                                'drawdown_pct', v_drawdown,
                                'scope', 'security_resume',
                                'track_before', v_track_before,
                                'resume_target', v_target,
                                'resume_sl_no_reduce', v_no_reduce
                            ),
                            v_sec.security_id, v_tf_id
                        );
                        v_closed := logic_close_security_positions_market(
                            p_logic_id, v_sec.security_id, FALSE,
                            format('stop_loss:security_resume:%s', v_side_name),
                            v_side_name
                        );
                        v_actions := v_actions + v_closed;
                        v_track_after := logic_security_side_track_value(
                            p_logic_id, v_sec.security_id, v_tf_id, FALSE, v_side_name
                        );

                        IF v_side_name = 'long' THEN
                            UPDATE logic_securities
                            SET real_trading_paused_long = TRUE,
                                stop_resume_equity_long = v_target,
                                stop_resume_baseline_long = v_track_after,
                                stop_resume_triggered_at_long = CURRENT_TIMESTAMP,
                                stop_resume_hwm_long = CASE
                                    WHEN v_no_reduce THEN v_target
                                    ELSE stop_resume_hwm_long
                                END,
                                real_trading_paused = TRUE
                            WHERE logic_id = p_logic_id
                              AND security_id = v_sec.security_id;
                        ELSE
                            UPDATE logic_securities
                            SET real_trading_paused_short = TRUE,
                                stop_resume_equity_short = v_target,
                                stop_resume_baseline_short = v_track_after,
                                stop_resume_triggered_at_short = CURRENT_TIMESTAMP,
                                stop_resume_hwm_short = CASE
                                    WHEN v_no_reduce THEN v_target
                                    ELSE stop_resume_hwm_short
                                END,
                                real_trading_paused = TRUE
                            WHERE logic_id = p_logic_id
                              AND security_id = v_sec.security_id;
                        END IF;
                        v_actions := v_actions + 1;
                    END LOOP;
                END;
                CONTINUE;
            END IF;

            IF v_stop.scope_type = 'security_inversion' THEN
                -- Same as resume (paper Г— side), keep inverted flag; toggle on shadowв†’zero.
                DECLARE
                    v_side_name TEXT;
                    v_side_paused BOOLEAN;
                    v_hwm NUMERIC;
                    v_target NUMERIC;
                    v_no_reduce BOOLEAN;
                    v_inverted BOOLEAN;
                    v_pos_side TEXT;
                BEGIN
                    v_no_reduce := COALESCE(
                        get_logic_param_boolean(p_logic_id, 'resume_sl_no_reduce', FALSE),
                        FALSE
                    );
                    FOREACH v_side_name IN ARRAY ARRAY['long', 'short']
                    LOOP
                        SELECT CASE
                            WHEN v_side_name = 'long'
                                THEN COALESCE(ls.real_trading_paused_long, FALSE)
                            ELSE COALESCE(ls.real_trading_paused_short, FALSE)
                        END,
                        CASE
                            WHEN v_side_name = 'long' THEN ls.stop_resume_hwm_long
                            ELSE ls.stop_resume_hwm_short
                        END,
                        COALESCE(ls.real_trading_inverted, FALSE)
                        INTO v_side_paused, v_hwm, v_inverted
                        FROM logic_securities ls
                        WHERE ls.logic_id = p_logic_id
                          AND ls.security_id = v_sec.security_id;

                        IF COALESCE(v_side_paused, FALSE) THEN
                            CONTINUE;
                        END IF;

                        v_pos_side := CASE
                            WHEN v_inverted THEN
                                CASE WHEN v_side_name = 'long' THEN 'short' ELSE 'long' END
                            ELSE v_side_name
                        END;

                        v_drawdown := logic_security_side_drawdown_pct(
                            p_logic_id, v_sec.security_id, v_tf_id, FALSE, v_pos_side
                        );
                        IF v_drawdown < v_stop.value THEN
                            CONTINUE;
                        END IF;

                        v_track_before := logic_security_side_track_value(
                            p_logic_id, v_sec.security_id, v_tf_id, FALSE, v_pos_side
                        );
                        v_target := logic_resume_sl_peak_target(
                            p_logic_id, v_track_before, v_hwm
                        );
                        PERFORM logic_trade_log(
                            p_logic_id, 'stop.trigger',
                            format(
                                'SL inversion sec=%s side=%s: РїСЂРѕСЃР°РґРєР° %s%% >= %s%% в†’ shadow',
                                v_sec.security_id, v_side_name,
                                round(v_drawdown, 4), v_stop.value
                            ),
                            jsonb_build_object(
                                'security_id', v_sec.security_id,
                                'position_side', v_side_name,
                                'pos_side', v_pos_side,
                                'drawdown_pct', v_drawdown,
                                'scope', 'security_inversion',
                                'inverted', v_inverted
                            ),
                            v_sec.security_id, v_tf_id
                        );
                        v_closed := logic_close_security_positions_market(
                            p_logic_id, v_sec.security_id, FALSE,
                            CASE
                                WHEN v_inverted THEN
                                    format('stop_loss:security_inversion:inverted:%s', v_side_name)
                                ELSE
                                    format('stop_loss:security_inversion:%s', v_side_name)
                            END,
                            v_pos_side
                        );
                        v_actions := v_actions + v_closed;
                        v_track_after := logic_security_side_track_value(
                            p_logic_id, v_sec.security_id, v_tf_id, FALSE, v_pos_side
                        );
                        PERFORM logic_security_inversion_enter_shadow(
                            p_logic_id, v_sec.security_id, v_tf_id,
                            v_target, v_track_after,
                            format(
                                'SL inversion sec=%s side=%s: Р±РѕР№ СЃС‚РѕСЂРѕРЅС‹ РІС‹РєР»., shadow (peak=%s)',
                                v_sec.security_id, v_side_name, v_target
                            ),
                            v_side_name
                        );
                        IF v_no_reduce THEN
                            IF v_side_name = 'long' THEN
                                UPDATE logic_securities
                                SET stop_resume_hwm_long = v_target
                                WHERE logic_id = p_logic_id AND security_id = v_sec.security_id;
                            ELSE
                                UPDATE logic_securities
                                SET stop_resume_hwm_short = v_target
                                WHERE logic_id = p_logic_id AND security_id = v_sec.security_id;
                            END IF;
                        END IF;
                        v_actions := v_actions + 1;
                    END LOOP;
                END;
                CONTINUE;
            END IF;

            v_drawdown := logic_security_drawdown_pct(
                p_logic_id, v_sec.security_id, v_tf_id, FALSE
            );

            IF v_drawdown < v_stop.value THEN
                CONTINUE;
            END IF;

            IF v_stop.scope_type = 'security' THEN
                PERFORM logic_trade_log(
                    p_logic_id, 'stop.trigger',
                    format(
                        'SL РїРѕ Р±СѓРјР°РіРµ sec=%s: РїСЂРѕСЃР°РґРєР° %s%% >= %s%%',
                        v_sec.security_id, round(v_drawdown, 4), v_stop.value
                    ),
                    jsonb_build_object(
                        'security_id', v_sec.security_id,
                        'drawdown_pct', v_drawdown,
                        'scope', 'security'
                    ),
                    v_sec.security_id, v_tf_id
                );
                v_closed := logic_close_security_positions_market(
                    p_logic_id, v_sec.security_id, FALSE
                );
                v_actions := v_actions + v_closed;
            END IF;
        END LOOP;
    END IF;

    -- Р›РёРЅРµР№РЅС‹Р№ TP РїРѕ РІСЃРµРјСѓ РїРѕСЂС‚С„РµР»СЋ СЃ РІРѕР·РѕР±РЅРѕРІР»РµРЅРёРµРј
    SELECT * INTO v_tp
    FROM logic_stops ls
    WHERE ls.logic_id = p_logic_id
      AND ls.rule_kind = 'take_profit'
      AND ls.scope_type = 'portfolio_ltp_renew'
      AND ls.is_active = TRUE
    ORDER BY ls.display_order, ls.id
    LIMIT 1;

    IF v_tp.id IS NOT NULL AND v_tp.value_unit = 'percent' THEN
        v_actions := v_actions + COALESCE(
            logic_process_linear_tp_portfolio(
                p_logic_id, v_tf_id, v_tp.value, v_closed_bar_dt
            ),
            0
        );
    END IF;

    PERFORM logic_upsert_param(
        p_logic_id, 'last_stop_bar_dt',
        to_char(v_closed_bar_dt, 'YYYY-MM-DD"T"HH24:MI:SS'), 'text'
    );

    RETURN v_actions;
END;
$$;

COMMENT ON FUNCTION process_logic_stops(INTEGER) IS
'РЎС‚РѕРї-Р»РѕСЃСЃС‹ + Р»РёРЅРµР№РЅС‹Р№ TP (portfolio_ltp_renew); TF РёР· stop_loss_timeframe';
-- @end logic_stop_runner

CREATE OR REPLACE FUNCTION process_logic_terminal_signals(p_logic_id INTEGER)
RETURNS INTEGER
LANGUAGE plpgsql AS $$
DECLARE
    v_logic RECORD;
    v_tf_id INTEGER;
    v_tf_sec INTEGER;
    v_closed_bar_dt TIMESTAMP;
    v_last_bar_raw TEXT;
    v_last_bar_dt TIMESTAMP;
    v_grp RECORD;
    v_sec RECORD;
    v_sig RECORD;
    v_pt RECORD;
    v_eval RECORD;
    v_all_ok BOOLEAN;
    v_formulas TEXT;
    v_signal_kind TEXT;
    v_pp NUMERIC;
    v_eff_side TEXT;
    v_inversion BOOLEAN;
    v_created INTEGER := 0;
    v_ids_dedup INTEGER[] := ARRAY[]::INTEGER[];
    v_ind_ids INTEGER[] := ARRAY[]::INTEGER[];
    v_eval_sec INTEGER;
    v_new_id BIGINT;
    -- РџРѕРґСЃС‚Р°РЅРѕРІРєР° РєРѕР»РёС‡РµСЃС‚РІР°/СЃСѓРјРјС‹ РІ Р±Р»РѕРє СЃРґРµР»РѕРє С‚РµСЂРјРёРЅР°Р»Р° (СЂР°СЃС‡С‘С‚ Р»РѕС‚Р° Р»РѕРіРёРєРё).
    -- Р‘Р°Р·Р°/РїСЂРѕС†РµРЅС‚С‹ СЃС‡РёС‚Р°СЋС‚СЃСЏ РћР”РРќ СЂР°Р· РЅР° РІС‹Р·РѕРІ (РґР»СЏ real вЂ” РѕРґРёРЅ Р·Р°РїСЂРѕСЃ T-Bank).
    v_sizing_base NUMERIC := 0;
    v_size_pct NUMERIC := 10;
    v_max_amt NUMERIC := NULL;
    v_base_ready BOOLEAN := FALSE;
    v_lot INTEGER := 1;
    v_sugg_qty INTEGER := 0;
    v_sugg_amount NUMERIC := 0;
    v_confirm_disabled BOOLEAN;      -- #972: РїРѕРІС‚РѕСЂРЅС‹Р№ РїСЂРѕРіРѕРЅ РїСЂРё РїРѕРґС‚РІРµСЂР¶РґРµРЅРёРё С†РµРЅС‹
    v_confirm_sec INTEGER;           -- #972: РЅР°СЃС‚СЂРѕР№РєР° РїРѕРґС‚РІРµСЂР¶РґРµРЅРёСЏ РіСЂСѓРїРїС‹ (СЃРµРє)
    v_group_filter_event TEXT;       -- #972: СЃРѕР·РґР°РІР°С‚СЊ С‚РѕР»СЊРєРѕ РїРѕРґС‚РІРµСЂР¶РґС‘РЅРЅСѓСЋ РіСЂСѓРїРїСѓ
    v_group_filter_side TEXT;
    v_group_filter_sec INTEGER;      -- #990: РїРѕРґС‚РІРµСЂР¶РґРµРЅРёРµ РЅР° СѓСЂРѕРІРЅРµ Р±СѓРјР°РіРё (security_id)
    v_expected_dir TEXT;             -- #972: РЅР°РїСЂР°РІР»РµРЅРёРµ РїРѕРґС‚РІРµСЂР¶РґРµРЅРёСЏ up/down
    v_light_ignore_dedup BOOLEAN;    -- #990: РјРѕР»РЅРёСЏ РїРµСЂРµСЃС‡РёС‚С‹РІР°РµС‚ Р·Р°РєСЂС‹С‚С‹Р№ Р±Р°СЂ РґР°Р¶Рµ РµСЃР»Рё С†РёРєР» СѓР¶Рµ РµРіРѕ РѕР±СЂР°Р±РѕС‚Р°Р»
BEGIN
    SELECT l.id, l.account_id, a.account_type,
           COALESCE(l.use_as_terminal_signal, FALSE) AS use_sig
    INTO v_logic
    FROM logics l
    JOIN accounts a ON a.id = l.account_id
    WHERE l.id = p_logic_id
      AND a.is_active = TRUE;

    IF NOT FOUND OR NOT COALESCE(v_logic.use_sig, FALSE) THEN
        RETURN 0;
    END IF;

    v_tf_id := logic_resolve_timeframe_id(p_logic_id);
    IF v_tf_id IS NULL THEN
        PERFORM logic_trade_log(p_logic_id, 'signal.skip', 'РќРµ Р·Р°РґР°РЅ timeframe РІ logic_params');
        RETURN 0;
    END IF;

    SELECT t.sec INTO v_tf_sec FROM timeframes t WHERE t.id = v_tf_id;
    -- Р‘Р°СЂ РѕР±СЂР°Р±РѕС‚РєРё: app.lightning_bar_dt = РїРѕСЃР»РµРґРЅРёР№ Р—РђРљР Р«РўР«Р™ Р±Р°СЂ РўР¤ РґР»СЏ РјРѕР»РЅРёРё (#990);
    -- СЃРј. comment РІ process_logic_trades.
    v_closed_bar_dt := COALESCE(
        NULLIF(current_setting('app.lightning_bar_dt', TRUE), '')::TIMESTAMP,
        logic_last_closed_bar_dt(v_tf_sec)
    );
    IF v_closed_bar_dt IS NULL THEN
        PERFORM logic_trade_log(p_logic_id, 'signal.skip', 'РќРµ СѓРґР°Р»РѕСЃСЊ РІС‹С‡РёСЃР»РёС‚СЊ Р·Р°РєСЂС‹С‚СѓСЋ СЃРІРµС‡Сѓ TF', NULL, NULL, v_tf_id);
        RETURN 0;
    END IF;

    -- #972: РїРѕРґС‚РІРµСЂР¶РґРµРЅРёРµ С‚РёРїР° СЃРёРіРЅР°Р»Р° (СЃРј. process_logic_trades).
    v_confirm_disabled := COALESCE(NULLIF(current_setting('app.confirm_disabled', TRUE), '')::BOOLEAN, FALSE);
    -- #990: РјРѕР»РЅРёСЏ СЃС‡РёС‚Р°РµС‚ РїРѕСЃР»РµРґРЅРёР№ Р—РђРљР Р«РўР«Р™ Р±Р°СЂ Рё РЅРµ РґРѕР»Р¶РЅР° В«РіР»РѕС…РЅСѓС‚СЊВ» РёР·-Р·Р° РґРµРґСѓРї-РјР°СЂРєРµСЂР°
    -- СѓР¶Рµ РѕР±СЂР°Р±РѕС‚Р°РЅРЅРѕРіРѕ С†РёРєР»Р° Р±Р°СЂР° вЂ” РїРµСЂРµСЃС‡РёС‚С‹РІР°РµС‚ (РґСѓР±Р»Рё РіР°СЃРёС‚ ON CONFLICT).
    v_light_ignore_dedup := COALESCE(NULLIF(current_setting('app.lightning_ignore_dedup', TRUE), '')::BOOLEAN, FALSE);
    v_group_filter_event := lower(NULLIF(current_setting('app.confirm_group_event', TRUE), ''));
    v_group_filter_side := lower(NULLIF(current_setting('app.confirm_group_side', TRUE), ''));
    v_group_filter_sec := NULLIF(current_setting('app.confirm_group_sec', TRUE), '')::INTEGER;
    v_confirm_sec := 0;

    -- РЎРІРѕСЏ РґРµРґСѓРї-СЏРјРєР° СЃРІРµС‡РµР№: СЃРёРіРЅР°Р»С‹ РїСЂРѕРіСЂРµСЃСЃРёСЂСѓСЋС‚ РЅРµР·Р°РІРёСЃРёРјРѕ РѕС‚ С‚РѕСЂРіРѕРІС‹С… last_trade_bar_dt.
    v_last_bar_raw := btrim(COALESCE(get_logic_param_text(p_logic_id, 'terminal_signal_last_bar_dt'), ''));
    IF v_last_bar_raw <> '' THEN
        BEGIN
            v_last_bar_dt := v_last_bar_raw::TIMESTAMP;
            IF v_closed_bar_dt <= v_last_bar_dt AND NOT v_confirm_disabled
               AND NOT v_light_ignore_dedup THEN
                RETURN 0;
            END IF;
        EXCEPTION WHEN OTHERS THEN
            NULL;
        END;
    END IF;

    IF NOT EXISTS (
        SELECT 1 FROM logic_indicator_signals lis
        WHERE lis.logic_id = p_logic_id AND lis.is_active = TRUE
          AND lower(COALESCE(lis.position_event, 'open')) = 'open'
    ) OR NOT EXISTS (
        SELECT 1 FROM logic_securities ls
        WHERE ls.logic_id = p_logic_id AND ls.is_active = TRUE
    ) THEN
        PERFORM logic_upsert_param(p_logic_id, 'terminal_signal_last_bar_dt',
            to_char(v_closed_bar_dt, 'YYYY-MM-DD"T"HH24:MI:SS'), 'text');
        RETURN 0;
    END IF;

    -- Р¦РµРЅС‹ + Р·РЅР°С‡РµРЅРёСЏ РёРЅРґРёРєР°С‚РѕСЂРѕРІ (РєР°Рє РІ process_logic_trades): Р±СѓРјР°РіРё РёР· logic_securities.
    -- Р”РѕРіСЂСѓР¶Р°РµРј РЅРµРґРѕСЃС‚Р°СЋС‰РёРµ closed-СЃРІРµС‡Рё РёРЅРєСЂРµРјРµРЅС‚Р°Р»СЊРЅРѕ, С‡С‚РѕР±С‹ СЃРёРіРЅР°Р»С‹ РїСЂРѕС…РѕРґРёР»Рё Р±РµР·
    -- РѕС‚РєСЂС‹С‚С‹С… РїР°РЅРµР»РµР№ С‚РµСЂРјРёРЅР°Р»Р° Рё Р±РµР· РІРєР»СЋС‡С‘РЅРЅРѕР№ С‚РѕСЂРіРѕРІР»Рё (skip_http РЅРµ РёСЃРїРѕР»СЊР·СѓРµС‚СЃСЏ).
    -- РЇРІРЅР°СЏ 4-Р°СЂРі СЃРёРіРЅР°С‚СѓСЂР° FALSE: Р·Р°С‰РёС‚Р° РѕС‚ СЃС‚Р°СЂС‹С… 3-Р°СЂРі overload'РѕРІ РІ Р¶РёРІРѕР№ Р‘Р”.
    CALL logic_refresh_market_data(p_logic_id, v_tf_id, v_closed_bar_dt, FALSE);

    PERFORM logic_ensure_non_trading_periods(p_logic_id);
    IF logic_skip_signal_by_periods(p_logic_id, v_closed_bar_dt) THEN
        PERFORM logic_trade_log(p_logic_id, 'signal.skip', 'РќРµС‚РѕСЂРіРѕРІС‹Р№ РїРµСЂРёРѕРґ (СЃРёРіРЅР°Р» РІ С‚РµСЂРјРёРЅР°Р» РЅРµ РІС‹РґР°С‘С‚СЃСЏ)', NULL, NULL, v_tf_id);
        PERFORM logic_upsert_param(p_logic_id, 'terminal_signal_last_bar_dt',
            to_char(v_closed_bar_dt, 'YYYY-MM-DD"T"HH24:MI:SS'), 'text');
        RETURN 0;
    END IF;

    v_inversion := get_logic_param_boolean(p_logic_id, 'inversion', FALSE);

    FOR v_sec IN
        SELECT ls.security_id,
               COALESCE(ls.real_trading_inverted, FALSE) AS real_trading_inverted
        FROM logic_securities ls
        WHERE ls.logic_id = p_logic_id AND ls.is_active = TRUE
          AND NOT logic_is_cash_fund_security(ls.security_id)
        ORDER BY ls.display_order NULLS LAST, ls.id
    LOOP
        -- #990: РїРѕРІС‚РѕСЂРЅС‹Р№ РїСЂРѕРіРѕРЅ РїРѕРґС‚РІРµСЂР¶РґС‘РЅРЅРѕР№ РіСЂСѓРїРїС‹ вЂ” С‚РѕР»СЊРєРѕ РґР»СЏ РїРѕРґС‚РІРµСЂР¶РґС‘РЅРЅРѕР№ Р±СѓРјР°РіРё.
        IF v_group_filter_sec IS NOT NULL AND v_sec.security_id <> v_group_filter_sec THEN
            CONTINUE;
        END IF;
        FOR v_grp IN
            SELECT lis.position_event, lis.position_side
            FROM logic_indicator_signals lis
            WHERE lis.logic_id = p_logic_id AND lis.is_active = TRUE
              AND lower(COALESCE(lis.position_event, 'open')) = 'open'
            GROUP BY lis.position_event, lis.position_side
            ORDER BY lis.position_side
        LOOP
            v_all_ok := TRUE;
            v_formulas := NULL;
            v_signal_kind := NULL;
            v_pp := NULL;
            v_ids_dedup := ARRAY[]::INTEGER[];
            v_ind_ids := ARRAY[]::INTEGER[];

            FOR v_sig IN
                SELECT lis.id, lis.position_side, lis.signal_kind, lis.formula, lis.indicator_id
                FROM logic_indicator_signals lis
                WHERE lis.logic_id = p_logic_id
                  AND lis.is_active = TRUE
                  AND lis.position_event = v_grp.position_event
                  AND lis.position_side = v_grp.position_side
                ORDER BY lis.display_order, lis.id
            LOOP
                SELECT * INTO v_pt
                FROM logic_signal_eval_point(v_sig.formula, v_tf_id, v_closed_bar_dt);
                IF v_pt.tf_id IS NULL OR v_pt.bar_dt IS NULL THEN
                    v_all_ok := FALSE;
                    CONTINUE;
                END IF;

                SELECT * INTO v_eval
                FROM logic_signal_evaluate_at(
                    v_sig.id, v_sec.security_id, v_pt.tf_id, v_pt.bar_dt, FALSE
                );

                IF v_eval.close_price IS NULL THEN
                    v_all_ok := FALSE;
                    CONTINUE;
                END IF;

                -- РРЅРґРёРєР°С‚РѕСЂС‹ РѕС‚СЂРёСЃРѕРІРєРё: С‚РѕР»СЊРєРѕ С‚Рµ, С‡С‚Рѕ РѕС†РµРЅРёРІР°СЋС‚СЃСЏ РїРѕ Р­РўРћР™ Р±СѓРјР°РіРµ
                -- (base_asset/contango СЃС‡РёС‚Р°СЋС‚СЃСЏ РїРѕ РґСЂСѓРіРёРј Р±СѓРјР°РіР°Рј вЂ” РёС… РЅР° РіСЂР°С„РёРє РЅРµ С‚СЏРЅРµРј).
                v_eval_sec := logic_signal_eval_security_id(v_sig.id, v_sec.security_id);
                IF v_eval_sec IS NOT NULL AND v_eval_sec = v_sec.security_id THEN
                    IF NOT (v_sig.indicator_id = ANY(v_ids_dedup)) THEN
                        v_ids_dedup := array_append(v_ids_dedup, v_sig.indicator_id);
                        v_ind_ids := array_append(v_ind_ids, v_sig.indicator_id);
                    END IF;
                END IF;

                IF v_signal_kind IS NULL THEN
                    v_signal_kind := v_sig.signal_kind;
                    v_pp := v_eval.close_price;
                END IF;
                v_formulas := CASE
                    WHEN v_formulas IS NULL THEN v_sig.formula
                    ELSE v_formulas || ' AND ' || v_sig.formula
                END;

                IF NOT COALESCE(v_eval.ok, FALSE) THEN
                    v_all_ok := FALSE;
                END IF;
            END LOOP;

            IF NOT v_all_ok OR v_pp IS NULL OR v_formulas IS NULL THEN
                CONTINUE;
            END IF;

            v_eff_side := lower(COALESCE(v_grp.position_side, 'long'));
            IF v_inversion <> v_sec.real_trading_inverted THEN
                v_eff_side := CASE WHEN v_eff_side = 'long' THEN 'short' ELSE 'long' END;
            END IF;

            -- #972: РїРѕРІС‚РѕСЂРЅС‹Р№ РїСЂРѕРіРѕРЅ РїРѕСЃР»Рµ РїРѕРґС‚РІРµСЂР¶РґРµРЅРёСЏ вЂ” СЃРѕР·РґР°С‘Рј С‚РѕР»СЊРєРѕ РїРѕРґС‚РІРµСЂР¶РґС‘РЅРЅСѓСЋ РіСЂСѓРїРїСѓ.
            IF (COALESCE(v_group_filter_event, '') <> '' OR COALESCE(v_group_filter_side, '') <> '')
               AND (v_group_filter_event <> lower(COALESCE(v_grp.position_event, 'open'))
                    OR v_group_filter_side <> lower(COALESCE(v_grp.position_side, 'long'))) THEN
                CONTINUE;
            END IF;
            -- #972: РїРѕРґС‚РІРµСЂР¶РґРµРЅРёРµ С‚РёРїР° СЃРёРіРЅР°Р»Р° (СЃРј. process_logic_trades).
            IF NOT v_confirm_disabled THEN
                SELECT COALESCE(max(lis.signal_confirm_sec), 0)
                INTO v_confirm_sec
                FROM logic_indicator_signals lis
                WHERE lis.logic_id = p_logic_id
                  AND lis.is_active = TRUE
                  AND lis.position_event = v_grp.position_event
                  AND lis.position_side = v_grp.position_side
                  AND lis.signal_confirm_sec > 0;
                IF v_confirm_sec > 0 THEN
                    v_expected_dir := CASE
                        WHEN lower(COALESCE(v_signal_kind, 'trend')) = 'counter'
                            THEN CASE WHEN v_eff_side = 'long' THEN 'up' ELSE 'down' END
                        ELSE CASE WHEN v_eff_side = 'long' THEN 'up' ELSE 'down' END
                    END;
                    INSERT INTO logic_signal_confirm_pending (
                        logic_id, security_id, timeframe_id, bar_dt,
                        position_event, position_side, signal_kind, formula,
                        fire_price, expected_dir, confirm_sec, deadline
                    )
                    VALUES (
                        p_logic_id, v_sec.security_id, v_tf_id, v_closed_bar_dt,
                        v_grp.position_event, v_grp.position_side, v_signal_kind, v_formulas,
                        v_pp, v_expected_dir, v_confirm_sec,
                        CURRENT_TIMESTAMP + make_interval(secs => v_confirm_sec)
                    )
                    ON CONFLICT (logic_id, security_id, timeframe_id, bar_dt, position_event, position_side)
                    DO NOTHING;
                    PERFORM logic_trade_log(
                        p_logic_id,
                        'signal.confirm_wait',
                        format('РЎРёРіРЅР°Р» %s/%s РїСЂРёРґРµСЂР¶Р°РЅ: РїСЂРѕРІРµСЂРєР° РЅР°РїСЂР°РІР»РµРЅРёСЏ С†РµРЅС‹ С‡РµСЂРµР· %s СЃ',
                            v_grp.position_event, v_grp.position_side, v_confirm_sec),
                        jsonb_build_object(
                            'closed_bar', v_closed_bar_dt,
                            'security_id', v_sec.security_id,
                            'fire_price', v_pp,
                            'expected_dir', v_expected_dir
                        ),
                        v_sec.security_id,
                        v_tf_id
                    );
                    CONTINUE;
                END IF;
            END IF;

            -- РљРѕР»РёС‡РµСЃС‚РІРѕ Рє РїРѕРґСЃС‚Р°РЅРѕРІРєРµ РІ С‚РµСЂРјРёРЅР°Р»: С‚Р° Р¶Рµ Р±Р°Р·Р°/%/Р»РѕС‚/РїРѕС‚РѕР»РѕРє, С‡С‚Рѕ Сѓ
            -- Р±РѕРµРІРѕРіРѕ РІС…РѕРґР° (Р»РѕРіРёРєР°_posSizing_base + logic_calc_open_quantity).
            v_sugg_qty := 0;
            v_sugg_amount := 0;
            IF v_pp IS NOT NULL AND v_pp > 0 THEN
                IF NOT v_base_ready THEN
                    v_sizing_base := logic_position_sizing_base(p_logic_id, v_tf_id);
                    -- Р”РµРјРѕ/С„РµР№РєРѕРІС‹Рµ СЃРёРіРЅР°Р»СЊРЅС‹Рµ Р»РѕРіРёРєРё С‡Р°СЃС‚Рѕ Р±РµР· current_balance:
                    -- РїРѕРґСЃС‚Р°РІР»СЏРµРј СЂР°СЃС‡С‘С‚ РёР· С‚РµСЃС‚РѕРІРѕРіРѕ РґРµРїРѕ Р»РѕРіРёРєРё, С‡С‚РѕР±С‹ РєРѕР»РёС‡РµСЃС‚РІРѕ
                    -- Рё СЃСѓРјРјР° РІ Р±Р»РѕРєРµ СЃРґРµР»РѕРє Р·Р°РїРѕР»РЅСЏР»РёСЃСЊ (РѕСЃС‚Р°Р»РѕСЃСЊ РЅР°Р¶Р°С‚СЊ В«РљСѓРїРёС‚СЊ/РџСЂРѕРґР°С‚СЊВ»).
                    IF COALESCE(v_sizing_base, 0) <= 0 THEN
                        v_sizing_base := COALESCE(
                            NULLIF(
                                get_logic_param_numeric(p_logic_id, 'current_balance', NULL), 0
                            ),
                            NULLIF(
                                get_logic_param_numeric(p_logic_id, 'initial_balance', NULL), 0
                            ),
                            NULLIF(
                                get_logic_param_numeric(p_logic_id, 'test_initial_balance', NULL), 0
                            ),
                            0
                        );
                    END IF;
                    v_size_pct := COALESCE(
                        get_logic_param_numeric(p_logic_id, 'position_size_pct', 10), 10
                    );
                    v_max_amt := NULLIF(
                        get_logic_param_numeric(p_logic_id, 'max_order_amount', NULL), 0
                    );
                    v_base_ready := TRUE;
                END IF;
                v_lot := logic_security_lot_size(v_sec.security_id);
                v_sugg_qty := logic_calc_open_quantity(
                    v_sizing_base, v_size_pct, v_pp, v_lot, v_max_amt
                );
                v_sugg_amount := round(v_sugg_qty * v_pp, 2);
            END IF;

            -- #982: Р¶С‘СЃС‚РєР°СЏ РїСЂРѕРІРµСЂРєР° С„Р»Р°РіР° РџР•Р Р•Р” Р·Р°РїРёСЃСЊСЋ. Р¤СѓРЅРєС†РёСЏ РјРѕРіР»Р° РЅР°С‡Р°С‚СЊ
            -- СЂР°Р±РѕС‚Сѓ, РєРѕРіРґР° В«СЃРёРіРЅР°Р» РІ С‚РµСЂРјРёРЅР°Р»В» Р±С‹Р» РІРєР»СЋС‡С‘РЅ, Рё Р·Р°С‚РµРј РІС‹РїРѕР»РЅРёС‚СЊ
            -- РґРѕР»РіСѓСЋ РґРѕРіСЂСѓР·РєСѓ С†РµРЅ (logic_refresh_market_data) Рё СЂР°СЃС‡С‘С‚
            -- РёРЅРґРёРєР°С‚РѕСЂРѕРІ. Р•СЃР»Рё РіР°Р»РѕС‡РєСѓ РІС‹РєР»СЋС‡РёР»Рё РЈР–Р• РІРѕ РІСЂРµРјСЏ РІС‹РїРѕР»РЅРµРЅРёСЏ вЂ”
            -- СЃРёРіРЅР°Р» РЅРµ СЃРѕР·РґР°С‘Рј: РѕС‚РґРµР»СЊРЅС‹Р№ SELECT РІРёРґРёС‚ СЃРІРµР¶РёРµ Р·Р°РєРѕРјРјРёС‡РµРЅРЅС‹Рµ
            -- РґР°РЅРЅС‹Рµ, РїРѕСЌС‚РѕРјСѓ РІС‹РєР»СЋС‡РµРЅРёРµ СЃСЂР°Р±Р°С‚С‹РІР°РµС‚ СЃСЂР°Р·Сѓ, Р° РЅРµ СЃРѕ СЃР»РµРґСѓСЋС‰РµРіРѕ
            -- С†РёРєР»Р°. RETURN вЂ” РїСЂРѕС…РѕРґ С†РµР»РёРєРѕРј РїСЂРµРєСЂР°С‰Р°РµРј.
            IF NOT COALESCE(
                (SELECT l.use_as_terminal_signal FROM logics l WHERE l.id = p_logic_id),
                FALSE
            ) THEN
                RETURN v_created;
            END IF;

            INSERT INTO logic_terminal_signals (
                logic_id, security_id, timeframe_id, bar_dt,
                position_side, signal_kind, formula, price,
                suggested_quantity, suggested_amount, indicator_ids
            )
            VALUES (
                p_logic_id, v_sec.security_id, v_tf_id, v_closed_bar_dt,
                v_eff_side, v_signal_kind, v_formulas, v_pp,
                v_sugg_qty, v_sugg_amount, v_ind_ids
            )
            ON CONFLICT (logic_id, security_id, timeframe_id, bar_dt, position_side) DO NOTHING
            RETURNING id INTO v_new_id;

            IF v_new_id IS NULL THEN
                CONTINUE;
            END IF;

            v_created := v_created + 1;
            PERFORM logic_trade_log(
                p_logic_id,
                'signal.terminal',
                format('РЎРёРіРЅР°Р» РІ С‚РµСЂРјРёРЅР°Р»: sec=%s side=%s', v_sec.security_id, v_eff_side),
                jsonb_build_object(
                    'closed_bar', v_closed_bar_dt,
                    'timeframe_id', v_tf_id,
                    'effective_side', v_eff_side,
                    'signal_kind', v_signal_kind,
                    'formula', v_formulas,
                    'price', v_pp,
                    'suggested_quantity', v_sugg_qty,
                    'suggested_amount', v_sugg_amount,
                    'indicator_ids', v_ind_ids
                ),
                v_sec.security_id,
                v_tf_id
            );
        END LOOP;
    END LOOP;

    -- #972: РїРѕРІС‚РѕСЂРЅС‹Р№ РїСЂРѕРіРѕРЅ РїРѕРґС‚РІРµСЂР¶РґС‘РЅРЅРѕР№ РіСЂСѓРїРїС‹ РЅРµ РґРѕР»Р¶РµРЅ РѕС‚РєР°С‚С‹РІР°С‚СЊ РґРµРґСѓРї-РјР°СЂРєРµСЂ.
    IF NOT v_confirm_disabled THEN
        PERFORM logic_upsert_param(p_logic_id, 'terminal_signal_last_bar_dt',
            to_char(v_closed_bar_dt, 'YYYY-MM-DD"T"HH24:MI:SS'), 'text');
    END IF;

    RETURN v_created;
END;
$$;

COMMENT ON FUNCTION process_logic_terminal_signals(INTEGER) IS
'Open-СЃРёРіРЅР°Р»С‹ Р»РѕРіРёРєРё РґР»СЏ С‚РµСЂРјРёРЅР°Р»Р°: Р·Р°РїРёСЃС‹РІР°РµС‚ logic_terminal_signals (СЃРґРµР»РєРё РќР• РёСЃРїРѕР»РЅСЏРµС‚). '
'РЎС‚РѕСЂРѕРЅР° вЂ” СЌС„С„РµРєС‚РёРІРЅР°СЏ СЃ СѓС‡С‘С‚РѕРј РёРЅРІРµСЂСЃРёР№: long в†’ РїРѕРєСѓРїРєР°, short в†’ РїСЂРѕРґР°Р¶Р°. '
'РџР»СЋСЃ suggested_quantity/suggested_amount вЂ” РєРѕР»РёС‡РµСЃС‚РІРѕ/СЃСѓРјРјР° Рє РїРѕРґСЃС‚Р°РЅРѕРІРєРµ РІ Р±Р»РѕРє СЃРґРµР»РѕРє '
'С‚РµСЂРјРёРЅР°Р»Р° (СЂР°СЃС‡С‘С‚ Р»РѕС‚Р° Р»РѕРіРёРєРё: Р»РѕРіРёРєР°_posSizing_base + logic_calc_open_quantity). '
'Р Р°Р±РѕС‚Р°РµС‚ РїСЂРё use_as_terminal_signal=TRUE РЅРµР·Р°РІРёСЃРёРјРѕ РѕС‚ is_enabled (РІРєР»СЋС‡С‘РЅРЅР°СЏ Р»РѕРіРёРєР° С‚РѕСЂРіСѓРµС‚ РєР°Рє РѕР±С‹С‡РЅРѕ + СЃРёРіРЅР°Р»РёС‚ РІ С‚РµСЂРјРёРЅР°Р»). '
'РќРµРґРѕСЃС‚Р°СЋС‰РёРµ closed-СЃРІРµС‡Рё С†РµРЅ СЃРёРіРЅР°Р»СЊРЅС‹С… Р±СѓРјР°Рі РґРѕРіСЂСѓР¶Р°СЋС‚СЃСЏ РёРЅРєСЂРµРјРµРЅС‚Р°Р»СЊРЅРѕ (1 HTTP С‡РµСЂРµР· prices_topup_date_from), '
'РїРѕСЌС‚РѕРјСѓ СЃРёРіРЅР°Р»С‹ РїСЂРѕС…РѕРґСЏС‚ РґР°Р¶Рµ Р±РµР· РѕС‚РєСЂС‹С‚С‹С… РїР°РЅРµР»РµР№ С‚РµСЂРјРёРЅР°Р»Р° Рё Р±РµР· РІРєР»СЋС‡С‘РЅРЅРѕР№ С‚РѕСЂРіРѕРІР»Рё Р»РѕРіРёРєРё.';

-- ============================================================
-- Р–РёРІР°СЏ С†РµРЅР° T-Bank РґР»СЏ РїРѕРґС‚РІРµСЂР¶РґРµРЅРёР№ (#985)
-- РћРґРёРЅ Р·Р°РїСЂРѕСЃ MarketDataService/GetLastPrices РїРѕ РІСЃРµРј Р±СѓРјР°РіР°Рј СЃСЂР°Р·Сѓ.
-- Р’РѕР·РІСЂР°С‰Р°РµС‚ {"<security_id>": price, ...} РґР»СЏ logic_signal_confirm_finalize;
-- РїСЂРё РѕС€РёР±РєРµ/РЅРµС‚ С‚РѕРєРµРЅР°/РЅРµС‚ pgsql-http в†’ {} (С„РёРЅР°Р»РёР·Р°С‚РѕСЂ РѕС‚РєР°С‚РёС‚СЃСЏ РЅР° СЃРІРµС‡Сѓ).
-- http-С‚РёРїС‹ РЅРµ РѕР±СЉСЏРІР»СЏСЋС‚СЃСЏ РІ DECLARE (РёС… РЅРµС‚ РґРѕ CREATE EXTENSION http) вЂ”
-- РёСЃРїРѕР»СЊР·СѓСЋС‚СЃСЏ РїСЂСЏРјРѕ РІ Р·Р°РїСЂРѕСЃРµ, РєРѕС‚РѕСЂС‹Р№ plpgsql СЂР°Р·Р±РёСЂР°РµС‚ РІ РјРѕРјРµРЅС‚ РІС‹Р·РѕРІР°.
-- ============================================================

CREATE OR REPLACE FUNCTION process_logic_trades(p_logic_id INTEGER)
RETURNS INTEGER
LANGUAGE plpgsql AS $$
DECLARE
    v_logic RECORD;
    v_tf_id INTEGER;
    v_tf_sec INTEGER;
    v_position_size_pct NUMERIC;
    v_max_positions INTEGER;
    v_max_order_amount NUMERIC;
    v_sizing_base NUMERIC;
    v_balance NUMERIC;
    v_open_positions INTEGER;
    v_created INTEGER := 0;
    v_side_open_id INTEGER;
    v_side_close_id INTEGER;
    v_action_long_id INTEGER;
    v_action_short_id INTEGER;
    v_grp RECORD;
    v_sig RECORD;
    v_sec RECORD;
    v_eval RECORD;
    v_pp NUMERIC;
    v_held_long NUMERIC;
    v_held_short NUMERIC;
    v_is_open_event BOOLEAN;
    v_quantity INTEGER;
    v_side_id INTEGER;
    v_action_id INTEGER;
    v_direction TEXT;
    v_is_simulated BOOLEAN;
    v_is_shadow BOOLEAN;
    v_broker_order_id TEXT;
    v_status TEXT;
    v_note TEXT;
    v_trade_id BIGINT;
    v_figi TEXT;
    v_order JSONB;
    v_commission NUMERIC;
    v_notional NUMERIC;
    v_is_open BOOLEAN;
    v_closed_bar_dt TIMESTAMP;
    v_last_bar_raw TEXT;
    v_last_bar_dt TIMESTAMP;
    v_all_ok BOOLEAN;
    v_formulas TEXT;
    v_signal_kind TEXT;
    v_ind_dt TIMESTAMP;
    v_lot_size INTEGER;
    v_is_futures BOOLEAN;
    v_inversion BOOLEAN;
    v_eff_inversion BOOLEAN;
    v_eff_side TEXT;
    v_cycle_budget NUMERIC;       -- Р±Р°Р·Р° % РЅР° РІРµСЃСЊ С†РёРєР» (РЅРµ СЂР°СЃС‚С‘С‚ РѕС‚ short-РєСЌС€Р°)
    v_max_exposure NUMERIC;       -- Р±Р°Р·Р° Г— (%/100) Г— max_open_positions
    v_spent_notional NUMERIC := 0; -- СѓР¶Рµ Р·Р°РЅСЏС‚С‹Р№ РЅРѕРјРёРЅР°Р» Open (СЃС‚Р°СЂС‹Рµ + СЌС‚РѕС‚ РїСЂРѕРіРѕРЅ)
    v_room NUMERIC;
    v_order_notional NUMERIC;
    v_gap_buffer_pct NUMERIC;     -- order_gap_buffer_pct: СЂР°СЃС‡С‘С‚ qty РїРѕ С†РµРЅРµ ppГ—(1+Р±СѓС„РµСЂ)
    v_max_open_gap_pct NUMERIC;   -- max_open_gap_pct: РїСЂРѕРїСѓСЃРє РІС…РѕРґР° РїСЂРё СЂРµР·РєРѕРј РґРІРёР¶РµРЅРёРё
    v_fresh RECORD;               -- СЃРІРµР¶Р°СЏ С†РµРЅР° (СЃС‚РѕРї-РўР¤) РґР»СЏ РіСЌРї-РїСЂРѕРІРµСЂРєРё
    v_q2 INTEGER;                 -- РєРѕР»РёС‡РµСЃС‚РІРѕ РїРѕСЃР»Рµ Р±СѓС„РµСЂР°
    v_up NUMERIC;                 -- С†РµРЅР° РёСЃРїРѕР»РЅРµРЅРёСЏ РёР· РѕС‚РІРµС‚Р°/СЃРѕСЃС‚РѕСЏРЅРёСЏ Р·Р°СЏРІРєРё
    v_state JSONB;                -- GetOrderState (РєРѕРјРёСЃСЃРёСЏ/С†РµРЅР° РёСЃРїРѕР»РЅРµРЅРёСЏ)
    v_c NUMERIC;                  -- РєРѕРјРёСЃСЃРёСЏ РёР· СЃРѕСЃС‚РѕСЏРЅРёСЏ Р·Р°СЏРІРєРё
    v_pt RECORD;                  -- С‚РѕС‡РєР° РѕС†РµРЅРєРё СЃРёРіРЅР°Р»Р° (РµРіРѕ РўР¤ + РІС‹СЂРѕРІРЅРµРЅРЅС‹Р№ Р±Р°СЂ)
    v_tf_list INTEGER[];          -- РІСЃРµ РўР¤ СЃРёРіРЅР°Р»РѕРІ Р»РѕРіРёРєРё (+ Р±Р°Р·РѕРІС‹Р№) РґР»СЏ Р·Р°РіСЂСѓР·РєРё
    v_rtf INTEGER;
    v_rtf_sec INTEGER;
    v_rclosed TIMESTAMP;
    v_confirm_disabled BOOLEAN;      -- #972: РїРѕРІС‚РѕСЂРЅС‹Р№ РїСЂРѕРіРѕРЅ РїСЂРё РїРѕРґС‚РІРµСЂР¶РґРµРЅРёРё С†РµРЅС‹
    v_confirm_sec INTEGER;           -- #972: РЅР°СЃС‚СЂРѕР№РєР° РїРѕРґС‚РІРµСЂР¶РґРµРЅРёСЏ РіСЂСѓРїРїС‹ (СЃРµРє)
    v_group_filter_event TEXT;       -- #972: СЃРѕР·РґР°РІР°С‚СЊ С‚РѕР»СЊРєРѕ РїРѕРґС‚РІРµСЂР¶РґС‘РЅРЅСѓСЋ РіСЂСѓРїРїСѓ
    v_group_filter_side TEXT;
    v_group_filter_sec INTEGER;      -- #990: РїРѕРґС‚РІРµСЂР¶РґРµРЅРёРµ РЅР° СѓСЂРѕРІРЅРµ Р±СѓРјР°РіРё (security_id)
    v_expected_dir TEXT;             -- #972: РЅР°РїСЂР°РІР»РµРЅРёРµ РїРѕРґС‚РІРµСЂР¶РґРµРЅРёСЏ up/down
BEGIN
    SELECT l.id, l.account_id, a.account_type,
           COALESCE(l.portfolio_trading_paused, FALSE) AS portfolio_trading_paused
    INTO v_logic
    FROM logics l
    JOIN accounts a ON a.id = l.account_id
    WHERE l.id = p_logic_id
      AND l.is_enabled = TRUE
      AND a.is_active = TRUE;

    IF NOT FOUND THEN
        PERFORM logic_trade_log(p_logic_id, 'logic.skip', 'Р›РѕРіРёРєР° РІС‹РєР»СЋС‡РµРЅР° РёР»Рё СЃС‡С‘С‚ РЅРµР°РєС‚РёРІРµРЅ');
        RETURN 0;
    END IF;

    v_tf_id := logic_resolve_timeframe_id(p_logic_id);
    IF v_tf_id IS NULL THEN
        PERFORM logic_trade_log(p_logic_id, 'logic.skip', 'РќРµ Р·Р°РґР°РЅ timeframe РІ logic_params');
        RETURN 0;
    END IF;

    SELECT t.sec INTO v_tf_sec FROM timeframes t WHERE t.id = v_tf_id;

    -- Р‘Р°СЂ РѕР±СЂР°Р±РѕС‚РєРё: logic_lightning_run РІС‹СЃС‚Р°РІР»СЏРµС‚ session-РїРµСЂРµРјРµРЅРЅСѓСЋ app.lightning_bar_dt
    -- (local, С‚РѕР»СЊРєРѕ РІ С‚СЂР°РЅР·Р°РєС†РёРё РјРѕР»РЅРёРё) = РїРѕСЃР»РµРґРЅРёР№ Р—РђРљР Р«РўР«Р™ Р±Р°СЂ РўР¤ (#990); РґР»СЏ РѕР±С‹С‡РЅРѕРіРѕ
    -- С†РёРєР»Р° РїРµСЂРµРјРµРЅРЅРѕР№ РЅРµС‚ вЂ” Р±РµСЂС‘Рј РїРѕСЃР»РµРґРЅРёР№ Р·Р°РєСЂС‹С‚С‹Р№ Р±Р°СЂ С‚РµРј Р¶Рµ СЃРїРѕСЃРѕР±РѕРј.
    v_closed_bar_dt := COALESCE(
        NULLIF(current_setting('app.lightning_bar_dt', TRUE), '')::TIMESTAMP,
        logic_last_closed_bar_dt(v_tf_sec)
    );
    IF v_closed_bar_dt IS NULL THEN
        PERFORM logic_trade_log(p_logic_id, 'logic.skip', 'РќРµ СѓРґР°Р»РѕСЃСЊ РІС‹С‡РёСЃР»РёС‚СЊ Р·Р°РєСЂС‹С‚СѓСЋ СЃРІРµС‡Сѓ TF', NULL, NULL, v_tf_id);
        RETURN 0;
    END IF;

    -- #972: РїРѕРґС‚РІРµСЂР¶РґРµРЅРёРµ С‚РёРїР° СЃРёРіРЅР°Р»Р°. РћР±С‹С‡РЅС‹Р№ С†РёРєР» вЂ” СѓРґРµСЂР¶Р°РЅРёРµ СЃСЂР°Р±РѕС‚Р°РІС€РµР№ РіСЂСѓРїРїС‹ РґРѕ РїСЂРѕРІРµСЂРєРё
    -- С†РµРЅС‹. РџРѕРІС‚РѕСЂРЅС‹Р№ РїСЂРѕРіРѕРЅ РїРѕРґС‚РІРµСЂР¶РґС‘РЅРЅРѕР№ РіСЂСѓРїРїС‹ (logic_signal_confirm_finalize) вЂ” session-С„Р»Р°РіРё
    -- app.confirm_disabled / app.confirm_group_{event,side}: СЃРѕР·РґР°С‘С‚СЃСЏ С‚РѕР»СЊРєРѕ РѕРЅР°, РґРµРґСѓРї РѕР±С…РѕРґРёС‚СЃСЏ.
    v_confirm_disabled := COALESCE(NULLIF(current_setting('app.confirm_disabled', TRUE), '')::BOOLEAN, FALSE);
    v_group_filter_event := lower(NULLIF(current_setting('app.confirm_group_event', TRUE), ''));
    v_group_filter_side := lower(NULLIF(current_setting('app.confirm_group_side', TRUE), ''));
    v_group_filter_sec := NULLIF(current_setting('app.confirm_group_sec', TRUE), '')::INTEGER;
    v_confirm_sec := 0;

    v_last_bar_raw := btrim(COALESCE(get_logic_param_text(p_logic_id, 'last_trade_bar_dt'), ''));
    IF v_last_bar_raw <> '' THEN
        BEGIN
            v_last_bar_dt := v_last_bar_raw::TIMESTAMP;
            -- Р•СЃР»Рё Р±Р°СЂ СѓР¶Рµ РѕР±СЂР°Р±РѕС‚Р°РЅ РѕР±С‹С‡РЅС‹Рј С†РёРєР»РѕРј вЂ” РїРѕРІС‚РѕСЂ С‚РѕР»СЊРєРѕ РґР»СЏ РїРѕРґС‚РІРµСЂР¶РґС‘РЅРЅРѕР№ РіСЂСѓРїРїС‹ (#972).
            IF v_closed_bar_dt <= v_last_bar_dt AND NOT v_confirm_disabled THEN
                PERFORM logic_trade_log(
                    p_logic_id,
                    'trade.bar_skip',
                    format('РЎРІРµС‡Р° %s СѓР¶Рµ РѕР±СЂР°Р±РѕС‚Р°РЅР° (last=%s)', v_closed_bar_dt, v_last_bar_dt),
                    jsonb_build_object('closed_bar', v_closed_bar_dt, 'last_bar', v_last_bar_dt),
                    NULL,
                    v_tf_id
                );
                -- Pulse every cycle while waiting for next TF bar (M15 etc.),
                -- so per-logic health is not tied to bar frequency.
                PERFORM logic_upsert_param(
                    p_logic_id,
                    'last_trade_check_at',
                    to_char(CURRENT_TIMESTAMP, 'YYYY-MM-DD"T"HH24:MI:SS'),
                    'text'
                );
                RETURN 0;
            END IF;
        EXCEPTION
            WHEN OTHERS THEN
                NULL;
        END;
    END IF;

    SELECT id INTO v_side_open_id FROM sides WHERE name = 'Open' LIMIT 1;
    SELECT id INTO v_side_close_id FROM sides WHERE name = 'Close' LIMIT 1;
    SELECT id INTO v_action_long_id FROM actions WHERE name = 'Long' LIMIT 1;
    SELECT id INTO v_action_short_id FROM actions WHERE name = 'Short' LIMIT 1;

    IF v_side_open_id IS NULL OR v_side_close_id IS NULL
       OR v_action_long_id IS NULL OR v_action_short_id IS NULL THEN
        RETURN 0;
    END IF;

    v_position_size_pct := get_logic_param_numeric(p_logic_id, 'position_size_pct', 10);
    v_max_positions := GREATEST(1, get_logic_param_numeric(p_logic_id, 'max_open_positions', 10)::INTEGER);
    v_max_order_amount := get_logic_param_numeric(p_logic_id, 'max_order_amount', NULL);
    v_inversion := get_logic_param_boolean(p_logic_id, 'inversion', FALSE);
    v_balance := logic_ensure_balance(p_logic_id);
    v_sizing_base := logic_position_sizing_base(p_logic_id, v_tf_id);
    -- Р—Р°С‰РёС‚Р° РѕС‚ Р·Р°Р№РјР° РїСЂРё СЂРµР·РєРѕРј РґРІРёР¶РµРЅРёРё С†РµРЅС‹ РјРµР¶РґСѓ СЃРёРіРЅР°Р»РѕРј Рё РёСЃРїРѕР»РЅРµРЅРёРµРј:
    -- Р±СѓС„РµСЂ СѓРІРµР»РёС‡РёРІР°РµС‚ СЂР°СЃС‡С‘С‚РЅСѓСЋ С†РµРЅСѓ (qty РјРµРЅСЊС€Рµ), РіСЌРї-РїРѕСЂРѕРі РїСЂРѕРїСѓСЃРєР°РµС‚ РІС…РѕРґ.
    v_gap_buffer_pct := GREATEST(0, COALESCE(get_logic_param_numeric(p_logic_id, 'order_gap_buffer_pct', 0), 0));
    v_max_open_gap_pct := GREATEST(0, COALESCE(get_logic_param_numeric(p_logic_id, 'max_open_gap_pct', 0), 0));
    -- Р‘Р°Р·Р° С†РёРєР»Р° в‰¤ equity: free_cash/cash_amount СЂР°СЃС‚С‘С‚ РѕС‚ short-РІС‹СЂСѓС‡РєРё / Р·Р°Р№РјР°;
    -- mid-cycle freeze alone does not stop that. LEAST(sizing, equity) = РїР»РµС‡Рѕ в‰¤ 1.
    -- РџРѕСЃР»Рµ Close Р±Р°Р·Сѓ РѕР±РЅРѕРІР»СЏРµРј (СЃРІРёС‚С‡: РєСЌС€ +/- РґР»СЏ СЃР»РµРґСѓСЋС‰РµРіРѕ Open).
    v_cycle_budget := logic_exposure_cycle_budget(p_logic_id, v_tf_id);
    -- РџРѕС‚РѕР»РѕРє СЂРёСЃРєР° РёР· С‚РµС… Р¶Рµ 2 РїР°СЂР°РјРµС‚СЂРѕРІ: 10 РїРѕР· Г— 10% = 100% Р±Р°Р·С‹; 20Г—10% = 200%.
    -- Long Рё short СЃС‡РёС‚Р°СЋС‚СЃСЏ РІ РѕРґРЅРѕРј РЅРѕРјРёРЅР°Р»Рµ (С€РѕСЂС‚ РЅРµ РјРѕР¶РµС‚ В«РЅР°Р±СЂР°С‚СЊВ» СЃРІРµСЂС… СЌС‚РѕРіРѕ).
    v_max_exposure := v_cycle_budget
        * (GREATEST(0, COALESCE(v_position_size_pct, 0)) / 100.0)
        * v_max_positions;
    v_spent_notional := logic_open_notional_exposure(p_logic_id, FALSE, '');
    v_open_positions := logic_count_open_positions(p_logic_id);

    IF NOT EXISTS (
        SELECT 1 FROM logic_indicator_signals lis
        WHERE lis.logic_id = p_logic_id AND lis.is_active = TRUE
    ) OR NOT EXISTS (
        SELECT 1 FROM logic_securities ls
        WHERE ls.logic_id = p_logic_id AND ls.is_active = TRUE
    ) THEN
        PERFORM logic_trade_log(p_logic_id, 'logic.skip', 'РќРµС‚ Р°РєС‚РёРІРЅС‹С… СЃРёРіРЅР°Р»РѕРІ РёР»Рё Р±СѓРјР°Рі');
        RETURN 0;
    END IF;

    -- Р—Р°РіСЂСѓР·РєР° С†РµРЅ/СЃРµСЂРёР№ РїРѕ РўР¤ Р»РѕРіРёРєРё Р РїРѕ РІСЃРµРј РўР¤ СЃРёРіРЅР°Р»РѕРІ (tf= РІ С„РѕСЂРјСѓР»Р°С…).
    v_tf_list := ARRAY[v_tf_id] || COALESCE(
        (SELECT array_agg(x.tf_id ORDER BY x.tf_id)
         FROM logic_signal_extra_tf_ids(p_logic_id, v_tf_id) x),
        ARRAY[]::INTEGER[]
    );
    FOREACH v_rtf IN ARRAY v_tf_list LOOP
        IF v_rtf IS NULL THEN
            CONTINUE;
        END IF;
        IF v_rtf = v_tf_id THEN
            CALL logic_refresh_market_data(p_logic_id, v_rtf, v_closed_bar_dt);
        ELSE
            SELECT t.sec INTO v_rtf_sec FROM timeframes t WHERE t.id = v_rtf;
            v_rclosed := COALESCE(
                logic_last_closed_bar_dt(v_rtf_sec),
                v_closed_bar_dt
            );
            CALL logic_refresh_market_data(p_logic_id, v_rtf, v_rclosed);
        END IF;
    END LOOP;

    -- Р РµР№С‚РёРЅРі СЃРёРіРЅР°Р»Р° РЅР° Р»РѕРіРёРєРµ: РїСЂРѕРІРµСЂРёС‚СЊ РїСЂРѕС€Р»С‹Рµ СЃСЂР°Р±Р°С‚С‹РІР°РЅРёСЏ РЅР° СЃР»РµРґСѓСЋС‰РµР№ СЃРІРµС‡Рµ
    PERFORM logic_signal_rating_resolve_pending(p_logic_id, v_tf_id, v_closed_bar_dt);

    PERFORM logic_ensure_non_trading_periods(p_logic_id);

    -- EOD-СЃРµСЃСЃРёСЏ: close_positions_eod Рё/РёР»Рё РїСЂРѕРґР°Р¶Р° С„СЊСЋС‡РµСЂСЃРѕРІ РґРѕ СЌРєСЃРїРёСЂР°С†РёРё
    IF logic_is_eod_session_bar(
        p_logic_id,
        v_closed_bar_dt,
        v_last_bar_dt,
        v_closed_bar_dt + make_interval(secs => v_tf_sec)
    ) THEN
        IF get_logic_param_boolean(p_logic_id, 'close_positions_eod', FALSE) THEN
            PERFORM logic_close_positions_eod_except_funds(p_logic_id);
        END IF;
        PERFORM logic_close_futures_near_expiry(p_logic_id, v_closed_bar_dt::DATE);
        v_balance := logic_ensure_balance(p_logic_id);
        v_sizing_base := logic_position_sizing_base(p_logic_id, v_tf_id);
        v_cycle_budget := logic_exposure_cycle_budget(p_logic_id, v_tf_id);
        v_max_exposure := v_cycle_budget
            * (GREATEST(0, COALESCE(v_position_size_pct, 0)) / 100.0)
            * v_max_positions;
        v_spent_notional := logic_open_notional_exposure(p_logic_id, FALSE, '');
        v_open_positions := logic_count_open_positions(p_logic_id);
    END IF;

    IF logic_skip_signal_by_periods(p_logic_id, v_closed_bar_dt) THEN
        PERFORM logic_trade_log(
            p_logic_id,
            'trade.non_trading_skip',
            format('РќРµС‚РѕСЂРіРѕРІС‹Р№ РїРµСЂРёРѕРґ: СЃРІРµС‡Р° %s вЂ” СЃРёРіРЅР°Р»С‹ РїСЂРѕРїСѓС‰РµРЅС‹', v_closed_bar_dt),
            jsonb_build_object('closed_bar', v_closed_bar_dt),
            NULL,
            v_tf_id
        );
        PERFORM logic_upsert_param(
            p_logic_id,
            'last_trade_check_at',
            to_char(CURRENT_TIMESTAMP, 'YYYY-MM-DD"T"HH24:MI:SS'),
            'text'
        );
        PERFORM logic_upsert_param(
            p_logic_id,
            'last_trade_bar_dt',
            to_char(v_closed_bar_dt, 'YYYY-MM-DD"T"HH24:MI:SS'),
            'text'
        );
        RETURN 0;
    END IF;

    PERFORM logic_trade_log(
        p_logic_id,
        'trade.bar_check',
        format('РџСЂРѕРІРµСЂРєР° AND-СЃРёРіРЅР°Р»РѕРІ РЅР° Р·Р°РєСЂС‹С‚РѕР№ СЃРІРµС‡Рµ %s', v_closed_bar_dt),
        jsonb_build_object('closed_bar', v_closed_bar_dt, 'timeframe_id', v_tf_id),
        NULL,
        v_tf_id
    );

    -- РџСЂРё РЅРµС…РІР°С‚РєРµ СЃР»РѕС‚РѕРІ вЂ” Р»СѓС‡С€РёР№ PnL; РѕРґРёРЅ GROUP BY, Р±РµР· РєРѕСЂСЂРµР»РёСЂРѕРІР°РЅРЅРѕРіРѕ SUM РЅР° Р±СѓРјР°РіСѓ.
    FOR v_sec IN
        SELECT
            ls.security_id,
            COALESCE(ls.real_trading_paused, FALSE) AS real_trading_paused,
            COALESCE(ls.real_trading_paused_long, FALSE) AS real_trading_paused_long,
            COALESCE(ls.real_trading_paused_short, FALSE) AS real_trading_paused_short,
            COALESCE(ls.real_trading_inverted, FALSE) AS real_trading_inverted
        FROM logic_securities ls
        LEFT JOIN (
            SELECT lt.security_id,
                   COALESCE(SUM(lt.financial_result), 0) AS pnl
            FROM logic_trades lt
            JOIN sides s ON s.id = lt.side_id
            WHERE lt.logic_id = p_logic_id
              AND lt.is_test = FALSE
              AND NOT lt.is_shadow
              AND COALESCE(lt.opt_lane, '') = ''
              AND s.name = 'Close'
              AND lt.status IN ('filled', 'submitted')
            GROUP BY lt.security_id
        ) pnl ON pnl.security_id = ls.security_id
        WHERE ls.logic_id = p_logic_id AND ls.is_active = TRUE
          -- Р”РµРЅРµР¶РЅС‹Р№ С„РѕРЅРґ С‚РѕР»СЊРєРѕ РґР»СЏ РїР°СЂРєРѕРІРєРё РєСЌС€Р°, РЅРµ РґР»СЏ СЃРёРіРЅР°Р»РѕРІ
          AND NOT logic_is_cash_fund_security(ls.security_id)
        ORDER BY COALESCE(pnl.pnl, 0) DESC,
                 ls.display_order NULLS LAST,
                 ls.id
    LOOP
        -- #990: РїРѕРІС‚РѕСЂРЅС‹Р№ РїСЂРѕРіРѕРЅ РїРѕРґС‚РІРµСЂР¶РґС‘РЅРЅРѕР№ РіСЂСѓРїРїС‹ вЂ” С‚РѕР»СЊРєРѕ РґР»СЏ РїРѕРґС‚РІРµСЂР¶РґС‘РЅРЅРѕР№ Р±СѓРјР°РіРё.
        IF v_group_filter_sec IS NOT NULL AND v_sec.security_id <> v_group_filter_sec THEN
            CONTINUE;
        END IF;
        v_lot_size := logic_security_lot_size(v_sec.security_id);
        v_is_futures := logic_security_is_futures(v_sec.security_id);

        FOR v_grp IN
            SELECT lis.position_event, lis.position_side
            FROM logic_indicator_signals lis
            WHERE lis.logic_id = p_logic_id AND lis.is_active = TRUE
            GROUP BY lis.position_event, lis.position_side
            ORDER BY lis.position_event, lis.position_side
        LOOP
            -- Shadow С‚РѕР»СЊРєРѕ РґР»СЏ РїСЂРѕСЃРµРІС€РµР№ СЃС‚РѕСЂРѕРЅС‹; РґСЂСѓРіР°СЏ СЃС‚РѕСЂРѕРЅР° Р±СѓРјР°РіРё РѕСЃС‚Р°С‘С‚СЃСЏ Р±РѕРµРІРѕР№.
            v_is_shadow := COALESCE(v_logic.portfolio_trading_paused, FALSE)
                OR CASE lower(btrim(COALESCE(v_grp.position_side, '')))
                    WHEN 'long' THEN v_sec.real_trading_paused_long
                        OR (v_sec.real_trading_paused
                            AND NOT v_sec.real_trading_paused_long
                            AND NOT v_sec.real_trading_paused_short)
                    WHEN 'short' THEN v_sec.real_trading_paused_short
                        OR (v_sec.real_trading_paused
                            AND NOT v_sec.real_trading_paused_long
                            AND NOT v_sec.real_trading_paused_short)
                    ELSE v_sec.real_trading_paused
                END;
            -- Shadow в†’ zero uses base logic only; paper inverted applies to real book.
            v_eff_inversion := (
                v_inversion <> CASE
                    WHEN v_is_shadow THEN FALSE
                    ELSE COALESCE(v_sec.real_trading_inverted, FALSE)
                END
            );
            v_all_ok := TRUE;
            v_formulas := NULL;
            v_signal_kind := NULL;
            v_pp := NULL;
            v_ind_dt := NULL;

            FOR v_sig IN
                SELECT lis.id, lis.position_event, lis.position_side, lis.signal_kind, lis.formula, lis.indicator_id
                FROM logic_indicator_signals lis
                WHERE lis.logic_id = p_logic_id
                  AND lis.is_active = TRUE
                  AND lis.position_event = v_grp.position_event
                  AND lis.position_side = v_grp.position_side
                ORDER BY lis.display_order, lis.id
            LOOP
                -- РўР¤ СЃРёРіРЅР°Р»Р° (tf= РІ С„РѕСЂРјСѓР»Рµ) Рё РµРіРѕ РїРѕСЃР»РµРґРЅРёР№ Р·Р°РєСЂС‹С‚С‹Р№ Р±Р°СЂ
                -- РґРѕ Р·Р°РєСЂС‹С‚РёСЏ Р±Р°СЂР° Р»РѕРіРёРєРё вЂ” Р±РµР· Р·Р°РіР»СЏРґС‹РІР°РЅРёСЏ РІ Р±СѓРґСѓС‰РµРµ.
                SELECT * INTO v_pt
                FROM logic_signal_eval_point(v_sig.formula, v_tf_id, v_closed_bar_dt);
                IF v_pt.tf_id IS NULL OR v_pt.bar_dt IS NULL THEN
                    v_all_ok := FALSE;
                    PERFORM logic_trade_log(
                        p_logic_id,
                        'trade.not_ready',
                        format('РќРµС‚ РёСЃС‚РѕСЂРёРё РґР»СЏ tf СЃРёРіРЅР°Р»Р°: %s', v_sig.formula),
                        jsonb_build_object('formula', v_sig.formula),
                        v_sec.security_id,
                        v_tf_id
                    );
                    CONTINUE;
                END IF;

                SELECT * INTO v_eval
                FROM logic_signal_evaluate_at(
                    -- Inversion flips sides only (see backtest runner); keep conditions.
                    v_sig.id, v_sec.security_id, v_pt.tf_id, v_pt.bar_dt, FALSE
                );

                IF v_eval.close_price IS NULL THEN
                    v_all_ok := FALSE;
                    PERFORM logic_trade_log(
                        p_logic_id,
                        'trade.not_ready',
                        format(
                            'РќРµС‚ РґР°РЅРЅС‹С… РЅР° СЃРІРµС‡Рµ %s РґР»СЏ security=%s signal=%s',
                            v_closed_bar_dt, v_sec.security_id, v_sig.formula
                        ),
                        jsonb_build_object(
                            'closed_bar', v_closed_bar_dt,
                            'security_id', v_sec.security_id,
                            'formula', v_sig.formula,
                            'position_event', v_grp.position_event,
                            'position_side', v_grp.position_side
                        ),
                        v_sec.security_id,
                        v_tf_id
                    );
                    CONTINUE;
                END IF;

                IF v_signal_kind IS NULL THEN
                    v_signal_kind := v_sig.signal_kind;
                    v_pp := v_eval.close_price;
                    v_ind_dt := v_eval.bar_dt;
                END IF;
                v_formulas := CASE
                    WHEN v_formulas IS NULL THEN v_sig.formula
                    ELSE v_formulas || ' AND ' || v_sig.formula
                END;

                IF COALESCE(v_eval.ok, FALSE) THEN
                    PERFORM logic_signal_record_fire(
                        v_sig.id, p_logic_id, v_sec.security_id, v_tf_id,
                        v_eval.bar_dt, v_eval.close_price,
                        v_sig.position_side, v_sig.signal_kind
                    );
                    PERFORM logic_trade_log(
                        p_logic_id,
                        'trade.signal_hit',
                        format(
                            'РЎРёРіРЅР°Р» %s/%s/%s: %s',
                            v_sig.position_event, v_sig.position_side, v_sig.signal_kind, v_sig.formula
                        ),
                        jsonb_build_object(
                            'formula', v_sig.formula,
                            'position_event', v_sig.position_event,
                            'pp', v_eval.close_price,
                            'ind_value', v_eval.ind_value,
                            'bar_dt', v_eval.bar_dt
                        ),
                        v_sec.security_id,
                        v_tf_id
                    );
                ELSE
                    v_all_ok := FALSE;
                    PERFORM logic_trade_log(
                        p_logic_id,
                        'trade.signal_skip',
                        format(
                            'РЈСЃР»РѕРІРёРµ РЅРµ РІС‹РїРѕР»РЅРµРЅРѕ: %s (pp=%s, value=%s)',
                            v_sig.formula, v_eval.close_price, v_eval.ind_value
                        ),
                        jsonb_build_object(
                            'formula', v_sig.formula,
                            'position_event', v_sig.position_event,
                            'signal_kind', v_sig.signal_kind,
                            'position_side', v_sig.position_side,
                            'pp', v_eval.close_price,
                            'ind_value', v_eval.ind_value,
                            'bar_dt', v_eval.bar_dt
                        ),
                        v_sec.security_id,
                        v_tf_id
                    );
                END IF;
            END LOOP;

            IF NOT v_all_ok OR v_pp IS NULL OR v_formulas IS NULL THEN
                CONTINUE;
            END IF;

            v_eff_side := lower(COALESCE(v_grp.position_side, 'long'));
            IF v_eff_inversion THEN
                v_eff_side := CASE WHEN v_eff_side = 'long' THEN 'short' ELSE 'long' END;
            END IF;

            -- #972: РїРѕРІС‚РѕСЂРЅС‹Р№ РїСЂРѕРіРѕРЅ РїРѕСЃР»Рµ РїРѕРґС‚РІРµСЂР¶РґРµРЅРёСЏ вЂ” СЃРѕР·РґР°С‘Рј С‚РѕР»СЊРєРѕ РїРѕРґС‚РІРµСЂР¶РґС‘РЅРЅСѓСЋ РіСЂСѓРїРїСѓ.
            IF (COALESCE(v_group_filter_event, '') <> '' OR COALESCE(v_group_filter_side, '') <> '')
               AND (v_group_filter_event <> lower(COALESCE(v_grp.position_event, 'open'))
                    OR v_group_filter_side <> lower(COALESCE(v_grp.position_side, 'long'))) THEN
                CONTINUE;
            END IF;
            -- #972: РїРѕРґС‚РІРµСЂР¶РґРµРЅРёРµ С‚РёРїР° СЃРёРіРЅР°Р»Р°. Р’СЃРµ Р°РєС‚РёРІРЅС‹Рµ СЃРёРіРЅР°Р»С‹ РіСЂСѓРїРїС‹ СЃСЂР°Р±РѕС‚Р°Р»Рё (AND), РЅРѕ
            -- Сѓ РѕРґРЅРѕРіРѕ РёР· РЅРёС… РІРєР»СЋС‡РµРЅРѕ РїРѕРґС‚РІРµСЂР¶РґРµРЅРёРµ вЂ” РІС…РѕРґ РїСЂРёРґРµСЂР¶РёРІР°РµС‚СЃСЏ РЅР° N СЃРµРєСѓРЅРґ: СЃРѕР·РґР°С‘С‚СЃСЏ
            -- Р·Р°РїРёСЃСЊ logic_signal_confirm_pending, РїРѕСЃР»Рµ deadline С„РёРЅР°Р»РёР·Р°С‚РѕСЂ СЃРІРµСЂСЏРµС‚ С†РµРЅСѓ Рё Р»РёС€СЊ
            -- РїСЂРё РїРѕРґС‚РІРµСЂР¶РґРµРЅРёРё РЅР°РїСЂР°РІР»РµРЅРёСЏ РїРѕРІС‚РѕСЂРЅРѕ РїСЂРѕРіРѕРЅСЏРµС‚ СЌС‚Сѓ РіСЂСѓРїРїСѓ РЅР° Р±Р°СЂРµ bar_dt.
            IF NOT v_confirm_disabled THEN
                SELECT COALESCE(max(lis.signal_confirm_sec), 0)
                INTO v_confirm_sec
                FROM logic_indicator_signals lis
                WHERE lis.logic_id = p_logic_id
                  AND lis.is_active = TRUE
                  AND lis.position_event = v_grp.position_event
                  AND lis.position_side = v_grp.position_side
                  AND lis.signal_confirm_sec > 0;
                IF v_confirm_sec > 0 THEN
                    v_expected_dir := CASE
                        WHEN lower(COALESCE(v_signal_kind, 'trend')) = 'counter'
                            THEN CASE WHEN v_eff_side = 'long' THEN 'up' ELSE 'down' END
                        ELSE CASE WHEN v_eff_side = 'long' THEN 'up' ELSE 'down' END
                    END;
                    INSERT INTO logic_signal_confirm_pending (
                        logic_id, security_id, timeframe_id, bar_dt,
                        position_event, position_side, signal_kind, formula,
                        fire_price, expected_dir, confirm_sec, deadline
                    )
                    VALUES (
                        p_logic_id, v_sec.security_id, v_tf_id, v_closed_bar_dt,
                        v_grp.position_event, v_grp.position_side, v_signal_kind, v_formulas,
                        v_pp, v_expected_dir, v_confirm_sec,
                        CURRENT_TIMESTAMP + make_interval(secs => v_confirm_sec)
                    )
                    ON CONFLICT (logic_id, security_id, timeframe_id, bar_dt, position_event, position_side)
                    DO NOTHING;
                    PERFORM logic_trade_log(
                        p_logic_id,
                        'trade.confirm_wait',
                        format('РЎРёРіРЅР°Р» %s/%s РїСЂРёРґРµСЂР¶Р°РЅ: РїСЂРѕРІРµСЂРєР° РЅР°РїСЂР°РІР»РµРЅРёСЏ С†РµРЅС‹ С‡РµСЂРµР· %s СЃ',
                            v_grp.position_event, v_grp.position_side, v_confirm_sec),
                        jsonb_build_object(
                            'closed_bar', v_closed_bar_dt,
                            'security_id', v_sec.security_id,
                            'fire_price', v_pp,
                            'expected_dir', v_expected_dir
                        ),
                        v_sec.security_id,
                        v_tf_id
                    );
                    CONTINUE;
                END IF;
            END IF;

            v_held_long := CASE
                WHEN v_eff_side = 'long'
                THEN logic_long_position_qty(p_logic_id, v_sec.security_id, v_is_shadow)
                ELSE 0
            END;
            v_held_short := CASE
                WHEN v_eff_side = 'short'
                THEN logic_short_position_qty(p_logic_id, v_sec.security_id, v_is_shadow)
                ELSE 0
            END;
            v_is_open_event := COALESCE(v_grp.position_event, 'open') = 'open';

                IF v_eff_side = 'long' THEN
                IF v_is_open_event THEN
                    IF v_held_long > 0 OR (NOT v_is_shadow AND v_open_positions >= v_max_positions) THEN
                        CONTINUE;
                    END IF;
                    -- Р“СЌРї-С„РёР»СЊС‚СЂ РІС…РѕРґР°: СЃРІРµР¶Р°СЏ С†РµРЅР° СѓС€Р»Р° РѕС‚ С†РµРЅС‹ СЃРёРіРЅР°Р»Р° Р±РѕР»СЊС€Рµ РїРѕСЂРѕРіР° вЂ” РїСЂРѕРїСѓСЃРє.
                    IF NOT v_is_shadow AND v_max_open_gap_pct > 0 THEN
                        SELECT * INTO v_fresh FROM logic_fresh_order_price(p_logic_id, v_sec.security_id, v_tf_id);
                        IF v_fresh.price IS NOT NULL AND v_fresh.bar_dt IS NOT NULL
                           AND v_fresh.bar_dt >= v_closed_bar_dt AND COALESCE(v_pp, 0) > 0
                           AND ABS(v_fresh.price - v_pp) / v_pp * 100.0 > v_max_open_gap_pct THEN
                            PERFORM logic_trade_log(
                                p_logic_id,
                                'trade.gap_skip',
                                format(
                                    'Р“СЌРї %s%% > %s%%: С†РµРЅР° СЃРёРіРЅР°Р»Р° %s в†’ СЂС‹РЅРѕРє %s вЂ” РІС…РѕРґ РїСЂРѕРїСѓС‰РµРЅ',
                                    round(ABS(v_fresh.price - v_pp) / v_pp * 100.0, 2),
                                    v_max_open_gap_pct, v_pp, v_fresh.price
                                ),
                                jsonb_build_object(
                                    'security_id', v_sec.security_id,
                                    'pp', v_pp,
                                    'fresh_price', v_fresh.price,
                                    'fresh_bar_dt', v_fresh.bar_dt,
                                    'max_open_gap_pct', v_max_open_gap_pct
                                ),
                                v_sec.security_id,
                                v_tf_id
                            );
                            CONTINUE;
                        END IF;
                    END IF;
                    -- РћСЃС‚Р°С‚РѕРє РїРѕРґ РїРѕС‚РѕР»РєРѕРј %Г—РјР°РєСЃ.РїРѕР·РёС†РёР№ (РЅРµ РІРµСЃСЊ Р±Р°Р»Р°РЅСЃ С†РµР»РёРєРѕРј).
                    v_room := GREATEST(0, v_max_exposure - v_spent_notional);
                    IF v_max_order_amount IS NOT NULL AND v_max_order_amount > 0 THEN
                        v_room := LEAST(v_room, v_max_order_amount);
                    END IF;
                    v_quantity := logic_calc_open_quantity(
                        v_cycle_budget, v_position_size_pct, v_pp, v_lot_size, v_room
                    );
                    -- Р‘СѓС„РµСЂ С†РµРЅС‹ РёСЃРїРѕР»РЅРµРЅРёСЏ: qty РїРѕ С…СѓРґС€РµР№ С†РµРЅРµ ppГ—(1+Р±СѓС„РµСЂ) вЂ” РјРµРЅСЊС€Рµ С€Р°РЅСЃ Р·Р°Р№РјР°.
                    IF v_quantity >= v_lot_size AND v_gap_buffer_pct > 0 THEN
                        v_q2 := logic_calc_open_quantity(
                            v_cycle_budget, v_position_size_pct,
                            v_pp * (1.0 + v_gap_buffer_pct / 100.0), v_lot_size, v_room
                        );
                        IF v_q2 < v_quantity THEN
                            v_quantity := v_q2;
                        END IF;
                    END IF;
                    IF v_quantity < v_lot_size THEN
                        -- Р¤СЊСЋС‡РµСЂСЃС‹: % РґРµРїРѕР·РёС‚Р° / С†РµРЅР° РєРѕРЅС‚СЂР°РєС‚Р° С‡Р°СЃС‚Рѕ РґР°С‘С‚ 0 в†’ 1 Р»РѕС‚
                        -- (С‚РѕР»СЊРєРѕ РїСЂРё РёР·РІРµСЃС‚РЅРѕР№ Р±Р°Р·Рµ; Р°РєС†РёРё вЂ” Р±РµР· force 1 Р»РѕС‚)
                        IF v_is_futures AND v_cycle_budget IS NOT NULL AND v_cycle_budget > 0
                           AND v_lot_size * v_pp <= v_room THEN
                            v_quantity := v_lot_size;
                        ELSE
                            CONTINUE;
                        END IF;
                    END IF;
                    v_order_notional := v_quantity * v_pp;
                    IF v_order_notional > v_room + 0.000001 THEN
                        CONTINUE;
                    END IF;
                    v_side_id := v_side_open_id;
                    v_action_id := v_action_long_id;
                    v_direction := 'BUY';
                ELSE
                    IF v_held_long <= 0 THEN
                        CONTINUE;
                    END IF;
                    v_quantity := v_held_long::INTEGER;
                    v_side_id := v_side_close_id;
                    v_action_id := v_action_long_id;
                    v_direction := 'SELL';
                END IF;
            ELSIF v_is_open_event THEN
                IF v_held_short > 0 OR (NOT v_is_shadow AND v_open_positions >= v_max_positions) THEN
                    CONTINUE;
                END IF;
                -- Р“СЌРї-С„РёР»СЊС‚СЂ РІС…РѕРґР° (С€РѕСЂС‚): СЃРІРµР¶Р°СЏ С†РµРЅР° СѓС€Р»Р° РѕС‚ С†РµРЅС‹ СЃРёРіРЅР°Р»Р° Р±РѕР»СЊС€Рµ РїРѕСЂРѕРіР° вЂ” РїСЂРѕРїСѓСЃРє.
                IF NOT v_is_shadow AND v_max_open_gap_pct > 0 THEN
                    SELECT * INTO v_fresh FROM logic_fresh_order_price(p_logic_id, v_sec.security_id, v_tf_id);
                    IF v_fresh.price IS NOT NULL AND v_fresh.bar_dt IS NOT NULL
                       AND v_fresh.bar_dt >= v_closed_bar_dt AND COALESCE(v_pp, 0) > 0
                       AND ABS(v_fresh.price - v_pp) / v_pp * 100.0 > v_max_open_gap_pct THEN
                        PERFORM logic_trade_log(
                            p_logic_id,
                            'trade.gap_skip',
                            format(
                                'Р“СЌРї %s%% > %s%%: С†РµРЅР° СЃРёРіРЅР°Р»Р° %s в†’ СЂС‹РЅРѕРє %s вЂ” РІС…РѕРґ РїСЂРѕРїСѓС‰РµРЅ',
                                round(ABS(v_fresh.price - v_pp) / v_pp * 100.0, 2),
                                v_max_open_gap_pct, v_pp, v_fresh.price
                            ),
                            jsonb_build_object(
                                'security_id', v_sec.security_id,
                                'pp', v_pp,
                                'fresh_price', v_fresh.price,
                                'fresh_bar_dt', v_fresh.bar_dt,
                                'max_open_gap_pct', v_max_open_gap_pct
                            ),
                            v_sec.security_id,
                            v_tf_id
                        );
                        CONTINUE;
                    END IF;
                END IF;
                -- Short: С‚РѕС‚ Р¶Рµ РїРѕС‚РѕР»РѕРє, С‡С‚Рѕ Рё long (10Г—10% = 100% Р±Р°Р·С‹ Рё С‚.Рґ.).
                v_room := GREATEST(0, v_max_exposure - v_spent_notional);
                IF v_max_order_amount IS NOT NULL AND v_max_order_amount > 0 THEN
                    v_room := LEAST(v_room, v_max_order_amount);
                END IF;
                v_quantity := logic_calc_open_quantity(
                    v_cycle_budget, v_position_size_pct, v_pp, v_lot_size, v_room
                );
                -- Р‘СѓС„РµСЂ С†РµРЅС‹ РёСЃРїРѕР»РЅРµРЅРёСЏ (С€РѕСЂС‚): qty РїРѕ С†РµРЅРµ ppГ—(1+Р±СѓС„РµСЂ) вЂ” РЅРѕРјРёРЅР°Р» РїРѕРґ РєРѕРЅС‚СЂРѕР»РµРј.
                IF v_quantity >= v_lot_size AND v_gap_buffer_pct > 0 THEN
                    v_q2 := logic_calc_open_quantity(
                        v_cycle_budget, v_position_size_pct,
                        v_pp * (1.0 + v_gap_buffer_pct / 100.0), v_lot_size, v_room
                    );
                    IF v_q2 < v_quantity THEN
                        v_quantity := v_q2;
                    END IF;
                END IF;
                IF v_quantity < v_lot_size THEN
                    IF v_is_futures AND v_cycle_budget IS NOT NULL AND v_cycle_budget > 0
                       AND v_lot_size * v_pp <= v_room THEN
                        v_quantity := v_lot_size;
                    ELSE
                        CONTINUE;
                    END IF;
                END IF;
                v_order_notional := v_quantity * v_pp;
                IF v_order_notional > v_room + 0.000001 THEN
                    CONTINUE;
                END IF;
                v_side_id := v_side_open_id;
                v_action_id := v_action_short_id;
                v_direction := 'SELL';
            ELSE
                IF v_held_short <= 0 THEN
                    CONTINUE;
                END IF;
                v_quantity := v_held_short::INTEGER;
                v_side_id := v_side_close_id;
                v_action_id := v_action_short_id;
                v_direction := 'BUY';
            END IF;

            v_is_simulated := v_logic.account_type = 'fake';
            v_broker_order_id := NULL;
            v_status := 'filled';
            v_note := NULL;
            v_commission := 0;

            -- Shadow (pause/resume track): paper only вЂ” never PostOrder to broker.
            IF v_logic.account_type <> 'fake' AND NOT v_is_shadow THEN
                v_is_simulated := FALSE;
                BEGIN
                    SELECT sp.tbank_figi INTO v_figi
                    FROM security_prefixes sp
                    WHERE sp.security_id = v_sec.security_id
                      AND sp.tbank_figi IS NOT NULL
                    ORDER BY sp.exchange_id
                    LIMIT 1;

                    IF v_figi IS NULL THEN
                        v_status := 'rejected';
                        v_note := 'РќРµС‚ tbank_figi РґР»СЏ Р±СѓРјР°РіРё';
                    ELSE
                        -- РџР°СѓР·Р° РјРµР¶РґСѓ СЂРµР°Р»СЊРЅС‹РјРё Р·Р°СЏРІРєР°РјРё: Р±РµР· РЅРµС‘ РїР°С‡РєР° СЃРёРіРЅР°Р»РѕРІ
                        -- СѓРїРёСЂР°РµС‚СЃСЏ РІ Р»РёРјРёС‚С‹ T-Bank API (HTTP 429) Рё РѕС‚РєР»РѕРЅСЏРµС‚СЃСЏ.
                        PERFORM pg_sleep(0.30);
                        v_order := tbank_post_order(
                            v_logic.account_id, v_figi, v_quantity, v_pp, v_direction,
                            logic_order_execution(p_logic_id)
                        );
                        v_broker_order_id := COALESCE(
                            v_order->>'orderId',
                            v_order->>'order_id',
                            v_order->'orderState'->>'orderId'
                        );
                        v_status := tbank_trade_status_from_post_order(v_order);
                        -- РўРѕС‡РЅР°СЏ С†РµРЅР° РёСЃРїРѕР»РЅРµРЅРёСЏ РІР°Р¶РЅР° РґР»СЏ РїРѕС‚РѕР»РєР° exposure:
                        -- РµСЃР»Рё PostOrder РЅРµ РґР°Р» С†РµРЅСѓ/РєРѕРјРёСЃСЃРёСЋ вЂ” РґРѕР±РёСЂР°РµРј РёР· GetOrderState.
                        v_c := tbank_order_commission(v_order);
                        IF v_c > 0 THEN
                            v_commission := v_c;
                        END IF;
                        v_up := tbank_order_unit_price(v_order);
                        IF (v_commission <= 0 OR v_up IS NULL) AND v_broker_order_id IS NOT NULL THEN
                            BEGIN
                                v_state := tbank_get_order_state(
                                    v_logic.account_id, v_broker_order_id
                                );
                                v_c := tbank_order_commission(v_state);
                                IF v_c > 0 THEN
                                    v_commission := v_c;
                                END IF;
                                v_status := COALESCE(
                                    NULLIF(tbank_trade_status_from_post_order(v_state), 'rejected'),
                                    v_status
                                );
                                IF v_up IS NULL THEN
                                    v_up := tbank_order_unit_price(v_state);
                                END IF;
                            EXCEPTION
                                WHEN OTHERS THEN
                                    NULL;
                            END;
                        END IF;
                        IF v_up IS NOT NULL AND v_up > 0 THEN
                            v_pp := v_up;
                        END IF;
                        IF v_status = 'rejected' THEN
                            v_note := v_order::TEXT;
                        END IF;
                    END IF;
                EXCEPTION
                    WHEN undefined_function THEN
                        v_status := 'rejected';
                        v_note := 'tbank_post_order РЅРµРґРѕСЃС‚СѓРїРµРЅ (РЅРµС‚ HTTP-СЂР°СЃС€РёСЂРµРЅРёСЏ)';
                    WHEN OTHERS THEN
                        v_status := 'rejected';
                        v_note := SQLERRM;
                END;
            END IF;

            INSERT INTO logic_trades (
                logic_id, account_id, security_id, timeframe_id,
                side_id, action_id, position_event, signal_kind, signal_formula,
                quantity, price, commission, bar_dt, is_simulated, is_fictitious, is_shadow, is_test,
                opt_lane, broker_order_id, status, note
            )
            VALUES (
                p_logic_id, v_logic.account_id, v_sec.security_id, v_tf_id,
                v_side_id, v_action_id, v_grp.position_event, v_signal_kind, v_formulas,
                -- bar_dt СЃРґРµР»РєРё = Р±Р°СЂ РўР¤ Р»РѕРіРёРєРё (СЃС‚Р°Р±РёР»СЊРЅР°СЏ РёРґРµРјРїРѕС‚РµРЅС‚РЅРѕСЃС‚СЊ,
                -- РґР°Р¶Рµ РµСЃР»Рё С‡Р»РµРЅС‹ AND-РіСЂСѓРїРїС‹ РЅР° СЂР°Р·РЅС‹С… tf=)
                v_quantity, v_pp, COALESCE(v_commission, 0), v_closed_bar_dt, v_is_simulated, FALSE, v_is_shadow, FALSE,
                '', v_broker_order_id, v_status, v_note
            )
            ON CONFLICT (logic_id, security_id, position_event, action_id, bar_dt, is_test, is_shadow, opt_lane) DO NOTHING
            RETURNING id INTO v_trade_id;

            IF v_trade_id IS NULL THEN
                CONTINUE;
            END IF;

            v_created := v_created + 1;

            -- Р‘СЋРґР¶РµС‚ С†РёРєР»Р°: СѓС‡РёС‚С‹РІР°РµРј РЅРѕРјРёРЅР°Р» Р±РѕРµРІРѕРіРѕ Open (РІ С‚.С‡. short вЂ” РёРЅР°С‡Рµ РјР°СЂР¶Р° РЅР°СЂР°СЃС‚Р°РµС‚)
            IF NOT v_is_shadow
               AND v_is_open_event
               AND v_status <> 'rejected'
               AND v_quantity IS NOT NULL
               AND v_pp IS NOT NULL THEN
                v_spent_notional := v_spent_notional + (v_quantity * v_pp);
            END IF;

            IF NOT v_is_shadow AND v_logic.account_type = 'fake' AND v_balance IS NOT NULL AND v_status <> 'rejected' THEN
                v_balance := logic_trade_finalize(v_trade_id, v_balance);
                v_notional := v_quantity * v_pp;
                v_is_open := v_is_open_event;
                IF v_eff_side = 'long' THEN
                    v_balance := v_balance + CASE WHEN v_is_open THEN -v_notional ELSE v_notional END;
                ELSE
                    v_balance := v_balance + CASE WHEN v_is_open THEN v_notional ELSE -v_notional END;
                END IF;
                IF v_is_open AND NOT v_is_shadow THEN
                    v_open_positions := v_open_positions + 1;
                ELSIF NOT v_is_open AND NOT v_is_shadow THEN
                    v_open_positions := GREATEST(0, v_open_positions - 1);
                END IF;
                v_balance := logic_cash_set_param(p_logic_id, v_balance);
            ELSIF NOT v_is_shadow THEN
                PERFORM logic_trade_finalize(v_trade_id, v_balance);
                -- Real: РїРµСЂРµС‡РёС‚Р°С‚СЊ РѕСЃС‚Р°С‚РѕРє СЃ Р±СЂРѕРєРµСЂР° (РЅРµ paper В± notional Рє РјРёР»Р»РёРѕРЅСѓ)
                IF v_logic.account_type <> 'fake' THEN
                    v_balance := logic_ensure_balance(p_logic_id);
                END IF;
                IF v_is_open_event AND v_status <> 'rejected' THEN
                    v_open_positions := v_open_positions + 1;
                ELSIF NOT v_is_open_event AND v_status <> 'rejected' THEN
                    v_open_positions := GREATEST(0, v_open_positions - 1);
                END IF;
            ELSE
                PERFORM logic_trade_finalize(v_trade_id, NULL);
            END IF;

            -- Switch same bar: after Close free exposure + refresh % base (cash in/out).
            -- Never refresh after Open вЂ” short proceeds must not inflate the cycle base.
            IF NOT v_is_shadow
               AND NOT v_is_open_event
               AND v_status <> 'rejected' THEN
                v_spent_notional := logic_open_notional_exposure(p_logic_id, FALSE, '');
                v_sizing_base := logic_position_sizing_base(p_logic_id, v_tf_id);
                v_cycle_budget := logic_exposure_cycle_budget(p_logic_id, v_tf_id);
                v_max_exposure := v_cycle_budget
                    * (GREATEST(0, COALESCE(v_position_size_pct, 0)) / 100.0)
                    * v_max_positions;
            END IF;

            PERFORM logic_trade_log(
                p_logic_id,
                'trade.created',
                format('РЎРґРµР»РєР° #%s qty=%s price=%s status=%s', v_trade_id, v_quantity, v_pp, v_status),
                jsonb_build_object(
                    'trade_id', v_trade_id,
                    'quantity', v_quantity,
                    'price', v_pp,
                    'status', v_status,
                    'position_event', v_grp.position_event,
                    'position_side', v_grp.position_side,
                    'effective_side', v_eff_side,
                    'global_inversion', v_inversion,
                    'security_inversion', COALESCE(v_sec.real_trading_inverted, FALSE),
                    'signal_kind', v_signal_kind,
                    'formula', v_formulas,
                    'bar_dt', v_ind_dt
                ),
                v_sec.security_id,
                v_tf_id
            );
        END LOOP;
    END LOOP;

    -- OPT challenger books (paper) + promote window
    BEGIN
        v_created := v_created + process_logic_opt_trades(p_logic_id, v_tf_id, v_closed_bar_dt);
        PERFORM logic_opt_maybe_promote(p_logic_id, v_tf_id, v_closed_bar_dt);
    EXCEPTION
        WHEN undefined_function THEN
            NULL;
        WHEN OTHERS THEN
            PERFORM logic_trade_log(
                p_logic_id,
                'opt.error',
                format('OPT runner: %s', SQLERRM),
                jsonb_build_object('sqlstate', SQLSTATE),
                NULL,
                v_tf_id
            );
    END;

    PERFORM logic_upsert_param(
        p_logic_id,
        'last_trade_check_at',
        to_char(CURRENT_TIMESTAMP, 'YYYY-MM-DD"T"HH24:MI:SS'),
        'text'
    );
    -- #972: РїРѕРІС‚РѕСЂРЅС‹Р№ РїСЂРѕРіРѕРЅ РїРѕРґС‚РІРµСЂР¶РґС‘РЅРЅРѕР№ РіСЂСѓРїРїС‹ РЅРµ РґРѕР»Р¶РµРЅ РѕС‚РєР°С‚С‹РІР°С‚СЊ РґРµРґСѓРї-РјР°СЂРєРµСЂ.
    IF NOT v_confirm_disabled THEN
        PERFORM logic_upsert_param(
            p_logic_id,
            'last_trade_bar_dt',
            to_char(v_closed_bar_dt, 'YYYY-MM-DD"T"HH24:MI:SS'),
            'text'
        );
    END IF;

    IF v_created = 0 THEN
        PERFORM logic_trade_log(
            p_logic_id,
            'trade.bar_done',
            format('РЎРІРµС‡Р° %s РїСЂРѕРІРµСЂРµРЅР°, СЃРґРµР»РѕРє РЅРµ СЃРѕР·РґР°РЅРѕ', v_closed_bar_dt),
            jsonb_build_object('closed_bar', v_closed_bar_dt),
            NULL,
            v_tf_id
        );
    END IF;

    RETURN v_created;
END;
$$;

COMMENT ON FUNCTION process_logic_trades(INTEGER) IS
'AND РїРѕ РіСЂСѓРїРїР°Рј (position_event Г— position_side): СЃРґРµР»РєР° С‚РѕР»СЊРєРѕ РµСЃР»Рё РІСЃРµ Р°РєС‚РёРІРЅС‹Рµ СЃРёРіРЅР°Р»С‹ РіСЂСѓРїРїС‹ СЃСЂР°Р±РѕС‚Р°Р»Рё; '
'СЂРµР№С‚РёРЅРі СЃРёРіРЅР°Р»Р° РЅР° Р»РѕРіРёРєРµ РѕР±РЅРѕРІР»СЏРµС‚СЃСЏ С‡РµСЂРµР· pending РЅР° СЃР»РµРґСѓСЋС‰РµР№ СЃРІРµС‡Рµ TF; '
'РїСЂРё OPT() вЂ” Р±СѓРјР°Р¶РЅС‹Рµ РІРµС‚РєРё opt_lane Рё promote РєР°Р¶РґС‹Рµ opt_eval_candles';

-- @include sql/logic_cash_fund_park.sql (stub; full after http)

CREATE OR REPLACE FUNCTION resolve_indicator_params(p_indicator_code VARCHAR,
    OUT param_period INTEGER,
    OUT param_fast_period INTEGER,
    OUT param_slow_period INTEGER,
    OUT param_signal_period INTEGER,
    OUT param_std_dev NUMERIC,
    OUT param_k_period INTEGER,
    OUT param_d_period INTEGER,
    OUT param_smooth INTEGER)
LANGUAGE plpgsql STABLE AS $$
BEGIN
    param_period := CASE upper(p_indicator_code)
        WHEN 'RSI' THEN 14 WHEN 'SMA' THEN 20 WHEN 'EMA' THEN 20 WHEN 'BB' THEN 20
        WHEN 'DONCHIAN' THEN 20
        WHEN 'ATR' THEN 14 WHEN 'STOCH' THEN 14 WHEN 'SMAT3' THEN 20
        WHEN 'CCI' THEN 20 WHEN 'ADX' THEN 14 WHEN 'LINREG' THEN 20 WHEN 'SQUARE' THEN 20
        WHEN 'ROC' THEN 10 WHEN 'SOLDIERS' THEN 3
        ELSE 14 END;
    BEGIN
        SELECT pv.value::INTEGER INTO param_period
        FROM parameter_values pv
        JOIN parameter_types pt ON pt.id = pv.parameter_type_id
        JOIN parameter_sets ps ON ps.id = pv.parameter_set_id
        WHERE ps.name = 'Default' AND pt.short_name = upper(p_indicator_code) || '_PERIOD'
        LIMIT 1;
    EXCEPTION WHEN OTHERS THEN NULL;
    END;
    param_fast_period := 12;
    param_slow_period := 26;
    param_signal_period := 9;
    param_std_dev := 2.0;
    param_k_period := COALESCE(param_period, 14);
    param_d_period := 3;
    param_smooth := 3;
END;
$$;

CREATE OR REPLACE FUNCTION resolve_tbank_account(p_api_url TEXT,
    p_token TEXT,
    p_preferred_account_id VARCHAR DEFAULT NULL)
RETURNS JSONB
LANGUAGE plpgsql AS $$
DECLARE
    v_accounts JSONB;
    v_acc JSONB;
    v_picked JSONB;
    v_i INTEGER;
    v_mapped JSONB := '[]'::jsonb;
BEGIN
    v_accounts := fetch_tbank_accounts(p_api_url, p_token);
    IF jsonb_array_length(v_accounts) = 0 THEN
        RAISE EXCEPTION 'РџРѕ С‚РѕРєРµРЅСѓ РЅРµ РЅР°Р№РґРµРЅРѕ РЅРё РѕРґРЅРѕРіРѕ СЃС‡С‘С‚Р° РІ T-Bank';
    END IF;

    IF p_preferred_account_id IS NOT NULL AND btrim(p_preferred_account_id) <> '' THEN
        FOR v_i IN 0 .. jsonb_array_length(v_accounts) - 1
        LOOP
            v_acc := v_accounts->v_i;
            IF v_acc->>'id' = p_preferred_account_id THEN
                v_picked := v_acc;
                EXIT;
            END IF;
        END LOOP;
    END IF;

    IF v_picked IS NULL THEN
        FOR v_i IN 0 .. jsonb_array_length(v_accounts) - 1
        LOOP
            v_acc := v_accounts->v_i;
            IF v_acc->>'status' = 'ACCOUNT_STATUS_OPEN' THEN
                v_picked := v_acc;
                EXIT;
            END IF;
        END LOOP;
    END IF;

    IF v_picked IS NULL THEN
        v_picked := v_accounts->0;
    END IF;

    FOR v_i IN 0 .. jsonb_array_length(v_accounts) - 1
    LOOP
        v_acc := v_accounts->v_i;
        v_mapped := v_mapped || jsonb_build_array(jsonb_build_object(
            'id', v_acc->>'id',
            'name', COALESCE(v_acc->>'name', ''),
            'type', COALESCE(v_acc->>'type', ''),
            'status', COALESCE(v_acc->>'status', '')
        ));
    END LOOP;

    RETURN jsonb_build_object(
        'accounts', v_mapped,
        'account_id', v_picked->>'id',
        'account_name', COALESCE(v_picked->>'name', '')
    );
END;
$$;

COMMENT ON FUNCTION resolve_tbank_account(TEXT, TEXT, VARCHAR) IS
'Р’С‹Р±РѕСЂ СЃС‡С‘С‚Р° T-Bank РїРѕ С‚РѕРєРµРЅСѓ (GetAccounts + preferred id)';

CREATE OR REPLACE FUNCTION resolve_tbank_instrument_id(p_security_id INTEGER,
    p_prefix VARCHAR,
    p_tbank_figi VARCHAR DEFAULT NULL,
    p_is_future BOOLEAN DEFAULT FALSE,
    p_class_code VARCHAR DEFAULT 'TQBR',
    p_moex_secid VARCHAR DEFAULT NULL)
RETURNS TEXT
LANGUAGE plpgsql AS $$
DECLARE
    v_token TEXT;
    v_headers http_header[];
    v_response http_response;
    v_instrument JSONB;
    v_id TEXT;
    v_try TEXT;
BEGIN
    v_token := get_tbank_token();

    IF p_is_future THEN
        IF v_token IS NULL OR btrim(v_token) = '' THEN
            RETURN COALESCE(p_tbank_figi, p_moex_secid, p_prefix);
        END IF;
        PERFORM configure_http_ssl();
        v_headers := ARRAY[
            http_header('Authorization', 'Bearer ' || v_token),
            http_header('Accept', 'application/json')
        ];
        FOREACH v_try IN ARRAY ARRAY[
            NULLIF(btrim(p_moex_secid), ''),
            NULLIF(btrim(p_prefix), '')
        ]
        LOOP
            CONTINUE WHEN v_try IS NULL;
            SELECT * INTO v_response FROM http((
                'POST',
                COALESCE(
                    (SELECT rtrim(b.api_url, '/') FROM brokers b WHERE b.code = 'T-BANK' LIMIT 1),
                    'https://invest-public-api.tbank.ru/rest'
                )
                    || '/tinkoff.public.invest.api.contract.v1.InstrumentsService/FutureBy',
                v_headers,
                'application/json',
                jsonb_build_object(
                    'id_type', 'INSTRUMENT_ID_TYPE_TICKER',
                    'classCode', 'SPBFUT',
                    'id', v_try
                )::TEXT
            )::http_request);
            IF v_response.status = 200 THEN
                v_instrument := v_response.content::JSONB->'instrument';
                v_id := COALESCE(v_instrument->>'uid', v_instrument->>'figi');
                IF p_security_id IS NOT NULL AND p_prefix IS NOT NULL AND v_instrument ? 'figi' THEN
                    UPDATE futures_expirations
                    SET tbank_figi = v_instrument->>'figi'
                    WHERE security_id = p_security_id
                      AND prefix = p_prefix
                      AND tbank_figi IS DISTINCT FROM v_instrument->>'figi';
                END IF;
                RETURN v_id;
            END IF;
        END LOOP;
        RETURN COALESCE(p_tbank_figi, p_moex_secid, p_prefix);
    END IF;

    IF v_token IS NULL OR btrim(v_token) = '' THEN
        RETURN COALESCE(p_tbank_figi, p_prefix);
    END IF;

    PERFORM configure_http_ssl();

    v_headers := ARRAY[
        http_header('Authorization', 'Bearer ' || v_token),
        http_header('Accept', 'application/json')
    ];

    SELECT * INTO v_response FROM http((
        'POST',
        COALESCE(
            (SELECT rtrim(b.api_url, '/') FROM brokers b WHERE b.code = 'T-BANK' LIMIT 1),
            'https://invest-public-api.tbank.ru/rest'
        )
            || '/tinkoff.public.invest.api.contract.v1.InstrumentsService/ShareBy',
        v_headers,
        'application/json',
        jsonb_build_object(
            'id_type', 'INSTRUMENT_ID_TYPE_TICKER',
            'classCode', p_class_code,
            'id', p_prefix
        )::TEXT
    )::http_request);

    IF v_response.status != 200 THEN
        RETURN COALESCE(p_tbank_figi, p_prefix);
    END IF;

    v_instrument := v_response.content::JSONB->'instrument';
    v_id := COALESCE(v_instrument->>'uid', v_instrument->>'figi', p_tbank_figi, p_prefix);

    IF p_security_id IS NOT NULL AND v_instrument ? 'figi' THEN
        UPDATE security_prefixes
        SET tbank_figi = v_instrument->>'figi'
        WHERE security_id = p_security_id
          AND exchange_id = 1
          AND tbank_figi IS DISTINCT FROM v_instrument->>'figi';
    END IF;

    RETURN v_id;
END;
$$;

