-- РЎРѕР±С‹С‚РёР№РЅС‹Р№ РїРµСЂРµСЃС‡С‘С‚ РїРѕСЃР»Рµ СЂР°Р±РѕС‚С‹ РєРѕРЅРєСЂРµС‚РЅРѕР№ Р»РѕРіРёРєРё: СЋРЅРёРІРµСЂСЃ = РµС‘ РїР°СЂС‹
-- (Р±СѓРјР°РіР° Г— РўР¤). РўСЂРѕС‚С‚Р» вЂ” РїРѕ Р»РѕРіРёРєРµ (indicator_rating_logic_run); advisory lock
-- РѕР±С‰РёР№ СЃ РїРѕР»РЅС‹Рј РїСЂРѕРіРѕРЅРѕРј, С‡С‚РѕР±С‹ С‚СЏР¶С‘Р»С‹Рµ СЂР°СЃС‡С‘С‚С‹ РЅРµ С€Р»Рё РѕРґРЅРѕРІСЂРµРјРµРЅРЅРѕ.
-- Р’РѕР·РІСЂР°С‚: 1 вЂ” СЃС‡РёС‚Р°Р»РѕСЃСЊ, 0 вЂ” РїСЂРѕРїСѓС‰РµРЅРѕ (С‚СЂРѕС‚С‚Р»/Р·Р°РЅСЏС‚Рѕ/РЅРµС‚ Р»РѕРіРёРєРё), -1 вЂ” РѕС€РёР±РєР°.

CREATE OR REPLACE FUNCTION run_trade_cycle()
RETURNS JSONB
LANGUAGE plpgsql AS $$
DECLARE
    v_logic RECORD;
    v_total_created INTEGER := 0;
    v_total_stops INTEGER := 0;
    v_total_signals INTEGER := 0;
    v_processed INTEGER := 0;
    v_skipped_bt INTEGER := 0;
    v_got_lock BOOLEAN;
BEGIN
    v_got_lock := pg_try_advisory_lock(hashtext('multilogictrade_run_trade_cycle'));
    IF NOT v_got_lock THEN
        PERFORM app_tech_log_event('trade-runner', 'cycle.skip', 'РџСЂРѕРїСѓСЃРє: РґСЂСѓРіРѕР№ С†РёРєР» СѓР¶Рµ РІС‹РїРѕР»РЅСЏРµС‚СЃСЏ', 'postgresql');
        RETURN jsonb_build_object('skipped', TRUE, 'reason', 'locked');
    END IF;

    IF trade_runner_require_ui() AND NOT trade_runner_ui_is_active() THEN
        PERFORM pg_advisory_unlock(hashtext('multilogictrade_run_trade_cycle'));
        PERFORM app_tech_log_event(
            'trade-runner',
            'cycle.skip',
            'РџСЂРѕРїСѓСЃРє: UI РЅРµ Р°РєС‚РёРІРµРЅ (APP_TRADE_RUNNER_REQUIRE_UI=1)',
            'postgresql'
        );
        RETURN jsonb_build_object('skipped', TRUE, 'reason', 'ui_inactive');
    END IF;

    PERFORM app_tech_log_event('trade-runner', 'cycle.start', 'run_trade_cycle РЅР°С‡Р°С‚', 'postgresql');

    FOR v_logic IN
        SELECT l.id, l.is_enabled,
               COALESCE(l.use_as_terminal_signal, FALSE) AS use_sig
        FROM logics l
        JOIN accounts a ON a.id = l.account_id
        WHERE (l.is_enabled = TRUE OR COALESCE(l.use_as_terminal_signal, FALSE))
          AND a.is_active = TRUE
        ORDER BY l.id
    LOOP
        -- РќРµ РјРµС€Р°С‚СЊ Р±СЌРєС‚РµСЃС‚Сѓ С‚РѕР№ Р¶Рµ Р»РѕРіРёРєРё (С†РµРЅС‹/РёРЅРґРёРєР°С‚РѕСЂС‹/СЃРґРµР»РєРё)
        IF EXISTS (
            SELECT 1
            FROM logic_backtest_runs r
            WHERE r.logic_id = v_logic.id
              AND r.status IN ('pending', 'loading_prices', 'loading_indicators', 'running')
        ) THEN
            v_skipped_bt := v_skipped_bt + 1;
            CONTINUE;
        END IF;

        v_processed := v_processed + 1;
        IF v_logic.use_sig THEN
            v_total_signals := v_total_signals + process_logic_terminal_signals(v_logic.id);
        END IF;
        IF v_logic.is_enabled THEN
            v_total_stops := v_total_stops + process_logic_stops(v_logic.id);
            v_total_created := v_total_created + process_logic_trades(v_logic.id);
            PERFORM logic_park_excess_cash(v_logic.id);
        END IF;
    END LOOP;

    PERFORM pg_advisory_unlock(hashtext('multilogictrade_run_trade_cycle'));

    -- #972: С„РёРЅР°Р»РёР·РёСЂСѓРµРј РѕС‚Р»РѕР¶РµРЅРЅС‹Рµ РїРѕРґС‚РІРµСЂР¶РґРµРЅРёСЏ СЃРёРіРЅР°Р»РѕРІ (СЃРІРµР¶РёРµ С†РµРЅС‹, РїРѕРІС‚РѕСЂ РіСЂСѓРїРї).
    BEGIN
        PERFORM logic_signal_confirm_finalize();
    EXCEPTION
        WHEN OTHERS THEN
            PERFORM app_tech_log_event(
                'trade-runner',
                'cycle.confirm_error',
                format('logic_signal_confirm_finalize: %s', SQLERRM),
                'postgresql',
                'error',
                NULL, NULL, NULL, NULL
            );
    END;

    CALL touch_trade_runner_last_ok('postgresql');

    PERFORM app_tech_log_event(
        'trade-runner',
        'cycle.end',
        format(
            'processed=%s stops=%s created=%s signals=%s skip_bt=%s',
            v_processed, v_total_stops, v_total_created, v_total_signals, v_skipped_bt
        ),
        'postgresql',
        'event',
        NULL,
        NULL,
        NULL,
        jsonb_build_object(
            'processed', v_processed,
            'stops', v_total_stops,
            'created', v_total_created,
            'signals', v_total_signals,
            'skipped_backtest', v_skipped_bt
        )
    );

    RETURN jsonb_build_object(
        'processed', v_processed,
        'stops', v_total_stops,
        'created', v_total_created,
        'signals', v_total_signals,
        'skipped_backtest', v_skipped_bt,
        'at', CURRENT_TIMESTAMP
    );
EXCEPTION
    WHEN OTHERS THEN
        PERFORM pg_advisory_unlock(hashtext('multilogictrade_run_trade_cycle'));
        RAISE;
END;
$$;

COMMENT ON FUNCTION run_trade_cycle() IS
'Р¦РёРєР» С‚РѕСЂРіРѕРІР»Рё РїРѕ РІРєР»СЋС‡С‘РЅРЅС‹Рј logics (РїСЂРѕРїСѓСЃРє Р»РѕРіРёРє СЃ Р°РєС‚РёРІРЅС‹Рј Р±СЌРєС‚РµСЃС‚РѕРј). '
'Node fallback РїСЂРµРґРїРѕС‡С‚РёС‚РµР»РµРЅ: РїРѕ Р»РѕРіРёРєРµ РѕС‚РґРµР»СЊРЅРѕ (РєРѕСЂРѕС‚РєРёРµ tx). pg_cron вЂ” СЌС‚Р° С„СѓРЅРєС†РёСЏ.';

-- ============================================================
-- РЎРёРіРЅР°Р»С‹ Р»РѕРіРёРє РІ С‚РµСЂРјРёРЅР°Р» (use_as_terminal_signal): Р°РЅР°Р»РёР·РёСЂСѓРµС‚
-- С‚РѕР»СЊРєРѕ open-СЃРёРіРЅР°Р»С‹ Р»РѕРіРёРєРё РЅР° Р·Р°РєСЂС‹С‚РѕР№ СЃРІРµС‡Рµ РµС‘ TF Рё Р·Р°РїРёСЃС‹РІР°РµС‚
-- logic_terminal_signals (РќР• С‚РѕСЂРіСѓРµС‚). РўРµСЂРјРёРЅР°Р» РґРѕР±Р°РІР»СЏРµС‚ Р±СѓРјР°РіСѓ+РўР¤
-- РґР»СЏ СЂСѓС‡РЅРѕРіРѕ СЂРµС€РµРЅРёСЏ РїРѕР»СЊР·РѕРІР°С‚РµР»СЏ.
-- ============================================================

CREATE OR REPLACE FUNCTION signal_param_value(p_params TEXT, p_key TEXT)
RETURNS TEXT
LANGUAGE plpgsql IMMUTABLE AS $$
DECLARE
    v_chunk TEXT;
    v_lower TEXT;
    v_prefix TEXT := lower(p_key) || '=';
BEGIN
    IF p_params IS NULL OR p_key IS NULL THEN
        RETURN NULL;
    END IF;
    FOR v_chunk IN
        SELECT unnest(signal_split_params_top_level(p_params))
    LOOP
        v_lower := lower(btrim(v_chunk));
        IF v_lower LIKE v_prefix || '%' THEN
            RETURN btrim(substr(v_lower, length(v_prefix) + 1));
        END IF;
    END LOOP;
    RETURN NULL;
END;
$$;

COMMENT ON FUNCTION signal_param_value(TEXT, TEXT) IS
'Р—РЅР°С‡РµРЅРёРµ РїР°СЂР°РјРµС‚СЂР° key=вЂ¦ РёР· СЃС‚СЂРѕРєРё params С„РѕСЂРјСѓР»С‹ СЃРёРіРЅР°Р»Р° (top-level Р·Р°РїСЏС‚С‹Рµ), NULL РµСЃР»Рё РЅРµС‚';

CREATE OR REPLACE FUNCTION signal_split_params_top_level(p_params TEXT)
RETURNS TEXT[]
LANGUAGE plpgsql IMMUTABLE AS $$
DECLARE
    v_out TEXT[] := ARRAY[]::TEXT[];
    v_cur TEXT := '';
    v_depth INTEGER := 0;
    v_ch TEXT;
    v_i INTEGER;
    v_s TEXT;
BEGIN
    v_s := COALESCE(p_params, '');
    FOR v_i IN 1..length(v_s) LOOP
        v_ch := substr(v_s, v_i, 1);
        IF v_ch = '(' THEN
            v_depth := v_depth + 1;
        ELSIF v_ch = ')' THEN
            v_depth := GREATEST(0, v_depth - 1);
        END IF;
        IF v_ch = ',' AND v_depth = 0 THEN
            IF btrim(v_cur) <> '' THEN
                v_out := v_out || btrim(v_cur);
            END IF;
            v_cur := '';
        ELSE
            v_cur := v_cur || v_ch;
        END IF;
    END LOOP;
    IF btrim(v_cur) <> '' THEN
        v_out := v_out || btrim(v_cur);
    END IF;
    RETURN v_out;
END;
$$;

CREATE OR REPLACE FUNCTION signal_tf_id_for_sec(p_sig_sec INTEGER, p_fallback_tf_id INTEGER)
RETURNS INTEGER
LANGUAGE plpgsql AS $$
DECLARE
    v_id INTEGER;
    v_name TEXT;
BEGIN
    IF p_sig_sec IS NULL OR p_sig_sec < 60 THEN
        RETURN p_fallback_tf_id;
    END IF;
    SELECT t.id INTO v_id FROM timeframes t WHERE t.sec = p_sig_sec LIMIT 1;
    IF v_id IS NOT NULL THEN
        RETURN v_id;
    END IF;
    v_name := signal_tf_name_for_sec(p_sig_sec);
    INSERT INTO timeframes (tf, full_name, sec, is_active)
    VALUES (
        v_name,
        v_name || ' (Р°РІС‚Рѕ, tf-РїР°СЂР°РјРµС‚СЂ СЃРёРіРЅР°Р»Р°)',
        p_sig_sec,
        TRUE
    )
    ON CONFLICT (tf) DO NOTHING
    RETURNING id INTO v_id;
    IF v_id IS NULL THEN
        SELECT t.id INTO v_id FROM timeframes t WHERE t.sec = p_sig_sec LIMIT 1;
    END IF;
    RETURN COALESCE(v_id, p_fallback_tf_id);
END;
$$;

COMMENT ON FUNCTION signal_tf_id_for_sec(INTEGER, INTEGER) IS
'id РєР°С‚Р°Р»РѕРіР° timeframes РґР»СЏ СЃРµРєСѓРЅРґ РўР¤; СЃС‚СЂРѕРєР° M7-style СЃРѕР·РґР°С‘С‚СЃСЏ РїСЂРё РїРµСЂРІРѕРј РёСЃРїРѕР»СЊР·РѕРІР°РЅРёРё';

-- РўРѕС‡РєР° РѕС†РµРЅРєРё СЃРёРіРЅР°Р»Р°: РµРіРѕ СЃРѕР±СЃС‚РІРµРЅРЅС‹Р№ tf_id Рё РІС‹СЂРѕРІРЅРµРЅРЅС‹Р№ Р·Р°РєСЂС‹С‚С‹Р№ Р±Р°СЂ
-- (РїРѕСЃР»РµРґРЅРёР№ Р±Р°СЂ sig-TF, Р·Р°РєСЂС‹РІС€РёР№СЃСЏ РЅРµ РїРѕР·Р¶Рµ close С‚РµРєСѓС‰РµРіРѕ Р±Р°СЂР° Р»РѕРіРёРєРё).

CREATE OR REPLACE FUNCTION signal_tf_name_for_sec(p_sec INTEGER)
RETURNS TEXT
LANGUAGE plpgsql IMMUTABLE AS $$
BEGIN
    IF p_sec IS NULL OR p_sec < 60 THEN
        RETURN NULL;
    END IF;
    IF p_sec < 3600 THEN
        RETURN 'M' || (p_sec / 60);
    ELSIF p_sec < 86400 AND p_sec % 3600 = 0 THEN
        RETURN 'H' || (p_sec / 3600);
    ELSIF p_sec < 604800 AND p_sec % 86400 = 0 THEN
        RETURN 'D' || (p_sec / 86400);
    ELSIF p_sec % 604800 = 0 THEN
        RETURN 'W' || (p_sec / 604800);
    ELSE
        RETURN 'T' || p_sec;
    END IF;
END;
$$;

CREATE OR REPLACE FUNCTION signal_tf_parse_sec(p_tf_expr TEXT)
RETURNS INTEGER
LANGUAGE plpgsql IMMUTABLE AS $$
DECLARE
    v TEXT;
    v_units TEXT;
    v_num INTEGER;
    v_mult INTEGER := 1;
    v_unit_sec INTEGER;
BEGIN
    v := lower(btrim(COALESCE(p_tf_expr, '')));
    IF v = '' THEN
        RETURN NULL;
    END IF;
    -- Р¤РѕСЂРјС‹: m15 | m15*4 | m15 x 4 | m15Г—4 ; СЂРµРіРёСЃС‚СЂ Рё РїСЂРѕР±РµР»С‹ РЅРµ РІР°Р¶РЅС‹
    IF v !~ '^([mhdw])[ ]?([0-9]{1,4})([ ]?[*xГ—][ ]?([0-9]{1,3}))?$' THEN
        RETURN NULL;
    END IF;
    v_units := substring(v from '^([mhdw])');
    v_num := substring(v from '[ ]?([0-9]{1,4})')::INTEGER;
    BEGIN
        v_mult := COALESCE(substring(v from '[*xГ—][ ]?([0-9]{1,3})$'), '')::INTEGER;
    EXCEPTION WHEN OTHERS THEN
        v_mult := 1;
    END;
    IF v_mult IS NULL OR v_mult < 1 THEN v_mult := 1; END IF;
    v_unit_sec := CASE v_units
        WHEN 'm' THEN 60
        WHEN 'h' THEN 3600
        WHEN 'd' THEN 86400
        WHEN 'w' THEN 604800
        ELSE NULL
    END;
    IF v_unit_sec IS NULL OR v_num < 1 THEN
        RETURN NULL;
    END IF;
    RETURN v_unit_sec * v_num * v_mult;
END;
$$;

COMMENT ON FUNCTION signal_tf_parse_sec(TEXT) IS
'tf-РІС‹СЂР°Р¶РµРЅРёРµ (M15, M1*7, H1Г—2 вЂ¦) в†’ СЃРµРєСѓРЅРґС‹ РўР¤; NULL РµСЃР»Рё РїСѓСЃС‚Рѕ/РЅРµРІРµСЂРЅРѕ';

CREATE OR REPLACE FUNCTION substitute_indicator_script(p_template TEXT,
    p_period INTEGER DEFAULT NULL,
    p_fast_period INTEGER DEFAULT NULL,
    p_slow_period INTEGER DEFAULT NULL,
    p_signal_period INTEGER DEFAULT NULL,
    p_std_dev NUMERIC DEFAULT NULL,
    p_k_period INTEGER DEFAULT NULL,
    p_d_period INTEGER DEFAULT NULL,
    p_smooth INTEGER DEFAULT NULL,
    p_series VARCHAR DEFAULT NULL,
    p_security_id INTEGER DEFAULT NULL,
    p_timeframe_id INTEGER DEFAULT NULL,
    p_dt TIMESTAMP DEFAULT NULL,
    p_indicator_id INTEGER DEFAULT NULL)
RETURNS TEXT
LANGUAGE plpgsql
STABLE
AS $$
DECLARE
    v_sql TEXT := p_template;
BEGIN
    IF v_sql IS NULL OR TRIM(v_sql) = '' THEN
        RETURN NULL;
    END IF;

    v_sql := REPLACE(v_sql, ':fast_period', COALESCE(p_fast_period::TEXT, 'NULL'));
    v_sql := REPLACE(v_sql, ':slow_period', COALESCE(p_slow_period::TEXT, 'NULL'));
    v_sql := REPLACE(v_sql, ':signal_period', COALESCE(p_signal_period::TEXT, 'NULL'));
    v_sql := REPLACE(v_sql, ':k_period', COALESCE(p_k_period::TEXT, 'NULL'));
    v_sql := REPLACE(v_sql, ':d_period', COALESCE(p_d_period::TEXT, 'NULL'));
    v_sql := REPLACE(v_sql, ':std_dev', COALESCE(p_std_dev::TEXT, 'NULL'));
    v_sql := REPLACE(v_sql, ':smooth', COALESCE(p_smooth::TEXT, 'NULL'));
    v_sql := REPLACE(v_sql, ':security_id', COALESCE(p_security_id::TEXT, 'NULL'));
    v_sql := REPLACE(v_sql, ':timeframe_id', COALESCE(p_timeframe_id::TEXT, 'NULL'));
    v_sql := REPLACE(v_sql, ':indicator_id', COALESCE(p_indicator_id::TEXT, 'NULL'));
    v_sql := REPLACE(v_sql, ':period', COALESCE(p_period::TEXT, 'NULL'));
    v_sql := REPLACE(v_sql, ':series', quote_literal(COALESCE(p_series, '')));
    v_sql := REPLACE(v_sql, ':dt', quote_literal(p_dt));

    RETURN v_sql;
END;
$$;

COMMENT ON FUNCTION substitute_indicator_script(TEXT, INTEGER, INTEGER, INTEGER, INTEGER, NUMERIC, INTEGER, INTEGER, INTEGER, VARCHAR, INTEGER, INTEGER, TIMESTAMP, INTEGER) IS
'РџРѕРґСЃС‚Р°РІР»СЏРµС‚ Р·РЅР°С‡РµРЅРёСЏ РїР°СЂР°РјРµС‚СЂРѕРІ Рё :series РІ С€Р°Р±Р»РѕРЅ indicators.script РґР»СЏ EXECUTE.';

CREATE OR REPLACE FUNCTION tbank_cancel_order(p_account_id INTEGER,
    p_order_id VARCHAR)
RETURNS JSONB
LANGUAGE plpgsql AS $$
DECLARE
    v_token TEXT;
    v_api_url TEXT;
    v_account_code VARCHAR;
    v_resolved JSONB;
BEGIN
    SELECT btrim(a.token_encrypted), b.api_url, a.account_code
    INTO v_token, v_api_url, v_account_code
    FROM accounts a
    JOIN brokers b ON b.id = a.broker_id
    WHERE a.id = p_account_id AND b.code = 'T-BANK';

    IF v_token IS NULL OR v_token = '' THEN
        RAISE EXCEPTION 'T-Bank С‚РѕРєРµРЅ РЅРµ РЅР°Р№РґРµРЅ РґР»СЏ account_id=%', p_account_id;
    END IF;

    v_resolved := resolve_tbank_account(v_api_url, v_token, v_account_code);

    RETURN tbank_http_post(
        v_api_url,
        'tinkoff.public.invest.api.contract.v1.OrdersService/CancelOrder',
        v_token,
        jsonb_build_object(
            'accountId', v_resolved->>'account_id',
            'orderId', p_order_id
        )
    );
END;
$$;

COMMENT ON FUNCTION tbank_cancel_order(INTEGER, VARCHAR) IS
'РћС‚РјРµРЅР° Р·Р°СЏРІРєРё T-Bank (CancelOrder)';

CREATE OR REPLACE FUNCTION tbank_figi_lot_size(p_api_url TEXT,
    p_token TEXT,
    p_figi VARCHAR)
RETURNS INTEGER
LANGUAGE plpgsql AS $$
DECLARE
    v_content JSONB;
    v_instrument JSONB;
    v_lot INTEGER;
    v_sec_id INTEGER;
BEGIN
    IF p_figi IS NULL OR btrim(p_figi) = '' THEN
        RETURN 1;
    END IF;

    BEGIN
        v_content := tbank_http_post(
            p_api_url,
            'tinkoff.public.invest.api.contract.v1.InstrumentsService/GetInstrumentBy',
            p_token,
            jsonb_build_object(
                'id_type', 'INSTRUMENT_ID_TYPE_FIGI',
                'id', btrim(p_figi)
            )
        );
        v_instrument := COALESCE(v_content->'instrument', v_content);
        v_lot := NULLIF(regexp_replace(COALESCE(v_instrument->>'lot', ''), '[^0-9]', '', 'g'), '')::INTEGER;
        IF v_lot IS NOT NULL AND v_lot >= 1 THEN
            SELECT sp.security_id INTO v_sec_id
            FROM security_prefixes sp
            WHERE sp.tbank_figi = btrim(p_figi)
            ORDER BY sp.exchange_id
            LIMIT 1;
            IF v_sec_id IS NOT NULL THEN
                UPDATE securities
                SET lot_size = v_lot
                WHERE id = v_sec_id
                  AND lot_size IS DISTINCT FROM v_lot;
            END IF;
            RETURN v_lot;
        END IF;
    EXCEPTION
        WHEN OTHERS THEN
            NULL;
    END;

    SELECT GREATEST(1, COALESCE(s.lot_size, 1))
    INTO v_lot
    FROM security_prefixes sp
    JOIN securities s ON s.id = sp.security_id
    WHERE sp.tbank_figi = btrim(p_figi)
    ORDER BY sp.exchange_id
    LIMIT 1;

    RETURN GREATEST(1, COALESCE(v_lot, 1));
END;
$$;

COMMENT ON FUNCTION tbank_figi_lot_size(TEXT, TEXT, VARCHAR) IS
'T-Bank instrument.lot РїРѕ FIGI (РєСЌС€ РІ securities.lot_size); РёРЅР°С‡Рµ lot_size РёР· Р‘Р” / 1.';

