COMMENT ON FUNCTION tbank_get_order_state(INTEGER, VARCHAR) IS
'T-Bank GetOrderState вЂ” СЃС‚Р°С‚СѓСЃ/РєРѕРјРёСЃСЃРёСЏ/С†РµРЅР° РёСЃРїРѕР»РЅРµРЅРёСЏ Р·Р°СЏРІРєРё';

CREATE OR REPLACE FUNCTION tbank_get_orders(p_account_id INTEGER)
RETURNS JSONB
LANGUAGE plpgsql AS $$
DECLARE
    v_token TEXT;
    v_api_url TEXT;
    v_account_code VARCHAR;
    v_resolved JSONB;
BEGIN
    SELECT btrim(a.token_encrypted), b.api_url, a.account_code
    INTO v_token, v_api_url, v_account_code
    FROM accounts a
    JOIN brokers b ON b.id = a.broker_id
    WHERE a.id = p_account_id AND b.code = 'T-BANK';

    IF v_token IS NULL OR v_token = '' THEN
        RAISE EXCEPTION 'T-Bank С‚РѕРєРµРЅ РЅРµ РЅР°Р№РґРµРЅ РґР»СЏ account_id=%', p_account_id;
    END IF;

    v_resolved := resolve_tbank_account(v_api_url, v_token, v_account_code);

    RETURN tbank_http_post(
        v_api_url,
        'tinkoff.public.invest.api.contract.v1.OrdersService/GetOrders',
        v_token,
        jsonb_build_object('accountId', v_resolved->>'account_id')
    );
END;
$$;

