'РЎРїРёСЃРѕРє Р·Р°СЏРІРѕРє T-Bank (GetOrders)';

CREATE OR REPLACE FUNCTION tbank_http_post(p_api_url TEXT,
    p_rpc_path TEXT,
    p_token TEXT,
    p_body JSONB DEFAULT '{}'::jsonb)
RETURNS JSONB
LANGUAGE plpgsql AS $$
DECLARE
    v_url TEXT;
    v_headers http_header[];
    v_response http_response;
    v_content JSONB;
    v_proxy_url TEXT;
    v_proxy_body JSONB;
BEGIN
    -- channel=node: proxy via local Express (Russian CA / system TLS), not libcurlв†’T-Bank.
    IF tbank_order_channel() = 'node' THEN
        v_proxy_url := tbank_order_node_base_url() || '/api/internal/tbank/http-post';
        v_proxy_body := jsonb_build_object(
            'api_url', COALESCE(p_api_url, get_tbank_api_url()),
            'rpc_path', ltrim(p_rpc_path, '/'),
            'token', p_token,
            'body', COALESCE(p_body, '{}'::jsonb)
        );
        v_headers := ARRAY[
            http_header('Accept', 'application/json'),
            http_header('Content-Type', 'application/json')
        ];
        SELECT * INTO v_response FROM http((
            'POST',
            v_proxy_url,
            v_headers,
            'application/json',
            v_proxy_body::TEXT
        )::http_request);
        IF v_response.status IS NULL THEN
            RAISE EXCEPTION 'Node API РЅРµРґРѕСЃС‚СѓРїРµРЅ (%). Р—Р°РїСѓСЃС‚РёС‚Рµ MultiLogic Trade РёР»Рё РєР°РЅР°Р» postgres.', v_proxy_url;
        END IF;
        BEGIN
            v_content := v_response.content::JSONB;
        EXCEPTION
            WHEN OTHERS THEN
                RAISE EXCEPTION 'Node API HTTP %: %', v_response.status, left(COALESCE(v_response.content, ''), 500);
        END;
        IF v_response.status != 200 OR COALESCE(v_content->>'ok', 'true') = 'false' THEN
            RAISE EXCEPTION 'Nodeв†’T-Bank: %',
                COALESCE(v_content->>'error', left(COALESCE(v_response.content, ''), 500));
        END IF;
        RETURN COALESCE(v_content->'data', v_content);
    END IF;

    PERFORM configure_http_ssl();

    v_url := rtrim(COALESCE(p_api_url, get_tbank_api_url()), '/')
        || '/' || ltrim(p_rpc_path, '/');

    v_headers := ARRAY[
        http_header('Authorization', 'Bearer ' || p_token),
        http_header('Accept', 'application/json')
    ];

    SELECT * INTO v_response FROM http((
        'POST',
        v_url,
        v_headers,
        'application/json',
        COALESCE(p_body, '{}'::jsonb)::TEXT
    )::http_request);

    IF v_response.status != 200 THEN
        RAISE EXCEPTION 'T-Bank API HTTP %: %', v_response.status, v_response.content;
    END IF;

    v_content := v_response.content::JSONB;
    IF v_content ? 'code' AND (v_content->>'code') NOT IN ('', '0') THEN
        RAISE EXCEPTION 'T-Bank API: %', COALESCE(v_content->>'message', v_response.content);
    END IF;

    RETURN v_content;
END;
$$;

COMMENT ON FUNCTION tbank_http_post(TEXT, TEXT, TEXT, JSONB) IS
'POST Рє T-Bank Invest API: postgres=pgsql-http; node=РїСЂРѕРєСЃРё localhost Express (CA РќРЈР¦).';

