CREATE OR REPLACE FUNCTION tbank_order_commission(p_order JSONB)
RETURNS NUMERIC
LANGUAGE plpgsql IMMUTABLE AS $$
DECLARE
    v NUMERIC;
BEGIN
    IF p_order IS NULL THEN
        RETURN 0;
    END IF;

    v := abs(COALESCE(
        parse_tbank_quotation(
            COALESCE(p_order->'executedCommission', p_order->'executed_commission')
        ),
        0
    ));
    IF v > 0 THEN
        RETURN round(v, 6);
    END IF;

    v := abs(COALESCE(
        parse_tbank_quotation(
            COALESCE(p_order->'initialCommission', p_order->'initial_commission')
        ),
        0
    ));
    IF v > 0 THEN
        RETURN round(v, 6);
    END IF;

    v := abs(COALESCE(
        parse_tbank_quotation(
            COALESCE(p_order->'serviceCommission', p_order->'service_commission')
        ),
        0
    ));
    RETURN round(COALESCE(v, 0), 6);
END;
$$;

COMMENT ON FUNCTION tbank_order_commission(JSONB) IS
'РљРѕРјРёСЃСЃРёСЏ T-Bank РёР· РѕС‚РІРµС‚Р° PostOrder/GetOrderState: executed в†’ initial в†’ service (в‚Ѕ)';

CREATE OR REPLACE FUNCTION tbank_order_unit_price(p_order JSONB)
RETURNS NUMERIC
LANGUAGE plpgsql IMMUTABLE AS $$
DECLARE
    v NUMERIC;
    v_lots NUMERIC;
    v_total NUMERIC;
BEGIN
    IF p_order IS NULL THEN
        RETURN NULL;
    END IF;

    v := parse_tbank_quotation(
        COALESCE(p_order->'averagePositionPrice', p_order->'average_position_price')
    );
    IF v IS NOT NULL AND v > 0 THEN
        RETURN round(v, 6);
    END IF;

    v := parse_tbank_quotation(
        COALESCE(p_order->'initialSecurityPrice', p_order->'initial_security_price')
    );
    IF v IS NOT NULL AND v > 0 THEN
        RETURN round(v, 6);
    END IF;

    v := parse_tbank_quotation(p_order->'stages'->0->'price');
    IF v IS NOT NULL AND v > 0 THEN
        RETURN round(v, 6);
    END IF;

    v_lots := COALESCE(
        NULLIF(regexp_replace(
            COALESCE(p_order->>'lotsExecuted', p_order->>'lots_executed', '0'),
            '[^0-9.\-]', '', 'g'
        ), ''),
        '0'
    )::numeric;

    v_total := parse_tbank_quotation(
        COALESCE(p_order->'executedOrderPrice', p_order->'executed_order_price')
    );
    IF v_total IS NOT NULL AND v_total > 0 THEN
        IF v_lots > 1 THEN
            RETURN round(v_total / v_lots, 6);
        END IF;
        RETURN round(v_total, 6);
    END IF;

    RETURN NULL;
END;
$$;

COMMENT ON FUNCTION tbank_order_unit_price(JSONB) IS
'Р¦РµРЅР° Р·Р° РµРґРёРЅРёС†Сѓ РёР· T-Bank: averagePositionPrice в†’ initialSecurityPrice в†’ stages в†’ executed/lots';

CREATE OR REPLACE FUNCTION tbank_post_order(p_account_id INTEGER,
    p_figi VARCHAR,
    p_quantity NUMERIC,
    p_price NUMERIC,
    p_direction VARCHAR,
    p_order_execution VARCHAR DEFAULT 'market',
    p_quantity_is_lots BOOLEAN DEFAULT FALSE)
RETURNS JSONB
LANGUAGE plpgsql AS $$
DECLARE
    v_token TEXT;
    v_api_url TEXT;
    v_account_code VARCHAR;
    v_resolved JSONB;
    v_dir VARCHAR;
    v_exec TEXT;
    v_body JSONB;
    v_order_type TEXT;
    v_lot INTEGER;
    v_lots BIGINT;
BEGIN
    -- Node channel: PostOrder via local Express (system CA), not pgsql-http в†’ T-Bank.
    IF tbank_order_channel() = 'node' THEN
        RETURN tbank_post_order_via_node(
            p_account_id, p_figi, p_quantity, p_price, p_direction,
            p_order_execution, p_quantity_is_lots
        );
    END IF;

    SELECT btrim(a.token_encrypted), b.api_url, a.account_code
    INTO v_token, v_api_url, v_account_code
    FROM accounts a
    JOIN brokers b ON b.id = a.broker_id
    WHERE a.id = p_account_id AND b.code = 'T-BANK';

    IF v_token IS NULL OR v_token = '' THEN
        RAISE EXCEPTION 'T-Bank С‚РѕРєРµРЅ РЅРµ РЅР°Р№РґРµРЅ РґР»СЏ account_id=%', p_account_id;
    END IF;

    v_resolved := resolve_tbank_account(v_api_url, v_token, v_account_code);
    v_dir := upper(btrim(p_direction));
    IF v_dir NOT IN ('BUY', 'SELL', 'ORDER_DIRECTION_BUY', 'ORDER_DIRECTION_SELL') THEN
        RAISE EXCEPTION 'direction: BUY РёР»Рё SELL';
    END IF;
    IF v_dir = 'BUY' THEN
        v_dir := 'ORDER_DIRECTION_BUY';
    ELSIF v_dir = 'SELL' THEN
        v_dir := 'ORDER_DIRECTION_SELL';
    END IF;

    v_exec := lower(btrim(COALESCE(p_order_execution, 'market')));
    IF v_exec IN ('limit', 'l', 'order_type_limit') THEN
        v_order_type := 'ORDER_TYPE_LIMIT';
        IF p_price IS NULL OR p_price <= 0 THEN
            RAISE EXCEPTION 'LIMIT-Р·Р°СЏРІРєР° С‚СЂРµР±СѓРµС‚ С†РµРЅСѓ > 0';
        END IF;
    ELSE
        v_order_type := 'ORDER_TYPE_MARKET';
    END IF;

    -- PostOrder.quantity = LOTS (T-Invest API). Runner/stops/cash-fund pass SHARES;
    -- sell-all / bond plan pass lots with p_quantity_is_lots=TRUE.
    IF COALESCE(p_quantity_is_lots, FALSE) THEN
        v_lots := floor(COALESCE(p_quantity, 0))::BIGINT;
    ELSE
        v_lot := tbank_figi_lot_size(v_api_url, v_token, p_figi);
        v_lots := floor(COALESCE(p_quantity, 0) / v_lot)::BIGINT;
    END IF;
    IF v_lots IS NULL OR v_lots < 1 THEN
        RAISE EXCEPTION
            'tbank_post_order: need в‰Ґ1 lot (qty=%, is_lots=%, figi=%)',
            p_quantity, COALESCE(p_quantity_is_lots, FALSE), p_figi;
    END IF;

    -- market: СЃСЂР°Р·Сѓ РІ СЃРµСЃСЃРёСЋ; limit: РїРѕ С†РµРЅРµ СЃРёРіРЅР°Р»Р° (РјРѕР¶РµС‚ РІРёСЃРµС‚СЊ).
    -- confirmMarginTrade вЂ” РґР»СЏ С€РѕСЂС‚Р°/РјР°СЂР¶Рё.
    v_body := jsonb_build_object(
        'accountId', v_resolved->>'account_id',
        'figi', p_figi,
        'quantity', v_lots,
        'direction', v_dir,
        'orderType', v_order_type,
        'confirmMarginTrade', TRUE,
        'orderId', gen_random_uuid()::text
    );
    IF p_price IS NOT NULL AND p_price > 0 THEN
        v_body := v_body || jsonb_build_object(
            'price', jsonb_build_object(
                'units', trunc(p_price)::bigint,
                'nano', round((p_price - trunc(p_price)) * 1000000000)::integer
            )
        );
    END IF;

    RETURN tbank_http_post(
        v_api_url,
        'tinkoff.public.invest.api.contract.v1.OrdersService/PostOrder',
        v_token,
        v_body
    );
END;
$$;

COMMENT ON FUNCTION tbank_post_order(INTEGER, VARCHAR, NUMERIC, NUMERIC, VARCHAR, VARCHAR, BOOLEAN) IS
'T-Bank PostOrder: quantity РІ Р»РѕС‚Р°С…. РљР°РЅР°Р» APP_TBANK_ORDER_CHANNEL: postgres (pgsql-http) РёР»Рё node (Р»РѕРєР°Р»СЊРЅС‹Р№ API). p_quantity=С€С‚СѓРєРё в†’ РґРµР»РµРЅРёРµ РЅР° lot; p_quantity_is_lots=TRUE РµСЃР»Рё СѓР¶Рµ Р»РѕС‚С‹.';

CREATE OR REPLACE FUNCTION tbank_post_order_via_node(p_account_id INTEGER,
    p_figi VARCHAR,
    p_quantity NUMERIC,
    p_price NUMERIC,
    p_direction VARCHAR,
    p_order_execution VARCHAR DEFAULT 'market',
    p_quantity_is_lots BOOLEAN DEFAULT FALSE)
RETURNS JSONB
LANGUAGE plpgsql AS $$
DECLARE
    v_token TEXT;
    v_api_url TEXT;
    v_account_code VARCHAR;
    v_url TEXT;
    v_headers http_header[];
    v_response http_response;
    v_body JSONB;
    v_content JSONB;
BEGIN
    -- Localhost Node proxy; UI heartbeat not required (API must be running).
    SELECT btrim(a.token_encrypted), b.api_url, a.account_code
    INTO v_token, v_api_url, v_account_code
    FROM accounts a
    JOIN brokers b ON b.id = a.broker_id
    WHERE a.id = p_account_id AND b.code = 'T-BANK';

    IF v_token IS NULL OR v_token = '' THEN
        RAISE EXCEPTION 'T-Bank С‚РѕРєРµРЅ РЅРµ РЅР°Р№РґРµРЅ РґР»СЏ account_id=%', p_account_id;
    END IF;

    v_url := tbank_order_node_base_url() || '/api/internal/tbank/post-order';
    v_body := jsonb_build_object(
        'account_id', p_account_id,
        'api_url', COALESCE(v_api_url, 'https://invest-public-api.tbank.ru/rest'),
        'token', v_token,
        'account_code', v_account_code,
        'figi', p_figi,
        'quantity', p_quantity,
        'price', p_price,
        'direction', p_direction,
        'order_execution', COALESCE(p_order_execution, 'market'),
        'quantity_is_lots', COALESCE(p_quantity_is_lots, FALSE)
    );

    v_headers := ARRAY[
        http_header('Accept', 'application/json'),
        http_header('Content-Type', 'application/json')
    ];

    SELECT * INTO v_response FROM http((
        'POST',
        v_url,
        v_headers,
        'application/json',
        v_body::TEXT
    )::http_request);

    IF v_response.status IS NULL THEN
        RAISE EXCEPTION 'Node API РЅРµРґРѕСЃС‚СѓРїРµРЅ (%). Р—Р°РїСѓСЃС‚РёС‚Рµ MultiLogic Trade (API) РёР»Рё РєР°РЅР°Р» Postgres.', v_url;
    END IF;

    BEGIN
        v_content := v_response.content::JSONB;
    EXCEPTION
        WHEN OTHERS THEN
            RAISE EXCEPTION 'Node API HTTP %: %', v_response.status, left(COALESCE(v_response.content, ''), 500);
    END;

    IF v_response.status != 200 THEN
        RAISE EXCEPTION 'Node API HTTP %: %',
            v_response.status,
            COALESCE(v_content->>'error', left(COALESCE(v_response.content, ''), 500));
    END IF;

    IF COALESCE(v_content->>'ok', 'true') = 'false' THEN
        RAISE EXCEPTION '%', COALESCE(v_content->>'error', 'Node PostOrder failed');
    END IF;

    RETURN COALESCE(v_content->'order', v_content);
END;
$$;

COMMENT ON FUNCTION tbank_post_order_via_node(INTEGER, VARCHAR, NUMERIC, NUMERIC, VARCHAR, VARCHAR, BOOLEAN) IS
'PostOrder С‡РµСЂРµР· Р»РѕРєР°Р»СЊРЅС‹Р№ Node API (РѕР±С…РѕРґ SSL pgsql-http). РўСЂРµР±СѓРµС‚ РѕС‚РєСЂС‹С‚С‹Р№ UI.';

CREATE OR REPLACE FUNCTION tbank_resolve_bond_by_isin(p_account_id INTEGER,
    p_isin TEXT)
RETURNS JSONB
LANGUAGE plpgsql AS $$
DECLARE
    v_acc RECORD;
    v_isin TEXT;
    v_headers http_header[];
    v_response http_response;
    v_instrument JSONB;
    v_figi TEXT;
    v_lot INTEGER;
    v_price NUMERIC;
    v_price_resp JSONB;
    v_units NUMERIC;
    v_nano NUMERIC;
BEGIN
    SELECT * INTO v_acc FROM account_require_real_tbank(p_account_id) LIMIT 1;
    v_isin := upper(btrim(COALESCE(p_isin, '')));
    IF v_isin = '' THEN
        RETURN jsonb_build_object('error', 'empty_isin');
    END IF;

    PERFORM configure_http_ssl();
    v_headers := ARRAY[
        http_header('Authorization', 'Bearer ' || v_acc.token),
        http_header('Accept', 'application/json')
    ];

    -- BondBy by ISIN
    SELECT * INTO v_response FROM http((
        'POST',
        rtrim(v_acc.api_url, '/') || '/tinkoff.public.invest.api.contract.v1.InstrumentsService/BondBy',
        v_headers,
        'application/json',
        jsonb_build_object(
            'idType', 'INSTRUMENT_ID_TYPE_ISIN',
            'id', v_isin
        )::TEXT
    )::http_request);

    IF v_response.status = 200 THEN
        v_instrument := v_response.content::JSONB->'instrument';
    END IF;

    IF v_instrument IS NULL THEN
        SELECT * INTO v_response FROM http((
            'POST',
            rtrim(v_acc.api_url, '/') || '/tinkoff.public.invest.api.contract.v1.InstrumentsService/FindInstrument',
            v_headers,
            'application/json',
            jsonb_build_object('query', v_isin)::TEXT
        )::http_request);
        IF v_response.status = 200 THEN
            SELECT elem
            INTO v_instrument
            FROM jsonb_array_elements(
                COALESCE(v_response.content::JSONB->'instruments', '[]'::JSONB)
            ) AS elem
            WHERE upper(COALESCE(elem->>'isin', '')) = v_isin
               OR upper(COALESCE(elem->>'ticker', '')) = v_isin
            ORDER BY CASE
                WHEN upper(COALESCE(elem->>'instrumentType', '')) LIKE '%BOND%' THEN 0
                ELSE 1
            END
            LIMIT 1;
        END IF;
    END IF;

    IF v_instrument IS NULL THEN
        RETURN jsonb_build_object('error', 'instrument_not_found', 'isin', v_isin);
    END IF;

    v_figi := COALESCE(v_instrument->>'figi', v_instrument->>'uid');
    v_lot := GREATEST(1, COALESCE(NULLIF(v_instrument->>'lot', '')::INTEGER, 1));
    IF v_figi IS NULL OR btrim(v_figi) = '' THEN
        RETURN jsonb_build_object('error', 'no_figi', 'isin', v_isin);
    END IF;

    SELECT * INTO v_response FROM http((
        'POST',
        rtrim(v_acc.api_url, '/') || '/tinkoff.public.invest.api.contract.v1.MarketDataService/GetLastPrices',
        v_headers,
        'application/json',
        jsonb_build_object('figi', jsonb_build_array(v_figi))::TEXT
    )::http_request);

    IF v_response.status = 200 THEN
        v_price_resp := COALESCE(
            v_response.content::JSONB->'lastPrices'->0->'price',
            '{}'::JSONB
        );
        v_units := COALESCE((v_price_resp->>'units')::NUMERIC, 0);
        v_nano := COALESCE((v_price_resp->>'nano')::NUMERIC, 0);
        v_price := v_units + v_nano / 1000000000.0;
    END IF;

    -- РћР±Р»РёРіР°С†РёРё T-Bank: last price РѕР±С‹С‡РЅРѕ РІ % РЅРѕРјРёРЅР°Р»Р° (в‰€90вЂ“110) в†’ в‚Ѕ РїСЂРё РЅРѕРјРёРЅР°Р»Рµ 1000.
    IF v_price IS NOT NULL AND v_price > 0 AND v_price < 200 THEN
        v_price := v_price / 100.0 * 1000.0;
    ELSIF v_price IS NULL OR v_price <= 0 THEN
        v_price := 980;
    END IF;

    RETURN jsonb_build_object(
        'isin', v_isin,
        'figi', v_figi,
        'lot', v_lot,
        'price', v_price,
        'ticker', COALESCE(v_instrument->>'ticker', v_isin),
        'name', v_instrument->>'name'
    );
EXCEPTION
    WHEN undefined_function THEN
        RETURN jsonb_build_object('error', 'http_unavailable', 'isin', p_isin);
    WHEN OTHERS THEN
        RETURN jsonb_build_object('error', SQLERRM, 'isin', p_isin);
END;
$$;

COMMENT ON FUNCTION tbank_resolve_bond_by_isin(INTEGER, TEXT) IS
'FIGI/Р»РѕС‚/С†РµРЅР° РѕР±Р»РёРіР°С†РёРё РїРѕ ISIN (BondBy / FindInstrument + GetLastPrices); С‚РѕР»СЊРєРѕ real T-Bank';

-- Р“Р»Р°РІРЅР°СЏ load_prices в†’ HTTP (РїРµСЂРµРѕРїСЂРµРґРµР»РµРЅРёРµ Р·Р°РіР»СѓС€РµРє С‡Р°СЃС‚Рё A)

