CREATE OR REPLACE FUNCTION tbank_verify_token()
RETURNS JSONB
LANGUAGE plpgsql AS $$
DECLARE
    v_token TEXT;
    v_api_url TEXT;
    v_headers http_header[];
    v_response http_response;
    v_content JSONB;
BEGIN
    v_token := get_tbank_token();
    IF v_token IS NULL OR btrim(v_token) = '' THEN
        RETURN jsonb_build_object(
            'has_token', false,
            'valid', false,
            'error_message', 'РўРѕРєРµРЅ T-Bank РЅРµ Р·Р°РґР°РЅ'
        );
    END IF;

    PERFORM configure_http_ssl();
    v_api_url := get_tbank_api_url();

    v_headers := ARRAY[
        http_header('Authorization', 'Bearer ' || v_token),
        http_header('Accept', 'application/json')
    ];

    SELECT * INTO v_response FROM http((
        'POST',
        rtrim(v_api_url, '/')
            || '/tinkoff.public.invest.api.contract.v1.UsersService/GetAccounts',
        v_headers,
        'application/json',
        '{}'
    )::http_request);

    IF v_response.status = 200 THEN
        v_content := v_response.content::JSONB;
        IF v_content ? 'code' AND btrim(COALESCE(v_content->>'code', '')) NOT IN ('', '0') THEN
            RETURN jsonb_build_object(
                'has_token', true,
                'valid', false,
                'error_message', COALESCE(
                    v_content->>'message',
                    'T-Bank API РѕС‚РєР»РѕРЅРёР» С‚РѕРєРµРЅ'
                )
            );
        END IF;
        RETURN jsonb_build_object(
            'has_token', true,
            'valid', true,
            'error_message', NULL
        );
    END IF;

    IF v_response.status = 401 THEN
        RETURN jsonb_build_object(
            'has_token', true,
            'valid', false,
            'error_message', 'РўРѕРєРµРЅ T-Bank РЅРµР°РєС‚РёРІРµРЅ РёР»Рё РїСЂРѕСЃСЂРѕС‡РµРЅ. Р’РІРµРґРёС‚Рµ РЅРѕРІС‹Р№ API-С‚РѕРєРµРЅ.'
        );
    END IF;

    RETURN jsonb_build_object(
        'has_token', true,
        'valid', false,
        'error_message', format('T-Bank API HTTP %s', v_response.status)
    );
EXCEPTION
    WHEN OTHERS THEN
        RETURN jsonb_build_object(
            'has_token', true,
            'valid', false,
            'error_message', SQLERRM
        );
END;
$$;

COMMENT ON FUNCTION tbank_verify_token() IS
'РџСЂРѕРІРµСЂРєР° API-С‚РѕРєРµРЅР° T-Bank (UsersService/GetAccounts); JSON: has_token, valid, error_message';

CREATE OR REPLACE FUNCTION terminal_sync_real_trade_broker_fees(p_account_id INTEGER DEFAULT NULL,
    p_trade_id BIGINT DEFAULT NULL)
RETURNS JSONB
LANGUAGE plpgsql AS $$
DECLARE
    v_tr RECORD;
    v_order JSONB;
    v_comm NUMERIC;
    v_unit NUMERIC;
    v_lots NUMERIC;
    v_qty NUMERIC;
    v_new_price NUMERIC;
    v_new_qty NUMERIC;
    v_updated INTEGER := 0;
    v_not_found INTEGER := 0;
    v_errors JSONB := '[]'::JSONB;
BEGIN
    FOR v_tr IN
        SELECT tt.id, tt.account_id, tt.broker_order_id, tt.quantity, tt.price, tt.commission,
               COALESCE(s.lot_size, 0) AS lot_size
        FROM terminal_trades tt
        JOIN securities s ON s.id = tt.security_id
        JOIN accounts a ON a.id = tt.account_id
        WHERE tt.broker_order_id IS NOT NULL
          AND btrim(tt.broker_order_id) <> ''
          AND COALESCE(tt.broker_order_missing, FALSE) = FALSE
          AND tt.status <> 'rejected'
          -- РљРѕРјРёСЃСЃРёСЏ РµС‰С‘ РЅРµ РїРѕРґС‚СЏРЅСѓС‚Р° СЃ Р±СЂРѕРєРµСЂР°.
          AND tt.commission <= 0
          AND (p_account_id IS NULL OR tt.account_id = p_account_id)
          AND (p_trade_id IS NULL OR tt.id = p_trade_id)
          AND a.account_type = 'real'
          AND a.broker_id IN (SELECT id FROM brokers WHERE code = 'T-BANK')
        ORDER BY tt.id
    LOOP
        BEGIN
            v_order := tbank_get_order_state(v_tr.account_id, v_tr.broker_order_id);
            v_comm := tbank_order_commission(v_order);
            v_unit := tbank_order_unit_price(v_order);

            -- Р¤Р°РєС‚РёС‡РµСЃРєРё РёСЃРїРѕР»РЅРµРЅРЅРѕРµ РєРѕР»РёС‡РµСЃС‚РІРѕ = Р»РѕС‚С‹ Г— СЂР°Р·РјРµСЂ Р»РѕС‚Р° (Сѓ С‚РµСЂРјРёРЅР°Р»Р° quantity РІ С€С‚СѓРєР°С…).
            v_lots := COALESCE(
                NULLIF(regexp_replace(
                    COALESCE(v_order->>'lotsExecuted', v_order->>'lots_executed', '0'),
                    '[^0-9.\-]', '', 'g'
                ), ''),
                '0'
            )::numeric;
            v_qty := CASE WHEN v_lots > 0 AND v_tr.lot_size > 0
                          THEN v_lots * v_tr.lot_size END;

            v_new_price := CASE WHEN v_unit IS NOT NULL AND v_unit > 0
                                THEN round(v_unit, 6) ELSE v_tr.price END;
            v_new_qty := COALESCE(v_qty, v_tr.quantity);

            IF v_comm > 0
               OR v_new_price IS DISTINCT FROM v_tr.price
               OR v_new_qty IS DISTINCT FROM v_tr.quantity THEN
                UPDATE terminal_trades
                SET commission = CASE WHEN v_comm > 0 THEN round(v_comm, 6) ELSE commission END,
                    price = v_new_price,
                    quantity = v_new_qty,
                    amount = round(v_new_price * v_new_qty, 2)
                WHERE id = v_tr.id;
                v_updated := v_updated + 1;
            END IF;
        EXCEPTION
            WHEN OTHERS THEN
                -- T-Bank Р±РѕР»СЊС€Рµ РЅРµ Р·РЅР°РµС‚ Р·Р°СЏРІРєСѓ (СЃС‚Р°СЂР°СЏ/С‡СѓР¶РѕР№ РєРѕРЅС‚СѓСЂ) в†’ РїРѕРјРµС‡Р°РµРј Рё РІС‹РІРѕРґРёРј РёР· СЃРёРЅРєР°.
                IF SQLERRM ILIKE '%order not found%'
                   OR SQLERRM ILIKE '%not found%'
                   OR SQLERRM LIKE '%HTTP 404%' THEN
                    UPDATE terminal_trades SET broker_order_missing = TRUE WHERE id = v_tr.id;
                    v_not_found := v_not_found + 1;
                ELSE
                    v_errors := v_errors || jsonb_build_array(jsonb_build_object(
                        'trade_id', v_tr.id,
                        'order_id', v_tr.broker_order_id,
                        'error', SQLERRM
                    ));
                END IF;
        END;
    END LOOP;

    RETURN jsonb_build_object(
        'ok', TRUE,
        'updated', v_updated,
        'order_not_found', v_not_found,
        'errors', v_errors,
        'account_id', p_account_id,
        'trade_id', p_trade_id
    );
END;
$$;

COMMENT ON FUNCTION terminal_sync_real_trade_broker_fees(INTEGER, BIGINT) IS
'РџРѕРґС‚СЏРЅСѓС‚СЊ РєРѕРјРёСЃСЃРёСЋ Рё С„Р°РєС‚РёС‡РµСЃРєСѓСЋ С†РµРЅСѓ/РєРѕР»РёС‡РµСЃС‚РІРѕ (Р»РѕС‚С‹ Г— СЂР°Р·РјРµСЂ Р»РѕС‚Р°) СЃ T-Bank GetOrderState РґР»СЏ СЂСѓС‡РЅС‹С… СЃРґРµР»РѕРє С‚РµСЂРјРёРЅР°Р»Р° РїРѕ СЂРµР°Р»СЊРЅРѕРјСѓ СЃС‡С‘С‚Сѓ; РїРѕРјРµС‡Р°РµС‚ broker_order_missing РїСЂРё 404 (NULL = РІСЃРµ СЃС‡РµС‚Р°/СЃРґРµР»РєРё)';

-- Р”РµС‚РµРєС‚РѕСЂ РёСЃРїРѕСЂС‡РµРЅРЅРѕРіРѕ Р±РѕРµРІРѕРіРѕ FinRes:
--  1) finres <> 0 РїСЂРё РїРѕР»РЅРѕРј РѕС‚СЃСѓС‚СЃС‚РІРёРё РїР°РєРµС‚РѕРІ Р·Р°РєСЂС‹С‚РёСЏ (Р·РЅР°С‡РµРЅРёРµ РїРёСЃР°Р»РѕСЃСЊ РјРёРјРѕ build_lots
--     РёР»Рё РїР°РєРµС‚С‹ РїРѕС‚РµСЂСЏРЅС‹) вЂ” РєР°Рє Р±Р°Рі MTLRP +20737 (2026-08-18);
--  2) |finres| РјР°С‚РµРјР°С‚РёС‡РµСЃРєРё РЅРµРІРѕР·РјРѕР¶РµРЅ РґР»СЏ Р·Р°РїРёСЃР°РЅРЅС‹С… С†РµРЅ:
--     |finres| > qty Г— GREATEST(price_close, max(price_open РёР· РїР°РєРµС‚РѕРІ)) + РєРѕРјРёСЃСЃРёРё.

CREATE OR REPLACE FUNCTION trade_runner_health()
RETURNS JSONB
LANGUAGE plpgsql STABLE AS $$
DECLARE
    v_last TIMESTAMP;
    v_ttl INTEGER := trade_runner_stale_sec();
    v_enabled INTEGER := trade_runner_enabled_count();
    v_age NUMERIC;
    v_stale BOOLEAN;
    v_status TEXT;
    v_logics JSONB := '[]'::jsonb;
BEGIN
    v_last := trade_runner_last_ok_at();
    IF v_last IS NULL THEN
        v_age := NULL;
    ELSE
        v_age := EXTRACT(EPOCH FROM (LOCALTIMESTAMP - v_last));
    END IF;

    v_stale := trade_runner_is_stale();

    IF v_enabled <= 0 THEN
        v_status := 'idle';
    ELSIF trade_runner_require_ui() AND NOT trade_runner_ui_is_active() THEN
        v_status := 'ui_required';
    ELSIF v_stale THEN
        v_status := 'stale';
    ELSE
        v_status := 'ok';
    END IF;

    SELECT COALESCE(jsonb_agg(row_to_json(x)::jsonb ORDER BY x.id), '[]'::jsonb)
    INTO v_logics
    FROM (
        SELECT
            l.id,
            l.name,
            a.account_type,
            a.account_code,
            l.is_enabled,
            NULLIF(btrim(lp.param_value), '') AS last_trade_check_at,
            CASE
                WHEN NOT l.is_enabled OR NOT a.is_active THEN FALSE
                WHEN NULLIF(btrim(lp.param_value), '') IS NULL THEN TRUE
                WHEN (
                    CASE
                        WHEN NULLIF(btrim(lp.param_value), '') ~ '^\d{4}-\d{2}-\d{2}'
                        THEN NULLIF(btrim(lp.param_value), '')::TIMESTAMP
                        ELSE NULL
                    END
                ) IS NULL THEN TRUE
                ELSE (
                    CASE
                        WHEN NULLIF(btrim(lp.param_value), '') ~ '^\d{4}-\d{2}-\d{2}'
                        THEN NULLIF(btrim(lp.param_value), '')::TIMESTAMP
                        ELSE NULL
                    END
                ) < (LOCALTIMESTAMP - make_interval(secs => v_ttl))
            END AS stale
        FROM logics l
        JOIN accounts a ON a.id = l.account_id
        LEFT JOIN logic_params lp
          ON lp.logic_id = l.id
         AND lp.param_key = 'last_trade_check_at'
        WHERE l.is_enabled = TRUE
          AND a.is_active = TRUE
        ORDER BY l.id
    ) x;

    RETURN jsonb_build_object(
        'status', v_status,
        'ok', (v_status = 'ok' OR v_status = 'idle'),
        'stale', v_stale,
        'last_ok_at', CASE WHEN v_last IS NULL THEN NULL ELSE to_char(v_last, 'YYYY-MM-DD"T"HH24:MI:SS') END,
        'age_sec', v_age,
        'stale_sec', v_ttl,
        'enabled_count', v_enabled,
        'require_ui', trade_runner_require_ui(),
        'ui_active', trade_runner_ui_is_active(),
        'logics', v_logics,
        'at', to_char(CURRENT_TIMESTAMP, 'YYYY-MM-DD"T"HH24:MI:SS')
    );
END;
$$;

COMMENT ON FUNCTION trade_runner_health() IS
'РЎРІРѕРґРєР° РґР»СЏ UI/API: Р¶РёРІ Р»Рё С†РёРєР», stale-Р»РѕРіРёРєРё (real/fake), require_ui';

CREATE OR REPLACE FUNCTION trade_runner_is_stale()
RETURNS BOOLEAN
LANGUAGE plpgsql STABLE AS $$
DECLARE
    v_last TIMESTAMP;
    v_ttl INTEGER;
BEGIN
    IF trade_runner_enabled_count() <= 0 THEN
        RETURN FALSE;
    END IF;
    IF trade_runner_require_ui() AND NOT trade_runner_ui_is_active() THEN
        RETURN TRUE;
    END IF;
    v_last := trade_runner_last_ok_at();
    IF v_last IS NULL THEN
        RETURN TRUE;
    END IF;
    v_ttl := trade_runner_stale_sec();
    RETURN v_last < (LOCALTIMESTAMP - make_interval(secs => v_ttl));
END;
$$;

COMMENT ON FUNCTION trade_runner_is_stale() IS
'TRUE РµСЃР»Рё РµСЃС‚СЊ РІРєР»СЋС‡С‘РЅРЅС‹Рµ Р»РѕРіРёРєРё Рё С†РёРєР» РґР°РІРЅРѕ РЅРµ РѕС‚РјРµС‡Р°Р»СЃСЏ (РёР»Рё UI РѕР±СЏР·Р°С‚РµР»РµРЅ, РЅРѕ РјС‘СЂС‚РІ)';

CREATE OR REPLACE FUNCTION trade_runner_kick_stuck(p_max_age_sec INTEGER DEFAULT 180)
RETURNS JSONB
LANGUAGE plpgsql AS $$
DECLARE
    v_killed INTEGER := 0;
    v_unlocked BOOLEAN := FALSE;
    r RECORD;
    v_max INTEGER := GREATEST(COALESCE(p_max_age_sec, 180), 30);
BEGIN
    FOR r IN
        SELECT a.pid
        FROM pg_stat_activity a
        WHERE a.datname = current_database()
          AND a.pid <> pg_backend_pid()
          AND a.state <> 'idle'
          AND a.query_start IS NOT NULL
          AND a.query_start < (clock_timestamp() - make_interval(secs => v_max))
          AND (
              a.query ILIKE '%process_logic_trades%'
              OR a.query ILIKE '%process_logic_stops%'
              OR a.query ILIKE '%run_trade_cycle%'
              OR a.query ILIKE '%logic_park_excess_cash%'
              OR a.query ILIKE '%logic_refresh_market_data%'
          )
    LOOP
        IF pg_terminate_backend(r.pid) THEN
            v_killed := v_killed + 1;
        END IF;
    END LOOP;

    BEGIN
        v_unlocked := pg_advisory_unlock(hashtext('multilogictrade_run_trade_cycle'));
    EXCEPTION
        WHEN OTHERS THEN
            v_unlocked := FALSE;
    END;

    PERFORM app_tech_log_event(
        'trade-runner',
        'watchdog.kick',
        format('kick_stuck killed=%s unlocked=%s max_age=%s', v_killed, v_unlocked, v_max),
        'postgresql',
        'event',
        NULL,
        NULL,
        NULL,
        jsonb_build_object('killed', v_killed, 'unlocked', v_unlocked, 'max_age_sec', v_max)
    );

    RETURN jsonb_build_object(
        'killed', v_killed,
        'unlocked', v_unlocked,
        'max_age_sec', v_max
    );
END;
$$;

COMMENT ON FUNCTION trade_runner_kick_stuck(INTEGER) IS
'РЎРЅСЏС‚СЊ Р·Р°РІРёСЃС€РёРµ СЃРµСЃСЃРёРё process_logic_* / run_trade_cycle Рё РїРѕРїС‹С‚Р°С‚СЊСЃСЏ СЃРЅСЏС‚СЊ advisory lock';

CREATE OR REPLACE FUNCTION trade_runner_last_ok_at()
RETURNS TIMESTAMP
LANGUAGE plpgsql STABLE AS $$
DECLARE
    v_raw TEXT;
    v_ts_part TEXT;
BEGIN
    SELECT btrim(pv.value)
    INTO v_raw
    FROM parameter_values pv
    JOIN parameter_types pt ON pt.id = pv.parameter_type_id
    JOIN parameter_sets ps ON ps.id = pv.parameter_set_id
    WHERE ps.name = 'Default'
      AND pt.short_name = 'APP_TRADE_RUNNER_LAST_OK'
    LIMIT 1;

    IF COALESCE(v_raw, '') = '' THEN
        RETURN NULL;
    END IF;

    v_ts_part := split_part(v_raw, '|', 1);
    BEGIN
        RETURN v_ts_part::TIMESTAMP;
    EXCEPTION
        WHEN OTHERS THEN
            RETURN NULL;
    END;
END;
$$;

COMMENT ON FUNCTION trade_runner_last_ok_at() IS
'TIMESTAMP РїРѕСЃР»РµРґРЅРµРіРѕ Р¶РёРІРѕРіРѕ С†РёРєР»Р° РёР· APP_TRADE_RUNNER_LAST_OK';

CREATE OR REPLACE FUNCTION trade_runner_require_ui()
RETURNS BOOLEAN
LANGUAGE plpgsql STABLE AS $$
DECLARE
    v_raw TEXT;
BEGIN
    SELECT lower(btrim(pv.value))
    INTO v_raw
    FROM parameter_values pv
    JOIN parameter_types pt ON pt.id = pv.parameter_type_id
    JOIN parameter_sets ps ON ps.id = pv.parameter_set_id
    WHERE ps.name = 'Default'
      AND pt.short_name = 'APP_TRADE_RUNNER_REQUIRE_UI'
    LIMIT 1;

    IF v_raw IS NULL OR v_raw = '' THEN
        RETURN FALSE;
    END IF;
    RETURN v_raw IN ('1', 'true', 'yes', 'on', 't');
END;
$$;

COMMENT ON FUNCTION trade_runner_require_ui() IS
'TRUE С‚РѕР»СЊРєРѕ РµСЃР»Рё APP_TRADE_RUNNER_REQUIRE_UI РІРєР»СЋС‡С‘РЅ; РїРѕ СѓРјРѕР»С‡Р°РЅРёСЋ FALSE (headless / СЃРµСЂРІРµСЂ)';

CREATE OR REPLACE FUNCTION trade_runner_stale_sec()
RETURNS INTEGER
LANGUAGE sql
IMMUTABLE AS $$
    SELECT 90;
$$;

COMMENT ON FUNCTION trade_runner_stale_sec() IS
'РЎРєРѕР»СЊРєРѕ СЃРµРєСѓРЅРґ Р±РµР· СѓСЃРїРµС€РЅРѕРіРѕ С†РёРєР»Р° = С‚РѕСЂРіРѕРІР»СЏ В«СЃРїРёС‚В» (Node/pg_cron watchdog)';

CREATE OR REPLACE FUNCTION trade_runner_ui_heartbeat_ttl_sec()
RETURNS INTEGER
LANGUAGE sql
IMMUTABLE AS $$
    SELECT 90;
$$;

COMMENT ON FUNCTION trade_runner_ui_heartbeat_ttl_sec() IS
'РЎРєРѕР»СЊРєРѕ СЃРµРєСѓРЅРґ heartbeat Angular СЃС‡РёС‚Р°РµС‚СЃСЏ Р°РєС‚РёРІРЅС‹Рј';

CREATE OR REPLACE FUNCTION trade_runner_ui_is_active()
RETURNS BOOLEAN
LANGUAGE plpgsql STABLE AS $$
DECLARE
    v_raw TEXT;
    v_ts TIMESTAMP;
    v_ttl INTEGER;
BEGIN
    SELECT btrim(pv.value)
    INTO v_raw
    FROM parameter_values pv
    JOIN parameter_types pt ON pt.id = pv.parameter_type_id
    JOIN parameter_sets ps ON ps.id = pv.parameter_set_id
    WHERE ps.name = 'Default'
      AND pt.short_name = 'APP_TRADE_RUNNER_HB'
    LIMIT 1;

    IF COALESCE(v_raw, '') = '' THEN
        RETURN FALSE;
    END IF;

    BEGIN
        v_ts := v_raw::TIMESTAMP;
    EXCEPTION
        WHEN OTHERS THEN
            RETURN FALSE;
    END;

    v_ttl := trade_runner_ui_heartbeat_ttl_sec();
    RETURN v_ts >= (LOCALTIMESTAMP - make_interval(secs => v_ttl));
END;
$$;

COMMENT ON FUNCTION trade_runner_ui_is_active() IS
'TRUE, РµСЃР»Рё Angular РЅРµРґР°РІРЅРѕ СЃР»Р°Р» heartbeat (APP_TRADE_RUNNER_HB)';

CREATE OR REPLACE FUNCTION trade_runner_watchdog_tick()
RETURNS JSONB
LANGUAGE plpgsql AS $$
DECLARE
    v_kick JSONB;
    v_cycle JSONB;
BEGIN
    IF NOT trade_runner_is_stale() THEN
        RETURN jsonb_build_object(
            'ok', TRUE,
            'action', 'none',
            'health', trade_runner_health()
        );
    END IF;

    v_kick := trade_runner_kick_stuck(180);
    v_cycle := run_trade_cycle();

    IF COALESCE((v_cycle->>'skipped')::boolean, FALSE) IS NOT TRUE THEN
        CALL touch_trade_runner_last_ok('postgresql-watchdog');
    ELSIF (v_cycle->>'reason') = 'ui_inactive' THEN
        NULL;
    ELSE
        CALL touch_trade_runner_last_ok('postgresql-watchdog-skip');
    END IF;

    PERFORM app_tech_log_event(
        'trade-runner',
        'watchdog.tick',
        format('staleв†’kick+cycle reason=%s', COALESCE(v_cycle->>'reason', 'ran')),
        'postgresql',
        'event',
        NULL,
        NULL,
        NULL,
        jsonb_build_object('kick', v_kick, 'cycle', v_cycle)
    );

    RETURN jsonb_build_object(
        'ok', TRUE,
        'action', 'raised',
        'kick', v_kick,
        'cycle', v_cycle,
        'health', trade_runner_health()
    );
END;
$$;

COMMENT ON FUNCTION trade_runner_watchdog_tick() IS
'Р•СЃР»Рё С†РёРєР» СЃРїРёС‚ вЂ” kick stuck + run_trade_cycle; РёРЅР°С‡Рµ no-op. Р”Р»СЏ pg_cron / Node.';
-- @end trade_runner_watchdog

CREATE OR REPLACE PROCEDURE cleanup_old_prices(p_days_to_keep INTEGER DEFAULT 365)
LANGUAGE plpgsql AS $$
DECLARE
    v_cutoff_date TIMESTAMP;
    v_deleted_count INTEGER;
BEGIN
    v_cutoff_date := CURRENT_TIMESTAMP - (p_days_to_keep || ' days')::INTERVAL;

    DELETE FROM prices
    WHERE dt < v_cutoff_date;

    GET DIAGNOSTICS v_deleted_count = ROW_COUNT;
    RAISE NOTICE 'РЈРґР°Р»РµРЅРѕ % СЃС‚Р°СЂС‹С… СЃРІРµС‡РµР№ (СЃС‚Р°СЂС€Рµ % РґРЅРµР№)', v_deleted_count, p_days_to_keep;
END;
$$;

COMMENT ON PROCEDURE cleanup_old_prices(INTEGER) IS 
'РЈРґР°Р»СЏРµС‚ С†РµРЅС‹ СЃС‚Р°СЂС€Рµ СѓРєР°Р·Р°РЅРЅРѕРіРѕ РєРѕР»РёС‡РµСЃС‚РІР° РґРЅРµР№ (РїРѕ СѓРјРѕР»С‡Р°РЅРёСЋ 365).';

-- @include sql/cleanup_trading_disk_space.sql
-- ============================================
-- РћС‡РёСЃС‚РєР° РґРёСЃРєР°: СЃС‚Р°СЂС‹Рµ/Р»РёС€РЅРёРµ С†РµРЅС‹, С‚РµСЃС‚С‹, tech log, indicator_values
-- Р’С‹Р·РѕРІ: SELECT cleanup_trading_disk_space();
--         SELECT cleanup_unused_indicator_values();
-- Advisory lock: РЅРµ РїРµСЂРµСЃРµРєР°РµС‚СЃСЏ СЃ С‚РѕСЂРіРѕРІР»РµР№ / РІС‚РѕСЂРѕР№ РѕС‡РёСЃС‚РєРѕР№.
