CREATE OR REPLACE PROCEDURE load_moex_interval_candles_paginated(p_security_id INTEGER,
    p_date_from DATE,
    p_date_to DATE,
    p_contract_prefix VARCHAR DEFAULT NULL,
    p_moex_interval INTEGER DEFAULT 1)
LANGUAGE plpgsql AS $$
DECLARE
    v_src_tf_id INTEGER;
    v_src_tf VARCHAR(20);
    v_day DATE;
    v_start INTEGER;
    v_batch INTEGER;
    v_total INTEGER := 0;
    v_interval INTEGER;
BEGIN
    v_interval := COALESCE(NULLIF(p_moex_interval, 0), 1);
    v_src_tf := CASE v_interval
        WHEN 1 THEN 'M1'
        WHEN 10 THEN 'M10'
        WHEN 60 THEN 'H1'
        ELSE 'M1'
    END;

    SELECT t.id INTO v_src_tf_id FROM timeframes t WHERE t.tf = v_src_tf LIMIT 1;
    IF v_src_tf_id IS NULL THEN
        RAISE EXCEPTION 'timeframe % not found for MOEX interval %', v_src_tf, v_interval;
    END IF;

    v_day := p_date_from;
    WHILE v_day <= p_date_to LOOP
        v_start := 0;
        LOOP
            CALL load_prices_from_moex_http(
                p_security_id, v_src_tf_id, v_day, v_day, p_contract_prefix, v_interval, v_start
            );
            SELECT records_loaded INTO v_batch
            FROM price_load_log
            WHERE security_id = p_security_id
              AND timeframe_id = v_src_tf_id
              AND date_from = v_day
              AND date_to = v_day
              AND source = 'MOEX'
            ORDER BY id DESC
            LIMIT 1;
            v_batch := COALESCE(v_batch, 0);
            v_total := v_total + v_batch;
            EXIT WHEN v_batch = 0 OR v_batch < 500;
            v_start := v_start + 500;
        END LOOP;
        v_day := v_day + 1;
    END LOOP;

    RAISE NOTICE 'MOEX % paginated: % СЃРІРµС‡РµР№ (% вЂ” %)', v_src_tf, v_total, p_date_from, p_date_to;
END;
$$;

COMMENT ON PROCEDURE load_moex_interval_candles_paginated(INTEGER, DATE, DATE, VARCHAR, INTEGER) IS
'Р—Р°РіСЂСѓР·РєР° MOEX FORTS/ISS РїРѕ РґРЅСЏРј СЃ РїР°РіРёРЅР°С†РёРµР№ (interval 1/10/60)';

-- РЎРѕРІРјРµСЃС‚РёРјРѕСЃС‚СЊ: СЃС‚Р°СЂРѕРµ РёРјСЏ в†’ M1

