CREATE OR REPLACE PROCEDURE load_prices_from_moex(p_security_id INTEGER,
    p_timeframe_id INTEGER,
    p_date_from DATE,
    p_date_to DATE)
LANGUAGE plpgsql AS $$
DECLARE
    v_prefix VARCHAR(50);
    v_tf_name VARCHAR(20);
    v_is_future BOOLEAN;
    v_engine VARCHAR(20) := 'stock';
    v_market VARCHAR(20) := 'shares';
    v_board VARCHAR(20) := 'TQBR';
    v_start_dt TIMESTAMP;
    v_end_dt TIMESTAMP;
    v_url TEXT;
    v_records_loaded INTEGER := 0;
BEGIN
    SELECT sp.prefix INTO v_prefix
    FROM security_prefixes sp
    WHERE sp.security_id = p_security_id AND sp.exchange_id = 1;

    IF v_prefix IS NULL THEN
        RAISE EXCEPTION 'РџСЂРµС„РёРєСЃ РЅРµ РЅР°Р№РґРµРЅ РґР»СЏ security_id=%', p_security_id;
    END IF;

    SELECT tf INTO v_tf_name
    FROM timeframes WHERE id = p_timeframe_id;

    -- РћРїСЂРµРґРµР»СЏРµРј СЂС‹РЅРѕРє
    SELECT 
        CASE st.name
            WHEN 'Stock' THEN 'stock'
            WHEN 'Futures' THEN 'futures'
            WHEN 'Bond' THEN 'bonds'
            WHEN 'Index' THEN 'stock'
            ELSE 'stock'
        END,
        CASE st.name
            WHEN 'Stock' THEN 'shares'
            WHEN 'Futures' THEN 'forts'
            WHEN 'Bond' THEN 'bonds'
            WHEN 'Index' THEN 'index'
            ELSE 'shares'
        END,
        CASE st.name
            WHEN 'Stock' THEN 'TQBR'
            WHEN 'Futures' THEN 'RFUD'
            ELSE 'TQBR'
        END
    INTO v_engine, v_market, v_board
    FROM securities s
    JOIN security_types st ON s.security_type_id = st.id
    WHERE s.id = p_security_id;

    -- Р”Р»СЏ С„СЊСЋС‡РµСЂСЃРѕРІ РѕРїСЂРµРґРµР»СЏРµРј Р°РєС‚РёРІРЅС‹Р№ РєРѕРЅС‚СЂР°РєС‚
    IF v_engine = 'futures' THEN
        v_prefix := get_active_future_prefix(p_security_id, p_date_from);
        IF v_prefix IS NULL THEN
            RAISE EXCEPTION 'РђРєС‚РёРІРЅС‹Р№ С„СЊСЋС‡РµСЂСЃ РЅРµ РЅР°Р№РґРµРЅ РґР»СЏ security_id=% РЅР° РґР°С‚Сѓ %', p_security_id, p_date_from;
        END IF;
    END IF;

    v_start_dt := p_date_from::TIMESTAMP;
    v_end_dt := (p_date_to + INTERVAL '1 day')::TIMESTAMP;

    -- Р¤РѕСЂРјРёСЂСѓРµРј URL MOEX ISS API
    v_url := format(
        'https://iss.moex.com/iss/engines/%s/markets/%s/boards/%s/securities/%s/candles.json?from=%s&till=%s&interval=%s',
        v_engine, v_market, v_board, v_prefix,
        to_char(v_start_dt, 'YYYY-MM-DD'),
        to_char(v_end_dt, 'YYYY-MM-DD'),
        get_moex_candle_interval(v_tf_name)::TEXT
    );

    RAISE NOTICE 'MOEX API URL: %', v_url;

    -- Р›РѕРіРёСЂСѓРµРј РїРѕРїС‹С‚РєСѓ
    INSERT INTO price_load_log (security_id, timeframe_id, date_from, date_to, source, records_loaded)
    VALUES (p_security_id, p_timeframe_id, p_date_from, p_date_to, 'MOEX', 0);

EXCEPTION
    WHEN OTHERS THEN
        INSERT INTO price_load_log (security_id, timeframe_id, date_from, date_to, source, records_loaded, error_message)
        VALUES (p_security_id, p_timeframe_id, p_date_from, p_date_to, 'MOEX', 0, SQLERRM);
        RAISE;
END;
$$;

COMMENT ON PROCEDURE load_prices_from_moex(INTEGER, INTEGER, DATE, DATE) IS 
'Р—Р°РіСЂСѓР¶Р°РµС‚ С†РµРЅС‹ С‡РµСЂРµР· РѕС‚РєСЂС‹С‚РѕРµ API MOEX ISS. Р”Р»СЏ С„СЊСЋС‡РµСЂСЃРѕРІ РІС‹Р±РёСЂР°РµС‚ Р°РєС‚РёРІРЅС‹Р№ РєРѕРЅС‚СЂР°РєС‚.';

-- ============================================
-- Р“Р›РђР’РќРђРЇ РџР РћР¦Р•Р”РЈР Рђ: load_prices
-- РЎРЅР°С‡Р°Р»Р° T-Bank, РµСЃР»Рё РЅРµ СЃСЂР°Р±РѕС‚Р°Р»Рѕ -- MOEX
-- ============================================

CREATE OR REPLACE PROCEDURE load_prices_from_moex_http(p_security_id INTEGER,
    p_timeframe_id INTEGER,
    p_date_from DATE,
    p_date_to DATE,
    p_contract_prefix VARCHAR DEFAULT NULL,
    p_moex_interval INTEGER DEFAULT NULL,
    p_start INTEGER DEFAULT 0)
LANGUAGE plpgsql AS $$
DECLARE
    v_prefix VARCHAR(50);
    v_tf_name VARCHAR(20);
    v_sec_type VARCHAR(50);
    v_engine VARCHAR(20);
    v_market VARCHAR(20);
    v_board VARCHAR(20);
    v_api_url TEXT;
    v_response http_response;
    v_status INTEGER;
    v_content JSONB;
    v_candles_data JSONB;
    v_columns JSONB;
    v_col_map JSONB;
    v_row JSONB;
    v_row_idx INTEGER;
    v_col_idx INTEGER;
    v_dt TIMESTAMP;
    v_open NUMERIC(18,6);
    v_high NUMERIC(18,6);
    v_low NUMERIC(18,6);
    v_close NUMERIC(18,6);
    v_volume NUMERIC(20,2);
    v_value NUMERIC(20,2);
    v_records_loaded INTEGER := 0;
    v_store_contract VARCHAR(50);
    v_moex_ticker VARCHAR(50);
    v_moex_interval INTEGER;
BEGIN
    PERFORM configure_http_ssl();

    SELECT tf INTO v_tf_name FROM timeframes WHERE id = p_timeframe_id;
    v_moex_interval := COALESCE(p_moex_interval, get_moex_candle_interval(v_tf_name));

    IF p_contract_prefix IS NOT NULL THEN
        v_prefix := p_contract_prefix;
        v_store_contract := p_contract_prefix;
        v_engine := 'futures';
        v_market := 'forts';
        v_board := 'RFUD';
        SELECT fe.moex_secid INTO v_moex_ticker
        FROM futures_expirations fe
        WHERE fe.security_id = p_security_id
          AND fe.prefix = p_contract_prefix
        LIMIT 1;
        v_moex_ticker := COALESCE(NULLIF(btrim(v_moex_ticker), ''), v_prefix);
    ELSE
        SELECT sp.prefix, st.name INTO v_prefix, v_sec_type
        FROM securities s
        JOIN security_types st ON s.security_type_id = st.id
        JOIN security_prefixes sp ON s.id = sp.security_id
        WHERE s.id = p_security_id AND sp.exchange_id = 1;

        IF v_prefix IS NULL THEN
            RAISE EXCEPTION 'РџСЂРµС„РёРєСЃ РЅРµ РЅР°Р№РґРµРЅ РґР»СЏ security_id=%', p_security_id;
        END IF;

        v_store_contract := NULL;
        v_engine := CASE v_sec_type
            WHEN 'Stock' THEN 'stock'
            WHEN 'Futures' THEN 'futures'
            WHEN 'Bond' THEN 'bonds'
            WHEN 'Index' THEN 'stock'
            ELSE 'stock'
        END;
        v_market := CASE v_sec_type
            WHEN 'Stock' THEN 'shares'
            WHEN 'Futures' THEN 'forts'
            WHEN 'Bond' THEN 'bonds'
            WHEN 'Index' THEN 'index'
            ELSE 'shares'
        END;
        v_board := CASE v_sec_type
            WHEN 'Stock' THEN 'TQBR'
            WHEN 'Futures' THEN 'RFUD'
            WHEN 'Bond' THEN 'TQOB'
            ELSE 'TQBR'
        END;

        IF v_engine = 'futures' THEN
            v_prefix := get_active_future_prefix(p_security_id, p_date_to);
            IF v_prefix IS NULL THEN
                RAISE EXCEPTION 'РђРєС‚РёРІРЅС‹Р№ С„СЊСЋС‡РµСЂСЃ РЅРµ РЅР°Р№РґРµРЅ РґР»СЏ security_id=% РЅР° РґР°С‚Сѓ %',
                    p_security_id, p_date_to;
            END IF;
            v_store_contract := v_prefix;
        END IF;
    END IF;

    -- FORTS ISS: РЅРµС‚ M15/M5/M2/вЂ¦ вЂ” С‚РѕР»СЊРєРѕ 1, 10, 60, 24, 7, 31, 4 в†’ M10/M1 + resample
    IF v_engine = 'futures'
       AND v_moex_interval NOT IN (1, 10, 60, 24, 7, 31, 4)
    THEN
        CALL load_prices_moex_via_m1_resample(
            p_security_id, p_timeframe_id, p_date_from, p_date_to, p_contract_prefix
        );
        RETURN;
    END IF;

    IF p_contract_prefix IS NOT NULL THEN
        v_prefix := v_moex_ticker;
    END IF;

    v_api_url := format(
        'https://iss.moex.com/iss/engines/%s/markets/%s/boards/%s/securities/%s/candles.json?from=%s&till=%s&interval=%s',
        v_engine, v_market, v_board, v_prefix,
        p_date_from::TEXT,
        p_date_to::TEXT,
        v_moex_interval::TEXT
    );
    IF COALESCE(p_start, 0) > 0 THEN
        v_api_url := v_api_url || format('&start=%s', p_start);
    END IF;

    RAISE NOTICE 'MOEX API URL: %', v_api_url;

    -- Р’С‹РїРѕР»РЅСЏРµРј GET-Р·Р°РїСЂРѕСЃ С‡РµСЂРµР· pgsql-http
    SELECT * INTO v_response FROM http_get(v_api_url);

    v_status := v_response.status;
    IF v_status != 200 THEN
        RAISE EXCEPTION 'MOEX API РІРµСЂРЅСѓР» СЃС‚Р°С‚СѓСЃ %: %', v_status, v_response.content;
    END IF;

    -- ============================================================
    -- Р‘Р›РћРљ 4: Р РђР—Р‘РћР  JSON-РћРўР’Р•РўРђ MOEX
    -- ============================================================
    v_content := v_response.content::JSONB;

    -- MOEX РІРѕР·РІСЂР°С‰Р°РµС‚ РґР°РЅРЅС‹Рµ РІ С„РѕСЂРјР°С‚Рµ: {"candles": {"columns": [...], "data": [...]}}
    v_candles_data := v_content->'candles'->'data';
    v_columns := v_content->'candles'->'columns';

    IF v_candles_data IS NULL OR jsonb_array_length(v_candles_data) = 0 THEN
        INSERT INTO price_load_log (security_id, timeframe_id, date_from, date_to, source, records_loaded, error_message)
        VALUES (p_security_id, p_timeframe_id, p_date_from, p_date_to, 'MOEX', 0,
            format('MOEX ISS: РЅРµС‚ СЃРІРµС‡РµР№ %s Р·Р° РїРµСЂРёРѕРґ (interval=%s; URL: %s)',
                v_tf_name, v_moex_interval, left(v_api_url, 160)));
        RAISE NOTICE 'MOEX РІРµСЂРЅСѓР» РїСѓСЃС‚РѕР№ РјР°СЃСЃРёРІ СЃРІРµС‡РµР№';
        RETURN;
    END IF;

    -- РЎРѕР·РґР°РµРј РјР°РїРїРёРЅРі РєРѕР»РѕРЅРѕРє: РЅР°Р·РІР°РЅРёРµ -> РёРЅРґРµРєСЃ
    v_col_map := '{}'::JSONB;
    FOR v_col_idx IN 0 .. jsonb_array_length(v_columns) - 1
    LOOP
        v_col_map := jsonb_set(v_col_map, ARRAY[v_columns->>v_col_idx], to_jsonb(v_col_idx));
    END LOOP;

    -- ============================================================
    -- Р‘Р›РћРљ 5: Р—РђРџРРЎР¬ РЎР’Р•Р§Р•Р™ Р’ Р‘РђР—РЈ
    -- ============================================================
    FOR v_row_idx IN 0 .. jsonb_array_length(v_candles_data) - 1
    LOOP
        v_row := v_candles_data->v_row_idx;

        -- РР·РІР»РµРєР°РµРј РґР°РЅРЅС‹Рµ РїРѕ РёРЅРґРµРєСЃР°Рј РєРѕР»РѕРЅРѕРє
        v_dt := (v_row->>(v_col_map->>'begin')::INTEGER)::TIMESTAMP;
        v_open := (v_row->>(v_col_map->>'open')::INTEGER)::NUMERIC;
        v_high := (v_row->>(v_col_map->>'high')::INTEGER)::NUMERIC;
        v_low := (v_row->>(v_col_map->>'low')::INTEGER)::NUMERIC;
        v_close := (v_row->>(v_col_map->>'close')::INTEGER)::NUMERIC;
        v_volume := (v_row->>(v_col_map->>'volume')::INTEGER)::NUMERIC;
        v_value := (v_row->>(v_col_map->>'value')::INTEGER)::NUMERIC;

        -- Р’СЃС‚Р°РІР»СЏРµРј СЃРІРµС‡Сѓ
        CALL insert_candle(
            p_security_id, p_timeframe_id, v_dt,
            v_open, v_high, v_low, v_close,
            v_volume, v_value, v_store_contract
        );

        v_records_loaded := v_records_loaded + 1;
    END LOOP;

    -- ============================================================
    -- Р‘Р›РћРљ 6: Р›РћР“РР РћР’РђРќРР•
    -- ============================================================
    INSERT INTO price_load_log (
        security_id, timeframe_id, date_from, date_to,
        source, records_loaded, contract_prefix
    )
    VALUES (
        p_security_id, p_timeframe_id, p_date_from, p_date_to,
        'MOEX', v_records_loaded, v_store_contract
    );

    RAISE NOTICE 'Р—Р°РіСЂСѓР¶РµРЅРѕ % СЃРІРµС‡РµР№ РёР· MOEX (РєРѕРЅС‚СЂР°РєС‚ %)', v_records_loaded, v_store_contract;

EXCEPTION
    WHEN OTHERS THEN
        INSERT INTO price_load_log (
            security_id, timeframe_id, date_from, date_to,
            source, records_loaded, contract_prefix, error_message
        )
        VALUES (
            p_security_id, p_timeframe_id, p_date_from, p_date_to,
            'MOEX', 0, v_store_contract, SQLERRM
        );
        RAISE;
END;
$$;

COMMENT ON PROCEDURE load_prices_from_moex_http(INTEGER, INTEGER, DATE, DATE, VARCHAR, INTEGER, INTEGER) IS 
'Р—Р°РіСЂСѓР·РєР° MOEX ISS. p_contract_prefix вЂ” С‚РёРєРµСЂ РєРѕРЅС‚СЂР°РєС‚Р°; p_moex_interval/p_start вЂ” M1 pagination.';

-- @include sql/load_prices_moex_resample.sql (СЃРј. sql/load_prices_moex_resample.sql вЂ” РґСѓР±Р»РёСЂСѓРµС‚СЃСЏ РЅРёР¶Рµ)
-- MOEX fallback РїРѕСЃР»Рµ РЅРµСѓРґР°С‡Рё T-Bank (РѕС€РёР±РєР° РёР»Рё 0 СЃРІРµС‡РµР№); base resample РґР»СЏ intraday TF.
-- FORTS ISS: С‚РѕР»СЊРєРѕ interval 1,10,60,24,7,31,4 вЂ” РґР»СЏ M15 Р±РµСЂС‘Рј M10 (Р±С‹СЃС‚СЂРµРµ M1).

CREATE OR REPLACE PROCEDURE load_prices_from_tbank(p_security_id INTEGER,
    p_timeframe_id INTEGER,
    p_date_from DATE,
    p_date_to DATE)
LANGUAGE plpgsql AS $$
DECLARE
    v_prefix VARCHAR(50);
    v_tf_sec INTEGER;
    v_tf_name VARCHAR(20);
    v_is_future BOOLEAN;
    v_token TEXT;
    v_start_ts TIMESTAMP;
    v_end_ts TIMESTAMP;
    v_records_loaded INTEGER := 0;
BEGIN
    -- РџРѕР»СѓС‡Р°РµРј РїСЂРµС„РёРєСЃ
    SELECT sp.prefix INTO v_prefix
    FROM security_prefixes sp
    WHERE sp.security_id = p_security_id AND sp.exchange_id = 1;

    IF v_prefix IS NULL THEN
        RAISE EXCEPTION 'РџСЂРµС„РёРєСЃ РЅРµ РЅР°Р№РґРµРЅ РґР»СЏ security_id=%', p_security_id;
    END IF;

    SELECT sec, tf INTO v_tf_sec, v_tf_name
    FROM timeframes WHERE id = p_timeframe_id;

    -- РџСЂРѕРІРµСЂСЏРµРј, СЌС‚Рѕ С„СЊСЋС‡РµСЂСЃ РёР»Рё РЅРµС‚
    SELECT (st.name = 'Futures') INTO v_is_future
    FROM securities s
    JOIN security_types st ON s.security_type_id = st.id
    WHERE s.id = p_security_id;

    -- Р”Р»СЏ С„СЊСЋС‡РµСЂСЃР° РѕРїСЂРµРґРµР»СЏРµРј Р°РєС‚РёРІРЅС‹Р№ РєРѕРЅС‚СЂР°РєС‚
    IF v_is_future THEN
        v_prefix := get_active_future_prefix(p_security_id, p_date_from);
        IF v_prefix IS NULL THEN
            RAISE EXCEPTION 'РђРєС‚РёРІРЅС‹Р№ С„СЊСЋС‡РµСЂСЃ РЅРµ РЅР°Р№РґРµРЅ РґР»СЏ security_id=% РЅР° РґР°С‚Сѓ %', p_security_id, p_date_from;
        END IF;
    END IF;

    -- РџРѕР»СѓС‡Р°РµРј С‚РѕРєРµРЅ
    v_token := get_tbank_token();
    IF v_token IS NULL THEN
        RAISE EXCEPTION 'T-Bank С‚РѕРєРµРЅ РЅРµ РЅР°Р№РґРµРЅ. Р—Р°РґР°Р№С‚Рµ TBANK_API_TOKEN РІ РїР°СЂР°РјРµС‚СЂР°С… РёР»Рё token_encrypted РІ accounts.';
    END IF;

    v_start_ts := p_date_from::TIMESTAMP;
    v_end_ts := (p_date_to + INTERVAL '1 day')::TIMESTAMP;

    RAISE NOTICE 'T-Bank API Р·Р°РїСЂРѕСЃ: figi=%, interval=%, from=%, to=%', 
        v_prefix, v_tf_name, v_start_ts, v_end_ts;

    -- Р›РѕРіРёСЂСѓРµРј РїРѕРїС‹С‚РєСѓ
    INSERT INTO price_load_log (security_id, timeframe_id, date_from, date_to, source, records_loaded)
    VALUES (p_security_id, p_timeframe_id, p_date_from, p_date_to, 'T-BANK', 0);

EXCEPTION
    WHEN OTHERS THEN
        INSERT INTO price_load_log (security_id, timeframe_id, date_from, date_to, source, records_loaded, error_message)
        VALUES (p_security_id, p_timeframe_id, p_date_from, p_date_to, 'T-BANK', 0, SQLERRM);
        RAISE;
END;
$$;

COMMENT ON PROCEDURE load_prices_from_tbank(INTEGER, INTEGER, DATE, DATE) IS 
'Р—Р°РіСЂСѓР¶Р°РµС‚ С†РµРЅС‹ С‡РµСЂРµР· API T-Bank. Р”Р»СЏ С„СЊСЋС‡РµСЂСЃРѕРІ Р°РІС‚РѕРјР°С‚РёС‡РµСЃРєРё РІС‹Р±РёСЂР°РµС‚ Р°РєС‚РёРІРЅС‹Р№ РєРѕРЅС‚СЂР°РєС‚.';

-- ============================================
-- РџСЂРѕС†РµРґСѓСЂР°: load_prices_from_moex
-- Р—Р°РіСЂСѓР¶Р°РµС‚ С†РµРЅС‹ С‡РµСЂРµР· API MOEX (ISS)
-- ============================================

CREATE OR REPLACE PROCEDURE load_prices_from_tbank_http(p_security_id INTEGER,
    p_timeframe_id INTEGER,
    p_date_from DATE,
    p_date_to DATE,
    p_contract_prefix VARCHAR DEFAULT NULL,
    p_contract_figi VARCHAR DEFAULT NULL)
LANGUAGE plpgsql AS $$
DECLARE
    v_prefix VARCHAR(50);
    v_tbank_figi VARCHAR(50);
    v_tf_name VARCHAR(20);
    v_is_future BOOLEAN;
    v_token TEXT;
    v_api_url TEXT;
    v_payload TEXT;
    v_headers http_header[];
    v_response http_response;
    v_status INTEGER;
    v_content JSONB;
    v_candles JSONB;
    v_candle JSONB;
    v_candle_time TIMESTAMP;
    v_candle_open NUMERIC(18,6);
    v_candle_high NUMERIC(18,6);
    v_candle_low NUMERIC(18,6);
    v_candle_close NUMERIC(18,6);
    v_candle_volume NUMERIC(20,2);
    v_records_loaded INTEGER := 0;
    v_i INTEGER;
    v_instrument_id VARCHAR(100);
    v_store_contract VARCHAR(50);
    v_moex_secid VARCHAR(20);
    v_note TEXT;
    v_max_days INTEGER;
    v_chunk_from DATE;
    v_chunk_to DATE;
BEGIN
    PERFORM configure_http_ssl();

    SELECT tf INTO v_tf_name FROM timeframes WHERE id = p_timeframe_id;
    v_max_days := GREATEST(1, get_tbank_max_request_days(v_tf_name));

    IF p_contract_prefix IS NOT NULL THEN
        v_prefix := p_contract_prefix;
        v_tbank_figi := p_contract_figi;
        v_is_future := TRUE;
        v_store_contract := p_contract_prefix;
        SELECT fe.moex_secid INTO v_moex_secid
        FROM futures_expirations fe
        WHERE fe.security_id = p_security_id
          AND fe.prefix = p_contract_prefix
        LIMIT 1;
    ELSE
        SELECT sp.prefix, sp.tbank_figi, sp.note
        INTO v_prefix, v_tbank_figi, v_note
        FROM security_prefixes sp
        WHERE sp.security_id = p_security_id AND sp.exchange_id = 1;

        IF v_prefix IS NULL THEN
            RAISE EXCEPTION 'РџСЂРµС„РёРєСЃ РЅРµ РЅР°Р№РґРµРЅ РґР»СЏ security_id=%', p_security_id;
        END IF;

        SELECT (st.name = 'Futures') INTO v_is_future
        FROM securities s
        JOIN security_types st ON s.security_type_id = st.id
        WHERE s.id = p_security_id;

        v_store_contract := NULL;

        IF v_is_future THEN
            IF is_perpetual_future_group(v_prefix, v_note) THEN
                v_store_contract := v_prefix;
            ELSE
                SELECT fe.prefix, fe.tbank_figi INTO v_prefix, v_tbank_figi
                FROM futures_expirations fe
                WHERE fe.security_id = p_security_id
                  AND fe.expiration_date > p_date_to
                  AND fe.is_active = TRUE
                ORDER BY fe.expiration_date ASC
                LIMIT 1;
                IF v_prefix IS NULL THEN
                    RAISE EXCEPTION 'РђРєС‚РёРІРЅС‹Р№ С„СЊСЋС‡РµСЂСЃ РЅРµ РЅР°Р№РґРµРЅ РґР»СЏ security_id=% РЅР° РґР°С‚Сѓ %',
                        p_security_id, p_date_to;
                END IF;
                v_store_contract := v_prefix;
                SELECT fe.moex_secid INTO v_moex_secid
                FROM futures_expirations fe
                WHERE fe.security_id = p_security_id
                  AND fe.prefix = v_prefix
                LIMIT 1;
            END IF;
        END IF;
    END IF;

    v_token := get_tbank_token();
    IF v_token IS NULL THEN
        RAISE EXCEPTION 'T-Bank С‚РѕРєРµРЅ РЅРµ РЅР°Р№РґРµРЅ. Р—Р°РґР°Р№С‚Рµ TBANK_API_TOKEN РІ РїР°СЂР°РјРµС‚СЂР°С… РёР»Рё token_encrypted РІ accounts.';
    END IF;

    v_instrument_id := resolve_tbank_instrument_id(
        p_security_id, v_prefix, v_tbank_figi, v_is_future, 'TQBR', v_moex_secid
    );

    v_api_url := 'https://invest-public-api.tbank.ru/rest/tinkoff.public.invest.api.contract.v1.MarketDataService/GetCandles';

    v_headers := ARRAY[
        http_header('Authorization', 'Bearer ' || v_token),
        http_header('Accept', 'application/json')
    ];

    v_chunk_from := p_date_from;
    WHILE v_chunk_from <= p_date_to LOOP
        v_chunk_to := LEAST(v_chunk_from + v_max_days - 1, p_date_to);

        v_payload := jsonb_build_object(
            'instrumentId', v_instrument_id,
            'from', tbank_iso_utc(v_chunk_from),
            'to', tbank_iso_utc(v_chunk_to + 1),
            'interval', get_tbank_candle_interval(v_tf_name)
        )::TEXT;

        SELECT * INTO v_response FROM http((
            'POST',
            v_api_url,
            v_headers,
            'application/json',
            v_payload
        )::http_request);

        v_status := v_response.status;

        IF v_status != 200 THEN
            IF v_status IN (401, 403) OR v_response.content ILIKE '%unauthenticated%' THEN
                RAISE EXCEPTION 'T-Bank API РІРµСЂРЅСѓР» СЃС‚Р°С‚СѓСЃ %: %', v_status, v_response.content;
            END IF;
            RAISE NOTICE 'T-Bank chunk %..%: HTTP %', v_chunk_from, v_chunk_to, v_status;
        ELSE
            v_content := v_response.content::JSONB;
            v_candles := v_content->'candles';

            IF v_candles IS NOT NULL AND jsonb_array_length(v_candles) > 0 THEN
                FOR v_i IN 0 .. jsonb_array_length(v_candles) - 1
                LOOP
                    v_candle := v_candles->v_i;
                    v_candle_time := market_candle_dt_from_iso(v_candle->>'time');
                    v_candle_open := parse_tbank_quotation(v_candle->'open');
                    v_candle_high := parse_tbank_quotation(v_candle->'high');
                    v_candle_low := parse_tbank_quotation(v_candle->'low');
                    v_candle_close := parse_tbank_quotation(v_candle->'close');
                    v_candle_volume := COALESCE(
                        parse_tbank_quotation(v_candle->'volume'),
                        (v_candle->>'volume')::NUMERIC
                    );

                    CALL insert_candle(
                        p_security_id,
                        p_timeframe_id,
                        v_candle_time,
                        v_candle_open,
                        v_candle_high,
                        v_candle_low,
                        v_candle_close,
                        v_candle_volume,
                        NULL,
                        v_store_contract
                    );

                    v_records_loaded := v_records_loaded + 1;
                END LOOP;
            END IF;
        END IF;

        v_chunk_from := v_chunk_to + 1;
    END LOOP;

    IF v_records_loaded = 0 THEN
        INSERT INTO price_load_log (
            security_id, timeframe_id, date_from, date_to,
            source, records_loaded, contract_prefix, error_message
        )
        VALUES (
            p_security_id, p_timeframe_id, p_date_from, p_date_to,
            'T-BANK', 0, v_store_contract, 'T-Bank РІРµСЂРЅСѓР» 0 СЃРІРµС‡РµР№ Р·Р° РїРµСЂРёРѕРґ'
        );
        RAISE NOTICE 'T-Bank: 0 СЃРІРµС‡РµР№ (% вЂ” %)', p_date_from, p_date_to;
        RETURN;
    END IF;

    INSERT INTO price_load_log (
        security_id, timeframe_id, date_from, date_to,
        source, records_loaded, contract_prefix
    )
    VALUES (
        p_security_id, p_timeframe_id, p_date_from, p_date_to,
        'T-BANK', v_records_loaded, v_store_contract
    );

    RAISE NOTICE 'Р—Р°РіСЂСѓР¶РµРЅРѕ % СЃРІРµС‡РµР№ РёР· T-Bank (% вЂ” %, РєРѕРЅС‚СЂР°РєС‚ %)',
        v_records_loaded, p_date_from, p_date_to, v_store_contract;

EXCEPTION
    WHEN OTHERS THEN
        IF v_records_loaded > 0 THEN
            INSERT INTO price_load_log (
                security_id, timeframe_id, date_from, date_to,
                source, records_loaded, contract_prefix, error_message
            )
            VALUES (
                p_security_id, p_timeframe_id, p_date_from, p_date_to,
                'T-BANK', v_records_loaded, v_store_contract,
                format('Р§Р°СЃС‚РёС‡РЅР°СЏ Р·Р°РіСЂСѓР·РєР°, Р·Р°С‚РµРј РѕС€РёР±РєР°: %s', SQLERRM)
            );
            RAISE NOTICE 'T-Bank: С‡Р°СЃС‚РёС‡РЅРѕ % СЃРІРµС‡РµР№, РѕС€РёР±РєР°: %', v_records_loaded, SQLERRM;
            RETURN;
        END IF;
        INSERT INTO price_load_log (
            security_id, timeframe_id, date_from, date_to,
            source, records_loaded, contract_prefix, error_message
        )
        VALUES (
            p_security_id, p_timeframe_id, p_date_from, p_date_to,
            'T-BANK', 0, v_store_contract, SQLERRM
        );
        RAISE;
END;
$$;

COMMENT ON PROCEDURE load_prices_from_tbank_http(INTEGER, INTEGER, DATE, DATE, VARCHAR, VARCHAR) IS
'Р—Р°РіСЂСѓР·РєР° СЃРІРµС‡РµР№ T-Bank РїРѕ С‡Р°РЅРєР°Рј (Р»РёРјРёС‚ РїРµСЂРёРѕРґР° API). p_contract_prefix вЂ” С‚РёРєРµСЂ РєРѕРЅС‚СЂР°РєС‚Р° РґР»СЏ С„СЊСЋС‡РµСЂСЃРѕРІ.';

-- ============================================
-- РџСЂРѕС†РµРґСѓСЂР°: load_prices_from_moex_http
-- Р—Р°РіСЂСѓР·РєР° С†РµРЅ С‡РµСЂРµР· MOEX ISS API СЃ РёСЃРїРѕР»СЊР·РѕРІР°РЅРёРµРј pgsql-http
-- ============================================

CREATE OR REPLACE PROCEDURE load_prices_futures_http(p_security_id INTEGER,
    p_timeframe_id INTEGER,
    p_date_from DATE,
    p_date_to DATE)
LANGUAGE plpgsql AS $$
DECLARE
    v_seg_to DATE := p_date_to;
    v_seg_from DATE;
    v_contract RECORD;
    v_tbank_total INTEGER := 0;
    v_seg_records INTEGER;
    v_moex_total INTEGER := 0;
    v_logged_no_contract BOOLEAN := FALSE;
    v_have INTEGER := 0;
BEGIN
    PERFORM configure_http_ssl();

    CALL sync_futures_expirations_from_moex(p_security_id, p_date_from, p_date_to);

    LOOP
        SELECT * INTO v_contract
        FROM get_future_contract_for_date(p_security_id, v_seg_to);

        IF NOT FOUND THEN
            CALL sync_futures_expirations_from_moex(p_security_id, p_date_from, v_seg_to);
            SELECT * INTO v_contract
            FROM get_future_contract_for_date(p_security_id, v_seg_to);
            IF NOT FOUND THEN
                IF NOT v_logged_no_contract AND v_tbank_total = 0 THEN
                    INSERT INTO price_load_log (
                        security_id, timeframe_id, date_from, date_to,
                        source, records_loaded, error_message
                    )
                    VALUES (
                        p_security_id, p_timeframe_id, p_date_from, p_date_to,
                        'T-BANK', 0,
                        format('РљРѕРЅС‚СЂР°РєС‚ РЅРµ РЅР°Р№РґРµРЅ РЅР° РґР°С‚Сѓ %s РїРѕСЃР»Рµ sync MOEX', v_seg_to)
                    );
                    v_logged_no_contract := TRUE;
                END IF;
                EXIT;
            END IF;
        END IF;

        v_seg_from := GREATEST(p_date_from, v_contract.start_date);

        BEGIN
            CALL load_prices_from_tbank_http(
                p_security_id, p_timeframe_id, v_seg_from, v_seg_to,
                v_contract.prefix, v_contract.tbank_figi
            );
            SELECT records_loaded INTO v_seg_records
            FROM price_load_log
            WHERE security_id = p_security_id
              AND timeframe_id = p_timeframe_id
              AND date_from = v_seg_from
              AND date_to = v_seg_to
              AND source = 'T-BANK'
            ORDER BY id DESC
            LIMIT 1;
            v_tbank_total := v_tbank_total + COALESCE(v_seg_records, 0);
        EXCEPTION
            WHEN OTHERS THEN
                INSERT INTO price_load_log (
                    security_id, timeframe_id, date_from, date_to,
                    source, records_loaded, contract_prefix, error_message
                )
                VALUES (
                    p_security_id, p_timeframe_id, v_seg_from, v_seg_to,
                    'T-BANK', 0, v_contract.prefix, SQLERRM
                );
        END;

        IF v_seg_from <= p_date_from THEN
            EXIT;
        END IF;
        v_seg_to := v_seg_from - 1;
    END LOOP;

    -- РќРµ РІС‹С…РѕРґРёРј СЃСЂР°Р·Сѓ РїРѕСЃР»Рµ С‡Р°СЃС‚РёС‡РЅРѕРіРѕ T-Bank: SSL С‡Р°СЃС‚Рѕ РѕР±СЂС‹РІР°РµС‚ РЅРµРґРµР»СЋ в†’ РґРѕР±РёРІР°РµРј MOEX
    SELECT COUNT(*)::INTEGER INTO v_have
    FROM prices p
    WHERE p.security_id = p_security_id
      AND p.timeframe_id = p_timeframe_id
      AND p.dt::date BETWEEN p_date_from AND p_date_to;
    IF v_tbank_total > 0 AND v_have >= 40 THEN
        RETURN;
    END IF;

    v_seg_to := p_date_to;
    LOOP
        SELECT * INTO v_contract
        FROM get_future_contract_for_date(p_security_id, v_seg_to);
        IF NOT FOUND THEN
            EXIT;
        END IF;
        v_seg_from := GREATEST(p_date_from, v_contract.start_date);

        BEGIN
            CALL load_prices_from_moex_http(
                p_security_id, p_timeframe_id, v_seg_from, v_seg_to,
                v_contract.prefix
            );
            SELECT records_loaded INTO v_seg_records
            FROM price_load_log
            WHERE security_id = p_security_id
              AND timeframe_id = p_timeframe_id
              AND date_from = v_seg_from
              AND date_to = v_seg_to
              AND source = 'MOEX'
            ORDER BY id DESC
            LIMIT 1;
            v_moex_total := v_moex_total + COALESCE(v_seg_records, 0);
        EXCEPTION
            WHEN OTHERS THEN
                NULL;
        END;

        IF v_seg_from <= p_date_from THEN
            EXIT;
        END IF;
        v_seg_to := v_seg_from - 1;
    END LOOP;
END;
$$;

COMMENT ON PROCEDURE load_prices_futures_http(INTEGER, INTEGER, DATE, DATE) IS
'Р¤СЊСЋС‡РµСЂСЃ-РіСЂСѓРїРїР°: Р·Р°РіСЂСѓР·РєР° РїРѕ РєРѕРЅС‚СЂР°РєС‚Р°Рј РѕС‚ date_to РЅР°Р·Р°Рґ (Si-6.26 в†’ Si-3.26 вЂ¦), T-Bank в†’ MOEX';

-- ============================================
-- Р“Р›РђР’РќРђРЇ РџР РћР¦Р•Р”РЈР Рђ: load_prices_http
-- РЎРЅР°С‡Р°Р»Р° T-Bank, РµСЃР»Рё РЅРµ СЃСЂР°Р±РѕС‚Р°Р»Рѕ -- MOEX
-- ============================================

CREATE OR REPLACE PROCEDURE load_prices_http(p_security_id INTEGER,
    p_timeframe_id INTEGER,
    p_date_from DATE,
    p_date_to DATE)
LANGUAGE plpgsql AS $$
DECLARE
    v_tbank_ok BOOLEAN := FALSE;
    v_tbank_records INTEGER := 0;
    v_tbank_error TEXT;
    v_moex_records INTEGER := 0;
    v_is_future BOOLEAN := FALSE;
    v_group_prefix VARCHAR(50);
    v_note TEXT;
    v_tf_sec INTEGER;
BEGIN
    PERFORM set_config('lock_timeout', '15000', true);
    PERFORM set_config('statement_timeout', '180000', true);
    PERFORM configure_http_ssl();

    SELECT (st.name = 'Futures') INTO v_is_future
    FROM securities s
    JOIN security_types st ON s.security_type_id = st.id
    WHERE s.id = p_security_id;

    SELECT sp.prefix, sp.note INTO v_group_prefix, v_note
    FROM security_prefixes sp
    WHERE sp.security_id = p_security_id AND sp.exchange_id = 1;

    -- Р¤СЊСЋС‡РµСЂСЃС‹: M10в†’M15 РїРѕ РґРЅСЏРј РґРѕР»СЊС€Рµ 3 РјРёРЅ РїСЂРё SSL-СЂРµС‚СЂР°СЏС…
    IF v_is_future THEN
        PERFORM set_config('statement_timeout', '900000', true);
    END IF;

    IF v_is_future AND is_perpetual_future_group(v_group_prefix, v_note) THEN
        BEGIN
            CALL load_prices_from_tbank_http(p_security_id, p_timeframe_id, p_date_from, p_date_to);
            SELECT records_loaded INTO v_tbank_records
            FROM price_load_log
            WHERE security_id = p_security_id
              AND timeframe_id = p_timeframe_id
              AND date_from = p_date_from
              AND date_to = p_date_to
              AND source = 'T-BANK'
            ORDER BY id DESC
            LIMIT 1;
            v_tbank_ok := COALESCE(v_tbank_records, 0) > 0;
        EXCEPTION
            WHEN OTHERS THEN
                v_tbank_error := SQLERRM;
                INSERT INTO price_load_log (
                    security_id, timeframe_id, date_from, date_to,
                    source, records_loaded, error_message
                )
                VALUES (
                    p_security_id, p_timeframe_id, p_date_from, p_date_to,
                    'T-BANK', 0, v_tbank_error
                );
        END;
        IF NOT v_tbank_ok THEN
            RAISE NOTICE 'T-Bank: РЅРµС‚ РґР°РЅРЅС‹С… (%), РїСЂРѕР±СѓРµРј MOEX...', COALESCE(v_tbank_error, '0 СЃРІРµС‡РµР№');
            BEGIN
                CALL load_prices_from_moex_http(p_security_id, p_timeframe_id, p_date_from, p_date_to);
            EXCEPTION
                WHEN OTHERS THEN
                    IF v_tbank_error IS NOT NULL THEN
                        RAISE EXCEPTION 'РћР±Р° РёСЃС‚РѕС‡РЅРёРєР° РЅРµРґРѕСЃС‚СѓРїРЅС‹. T-Bank: %; MOEX: %', v_tbank_error, SQLERRM;
                    ELSE
                        RAISE;
                    END IF;
            END;
        END IF;
        RETURN;
    END IF;

    IF v_is_future THEN
        CALL load_prices_futures_http(p_security_id, p_timeframe_id, p_date_from, p_date_to);
        SELECT COALESCE(SUM(records_loaded), 0) INTO v_tbank_records
        FROM price_load_log
        WHERE security_id = p_security_id
          AND timeframe_id = p_timeframe_id
          AND date_from >= p_date_from
          AND date_to <= p_date_to
          AND source = 'T-BANK'
          AND loaded_at >= (CURRENT_TIMESTAMP - INTERVAL '5 minutes');
        IF COALESCE(v_tbank_records, 0) = 0 THEN
            SELECT COALESCE(SUM(records_loaded), 0) INTO v_moex_records
            FROM price_load_log
            WHERE security_id = p_security_id
              AND timeframe_id = p_timeframe_id
              AND date_from >= p_date_from
              AND date_to <= p_date_to
              AND source = 'MOEX'
              AND loaded_at >= (CURRENT_TIMESTAMP - INTERVAL '5 minutes');
        END IF;
        RETURN;
    END IF;

    -- РђРєС†РёРё Рё РїСЂРѕС‡РµРµ: T-Bank в†’ MOEX
    BEGIN
        CALL load_prices_from_tbank_http(p_security_id, p_timeframe_id, p_date_from, p_date_to);
        SELECT records_loaded INTO v_tbank_records
        FROM price_load_log
        WHERE security_id = p_security_id
          AND timeframe_id = p_timeframe_id
          AND date_from = p_date_from
          AND date_to = p_date_to
          AND source = 'T-BANK'
        ORDER BY id DESC
        LIMIT 1;
        v_tbank_ok := COALESCE(v_tbank_records, 0) > 0;
        IF v_tbank_ok THEN
            RAISE NOTICE 'Р¦РµРЅС‹ СѓСЃРїРµС€РЅРѕ Р·Р°РіСЂСѓР¶РµРЅС‹ РёР· T-Bank: % СЃРІРµС‡РµР№', v_tbank_records;
        END IF;
    EXCEPTION
        WHEN OTHERS THEN
            v_tbank_error := SQLERRM;
            INSERT INTO price_load_log (
                security_id, timeframe_id, date_from, date_to,
                source, records_loaded, error_message
            )
            VALUES (
                p_security_id, p_timeframe_id, p_date_from, p_date_to,
                'T-BANK', 0, v_tbank_error
            );
            RAISE NOTICE 'T-Bank РЅРµРґРѕСЃС‚СѓРїРµРЅ: %', v_tbank_error;
    END;

    IF NOT v_tbank_ok THEN
        RAISE NOTICE 'T-Bank РЅРµ РґР°Р» РґР°РЅРЅС‹С…, РїСЂРѕР±СѓРµРј MOEX...';
        BEGIN
            CALL load_prices_from_moex_http(p_security_id, p_timeframe_id, p_date_from, p_date_to);
            SELECT records_loaded INTO v_moex_records
            FROM price_load_log
            WHERE security_id = p_security_id
              AND timeframe_id = p_timeframe_id
              AND date_from = p_date_from
              AND date_to = p_date_to
              AND source = 'MOEX'
            ORDER BY id DESC
            LIMIT 1;
            IF COALESCE(v_moex_records, 0) > 0 THEN
                RAISE NOTICE 'Р¦РµРЅС‹ СѓСЃРїРµС€РЅРѕ Р·Р°РіСЂСѓР¶РµРЅС‹ РёР· MOEX: % СЃРІРµС‡РµР№', v_moex_records;
            END IF;
        EXCEPTION
            WHEN OTHERS THEN
                IF v_tbank_error IS NOT NULL THEN
                    RAISE EXCEPTION 'РћР±Р° РёСЃС‚РѕС‡РЅРёРєР° РЅРµРґРѕСЃС‚СѓРїРЅС‹. T-Bank: %; MOEX: %', v_tbank_error, SQLERRM;
                ELSE
                    RAISE EXCEPTION 'MOEX: %', SQLERRM;
                END IF;
        END;

        IF COALESCE(v_moex_records, 0) = 0 THEN
            SELECT t.sec INTO v_tf_sec FROM timeframes t WHERE t.id = p_timeframe_id;
            IF COALESCE(v_tf_sec, 0) > 60 AND COALESCE(v_tf_sec, 0) < 86400 THEN
                BEGIN
                    CALL load_prices_moex_via_m1_resample(
                        p_security_id, p_timeframe_id, p_date_from, p_date_to
                    );
                    RAISE NOTICE 'MOEX M1 resample РІС‹РїРѕР»РЅРµРЅ РґР»СЏ security_id=% tf_id=%',
                        p_security_id, p_timeframe_id;
                EXCEPTION
                    WHEN OTHERS THEN
                        RAISE NOTICE 'MOEX M1 resample РЅРµ СѓРґР°Р»СЃСЏ: %', SQLERRM;
                END;
            END IF;
        END IF;
    END IF;
END;
$$;

COMMENT ON PROCEDURE load_prices_http(INTEGER, INTEGER, DATE, DATE) IS 
'Р—Р°РіСЂСѓР·РєР° С†РµРЅ: СЃРЅР°С‡Р°Р»Р° T-Bank; РїСЂРё РѕС€РёР±РєРµ РёР»Рё 0 СЃРІРµС‡РµР№ вЂ” MOEX (+ M1 resample).';

-- ============================================
-- РџСЂРѕС†РµРґСѓСЂР°: load_prices_batch_http
-- Р—Р°РіСЂСѓР·РєР° С†РµРЅ РґР»СЏ РЅРµСЃРєРѕР»СЊРєРёС… Р±СѓРјР°Рі СЃСЂР°Р·Сѓ
-- ============================================

CREATE OR REPLACE PROCEDURE load_prices_moex_resample_chunked(p_security_id INTEGER,
    p_timeframe_id INTEGER,
    p_date_from DATE,
    p_date_to DATE)
LANGUAGE plpgsql AS $$
DECLARE
    v_day DATE;
    v_tf_sec INTEGER;
BEGIN
    SELECT t.sec INTO v_tf_sec FROM timeframes t WHERE t.id = p_timeframe_id;
    IF COALESCE(v_tf_sec, 0) <= 60 OR COALESCE(v_tf_sec, 0) >= 86400 THEN
        RAISE EXCEPTION 'chunked resample: РїРѕРґРґРµСЂР¶РёРІР°СЋС‚СЃСЏ С‚РѕР»СЊРєРѕ РёРЅС‚СЂР°РґРµР№-TF (60<sec<86400), tf_id=%', p_timeframe_id;
    END IF;

    v_day := p_date_from;
    WHILE v_day <= p_date_to LOOP
        BEGIN
            CALL load_prices_moex_via_m1_resample(
                p_security_id, p_timeframe_id, v_day, v_day
            );
        EXCEPTION
            WHEN OTHERS THEN
                RAISE NOTICE 'chunked resample: РґРµРЅСЊ % РЅРµ СѓРґР°Р»СЃСЏ: %', v_day, SQLERRM;
        END;
        v_day := v_day + 1;
    END LOOP;
END;
$$;

COMMENT ON PROCEDURE load_prices_moex_resample_chunked(INTEGER, INTEGER, DATE, DATE) IS
'Р§Р°РЅРєРѕРІР°РЅРЅС‹Р№ M10в†’M15 resample РїРѕ РґРЅСЏРј (РґР»СЏ РёРЅС‚СЂР°РґРµР№-TF СЃ РЅРµРґРѕСЃС‚СѓРїРЅС‹Рј РїСЂСЏРјС‹Рј interval)';

-- MOEX ASSETCODE РґР»СЏ РіСЂСѓРїРїРѕРІРѕРіРѕ РїСЂРµС„РёРєСЃР° (CR в†’ CNY, GD в†’ GOLD, вЂ¦)

CREATE OR REPLACE PROCEDURE load_prices_moex_via_base_resample(p_security_id INTEGER,
    p_timeframe_id INTEGER,
    p_date_from DATE,
    p_date_to DATE,
    p_contract_prefix VARCHAR DEFAULT NULL,
    p_base_interval INTEGER DEFAULT 10)
LANGUAGE plpgsql AS $$
DECLARE
    v_src_tf_id INTEGER;
    v_src_tf VARCHAR(20);
    v_tf_name VARCHAR(20);
    v_resampled INTEGER := 0;
    v_base INTEGER;
BEGIN
    v_base := moex_forts_base_interval(COALESCE(p_base_interval, 10));
    v_src_tf := CASE v_base
        WHEN 1 THEN 'M1'
        WHEN 10 THEN 'M10'
        WHEN 60 THEN 'H1'
        ELSE 'M1'
    END;
    SELECT t.id INTO v_src_tf_id FROM timeframes t WHERE t.tf = v_src_tf LIMIT 1;
    SELECT tf INTO v_tf_name FROM timeframes WHERE id = p_timeframe_id;

    RAISE NOTICE 'MOEX resample: % в†’ % в†’ % (% вЂ” %)', v_tf_name, v_src_tf, v_tf_name, p_date_from, p_date_to;

    CALL load_moex_interval_candles_paginated(
        p_security_id, p_date_from, p_date_to, p_contract_prefix, v_base
    );
    CALL resample_prices_to_timeframe(
        p_security_id, v_src_tf_id, p_timeframe_id, p_date_from, p_date_to
    );

    SELECT COUNT(*)::INTEGER INTO v_resampled
    FROM prices p
    WHERE p.security_id = p_security_id
      AND p.timeframe_id = p_timeframe_id
      AND p.dt::date BETWEEN p_date_from AND p_date_to;

    INSERT INTO price_load_log (
        security_id, timeframe_id, date_from, date_to,
        source, records_loaded, contract_prefix, error_message
    )
    VALUES (
        p_security_id, p_timeframe_id, p_date_from, p_date_to,
        format('MOEX-%s', v_src_tf), v_resampled, p_contract_prefix,
        format('MOEX ISS РЅРµ РѕС‚РґР°С‘С‚ %s РЅР°РїСЂСЏРјСѓСЋ; resample РёР· %s', v_tf_name, v_src_tf)
    );
END;
$$;

COMMENT ON PROCEDURE load_prices_moex_via_base_resample(INTEGER, INTEGER, DATE, DATE, VARCHAR, INTEGER) IS
'Fallback: Р·Р°РіСЂСѓР·РєР° Р±Р°Р·РѕРІРѕРіРѕ FORTS interval (РѕР±С‹С‡РЅРѕ M10) + resample РІ С†РµР»РµРІРѕР№ TF';

CREATE OR REPLACE PROCEDURE load_prices_moex_via_m1_resample(p_security_id INTEGER,
    p_timeframe_id INTEGER,
    p_date_from DATE,
    p_date_to DATE,
    p_contract_prefix VARCHAR DEFAULT NULL)
LANGUAGE plpgsql AS $$
DECLARE
    v_tf_name VARCHAR(20);
    v_req INTEGER;
    v_base INTEGER;
BEGIN
    SELECT tf INTO v_tf_name FROM timeframes WHERE id = p_timeframe_id;
    v_req := get_moex_candle_interval(v_tf_name);
    v_base := moex_forts_base_interval(v_req);
    -- Р”Р»СЏ M15/M20/M30 РїСЂРµРґРїРѕС‡РёС‚Р°РµРј M10 (РІ ~10Г— РјРµРЅСЊС€Рµ HTTP, С‡РµРј M1)
    CALL load_prices_moex_via_base_resample(
        p_security_id, p_timeframe_id, p_date_from, p_date_to, p_contract_prefix, v_base
    );
END;
$$;

COMMENT ON PROCEDURE load_prices_moex_via_m1_resample(INTEGER, INTEGER, DATE, DATE, VARCHAR) IS
'Fallback: FORTS base interval (M10 РґР»СЏ M15) + resample РІ С†РµР»РµРІРѕР№ TF';

-- ============================================
-- Р§Р°РЅРєРѕРІР°РЅРЅС‹Р№ M10в†’M15 resample РїРѕ РґРЅСЏРј.
-- MOEX ISS РЅРµ РѕС‚РґР°С‘С‚ РёРЅС‚СЂР°РґРµР№-РёРЅС‚РµСЂРІР°Р»С‹ РІСЂРѕРґРµ 15/30 РЅР°РїСЂСЏРјСѓСЋ (0 СЃРІРµС‡РµР№),
-- Р° Р±РѕР»СЊС€РѕР№ РґРёР°РїР°Р·РѕРЅ РІ РѕРґРёРЅ РІС‹Р·РѕРІ РЅРµ СѓСЃРїРµРІР°РµС‚ РІ statement_timeout (С‚Р°Р№РјР°СѓС‚),
-- РїРѕСЌС‚РѕРјСѓ РёРґС‘Рј РїРѕ РґРЅСЏРј вЂ” РєР°Р¶РґС‹Р№ РґРЅРµРІРЅРѕР№ РІС‹Р·РѕРІ РјР°Р» Рё СѓСЃРїРµРІР°РµС‚.

CREATE OR REPLACE PROCEDURE logic_apply_indicator_params_from_signals(p_logic_id INTEGER,
    p_security_id INTEGER)
LANGUAGE plpgsql
AS $$
DECLARE
    v_sig RECORD;
    v_parsed RECORD;
    v_period NUMERIC;
    v_std NUMERIC;
    v_fast NUMERIC;
    v_slow NUMERIC;
    v_signal NUMERIC;
    v_k NUMERIC;
    v_d NUMERIC;
    v_smooth NUMERIC;
BEGIN
    FOR v_sig IN
        SELECT lis.indicator_id, lis.formula
        FROM logic_indicator_signals lis
        WHERE lis.logic_id = p_logic_id AND lis.is_active = TRUE
    LOOP
        SELECT * INTO v_parsed FROM parse_signal_formula(v_sig.formula);
        IF NOT COALESCE(v_parsed.valid, FALSE) THEN
            CONTINUE;
        END IF;
        v_period := parse_signal_param_num(v_parsed.params, 'period');
        v_std := COALESCE(
            parse_signal_param_num(v_parsed.params, 'std_dev'),
            parse_signal_param_num(v_parsed.params, 'std')
        );
        v_fast := COALESCE(
            parse_signal_param_num(v_parsed.params, 'fast_period'),
            parse_signal_param_num(v_parsed.params, 'fast')
        );
        v_slow := COALESCE(
            parse_signal_param_num(v_parsed.params, 'slow_period'),
            parse_signal_param_num(v_parsed.params, 'slow')
        );
        v_signal := COALESCE(
            parse_signal_param_num(v_parsed.params, 'signal_period'),
            parse_signal_param_num(v_parsed.params, 'signal')
        );
        v_k := COALESCE(
            parse_signal_param_num(v_parsed.params, 'k_period'),
            parse_signal_param_num(v_parsed.params, 'k')
        );
        v_d := COALESCE(
            parse_signal_param_num(v_parsed.params, 'd_period'),
            parse_signal_param_num(v_parsed.params, 'd')
        );
        v_smooth := parse_signal_param_num(v_parsed.params, 'smooth');

        -- #1032: РїР°СЂР°РјРµС‚СЂС‹ РёР· С„РѕСЂРјСѓР»С‹ Р±РѕР»СЊС€Рµ РќР• РїРёС€СѓС‚СЃСЏ РІ РѕР±С‰СѓСЋ СЃРµСЂРёСЋ
        -- security_indicator_series вЂ” РёРЅР°С‡Рµ РїРѕСЃР»РµРґРЅСЏСЏ Р»РѕРіРёРєР° РјРµРЅСЏР»Р° РїР°СЂР°РјРµС‚СЂС‹
        -- РёРЅРґРёРєР°С‚РѕСЂР° РґР»СЏ РІСЃРµС…. РљР°Р¶РґР°СЏ Р»РѕРіРёРєР° СЃС‡РёС‚Р°РµС‚ РїРѕ СЃРІРѕРµР№ С„РѕСЂРјСѓР»Рµ.
        NULL;
    END LOOP;
END;
$$;

COMMENT ON PROCEDURE logic_apply_indicator_params_from_signals(INTEGER, INTEGER) IS
'РЈСЃС‚Р°СЂРµР»Р° (#1032): РЅРёС‡РµРіРѕ РЅРµ РґРµР»Р°РµС‚ вЂ” РїР°СЂР°РјРµС‚СЂС‹ РёРЅРґРёРєР°С‚РѕСЂР° Р±РµСЂСѓС‚СЃСЏ РёР· С„РѕСЂРјСѓР»С‹ СЃРёРіРЅР°Р»Р° СЃРІРѕРµР№ Р»РѕРіРёРєРё, РѕР±С‰Р°СЏ СЃРµСЂРёСЏ РЅРµ РїРµСЂРµР·Р°РїРёСЃС‹РІР°РµС‚СЃСЏ.';
-- @end calc_ind_extra






































































































































































-- Р”РёСЃРїРµС‚С‡РµСЂ РјР°СЃСЃРёРІРЅРѕРіРѕ СЂР°СЃС‡С‘С‚Р° РїРѕ РєРѕРґСѓ РёРЅРґРёРєР°С‚РѕСЂР°

CREATE OR REPLACE PROCEDURE logic_backtest_ensure_security_data(p_run_id BIGINT,
    p_logic_id INTEGER,
    p_security_id INTEGER,
    p_tf_id INTEGER,
    p_warmup_from DATE,
    p_date_from DATE,
    p_date_to DATE,
    p_end_dt TIMESTAMP,
    p_point_count INTEGER,
    p_prices_loaded OUT INTEGER,
    p_prices_cached OUT INTEGER,
    p_ind_synced OUT INTEGER,
    p_ind_cached OUT INTEGER,
    p_ind_errors OUT INTEGER)
LANGUAGE plpgsql AS $$
DECLARE
    v_ind RECORD;
    v_need_prices BOOLEAN;
    v_mtf RECORD;
    v_mtf_point_count INTEGER;
BEGIN
    p_prices_loaded := 0;
    p_prices_cached := 0;
    p_ind_synced := 0;
    p_ind_cached := 0;
    p_ind_errors := 0;

    v_need_prices := NOT backtest_prices_cached(
        p_security_id, p_tf_id, p_warmup_from, p_date_from, p_date_to, 20
    );

    IF v_need_prices THEN
        BEGIN
            CALL load_prices(p_security_id, p_tf_id, p_warmup_from, p_date_to);
            p_prices_loaded := 1;
        EXCEPTION WHEN OTHERS THEN
            PERFORM logic_backtest_log(
                p_run_id, p_logic_id, 'backtest.prices.error', SQLERRM,
                jsonb_build_object('security_id', p_security_id),
                p_security_id, p_tf_id
            );
            RETURN;
        END;
    ELSE
        p_prices_cached := 1;
        PERFORM logic_backtest_log(
            p_run_id, p_logic_id, 'backtest.prices.cached',
            format('РљСЌС€ С†РµРЅ sec=%s (%s вЂ” %s)', p_security_id, p_warmup_from, p_date_to),
            jsonb_build_object('security_id', p_security_id),
            p_security_id, p_tf_id
        );
    END IF;

    -- Р¦РµРЅС‹ Р±Р°Р·РѕРІС‹С… Р°РєС‚РёРІРѕРІ РґР»СЏ signal_acts_on=base_asset|contango
    FOR v_ind IN
        SELECT DISTINCT logic_future_underlying_security_id(p_security_id) AS und_id
        FROM logic_indicator_signals lis
        WHERE lis.logic_id = p_logic_id
          AND lis.is_active = TRUE
          AND COALESCE(lis.signal_acts_on, 'security') IN ('base_asset', 'contango')
    LOOP
        IF v_ind.und_id IS NULL OR v_ind.und_id = p_security_id THEN
            CONTINUE;
        END IF;
        IF backtest_prices_cached(
            v_ind.und_id, p_tf_id, p_warmup_from, p_date_from, p_date_to, 20
        ) THEN
            CONTINUE;
        END IF;
        BEGIN
            CALL load_prices(v_ind.und_id, p_tf_id, p_warmup_from, p_date_to);
        EXCEPTION WHEN OTHERS THEN
            PERFORM logic_backtest_log(
                p_run_id, p_logic_id, 'backtest.prices.error', SQLERRM,
                jsonb_build_object(
                    'security_id', v_ind.und_id,
                    'trade_security_id', p_security_id,
                    'role', 'base_asset'
                ),
                p_security_id, p_tf_id
            );
        END;
    END LOOP;

    -- РЎРёРЅС‚РµС‚РёРєР° contango (fut в€’ und) РєР°Рє СЂСЏРґ С†РµРЅ РґР»СЏ РёРЅРґРёРєР°С‚РѕСЂРѕРІ
    IF EXISTS (
        SELECT 1 FROM logic_indicator_signals lis
        WHERE lis.logic_id = p_logic_id AND lis.is_active
          AND COALESCE(lis.signal_acts_on, 'security') = 'contango'
    ) THEN
        BEGIN
            PERFORM sync_contango_prices(
                p_security_id, p_tf_id, p_warmup_from::DATE, p_date_to
            );
        EXCEPTION WHEN OTHERS THEN
            PERFORM logic_backtest_log(
                p_run_id, p_logic_id, 'backtest.prices.contango_error', SQLERRM,
                jsonb_build_object('security_id', p_security_id, 'role', 'contango'),
                p_security_id, p_tf_id
            );
        END;
    END IF;

    -- Apply @CODE(...period/std_dev...) from signals onto series BEFORE cache skip,
    -- otherwise indicator_values stay on old defaults (e.g. std_dev=2).
    CREATE TEMP TABLE IF NOT EXISTS _bt_ind_fp (
        indicator_id INTEGER PRIMARY KEY,
        params_fp TEXT NOT NULL
    ) ON COMMIT DROP;
    DELETE FROM _bt_ind_fp;

    FOR v_ind IN
        SELECT DISTINCT lis.indicator_id
        FROM logic_indicator_signals lis
        WHERE lis.logic_id = p_logic_id AND lis.is_active = TRUE
    LOOP
        BEGIN
            CALL ensure_security_indicator_series(p_security_id, v_ind.indicator_id);
            INSERT INTO _bt_ind_fp (indicator_id, params_fp)
            SELECT
                v_ind.indicator_id,
                COALESCE(string_agg(
                    concat_ws('|',
                        param_period::text,
                        param_std_dev::text,
                        param_fast_period::text,
                        param_slow_period::text,
                        param_signal_period::text,
                        param_k_period::text,
                        param_d_period::text,
                        param_smooth::text
                    ),
                    ';' ORDER BY id
                ), '')
            FROM security_indicator_series
            WHERE security_id = p_security_id
              AND indicator_id = v_ind.indicator_id
              AND is_active = TRUE
            ON CONFLICT (indicator_id) DO UPDATE SET params_fp = EXCLUDED.params_fp;
        EXCEPTION WHEN OTHERS THEN
            p_ind_errors := p_ind_errors + 1;
            PERFORM logic_backtest_log(
                p_run_id, p_logic_id, 'backtest.indicator.error', SQLERRM,
                jsonb_build_object(
                    'security_id', p_security_id,
                    'indicator_id', v_ind.indicator_id,
                    'phase', 'ensure'
                ),
                p_security_id, p_tf_id
            );
        END;
    END LOOP;

    BEGIN
        CALL logic_apply_indicator_params_from_signals(p_logic_id, p_security_id);
    EXCEPTION WHEN OTHERS THEN
        p_ind_errors := p_ind_errors + 1;
        PERFORM logic_backtest_log(
            p_run_id, p_logic_id, 'backtest.indicator.error', SQLERRM,
            jsonb_build_object('security_id', p_security_id, 'phase', 'apply_params'),
            p_security_id, p_tf_id
        );
    END;

    FOR v_ind IN
        SELECT DISTINCT lis.indicator_id
        FROM logic_indicator_signals lis
        WHERE lis.logic_id = p_logic_id AND lis.is_active = TRUE
    LOOP
        DECLARE
            v_fp_before TEXT;
            v_fp_after TEXT;
            v_params_changed BOOLEAN;
        BEGIN
            SELECT params_fp INTO v_fp_before
            FROM _bt_ind_fp
            WHERE indicator_id = v_ind.indicator_id;

            SELECT COALESCE(string_agg(
                concat_ws('|',
                    param_period::text,
                    param_std_dev::text,
                    param_fast_period::text,
                    param_slow_period::text,
                    param_signal_period::text,
                    param_k_period::text,
                    param_d_period::text,
                    param_smooth::text
                ),
                ';' ORDER BY id
            ), '') INTO v_fp_after
            FROM security_indicator_series
            WHERE security_id = p_security_id
              AND indicator_id = v_ind.indicator_id
              AND is_active = TRUE;

            v_params_changed := COALESCE(v_fp_before, '') IS DISTINCT FROM COALESCE(v_fp_after, '');

            IF NOT v_need_prices
               AND NOT v_params_changed
               AND backtest_indicators_cached(
                   p_security_id, p_tf_id, v_ind.indicator_id, p_date_from, p_date_to
               ) THEN
                p_ind_cached := p_ind_cached + 1;
                CONTINUE;
            END IF;

            CALL sync_security_indicator_series_for_indicator(
                p_security_id, v_ind.indicator_id, p_tf_id, p_end_dt, p_point_count, FALSE
            );
            p_ind_synced := p_ind_synced + 1;
        EXCEPTION WHEN OTHERS THEN
            p_ind_errors := p_ind_errors + 1;
            PERFORM logic_backtest_log(
                p_run_id, p_logic_id, 'backtest.indicator.error', SQLERRM,
                jsonb_build_object('security_id', p_security_id, 'indicator_id', v_ind.indicator_id),
                p_security_id, p_tf_id
            );
        END;
    END LOOP;

    -- РњСѓР»СЊС‚РёС‚Р°Р№РјС„СЂРµР№Рј-СЃРёРіРЅР°Р»С‹ (#843): С†РµРЅС‹ + СЃРµСЂРёРё РЅР° РўР¤ РєР°Р¶РґРѕРіРѕ tf= СЃРёРіРЅР°Р»Р°.
    -- РћРєРЅРѕ С‚РѕС‡РµРє РјР°СЃС€С‚Р°Р±РёСЂСѓРµС‚СЃСЏ РѕС‚ РўР¤ Р»РѕРіРёРєРё (M5-СЃРёРіРЅР°Р» РЅР° M15-Р»РѕРіРёРєРµ в†’ Г—3 Р±Р°СЂРѕРІ).
    FOR v_mtf IN
        SELECT x.tf_id, GREATEST(t.sec, 60) AS tf_sec
        FROM logic_signal_extra_tf_ids(p_logic_id, p_tf_id) x
        JOIN timeframes t ON t.id = x.tf_id
    LOOP
        BEGIN
            v_mtf_point_count := CEIL(
                p_point_count * GREATEST((SELECT t.sec FROM timeframes t WHERE t.id = p_tf_id), 60)::NUMERIC
                / v_mtf.tf_sec
            )::INTEGER + 50;

            BEGIN
                CALL load_prices(p_security_id, v_mtf.tf_id, p_warmup_from, p_date_to);
                p_prices_loaded := p_prices_loaded + 1;
            EXCEPTION WHEN OTHERS THEN
                PERFORM logic_backtest_log(
                    p_run_id, p_logic_id, 'backtest.prices.error', SQLERRM,
                    jsonb_build_object('security_id', p_security_id, 'role', 'signal_tf'),
                    p_security_id, v_mtf.tf_id
                );
            END;

            FOR v_ind IN
                SELECT DISTINCT lis.indicator_id
                FROM logic_indicator_signals lis
                WHERE lis.logic_id = p_logic_id AND lis.is_active = TRUE
            LOOP
                BEGIN
                    CALL ensure_security_indicator_series(p_security_id, v_ind.indicator_id);
                    CALL logic_apply_indicator_params_from_signals(p_logic_id, p_security_id);
                    CALL sync_security_indicator_series_for_indicator(
                        p_security_id, v_ind.indicator_id, v_mtf.tf_id, p_end_dt, v_mtf_point_count, FALSE
                    );
                    p_ind_synced := p_ind_synced + 1;
                EXCEPTION WHEN OTHERS THEN
                    p_ind_errors := p_ind_errors + 1;
                    PERFORM logic_backtest_log(
                        p_run_id, p_logic_id, 'backtest.indicator.error', SQLERRM,
                        jsonb_build_object('security_id', p_security_id, 'indicator_id', v_ind.indicator_id, 'role', 'signal_tf'),
                        p_security_id, v_mtf.tf_id
                    );
                END;
            END LOOP;
        EXCEPTION WHEN OTHERS THEN
            p_ind_errors := p_ind_errors + 1;
            PERFORM logic_backtest_log(
                p_run_id, p_logic_id, 'backtest.signal_tf.error', SQLERRM,
                jsonb_build_object('security_id', p_security_id, 'tf_id', v_mtf.tf_id),
                p_security_id, v_mtf.tf_id
            );
        END;
    END LOOP;

    -- РРЅРґРёРєР°С‚РѕСЂС‹ РЅР° Р±Р°Р·РѕРІРѕРј Р°РєС‚РёРІРµ (signal_acts_on=base_asset)
    FOR v_ind IN
        SELECT DISTINCT
            lis.indicator_id,
            logic_future_underlying_security_id(p_security_id) AS eval_sec_id
        FROM logic_indicator_signals lis
        WHERE lis.logic_id = p_logic_id
          AND lis.is_active = TRUE
          AND COALESCE(lis.signal_acts_on, 'security') = 'base_asset'
    LOOP
        IF v_ind.eval_sec_id IS NULL OR v_ind.eval_sec_id = p_security_id THEN
            CONTINUE;
        END IF;
        BEGIN
            CALL ensure_security_indicator_series(v_ind.eval_sec_id, v_ind.indicator_id);
            CALL logic_apply_indicator_params_from_signals(p_logic_id, v_ind.eval_sec_id);
            CALL sync_security_indicator_series_for_indicator(
                v_ind.eval_sec_id, v_ind.indicator_id, p_tf_id, p_end_dt, p_point_count, FALSE
            );
            p_ind_synced := p_ind_synced + 1;
        EXCEPTION WHEN OTHERS THEN
            p_ind_errors := p_ind_errors + 1;
            PERFORM logic_backtest_log(
                p_run_id, p_logic_id, 'backtest.indicator.error', SQLERRM,
                jsonb_build_object(
                    'security_id', v_ind.eval_sec_id,
                    'trade_security_id', p_security_id,
                    'indicator_id', v_ind.indicator_id,
                    'role', 'base_asset'
                ),
                p_security_id, p_tf_id
            );
        END;
    END LOOP;

    -- РРЅРґРёРєР°С‚РѕСЂС‹ РЅР° РєРѕРЅС‚Р°РЅРіРѕ (signal_acts_on=contango)
    FOR v_ind IN
        SELECT DISTINCT
            lis.indicator_id,
            logic_contango_security_id(p_security_id) AS eval_sec_id
        FROM logic_indicator_signals lis
        WHERE lis.logic_id = p_logic_id
          AND lis.is_active = TRUE
          AND COALESCE(lis.signal_acts_on, 'security') = 'contango'
    LOOP
        IF v_ind.eval_sec_id IS NULL OR v_ind.eval_sec_id = p_security_id THEN
            CONTINUE;
        END IF;
        BEGIN
            CALL ensure_security_indicator_series(v_ind.eval_sec_id, v_ind.indicator_id);
            CALL logic_apply_indicator_params_from_signals(p_logic_id, v_ind.eval_sec_id);
            CALL sync_security_indicator_series_for_indicator(
                v_ind.eval_sec_id, v_ind.indicator_id, p_tf_id, p_end_dt, p_point_count, FALSE
            );
            p_ind_synced := p_ind_synced + 1;
        EXCEPTION WHEN OTHERS THEN
            p_ind_errors := p_ind_errors + 1;
            PERFORM logic_backtest_log(
                p_run_id, p_logic_id, 'backtest.indicator.error', SQLERRM,
                jsonb_build_object(
                    'security_id', v_ind.eval_sec_id,
                    'trade_security_id', p_security_id,
                    'indicator_id', v_ind.indicator_id,
                    'role', 'contango'
                ),
                p_security_id, p_tf_id
            );
        END;
    END LOOP;
END;
$$;

COMMENT ON PROCEDURE logic_backtest_ensure_security_data IS
'Backtest: load_prices; sync contango; apply signal params; sync indicators. '
'Also loads/syncs base_asset and contango synthetics for futures signals.';

CREATE OR REPLACE PROCEDURE logic_backtest_run_bars(p_run_id BIGINT)
LANGUAGE plpgsql AS $$
DECLARE
    v_run RECORD;
    v_logic RECORD;
    v_tf_id INTEGER;
    v_balance NUMERIC;
    v_bars TIMESTAMP[];
    v_total INTEGER;
    v_i INTEGER;
    v_bar_dt TIMESTAMP;
    v_prev_bar TIMESTAMP;
    v_next_bar TIMESTAMP;
    v_pnl NUMERIC;
    v_trades_created INTEGER;
    v_diag JSONB;
    v_commit_every INTEGER := 5;
BEGIN
    SELECT r.id, r.logic_id, r.date_from, r.date_to, r.status, r.cancel_requested, r.test_balance,
           r.close_all_at_end
    INTO v_run
    FROM logic_backtest_runs r
    WHERE r.id = p_run_id;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'backtest run % РЅРµ РЅР°Р№РґРµРЅ', p_run_id;
    END IF;

    IF v_run.status IN ('completed', 'cancelled', 'failed') THEN
        RETURN;
    END IF;

    IF COALESCE(v_run.cancel_requested, FALSE) THEN
        PERFORM logic_backtest_update_run(p_run_id, 'cancelled', NULL, 'РћС‚РјРµРЅРµРЅРѕ', NULL);
        COMMIT;
        RETURN;
    END IF;

    SELECT l.id, l.account_id INTO v_logic
    FROM logics l WHERE l.id = v_run.logic_id;
    IF NOT FOUND THEN
        PERFORM logic_backtest_update_run(
            p_run_id, 'failed', 100, 'Р›РѕРіРёРєР° РЅРµ РЅР°Р№РґРµРЅР°', NULL, NULL, NULL, NULL, NULL, 0,
            format('Р›РѕРіРёРєР° %s РЅРµ РЅР°Р№РґРµРЅР°', v_run.logic_id)
        );
        COMMIT;
        RETURN;
    END IF;

    PERFORM logic_ensure_non_trading_periods(v_run.logic_id);

    v_tf_id := logic_resolve_timeframe_id(v_run.logic_id);
    IF v_tf_id IS NULL THEN
        PERFORM logic_backtest_update_run(
            p_run_id, 'failed', 100, 'РќРµ Р·Р°РґР°РЅ timeframe', NULL, NULL, NULL, NULL, NULL, 0,
            'РќРµ Р·Р°РґР°РЅ timeframe'
        );
        COMMIT;
        RETURN;
    END IF;

    v_balance := COALESCE(
        NULLIF(v_run.test_balance, 0),
        NULLIF(get_logic_param_numeric(v_run.logic_id, 'initial_balance', NULL), 0),
        1000000
    );

    SELECT array_agg(DISTINCT p.dt ORDER BY p.dt)
    INTO v_bars
    FROM prices p
    JOIN logic_securities ls ON ls.security_id = p.security_id
    WHERE ls.logic_id = v_run.logic_id AND ls.is_active = TRUE
      AND p.timeframe_id = v_tf_id
      AND p.dt::date BETWEEN v_run.date_from AND v_run.date_to;

    v_total := COALESCE(array_length(v_bars, 1), 0);
    UPDATE logic_backtest_runs
    SET total_bars = v_total,
        trades_created = 0,
        processed_bars = 0
    WHERE id = p_run_id;

    IF v_total = 0 THEN
        PERFORM logic_backtest_update_run(
            p_run_id, 'failed', 100, 'РќРµС‚ СЃРІРµС‡РµР№', NULL, NULL, NULL, NULL, v_balance, 0,
            'РќРµС‚ С†РµРЅ РІ РІС‹Р±СЂР°РЅРЅРѕРј РїРµСЂРёРѕРґРµ'
        );
        COMMIT;
        RETURN;
    END IF;

    PERFORM logic_backtest_update_run(
        p_run_id, 'running', 40, 'РџСЂРѕРіРѕРЅ РїРѕ СЃРІРµС‡Р°Рј',
        format('0 / %s Р±Р°СЂРѕРІ', v_total),
        NULL, 0, NULL, v_balance
    );
    COMMIT;

    FOR v_i IN 1..v_total LOOP
        IF logic_backtest_cancel_requested(p_run_id) THEN
            SELECT COALESCE(SUM(financial_result), 0) INTO v_pnl
            FROM logic_trades
            WHERE logic_id = v_run.logic_id
              AND is_test = TRUE
              AND COALESCE(opt_lane, '') = '';
            PERFORM logic_opt_restore_formulas_from_run(p_run_id);
            PERFORM logic_backtest_log(
                p_run_id, v_run.logic_id, 'backtest.cancelled',
                format('РћС‚РјРµРЅРµРЅРѕ РЅР° %s/%s', v_i, v_total), NULL
            );
            PERFORM logic_backtest_update_run(
                p_run_id, 'cancelled',
                round(40 + v_i::NUMERIC / v_total * 60, 2),
                'РћС‚РјРµРЅРµРЅРѕ РїРѕР»СЊР·РѕРІР°С‚РµР»РµРј', NULL, v_bars[v_i], v_i, NULL, v_balance, v_pnl
            );
            COMMIT;
            RETURN;
        END IF;

        v_bar_dt := v_bars[v_i];
        v_prev_bar := CASE WHEN v_i > 1 THEN v_bars[v_i - 1] ELSE NULL END;
        v_next_bar := CASE WHEN v_i < v_total THEN v_bars[v_i + 1] ELSE NULL END;

        v_balance := logic_backtest_process_bar(
            p_run_id, v_run.logic_id, v_logic.account_id, v_tf_id,
            v_bar_dt, v_prev_bar, v_next_bar, v_balance
        );

        IF v_i % v_commit_every = 0 OR v_i = v_total THEN
            PERFORM logic_backtest_update_run(
                p_run_id, 'running',
                round(40 + v_i::NUMERIC / v_total * 60, 2),
                'РџСЂРѕРіРѕРЅ РїРѕ СЃРІРµС‡Р°Рј',
                format('%s / %s Р±Р°СЂРѕРІ', v_i, v_total),
                v_bar_dt, v_i, NULL, v_balance
            );
            COMMIT;
        END IF;
    END LOOP;

    IF v_total > 0 THEN
        v_balance := logic_backtest_park_excess_cash(
            p_run_id, v_run.logic_id, v_logic.account_id, v_tf_id, v_bars[v_total], v_balance
        );
        -- #1061: РіР°Р»РѕС‡РєР° В«РџРѕ РѕРєРѕРЅС‡Р°РЅРёРё С‚РµСЃС‚Р° Р·Р°РєСЂС‹С‚СЊ РІСЃРµ РїРѕР·РёС†РёРёВ» (default TRUE).
        -- #1040 РѕСЃС‚Р°РІРёР» equity СЃ РїРµСЂРµРѕС†РµРЅРєРѕР№ РЅР° РєР°Р¶РґРѕРј Р±Р°СЂРµ; С‚РµРїРµСЂСЊ РїРѕСЃР»РµРґРЅРёРј
        -- Р°РєС‚РѕРј РїСЂРѕРіРѕРЅР° СЃС‚Р°РЅРѕРІРёС‚СЃСЏ Р»РёРєРІРёРґР°С†РёСЏ, РµСЃР»Рё РіР°Р»РѕС‡РєР° РІРєР»СЋС‡РµРЅР°.
        IF COALESCE(v_run.close_all_at_end, TRUE) THEN
            v_balance := logic_backtest_close_all_except_funds(
                p_run_id, v_run.logic_id, v_logic.account_id, v_tf_id, v_bars[v_total], v_balance
            );
        END IF;
    END IF;

    -- #1039: С‚РµРЅРµРІС‹Рµ (shadow) СЃРґРµР»РєРё вЂ” Р±СѓРјР°Р¶РЅС‹Рµ, РІ С„РёРЅСЂРµР· РїСЂРѕРіРѕРЅР° РЅРµ РІС…РѕРґСЏС‚.
    SELECT COALESCE(SUM(financial_result), 0) INTO v_pnl
    FROM logic_trades
    WHERE logic_id = v_run.logic_id
      AND is_test = TRUE
      AND COALESCE(is_shadow, FALSE) = FALSE
      AND COALESCE(opt_lane, '') = '';

    SELECT COUNT(*)::INTEGER INTO v_trades_created
    FROM logic_trades
    WHERE logic_id = v_run.logic_id
      AND is_test = TRUE
      AND COALESCE(opt_lane, '') = '';

    v_diag := logic_backtest_diagnose(
        p_run_id, v_run.logic_id, v_tf_id, v_run.date_from, v_run.date_to
    );

    PERFORM logic_opt_restore_formulas_from_run(p_run_id);

    PERFORM logic_backtest_log(
        p_run_id, v_run.logic_id, 'backtest.complete',
        CASE WHEN v_trades_created > 0
            THEN format('Р—Р°РІРµСЂС€РµРЅРѕ: %s СЃРґРµР»РѕРє, PnL=%s', v_trades_created, round(v_pnl, 2))
            ELSE format('Р—Р°РІРµСЂС€РµРЅРѕ Р±РµР· СЃРґРµР»РѕРє (%s Р±Р°СЂРѕРІ)', v_total)
        END,
        v_diag || jsonb_build_object(
            'trades_created', v_trades_created,
            'financial_result', v_pnl,
            'total_bars', v_total,
            'engine', 'sql_procedure'
        ),
        NULL, v_tf_id
    );

    PERFORM logic_backtest_update_run(
        p_run_id, 'completed', 100,
        CASE WHEN v_trades_created > 0 THEN 'РўРµСЃС‚РёСЂРѕРІР°РЅРёРµ Р·Р°РІРµСЂС€РµРЅРѕ' ELSE 'РўРµСЃС‚ Р·Р°РІРµСЂС€С‘РЅ вЂ” СЃРґРµР»РѕРє РЅРµС‚' END,
        format('%s Р±Р°СЂРѕРІ, СЃРґРµР»РѕРє: %s', v_total, v_trades_created),
        v_bars[v_total], v_total, v_trades_created, v_balance, v_pnl
    );
    COMMIT;
END;
$$;

COMMENT ON PROCEDURE logic_backtest_run_bars(BIGINT) IS
'SQL-СЂРѕР±РѕС‚ С‚РµСЃС‚Р°: РїСЂРѕРіРѕРЅ Р±Р°СЂРѕРІ СЃ COMMIT РєР°Р¶РґС‹Рµ 5 СЃРІРµС‡РµР№ (Р±РµР· РґР»РёРЅРЅРѕРіРѕ Р»РѕРєР° РЅР° РІРµСЃСЊ С‚РµСЃС‚)';

DROP ROUTINE IF EXISTS run_logic_backtest(INTEGER, DATE, DATE);
DROP ROUTINE IF EXISTS run_logic_backtest(INTEGER, DATE, DATE, BIGINT);

CREATE OR REPLACE PROCEDURE logic_rating_precalc_ensure_data(p_logic_id INTEGER,
    p_timeframe_id INTEGER,
    p_lookback_days INTEGER)
LANGUAGE plpgsql AS $$
DECLARE
    v_sec RECORD;
    v_sig RECORD;
    v_tf_sec INTEGER;
    v_date_from DATE;
    v_date_to DATE;
    v_point_count INTEGER;
    v_end_dt TIMESTAMP;
    v_days INTEGER;
    v_err TEXT;
BEGIN
    v_days := GREATEST(1, LEAST(90, COALESCE(p_lookback_days, 7)));
    SELECT t.sec INTO v_tf_sec FROM timeframes t WHERE t.id = p_timeframe_id;
    IF v_tf_sec IS NULL OR v_tf_sec <= 0 THEN
        RAISE EXCEPTION 'logic_rating_precalc_ensure_data: РЅРµРёР·РІРµСЃС‚РЅС‹Р№ timeframe_id %', p_timeframe_id;
    END IF;

    v_date_to := CURRENT_DATE;
    -- M1/M2: Сѓ T-Bank РѕР±С‹С‡РЅРѕ С‚РѕР»СЊРєРѕ С‚РµРєСѓС‰РёР№ РґРµРЅСЊ
    IF COALESCE(v_tf_sec, 0) <= 120 THEN
        v_date_from := v_date_to;
    ELSE
        v_date_from := v_date_to - v_days;
    END IF;

    v_point_count := GREATEST(
        logic_trade_sync_point_count(v_tf_sec),
        (CEIL(v_days * 86400.0 / v_tf_sec)::INTEGER) + 80
    );
    v_end_dt := logic_last_closed_bar_dt(v_tf_sec, LOCALTIMESTAMP);

    FOR v_sec IN
        SELECT ls.security_id
        FROM logic_securities ls
        WHERE ls.logic_id = p_logic_id AND ls.is_active = TRUE
        ORDER BY ls.display_order, ls.security_id
    LOOP
        BEGIN
            CALL load_prices(v_sec.security_id, p_timeframe_id, v_date_from, v_date_to);
        EXCEPTION
            WHEN undefined_function THEN
                NULL;
            WHEN OTHERS THEN
                v_err := SQLERRM;
                PERFORM logic_trade_log(
                    p_logic_id,
                    'rating.precalc.prices.error',
                    format('РџСЂРµРґСЂР°СЃС‡С‘С‚: РѕС€РёР±РєР° С†РµРЅ sec=%s: %s', v_sec.security_id, v_err),
                    jsonb_build_object(
                        'security_id', v_sec.security_id,
                        'date_from', v_date_from,
                        'date_to', v_date_to,
                        'error', v_err
                    ),
                    v_sec.security_id,
                    p_timeframe_id
                );
        END;

        -- underlying + contango РґР»СЏ СЃРёРіРЅР°Р»РѕРІ base_asset/contango
        FOR v_sig IN
            SELECT DISTINCT logic_future_underlying_security_id(v_sec.security_id) AS und_id
            FROM logic_indicator_signals lis
            WHERE lis.logic_id = p_logic_id
              AND lis.is_active = TRUE
              AND COALESCE(lis.signal_acts_on, 'security') IN ('base_asset', 'contango')
        LOOP
            IF v_sig.und_id IS NULL OR v_sig.und_id = v_sec.security_id THEN
                CONTINUE;
            END IF;
            BEGIN
                CALL load_prices(v_sig.und_id, p_timeframe_id, v_date_from, v_date_to);
            EXCEPTION
                WHEN OTHERS THEN
                    NULL;
            END;
        END LOOP;

        IF EXISTS (
            SELECT 1 FROM logic_indicator_signals lis
            WHERE lis.logic_id = p_logic_id AND lis.is_active
              AND COALESCE(lis.signal_acts_on, 'security') = 'contango'
        ) THEN
            PERFORM sync_contango_prices(
                v_sec.security_id, p_timeframe_id, v_date_from, v_date_to
            );
        END IF;

        FOR v_sig IN
            SELECT DISTINCT
                lis.indicator_id,
                logic_signal_resolve_eval_security(
                    lis.signal_acts_on, v_sec.security_id
                ) AS eval_sec_id
            FROM logic_indicator_signals lis
            WHERE lis.logic_id = p_logic_id AND lis.is_active = TRUE
        LOOP
            IF v_sig.eval_sec_id IS NULL THEN
                CONTINUE;
            END IF;
            BEGIN
                CALL ensure_security_indicator_series(v_sig.eval_sec_id, v_sig.indicator_id);
                CALL logic_apply_indicator_params_from_signals(p_logic_id, v_sig.eval_sec_id);
                CALL sync_security_indicator_series_for_indicator(
                    v_sig.eval_sec_id,
                    v_sig.indicator_id,
                    p_timeframe_id,
                    v_end_dt,
                    v_point_count,
                    FALSE
                );
            EXCEPTION WHEN OTHERS THEN
                v_err := SQLERRM;
                PERFORM logic_trade_log(
                    p_logic_id,
                    'rating.precalc.indicator.error',
                    format('РџСЂРµРґСЂР°СЃС‡С‘С‚: РѕС€РёР±РєР° РёРЅРґРёРєР°С‚РѕСЂР° sec=%s ind=%s: %s',
                           v_sig.eval_sec_id, v_sig.indicator_id, v_err),
                    jsonb_build_object(
                        'security_id', v_sig.eval_sec_id,
                        'trade_security_id', v_sec.security_id,
                        'indicator_id', v_sig.indicator_id,
                        'error', v_err
                    ),
                    v_sec.security_id,
                    p_timeframe_id
                );
            END;
        END LOOP;
    END LOOP;
END;
$$;

COMMENT ON PROCEDURE logic_rating_precalc_ensure_data(INTEGER, INTEGER, INTEGER) IS
'РџРµСЂРµРґ Р±РѕРµРІС‹Рј РїСЂРµРґСЂР°СЃС‡С‘С‚РѕРј СЂРµР№С‚РёРЅРіР°: load_prices + contango sync + sync РёРЅРґРёРєР°С‚РѕСЂРѕРІ';

-- ============================================================================
-- РўРµСЃС‚ Р’Р«Р§РРЎР›РРњР«РҐ РёРЅРґРёРєР°С‚РѕСЂРѕРІ СЃРїСЂР°РІРѕС‡РЅРёРєР° в†’ СЂРµР№С‚РёРЅРі (% РіРѕРґРѕРІС‹С…).
-- Р¤РѕРЅРѕРІС‹Р№, РїРѕ РѕСЃС‚Р°С‚РѕС‡РЅРѕРјСѓ РїСЂРёРЅС†РёРїСѓ, РЅР° РЈР–Р• Р·Р°РіСЂСѓР¶РµРЅРЅС‹С… С†РµРЅР°С… (Р±РµР· load_prices).
-- РџСЂРёСЃС‚СЂР°РёРІР°РµС‚СЃСЏ Рє СЂР°Р±РѕС‚Р°СЋС‰РµР№ Р»РѕРіРёРєРµ: РїРѕСЃР»Рµ РµС‘ С†РёРєР»Р°/Р·Р°РіСЂСѓР·РєРё С†РµРЅ РїРµСЂРµСЃС‡РёС‚С‹РІР°РµРј
-- СЂРµР№С‚РёРЅРі РїРѕ СЋРЅРёРІРµСЂСЃСѓ РїР°СЂ (Р±СѓРјР°РіР° Г— РўР¤) РёРјРµРЅРЅРѕ СЌС‚РѕР№ Р»РѕРіРёРєРё (p_logic_id), РІ С„РѕРЅРµ.
--
-- Р”Р»СЏ РєР°Р¶РґРѕРіРѕ РІС‹С‡РёСЃР»РёРјРѕРіРѕ РёРЅРґРёРєР°С‚РѕСЂР° (РµСЃС‚СЊ formula/script Рё non-threshold С‚РёРїС‹):
--   1) РїРѕ РєР°Р¶РґРѕР№ РїР°СЂРµ (Р±СѓРјР°РіР° Г— РўР¤) вЂ” РёР· СЋРЅРёРІРµСЂСЃР° Р»РѕРіРёРєРё (РёР»Рё РІСЃРµС… Р»РѕРіРёРє, РµСЃР»Рё
--      p_logic_id IS NULL) вЂ” РѕРґРёРЅ СЂР°Р· СЃС‡РёС‚Р°РµРј Р·РЅР°С‡РµРЅРёСЏ РёРЅРґРёРєР°С‚РѕСЂР° РёР· СЃСѓС‰РµСЃС‚РІСѓСЋС‰РёС…
--      С†РµРЅ (РёРЅРєСЂРµРјРµРЅС‚Р°Р»СЊРЅРѕ);
--      РґР»СЏ РѕС†РµРЅРєРё Р±РµСЂС‘Рј РїРѕСЃР»РµРґРЅРёРµ p_bars_window Р·Р°РіСЂСѓР¶РµРЅРЅС‹С… СЃРІРµС‡РµР№ РїР°СЂС‹ (Р·Р°С‰РёС‚Р°
--      РѕС‚ СЂРѕСЃС‚Р° РЅР° РґР»РёРЅРЅС‹С… РёСЃС‚РѕСЂРёСЏС… M1);
--   2) РїРѕ РєР°Р¶РґРѕР№ Р·Р°РєСЂС‹С‚РѕР№ СЃРІРµС‡Рµ РїСЂРѕРІРµСЂСЏРµРј СѓСЃР»РѕРІРёСЏ С‚СЂРµРЅРґ/РєРѕРЅС‚СЂС‚СЂРµРЅРґ РёР·
--      indicators.sig_trend_def / sig_ct_def (РЅРѕСЂРјР°Р»РёР·РѕРІР°РЅС‹ Рє РѕРґРЅРѕРјСѓ СЂСЏРґСѓ VALUE);
--   3) В«РїСЂРёР±С‹Р»СЊВ» = Р»СѓС‡С€РёР№ С…РѕРґ: РјР°РєСЃРёРјР°Р»СЊРЅС‹Р№ high (Р»РѕРЅРі) / РјРёРЅРёРјР°Р»СЊРЅС‹Р№ low (С€РѕСЂС‚)
--      СЃСЂРµРґРё Р’РЎР•РҐ СѓР¶Рµ Р·Р°РіСЂСѓР¶РµРЅРЅС‹С… РїРѕСЃР»РµРґСѓСЋС‰РёС… СЃРІРµС‡РµР№, РІ % РіРѕРґРѕРІС‹С… РїРѕ РІСЂРµРјРµРЅРё
--      СѓРґРµСЂР¶Р°РЅРёСЏ РґРѕ СЌС‚РѕР№ Р»СѓС‡С€РµР№ С‚РѕС‡РєРё;
--   4) СѓСЃСЂРµРґРЅСЏРµРј РїРѕ Р±СѓРјР°РіР°Рј РІ СЂР°Р·СЂРµР·Рµ (Р»РѕРЅРі/С€РѕСЂС‚ Г— С‚СЂРµРЅРґ/РєРѕРЅС‚СЂ Г— С‚РёРї РІСЂРµРјРµРЅРё),
--      РіРґРµ С‚РёРї РІСЂРµРјРµРЅРё: СЂР°Р±РѕС‡РёР№ РґРµРЅСЊ/РІС‹С…РѕРґРЅРѕР№ Г— С‚РѕСЂРіРѕРІР°СЏ/РЅРµС‚РѕСЂРіРѕРІР°СЏ СЃРµСЃСЃРёСЏ
--      (СЂС‹РЅРѕС‡РЅС‹Р№ С€Р°Р±Р»РѕРЅ MOEX logic_moex_equity_non_trading_template);
--   5) СЂР°Р·СЂРµР·С‹ СЃ С‡РёСЃР»РѕРј СЃРёРіРЅР°Р»РѕРІ РјРµРЅСЊС€Рµ РїРѕСЂРѕРіР° РЅРµ СѓС‡РёС‚С‹РІР°СЋС‚СЃСЏ; РіРѕРґРѕРІС‹Рµ РѕР±СЂРµР·Р°СЋС‚СЃСЏ
--      (СѓРёРЅСЃРѕСЂРёР·Р°С†РёСЏ) РґР»СЏ РіР°С€РµРЅРёСЏ РІС‹Р±СЂРѕСЃРѕРІ.
--   Р РµР№С‚РёРЅРі РёРЅРґРёРєР°С‚РѕСЂР° = РјР°РєСЃРёРјСѓРј СЃСЂРµРґРЅРµРіРѕ % РіРѕРґРѕРІС‹С… РїРѕ РІСЃРµРј СЂР°Р·СЂРµР·Р°Рј.
--
-- РќР• РїСѓС‚Р°С‚СЊ СЃ СЂРµР№С‚РёРЅРіРѕРј СЃРёРіРЅР°Р»Р° РЅР° Р»РѕРіРёРєРµ (sql/logic_signal_and_rating.sql).
-- Р РµР·СѓР»СЊС‚Р°С‚С‹: indicator_rating_sample (СЃС‹СЂСЊС‘, СЃСѓС‚РєРё) Рё indicator_rating (Р°РіСЂРµРіР°С‚).
-- ============================================================================

-- РџР°СЂР°РјРµС‚СЂС‹ РїРѕ СѓРјРѕР»С‡Р°РЅРёСЋ РґР»СЏ Р°РІС‚Рѕ-С„РѕСЂРјСѓР»С‹ РёРЅРґРёРєР°С‚РѕСЂР° (СЃРµСЂРёСЏ РІС‹РЅРµСЃРµРЅР° РІ series=).

CREATE OR REPLACE PROCEDURE logic_refresh_market_data(p_logic_id INTEGER,
    p_timeframe_id INTEGER,
    p_closed_bar_dt TIMESTAMP,
    p_skip_http BOOLEAN DEFAULT FALSE)
LANGUAGE plpgsql AS $$
DECLARE
    v_sec RECORD;
    v_sig RECORD;
    v_date_from DATE;
    v_date_to DATE;
    v_point_count INTEGER;
    v_tf_sec INTEGER;
    v_err TEXT;
    v_skip_http BOOLEAN := FALSE;
    v_missing_prices INTEGER;
BEGIN
    -- #1022: В«СЃРґРІРёРЅСѓС‚Р°СЏВ» РјРѕР»РЅРёСЏ СЃС‡РёС‚Р°РµС‚ СЃРёРіРЅР°Р»С‹ РЅР° РІСЂРµРјРµРЅРЅРѕРј СЂСЏРґРµ prices вЂ”
    -- РґРѕРіСЂСѓР·РєР°/СЂРµР·СЌРјРїР»РёРЅРі РЅР°С‚РёРІРЅС‹С… Р±Р°СЂРѕРІ СЃСЋРґР° РЅРµ РЅСѓР¶РЅС‹ Рё С‚РѕР»СЊРєРѕ СЃРјРµС€Р°СЋС‚ СЂСЏРґ.
    IF current_setting('app.lightning_skip_refresh', TRUE) = '1' THEN
        RETURN;
    END IF;

    SELECT t.sec INTO v_tf_sec FROM timeframes t WHERE t.id = p_timeframe_id;

    v_point_count := logic_trade_sync_point_count(v_tf_sec);
    v_date_to := GREATEST(p_closed_bar_dt::date, CURRENT_DATE);
    v_date_from := logic_trade_load_date_from(v_tf_sec, v_point_count, p_closed_bar_dt);

    SELECT EXISTS (
        SELECT 1
        FROM logic_backtest_runs r
        WHERE r.status IN ('pending', 'loading_prices', 'loading_indicators', 'running')
    ) INTO v_skip_http;

    -- РўРµСЂРјРёРЅР°Р»СЊРЅС‹Рµ СЃРёРіРЅР°Р»С‹ (use_as_terminal_signal) РґРѕРіСЂСѓР¶Р°СЋС‚ РЅРµРґРѕСЃС‚Р°СЋС‰РёРµ closed-СЃРІРµС‡Рё
    -- РёРЅРєСЂРµРјРµРЅС‚Р°Р»СЊРЅРѕ (1 HTTP С‡РµСЂРµР· prices_topup_date_from), РєР°Рє РѕР±С‹С‡РЅР°СЏ С‚РѕСЂРіРѕРІР»СЏ вЂ” С‡С‚РѕР±С‹
    -- СЃРёРіРЅР°Р»С‹ С€Р»Рё РґР°Р¶Рµ Р±РµР· РѕС‚РєСЂС‹С‚С‹С… РїР°РЅРµР»РµР№. Р‘РµР· HTTP РѕСЃС‚Р°СЋС‚СЃСЏ С‚РѕР»СЊРєРѕ РїСЂРё Р°РєС‚РёРІРЅРѕРј Р±СЌРєС‚РµСЃС‚Рµ.
    v_skip_http := v_skip_http OR COALESCE(p_skip_http, FALSE);

    SELECT COUNT(*)::INTEGER INTO v_missing_prices
    FROM logic_securities ls
    WHERE ls.logic_id = p_logic_id
      AND ls.is_active = TRUE
      AND NOT prices_have_closed_bar(ls.security_id, p_timeframe_id, p_closed_bar_dt);

    -- Р‘С‹СЃС‚СЂС‹Р№ РїСѓС‚СЊ: С†РµРЅС‹ РЅР° closed bar РµСЃС‚СЊ Сѓ РІСЃРµС… вЂ” С‚РѕР»СЊРєРѕ РЅРµРґРѕСЃС‚Р°СЋС‰РёРµ РёРЅРґРёРєР°С‚РѕСЂС‹, Р±РµР· HTTP.
    IF v_missing_prices = 0 THEN
        FOR v_sec IN
            SELECT ls.security_id
            FROM logic_securities ls
            WHERE ls.logic_id = p_logic_id AND ls.is_active = TRUE
        LOOP
            -- РџР°СЂР°РјРµС‚СЂС‹ РёР· С„РѕСЂРјСѓР» вЂ” РѕРґРёРЅ СЂР°Р· РЅР° Р±СѓРјР°РіСѓ (РЅРµ РЅР° РєР°Р¶РґС‹Р№ indicator_id)
            BEGIN
                CALL logic_apply_indicator_params_from_signals(p_logic_id, v_sec.security_id);
            EXCEPTION
                WHEN OTHERS THEN
                    NULL;
            END;
            -- Contango: РјР°С‚РµСЂРёР°Р»РёР·РѕРІР°С‚СЊ СЃРїСЂРµРґ, РµСЃР»Рё РµСЃС‚СЊ С‚Р°РєРёРµ СЃРёРіРЅР°Р»С‹
            IF EXISTS (
                SELECT 1 FROM logic_indicator_signals lis
                WHERE lis.logic_id = p_logic_id AND lis.is_active
                  AND COALESCE(lis.signal_acts_on, 'security') = 'contango'
            ) THEN
                PERFORM sync_contango_prices(
                    v_sec.security_id,
                    p_timeframe_id,
                    prices_topup_date_from(
                        v_sec.security_id, p_timeframe_id, p_closed_bar_dt, v_date_from
                    ),
                    v_date_to
                );
            END IF;
            FOR v_sig IN
                SELECT DISTINCT
                    lis.indicator_id,
                    logic_signal_resolve_eval_security(
                        lis.signal_acts_on, v_sec.security_id
                    ) AS eval_sec_id
                FROM logic_indicator_signals lis
                WHERE lis.logic_id = p_logic_id AND lis.is_active = TRUE
            LOOP
                IF v_sig.eval_sec_id IS NULL THEN
                    CONTINUE;
                END IF;
                IF indicator_has_closed_bar(
                    v_sig.eval_sec_id, p_timeframe_id, v_sig.indicator_id, p_closed_bar_dt
                ) THEN
                    CONTINUE;
                END IF;
                BEGIN
                    CALL ensure_security_indicator_series(v_sig.eval_sec_id, v_sig.indicator_id);
                    CALL logic_apply_indicator_params_from_signals(p_logic_id, v_sig.eval_sec_id);
                    CALL sync_security_indicator_series_for_indicator(
                        v_sig.eval_sec_id,
                        v_sig.indicator_id,
                        p_timeframe_id,
                        p_closed_bar_dt,
                        v_point_count,
                        TRUE
                    );
                EXCEPTION
                    WHEN OTHERS THEN
                        v_err := SQLERRM;
                        PERFORM logic_trade_log(
                            p_logic_id,
                            'trade.indicator.error',
                            format('РћС€РёР±РєР° СЂР°СЃС‡С‘С‚Р° РёРЅРґРёРєР°С‚РѕСЂР° id=%s sec=%s: %s', v_sig.indicator_id, v_sig.eval_sec_id, v_err),
                            jsonb_build_object(
                                'security_id', v_sig.eval_sec_id,
                                'trade_security_id', v_sec.security_id,
                                'indicator_id', v_sig.indicator_id,
                                'error', v_err
                            ),
                            v_sec.security_id,
                            p_timeframe_id
                        );
                END;
            END LOOP;
        END LOOP;
        RETURN;
    END IF;

    IF v_skip_http THEN
        PERFORM logic_trade_log(
            p_logic_id,
            'trade.prices.skip_http',
            'РџСЂРѕРїСѓСЃРє load_prices: Р°РєС‚РёРІРµРЅ Р±СЌРєС‚РµСЃС‚ (РёСЃРїРѕР»СЊР·СѓРµРј СѓР¶Рµ Р·Р°РіСЂСѓР¶РµРЅРЅС‹Рµ С†РµРЅС‹)',
            jsonb_build_object('closed_bar', p_closed_bar_dt),
            NULL,
            p_timeframe_id
        );
    END IF;

    FOR v_sec IN
        SELECT ls.security_id
        FROM logic_securities ls
        WHERE ls.logic_id = p_logic_id AND ls.is_active = TRUE
    LOOP
        -- РџРѕРІС‚РѕСЂРЅС‹Р№ HTTP РЅР° СѓР¶Рµ РёРјРµСЋС‰СѓСЋСЃСЏ closed-СЃРІРµС‡Сѓ Р±Р»РѕРєРёСЂСѓРµС‚ API / СЂР°СЃРєСЂС‹С‚РёРµ Р±СѓРјР°РіРё
        IF NOT v_skip_http
           AND NOT prices_have_closed_bar(v_sec.security_id, p_timeframe_id, p_closed_bar_dt) THEN
            BEGIN
                CALL load_prices(
                    v_sec.security_id,
                    p_timeframe_id,
                    prices_topup_date_from(
                        v_sec.security_id, p_timeframe_id, p_closed_bar_dt, v_date_from
                    ),
                    v_date_to
                );
            EXCEPTION
                WHEN undefined_function THEN
                    PERFORM logic_trade_log(
                        p_logic_id,
                        'trade.prices.error',
                        'load_prices РЅРµРґРѕСЃС‚СѓРїРµРЅ (РЅРµС‚ HTTP-СЂР°СЃС€РёСЂРµРЅРёСЏ)',
                        jsonb_build_object('security_id', v_sec.security_id),
                        v_sec.security_id,
                        p_timeframe_id
                    );
                WHEN OTHERS THEN
                    v_err := SQLERRM;
                    PERFORM logic_trade_log(
                        p_logic_id,
                        'trade.prices.error',
                        format('РћС€РёР±РєР° Р·Р°РіСЂСѓР·РєРё С†РµРЅ sec=%s: %s', v_sec.security_id, v_err),
                        jsonb_build_object('security_id', v_sec.security_id, 'error', v_err),
                        v_sec.security_id,
                        p_timeframe_id
                    );
            END;
        END IF;

        -- Р¦РµРЅС‹ Р±Р°Р·РѕРІС‹С… Р°РєС‚РёРІРѕРІ РґР»СЏ base_asset / contango
        IF NOT v_skip_http THEN
            FOR v_sig IN
                SELECT DISTINCT logic_future_underlying_security_id(v_sec.security_id) AS und_id
                FROM logic_indicator_signals lis
                WHERE lis.logic_id = p_logic_id
                  AND lis.is_active = TRUE
                  AND COALESCE(lis.signal_acts_on, 'security') IN ('base_asset', 'contango')
            LOOP
                IF v_sig.und_id IS NULL OR v_sig.und_id = v_sec.security_id THEN
                    CONTINUE;
                END IF;
                IF prices_have_closed_bar(v_sig.und_id, p_timeframe_id, p_closed_bar_dt) THEN
                    CONTINUE;
                END IF;
                BEGIN
                    CALL load_prices(
                        v_sig.und_id,
                        p_timeframe_id,
                        prices_topup_date_from(
                            v_sig.und_id, p_timeframe_id, p_closed_bar_dt, v_date_from
                        ),
                        v_date_to
                    );
                EXCEPTION
                    WHEN OTHERS THEN
                        NULL;
                END;
            END LOOP;
        END IF;

        IF EXISTS (
            SELECT 1 FROM logic_indicator_signals lis
            WHERE lis.logic_id = p_logic_id AND lis.is_active
              AND COALESCE(lis.signal_acts_on, 'security') = 'contango'
        ) THEN
            PERFORM sync_contango_prices(
                v_sec.security_id, p_timeframe_id, v_date_from, v_date_to
            );
        END IF;

        BEGIN
            CALL logic_apply_indicator_params_from_signals(p_logic_id, v_sec.security_id);
        EXCEPTION
            WHEN OTHERS THEN
                NULL;
        END;

        FOR v_sig IN
            SELECT DISTINCT
                lis.indicator_id,
                logic_signal_resolve_eval_security(
                    lis.signal_acts_on, v_sec.security_id
                ) AS eval_sec_id
            FROM logic_indicator_signals lis
            WHERE lis.logic_id = p_logic_id AND lis.is_active = TRUE
        LOOP
            IF v_sig.eval_sec_id IS NULL THEN
                CONTINUE;
            END IF;
            IF indicator_has_closed_bar(
                v_sig.eval_sec_id, p_timeframe_id, v_sig.indicator_id, p_closed_bar_dt
            ) THEN
                CONTINUE;
            END IF;
            BEGIN
                CALL ensure_security_indicator_series(v_sig.eval_sec_id, v_sig.indicator_id);
                CALL logic_apply_indicator_params_from_signals(p_logic_id, v_sig.eval_sec_id);
                CALL sync_security_indicator_series_for_indicator(
                    v_sig.eval_sec_id,
                    v_sig.indicator_id,
                    p_timeframe_id,
                    p_closed_bar_dt,
                    v_point_count,
                    TRUE
                );
            EXCEPTION
                WHEN OTHERS THEN
                    v_err := SQLERRM;
                    PERFORM logic_trade_log(
                        p_logic_id,
                        'trade.indicator.error',
                        format('РћС€РёР±РєР° СЂР°СЃС‡С‘С‚Р° РёРЅРґРёРєР°С‚РѕСЂР° id=%s sec=%s: %s', v_sig.indicator_id, v_sig.eval_sec_id, v_err),
                        jsonb_build_object(
                            'security_id', v_sig.eval_sec_id,
                            'trade_security_id', v_sec.security_id,
                            'indicator_id', v_sig.indicator_id,
                            'error', v_err
                        ),
                        v_sec.security_id,
                        p_timeframe_id
                    );
            END;
        END LOOP;
    END LOOP;
END;
$$;

COMMENT ON PROCEDURE logic_refresh_market_data(INTEGER, INTEGER, TIMESTAMP, BOOLEAN) IS
'Р”РѕРіСЂСѓР¶Р°РµС‚/СЂРµР·СЌРјРїР»РёС‚ Р·Р°РєСЂС‹С‚С‹Рµ СЃРІРµС‡Рё РўР¤ Р»РѕРіРёРєРё Рё РґРѕРї. РўР¤ С„РѕСЂРјСѓР», РїСЂРёРјРµРЅСЏРµС‚ РїР°СЂР°РјРµС‚СЂС‹ РёРЅРґРёРєР°С‚РѕСЂРѕРІ; '
'p_skip_http=TRUE РёР»Рё session app.lightning_skip_refresh=1 вЂ” Р±РµР· HTTP (РјРѕР»РЅРёСЏ/Р±СЌРєС‚РµСЃС‚).';

CREATE OR REPLACE PROCEDURE run_logic_backtest(p_logic_id INTEGER,
    p_date_from DATE,
    p_date_to DATE,
    INOUT o_run_id BIGINT DEFAULT NULL)
LANGUAGE plpgsql AS $$
DECLARE
    v_run_id BIGINT;
    v_logic RECORD;
    v_tf_id INTEGER;
    v_tf_sec INTEGER;
    v_balance NUMERIC;
    v_secs INTEGER;
    v_sec_i INTEGER := 0;
    v_sec RECORD;
    v_date_from DATE;
    v_date_to DATE;
    v_load_from DATE;
    v_cash_fund_code TEXT;
    v_cash_fund_id INTEGER;
    v_end_dt TIMESTAMP;
    v_point_count INTEGER;
    v_prices_in_period INTEGER;
    v_ind_in_period INTEGER;
    v_days_span INTEGER;
    v_tbank JSONB;
    v_pl INTEGER;
    v_pc INTEGER;
    v_is INTEGER;
    v_ic INTEGER;
    v_ie INTEGER;
BEGIN
    v_date_from := LEAST(p_date_from, p_date_to);
    v_date_to := GREATEST(p_date_from, p_date_to);
    v_load_from := v_date_from - 30;
    v_end_dt := (v_date_to::TEXT || ' 23:59:59')::TIMESTAMP;

    SELECT l.id, l.account_id INTO v_logic
    FROM logics l WHERE l.id = p_logic_id;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'Р›РѕРіРёРєР° % РЅРµ РЅР°Р№РґРµРЅР°', p_logic_id;
    END IF;

    PERFORM logic_ensure_non_trading_periods(p_logic_id);

    v_tf_id := logic_resolve_timeframe_id(p_logic_id);
    IF v_tf_id IS NULL THEN
        RAISE EXCEPTION 'РќРµ Р·Р°РґР°РЅ timeframe';
    END IF;
    SELECT t.sec INTO v_tf_sec FROM timeframes t WHERE t.id = v_tf_id;

    v_balance := COALESCE(
        NULLIF(get_logic_param_numeric(p_logic_id, 'initial_balance', NULL), 0),
        1000000
    );
    v_days_span := GREATEST(1, (v_date_to - v_load_from) + 1);
    v_point_count := GREATEST(500, CEIL(v_days_span * (86400.0 / GREATEST(v_tf_sec, 60)))::INTEGER + 200);

    DELETE FROM logic_trades WHERE logic_id = p_logic_id AND is_test = TRUE;
    PERFORM logic_backtest_reset_signal_ratings(p_logic_id);

    v_cash_fund_code := upper(btrim(COALESCE(get_logic_param_text(p_logic_id, 'cash_fund_code'), '')));
    IF v_cash_fund_code IN ('TMON', 'LQDT', 'SBMM') THEN
        PERFORM logic_ensure_cash_fund_security(p_logic_id, v_cash_fund_code);
        SELECT s.id
        INTO v_cash_fund_id
        FROM securities s
        JOIN security_prefixes sp ON sp.security_id = s.id
        WHERE upper(sp.prefix) = v_cash_fund_code
        ORDER BY sp.exchange_id
        LIMIT 1;
    ELSE
        v_cash_fund_id := NULL;
    END IF;

    INSERT INTO logic_backtest_runs (
        logic_id, date_from, date_to, status, progress_pct,
        phase_message, test_balance, started_at
    )
    VALUES (
        p_logic_id, v_date_from, v_date_to, 'loading_prices', 0,
        'Р—Р°РіСЂСѓР·РєР° С†РµРЅ', v_balance, CURRENT_TIMESTAMP
    )
    RETURNING id INTO v_run_id;
    o_run_id := v_run_id;
    COMMIT;

    IF v_tf_sec < 86400 THEN
        v_tbank := tbank_verify_token();
        IF NOT COALESCE((v_tbank->>'valid')::BOOLEAN, FALSE) THEN
            PERFORM logic_backtest_log(
                v_run_id, p_logic_id, 'backtest.failed',
                COALESCE(v_tbank->>'error_message', 'РќСѓР¶РµРЅ С‚РѕРєРµРЅ T-Bank РґР»СЏ intraday'),
                v_tbank
            );
            PERFORM logic_backtest_update_run(
                v_run_id, 'failed', 100, 'РќСѓР¶РµРЅ T-Bank', NULL, NULL, NULL, NULL, v_balance, 0,
                COALESCE(v_tbank->>'error_message', 'Р”Р»СЏ M15 РЅСѓР¶РµРЅ РІР°Р»РёРґРЅС‹Р№ С‚РѕРєРµРЅ T-Bank')
            );
            COMMIT;
            RETURN;
        END IF;
    END IF;

    PERFORM logic_backtest_log(
        v_run_id, p_logic_id, 'backtest.start',
        format('РЎС‚Р°СЂС‚ %s вЂ” %s', v_date_from, v_date_to),
        jsonb_build_object('date_from', v_date_from, 'date_to', v_date_to, 'load_from', v_load_from)
    );

    SELECT COUNT(*)::INTEGER INTO v_secs
    FROM logic_securities ls
    WHERE ls.logic_id = p_logic_id AND ls.is_active = TRUE;

    FOR v_sec IN
        SELECT ls.security_id FROM logic_securities ls
        WHERE ls.logic_id = p_logic_id AND ls.is_active = TRUE
          AND NOT EXISTS (
              SELECT 1 FROM security_prefixes sp
              WHERE sp.security_id = ls.security_id
                AND upper(sp.prefix) IN ('TMON', 'LQDT', 'SBMM')
          )
        ORDER BY ls.display_order, ls.id
    LOOP
        IF logic_backtest_cancel_requested(v_run_id) THEN
            PERFORM logic_backtest_log(v_run_id, p_logic_id, 'backtest.cancelled', 'РћС‚РјРµРЅРµРЅРѕ РЅР° Р·Р°РіСЂСѓР·РєРµ', NULL);
            PERFORM logic_backtest_update_run(v_run_id, 'cancelled', NULL, 'РћС‚РјРµРЅРµРЅРѕ', NULL);
            COMMIT;
            RETURN;
        END IF;
        v_sec_i := v_sec_i + 1;
        BEGIN
            CALL logic_backtest_ensure_security_data(
                v_run_id, p_logic_id, v_sec.security_id, v_tf_id,
                v_load_from, v_date_from, v_date_to, v_end_dt, v_point_count,
                v_pl, v_pc, v_is, v_ic, v_ie
            );
        EXCEPTION WHEN OTHERS THEN
            PERFORM logic_backtest_log(
                v_run_id, p_logic_id, 'backtest.prices.error', SQLERRM,
                jsonb_build_object('security_id', v_sec.security_id), v_sec.security_id, v_tf_id
            );
        END;
        PERFORM logic_backtest_update_run(
            v_run_id, 'loading_prices',
            round(v_sec_i::NUMERIC / GREATEST(v_secs, 1) * 35, 2),
            'РџРѕРґРіРѕС‚РѕРІРєР° РґР°РЅРЅС‹С…',
            format('Р‘СѓРјР°РіР° %s/%s', v_sec_i, v_secs)
        );
        COMMIT;
    END LOOP;

    -- Р¦РµРЅС‹ РґРµРЅРµР¶РЅРѕРіРѕ С„РѕРЅРґР° (СЃРёРіРЅР°Р»С‹ РїРѕ РЅРµРјСѓ РЅРµ РіРѕРЅСЏРµРј, РЅРѕ РїР°СЂРєРѕРІРєР° РІ С‚РµСЃС‚Рµ РЅСѓР¶РЅР°).
    IF v_cash_fund_id IS NOT NULL THEN
        BEGIN
            CALL logic_backtest_ensure_security_data(
                v_run_id, p_logic_id, v_cash_fund_id, v_tf_id,
                v_load_from, v_date_from, v_date_to, v_end_dt, v_point_count,
                v_pl, v_pc, v_is, v_ic, v_ie
            );
        EXCEPTION WHEN OTHERS THEN
            PERFORM logic_backtest_log(
                v_run_id, p_logic_id, 'backtest.cash_fund.prices.error', SQLERRM,
                jsonb_build_object('security_id', v_cash_fund_id, 'fund', v_cash_fund_code),
                v_cash_fund_id, v_tf_id
            );
        END;
        COMMIT;
    END IF;

    SELECT COUNT(*)::INTEGER INTO v_prices_in_period
    FROM prices p
    JOIN logic_securities ls ON ls.security_id = p.security_id
    WHERE ls.logic_id = p_logic_id AND ls.is_active = TRUE
      AND p.timeframe_id = v_tf_id
      AND p.dt::date BETWEEN v_date_from AND v_date_to;

    PERFORM logic_backtest_log(
        v_run_id, p_logic_id, 'backtest.prices.done',
        format('Р¦РµРЅС‹ РІ РїРµСЂРёРѕРґРµ=%s', v_prices_in_period),
        jsonb_build_object('prices_in_period', v_prices_in_period),
        NULL, v_tf_id
    );

    IF v_prices_in_period = 0 THEN
        PERFORM logic_backtest_update_run(
            v_run_id, 'failed', 100, 'РќРµС‚ СЃРІРµС‡РµР№', NULL, NULL, NULL, NULL, v_balance, 0,
            'РќРµ Р·Р°РіСЂСѓР¶РµРЅС‹ С†РµРЅС‹. Р—Р°РґР°Р№С‚Рµ С‚РѕРєРµРЅ T-Bank (M15) РёР»Рё СЃРј. price_load_log.'
        );
        COMMIT;
        RETURN;
    END IF;

    SELECT COUNT(*)::INTEGER INTO v_ind_in_period
    FROM indicator_values iv
    JOIN logic_securities ls ON ls.security_id = iv.security_id
    WHERE ls.logic_id = p_logic_id AND ls.is_active = TRUE
      AND iv.timeframe_id = v_tf_id
      AND iv.dt::date BETWEEN v_date_from AND v_date_to;

    PERFORM logic_backtest_log(
        v_run_id, p_logic_id, 'backtest.indicators.done',
        format('РРЅРґРёРєР°С‚РѕСЂС‹ РІ РїРµСЂРёРѕРґРµ=%s', v_ind_in_period),
        jsonb_build_object('indicator_values_in_period', v_ind_in_period),
        NULL, v_tf_id
    );
    COMMIT;

    IF v_ind_in_period = 0 THEN
        PERFORM logic_backtest_update_run(
            v_run_id, 'failed', 100, 'РќРµС‚ РёРЅРґРёРєР°С‚РѕСЂРѕРІ', NULL, NULL, NULL, NULL, v_balance, 0,
            'РРЅРґРёРєР°С‚РѕСЂС‹ РЅРµ СЂР°СЃСЃС‡РёС‚Р°РЅС‹. РЎРј. backtest.indicator.error.'
        );
        COMMIT;
        RETURN;
    END IF;

    -- Р•РґРёРЅС‹Р№ SQL-РїСЂРѕРіРѕРЅ Р±Р°СЂРѕРІ (С‚РѕС‚ Р¶Рµ РїСѓС‚СЊ, С‡С‚Рѕ РІС‹Р·С‹РІР°РµС‚ Node РїРѕСЃР»Рµ parallel prep).
    CALL logic_backtest_run_bars(v_run_id);
    o_run_id := v_run_id;
END;
$$;

